INSERT INTO skill_descriptions (skill_id, name, max_level, type, description, level_details) VALUES
('NV_BASIC', 'Basic Skill', 9, NULL, 'ใช้ความสามารถขั้นพื้นฐาน', '[Level 1] : แลกเปลี่ยน\nทำให้แลกเปลี่ยนสิ่งของกับตัวละครอื่นได้\nClick ขวา บนตัวละครที่ต้องการแลกเปลี่ยนด้วย\n[Level 2] : แสดงความรู้สึก\nใช้ปุ่ม Alt+0~9, Ctrl+1, -, =,  keys, ในการแสดงความรู้สึกต่างๆ และเลือกความรู้สึกเพิ่มเติมด้วย Alt+L\n[Level 3] : ทำให้นั่งได้\nสามารถฟื้นพลัง HP/SP ได้เร็วขึ้นสองเท่าด้วยการกดปุ่ม Insert\n[Level 4] : ทำให้เปิดห้องพูดคุยได้\nทำให้เปิดห้องสำหรับพูดคุยได้ด้วยปุ่ม Alt+C\n[Level 5] : เข้าร่วมกลุ่ม\nทำให้สามารถเข้าร่วมกลุ่มได้\nคำสั่ง: /join [ชื่อกลุ่ม]\n[Level 6] : ฝากของ\nทำให้ฝากของกับ Kafra ได้\n[Level 7] : สร้างกลุ่ม\nทำให้สร้างกลุ่มของตัวเองได้\nคำสั่ง: /organize [ชื่อกลุ่ม], เปลี่ยนแปลงการตั้งค่าของกลุ่มได้ด้วยปุ่ม Alt+Z\n[Level 9] : เปลี่ยนอาชีพ\nทำให้สามารถเปลี่ยนอาชีพได้'),
('SM_SWORD', 'Sword Mastery', 10, 'Passive', 'เพิ่มพลังโจมตีเมื่อใช้ดาบมือเดียว โดยพลังโจมตีที่เพิ่มมานี้จะเป็น Ignore Target Defence', '[Lv 1] : ATK +4\n[Lv 2] : ATK +8\n[Lv 3] : ATK +12\n[Lv 4] : ATK +16\n[Lv 5] : ATK +20\n[Lv 6] : ATK +24\n[Lv 7] : ATK +28\n[Lv 8] : ATK +32\n[Lv 9] : ATK +36\n[Lv10] : ATK +40'),
('SM_TWOHAND', 'Two-Handed Sword Mastery', 10, 'Passive', 'Requirement : Sword Mastery 1\nเพิ่มพลังโจมตีเมื่อใช้ดาบ 2 มือ โดยพลังโจมตีที่เพิ่มมานี้จะเป็น Ignore Target Defence', '[Lv 1] : ATK +4\n[Lv 2] : ATK +8\n[Lv 3] : ATK +12\n[Lv 4] : ATK +16\n[Lv 5] : ATK +20\n[Lv 6] : ATK +24\n[Lv 7] : ATK +28\n[Lv 8] : ATK +32\n[Lv 9] : ATK +36\n[Lv10] : ATK +40'),
('SM_RECOVERY', 'Increase HP Recovery', 10, 'Passive', 'ความสามารถช่วยฟื้น HP ทุก 10 วินาที ขณะที่นั่งหรือยืนอยู่กับที่เท่านั้น ค่า VIT จะมีผลทำให้ HP ที่ได้จาก Skill นี้มากขึ้นกว่าปกติ และทำให้ Item สำหรับเพิ่ม HP ทุกชนิดให้ผลดีขึ้นอีก 10% ต่อ 1 Level', '[Lv 1] : HP +5\n[Lv 2] : HP +10\n[Lv 3] : HP +15\n[Lv 4] : HP +20\n[Lv 5] : HP +25\n[Lv 6] : HP +30\n[Lv 7] : HP +35\n[Lv 8] : HP +40\n[Lv 9] : HP +45\n[Lv10] : HP +50'),
('SM_BASH', 'Bash', 10, 'Active,Offensive', 'เป้าหมาย : ศัตรู\nใช้สำหรับโจมตีศัตรูตัวเดียว ถ้ามี Skill Fatal Blow ,Bash ตั้งแต่ LV 5  ขึ้นไปมีโอกาสทำให้ศัตรูติด Stun ได้', '[Lv 1] : ATK +130%\n[Lv 2] : ATK +160%\n[Lv 3] : ATK +190%\n[Lv 4] : ATK +220%\n[Lv 5] : ATK +250%\n[Lv 6] : ATK +280%\n[Lv 7] : ATK +310%\n[Lv 8] : ATK +340%\n[Lv 9] : ATK +370%\n[Lv10] : ATK +400%'),
('SM_PROVOKE', 'Provoke', 10, 'Active,Supportive', 'เป้าหมาย : ศัตรู\nทำให้พลังป้องกันของศัตรูลดลงแต่พลังโจมตีจะสูงขึ้น ใช้กับ Undead ไม่ได้', '[Lv 1] : +5% Atk, -10% DEF\n[Lv 2] : +8% Atk, -15% DEF\n[Lv 3] : +11% Atk, -20% DEF\n[Lv 4] : +14% Atk, -25% DEF\n[Lv 5] : +17% Atk, -30% DEF\n[Lv 6] : +20% Atk, -35% DEF\n[Lv 7] : +23% Atk, -40% DEF\n[Lv 8] : +26% Atk, -45% DEF\n[Lv 9] : +29% Atk, -50% DEF\n[Lv10] : +32% Atk, -55% DEF'),
('SM_MAGNUM', 'Magnum Break', 10, 'Active,Offensive', 'Requirement : Bash 5\nProperty : Fire\nใช้สำหรับโจมตีศัตรูเป็นกลุ่มรอบบริเวณผู้ใช้กิน ภายใน 10 วินาทีหลังใช้ Magnum Break มีผลเพิ่ม Fire Property ใส่อาวุธชั่วขณะหนึ่ง เมื่อใช้แล้วจะเสีย HP เล็กน้อย', '[Lv 1] : +Atk 120%\n[Lv 2] : +Atk 140%\n[Lv 3] : +Atk 160%\n[Lv 4] : +Atk 180%\n[Lv 5] : +Atk 200%\n[Lv 6] : +Atk 220%\n[Lv 7] : +Atk 240%\n[Lv 8] : +Atk 260%\n[Lv 9] : +Atk 280%\n[Lv10] : +Atk 300%'),
('SM_ENDURE', 'Endure', 10, 'Supportive', 'Requirement : Provoke 5\nทำให้ไม่หยุดชะงักเมื่อถูกศัตรูโจมตี และ เพิ่ม Magic Defense, ไม่สามารถใช้ในกิลวอร์ได้. เมื่อโดนโจมตี 7 ครั้งโดย Monster ผลของ Endure จะถูกยกเลิก และจะมี Cooldown 10 วินาทีสำหรับการร่าย Endure ครั้งต่อไป', '[Lv 1] : 10 วินาที, Mdef +1\n[Lv 2] : 13 วินาที, Mdef +2\n[Lv 3] : 16 วินาที, Mdef +3\n[Lv 4] : 19 วินาที, Mdef +4\n[Lv 5] : 22 วินาที, Mdef +5\n[Lv 6] : 25 วินาที, Mdef +6\n[Lv 7] : 28 วินาที, Mdef +7\n[Lv 8] : 31 วินาที, Mdef +8\n[Lv 9] : 34 วินาที, Mdef +9\n[Lv10] : 37 วินาที, Mdef +10'),
('MG_SRECOVERY', 'Increase SP Recovery', 10, 'Passive', 'เพิ่มการฟื้นค่า SP หาก Max SP สูง การฟื้นฟู จะสูงขึ้นตามไปด้วย', '[Lv 1] : ทุก 10 วินาที/SP +3\n[Lv 2] : ทุก 10 วินาที/SP +6\n[Lv 3] : ทุก 10 วินาที/SP +9\n[Lv 4] : ทุก 10 วินาที/SP +12\n[Lv 5] : ทุก 10 วินาที/SP +15\n[Lv 6] : ทุก 10 วินาที/SP +18\n[Lv 7] : ทุก 10 วินาที/SP +21\n[Lv 8] : ทุก 10 วินาที/SP +24\n[Lv 9] : ทุก 10 วินาที/SP +27\n[Lv10] : ทุก 10 วินาที/SP +30'),
('MG_SIGHT', 'Sight', 1, 'Supportive(Fire)', 'สร้างลูกไฟหมุนรอบตัวผู้ร่าย เพื่อตรวจจับศัตรูที่ซ่อนอยู่', NULL),
('MG_NAPALMBEAT', 'Napalm Beat', 10, 'Active,Offensive', 'เป้าหมาย : ศัตรู\nโจมตีศัตรูเป็นกลุ่มด้วยพลังวิญญาณ กินบริเวณ 9 ช่อง และ HP ที่เสียจะเป็นแบบหารตามจำนวนศัตรูที่โดนโจมตี  Delay ลดลง เมื่อ Level ของ Skill เพิ่มขึ้น', NULL),
('MG_SAFETYWALL', 'Safety Wall', 10, 'Supportive(Spiritual)', 'Requirement : Napalm Beat 7, Soul Strike 5\nRequirement : Napalm Beat 7, Soul Strike 5\nRequirement : Aspersio 4, Sanctuary 3\nเป้าหมาย : พื้นดิน\nสร้างเกราะเวทมนตร์ขนาด 1 ช่อง โดยผู้ร่ายเวทย์จะต้องเสียใช้ Blue Gemstone 1 เม็ด สามารถป้องกันการโจมตีระยะประชิดได้อย่างสมบูรณ์ในระยะเวลาจำกัด', NULL),
('MG_SOULSTRIKE', 'Soul Strike', 10, 'Active,Offensive', 'Requirement : Napalm Beat 4\nเป้าหมาย : ศัตรู\nโจมตีศัตรูตัวเดียวด้วยวิญญาณ มีพลังโจมตีเพิ่มขึ้นต่อศัตรูประเภท Undead', NULL),
('MG_COLDBOLT', 'Cold Bolt', 10, 'Offensive(Ice)', 'เป้าหมาย : ศัตรู\nสร้างหอกน้ำแข็งจากท้องฟ้าโจมตีศัตรู พลังโจมตีจะเท่ากับ MATK Level ที่เพิ่มขึ้นจะทำให้จำนวนครั้งในการโจมตีเพิ่มขึ้น', NULL),
('MG_FROSTDIVER', 'Frost Driver', 10, 'Offensive(Ice)', 'Requirement : Cold Bolt 5\nเป้าหมาย : ศัตรู\nใช้เวทมนตร์ทำให้ศัตรูแข็งเป็นน้ำแข็ง และเปลี่ยนธาตุของศัตรูเป็นธาตุน้ำ Level ที่สูงขึ้นทำให้โอกาสที่ศัตรูเป็นน้ำแข็งมีสูงขึ้นและระยะเวลานานขึ้น', NULL),
('MG_STONECURSE', 'Stone Curse', 10, 'Curse(Earth)', 'เป้าหมาย : ศัตรู\nทำให้ศัตรูกลายเป็นหิน และลดค่า HP ของศัตรูอย่างช้าๆจนเหลือ 1 หากศัตรูตัวนั้นถูกโจมตีจะทำให้กลับสู่สภาพเดิม ต้องใช้ Red Gemstone 1 เม็ด Level ที่สูงขึ้นทำให้โอกาสที่ศัตรูเป็นหินมีสูงขึ้น', NULL),
('MG_FIREBALL', 'Fire Ball', 10, 'Offensive(Fire)', 'Requirement : Fire Bolt 4\nเป้าหมาย : ศัตรู\nโจมตีศัตรูเป็นกลุ่มด้วยลูกไฟขนาดใหญ่ กินบริเวณ 9 ช่อง ศัตรูที่อยู่รอบๆจะเสีย HP เป็น 3/4 ของศัตรูที่ถูกเล็งไว้ หลังเลเวล 6 ระยะเวลาการร่ายสกิลและดีเลย์จะลดลง', NULL),
('MG_FIREWALL', 'Fire Wall', 10, 'Offensive(Fire)', 'Requirement : Sight 1, Fire Ball 5\nเป้าหมาย : พื้นดิน\nสร้างกำแพงเพลิงด้านหน้าของผู้ร่ายเวทย์ ถ้าศัตรูเข้ามาชนกำแพงนี้จะทำให้ศัตรูเสีย HP และกระเด็นถอยหลัง Level ที่เพิ่มขึ้นจะทำให้ Fire Wall รุนแรงขึ้น', NULL),
('MG_FIREBOLT', 'Fire Bolt', 10, 'Offensive(Fire)', 'เป้าหมาย : ศัตรู\nสร้างธนูไฟจากท้องฟ้าโจมตีศัตรู พลังโจมตีจะเท่ากับ MATK Level ที่เพิ่มขึ้นจะทำให้จำนวนครั้งในการโจมตีเพิ่มขึ้น', NULL),
('MG_LIGHTNINGBOLT', 'Lightning Bolt', 10, 'Offensive(Lightning)', 'เป้าหมาย : ศัตรู\nเรียกสายฟ้าฟาดใส่ศัตรู พลังโจมตีจะเท่ากับ MATK Level ที่เพิ่มขึ้นจะทำให้จำนวนครั้งในการโจมตีเพิ่มขึ้น', NULL),
('MG_THUNDERSTORM', 'Thunder Storm', 10, 'Offensive(Lightning)', 'Requirement : Lightning Bolt 4\nเป้าหมาย : พื้นดิน\nเรียกสายฟ้าขนาดใหญ่ฟาดใส่ศัตรูเป็นกลุ่ม กินบริเวณ 9 ช่อง และ HP ที่เสียจะไม่ลดลงตามจำนวนศัตรูที่โดนโจมตี ไม่ว่าจะมีศัตรูกี่ตัวที่โดน Thunder Storm ก็ตาม Level ที่เพิ่มขึ้นจะทำให้จำนวนครั้งในการโจมตีเพิ่มขึ้น', NULL),
('AL_DP', 'Divine Protection', 10, 'Passive', 'Requirement : Cure 1\nเพิ่มค่าการป้องกันจากผีดิบและวิญญาณ, Level ของตัวละครที่สูงขึ้น ทำให้ผลของท่านี้สูงขึ้น', '[Lv 1] : DEF + 3\n[Lv 2] : DEF + 6\n[Lv 3] : DEF + 9\n[Lv 4] : DEF + 12\n[Lv 5] : DEF + 15\n[Lv 6] : DEF + 18\n[Lv 7] : DEF + 21\n[Lv 8] : DEF + 24\n[Lv 9] : DEF + 27\n[Lv10] : DEF + 30'),
('AL_DEMONBANE', 'Demon Bane', 10, 'Passive', 'Requirement : Divine Protection 3\nเพิ่มพลังโจมตีต่อผีดิบและวิญญาณ, Level ของตัวละครที่สูงขึ้น ทำให้ผลของท่านี้สูงขึ้น', '[Lv 1] : ATK + 3\n[Lv 2] : ATK + 6\n[Lv 3] : ATK + 9\n[Lv 4] : ATK + 12\n[Lv 5] : ATK + 15\n[Lv 6] : ATK + 18\n[Lv 7] : ATK + 21\n[Lv 8] : ATK + 24\n[Lv 9] : ATK + 27\n[Lv10] : ATK + 30'),
('AL_RUWACH', 'Ruwach', 1, 'Active,Supportive', 'สร้างลูกไฟหมุนรอบตัวผู้ร่าย เพื่อตรวจจับศัตรูที่ซ่อนอยู่ ศัตรูที่ปรากฏตัวขึ้นมาจะเสียพลัง 145% ของ MATK ของผู้ร่าย ใช้ SP 10', NULL),
('AL_PNEUMA', 'Pneuma', 1, 'Active,Supportive', 'Requirement : Warp Portal 4\nเป้าหมาย : พื้นดิน\nสร้างม่านสีเขียวขนาด 1 ช่อง เพื่อป้องกันการโจมตีระยะไกลในระยะ 3x3 รอบๆ Skill', NULL),
('AL_TELEPORT', 'Teleport', 2, 'Supportive', 'Requirement : Ruwach 1\nเปิดประตูเพื่อไปสู่สถานที่อื่น', '[Lv 1] : ส่งคุณไปยังจุดใดจุดหนึ่งในแผนที่ที่คุณอยู่แบบสุ่ม\n[Lv 2] : จะส่งคุณไปยังจุดสุดท้ายที่ Save'),
('AL_WARP', 'Warp Portal', 4, 'Supportive', 'Requirement : Teleport 2\nเป้าหมาย : พื้นดิน\nเปิดประตูเพื่อ Warp ไปยังสถานที่ที่ทำการบันทึกไว้ ซึ่งผู้เล่นอื่นสามารถใช้ประตู Warp นี้ได้เช่นกัน การบันทึกตำแหน่ง Warp ได้ด้วยคำสั่ง /memo สามารถจดจำตำแหน่งได้สูงสุด 3 จุด และยังรวมจุด Save Point ที่คุณทำการเซฟไว้กับ Kafra ด้วย ดังนั้นตำแหน่งที่จดจำได้จะรวมทั้งหมดเป็น 4 ตำแหน่ง', '[Lv 1] : Warp to Saved Point.\n[Lv 2] : Enable 1 Memo point.\n[Lv 3] : Enable 2 Memo points.\n[Lv 4] : Enables 3 Memo points.\n[Memo Point] : การตั้งค่าจุด Warp Portal. ให้พิมพ์ /memo ในสถานที่ที่ท่านต้องการบันทึกเป็นจุด Memo Point.'),
('AL_HEAL', 'Heal', 10, 'Active,Supportive', 'Requirement : Faith 10, Demon Bane 5\nเป้าหมาย : ผู้เล่น\nใช้ในการเพิ่มค่า HP สำหรับ 1 คนใน 1 ครั้ง โดย HP ที่เพิ่มได้ขึ้นอยู่กับ Base Level , INT และ Level ของ Skill Heal สามารถใช้ในอีกรูปแบบหนึ่งได้คือใช้โจมตีศัตรูประเภท Undead โดยการเลือกใช้ Skill Heal และกด Shift ค้างไว้แล้วจึงเลือกไปที่ตัวศัตรูเพื่อโจมตี', NULL),
('AL_INCAGI', 'Increase AGI', 10, 'Supportive', 'Requirement : Heal 3\nเป้าหมาย : ผู้เล่น\nเพิ่ม AGI ของตัวเองหรือผู้เล่นอื่นชั่วคราว ทำให้ความเร็วของการโจมตีเพิ่มขึ้น เดินเร็วขึ้นและอัตราการหลบหลีกเพิ่มขึ้น', NULL),
('AL_DECAGI', 'Decrease AGI', 10, 'Supportive', 'Requirement : Increase Agi 1\nเป้าหมาย : ศัตรู\nลด AGI ของศัตรูชั่วคราว ทำให้ความเร็วของการโจมตีลดลง เดินช้าลงและอัตราการหลบหลีกลดลง  int และ Agi จะมีผลกับระยะเวลาพื้นฐาน และระยะเวลาทั้งหมดจะลดลงครึ่งหนึ่งถ้าใช้กับผู้เล่นอื่น', NULL),
('AL_HOLYWATER', 'Aqua Benedicta', 1, 'Active,Supportive', 'สร้างน้ำมนต์ที่ใช้ในการแก้คำสาปหรือ จะต้องอยู่ในน้ำเท่านั้นจึงจะใช้ได้และต้องใช้ Empty Bottle 1 ขวด', NULL),
('AL_CRUCIS', 'Signum Crucis', 10, 'Supportive', 'Requirement : Demon Bane 3\nRange : Entire Screen\nใช้ลดพลังป้องกันของศัตรูประเภท Undead และ Demon ทั้งจอที่คุณมองเห็น หากใช้สำเร็จ จะมี Emotion /swt ปรากฎขึ้น และสภาวะดังกล่าวจะคงอยู่จนศัตรูตาย Level ที่มากขึ้นจะทำให้ลดพลังป้องกันได้มากขึ้นและโอกาสสำเร็จมากขึ้น', NULL),
('AL_ANGELUS', 'Angelus', 10, 'Supportive', 'Requirement : Divine Protection 3\nเพิ่มพลังป้องกันให้กับสมาชิกใน Party ทั้งหมดที่คุณมองเห็น ด้วยการเพิ่ม VIT แต่จะไม่ได้ Max HP', NULL),
('AL_BLESSING', 'Blessing', 10, 'Supportive', 'Requirement : Divine Protection 5\nเป้าหมาย : ผู้เล่น\nเพิ่มค่า STR/INT/DEX ของตัวเองหรือผู้เล่นอื่นชั่วคราว Blessing สามารถใช้ในอีกรูปแบบหนึ่งได้คือทำให้ศัตรูประเภท Undead โดนคำสาป โดยการเลือกใช้ Skill Blessing และกด Shift ค้างไว้แล้วจึงเลือกไปที่ตัวศัตรูเพื่อใช้ สามารถรักษาอาการผิดปกติจาก Curse และ Stone Curse', NULL),
('AL_CURE', 'Cure', 1, 'Recovery', 'Requirement : Heal 2\nRequirement : Faith 5\nเป้าหมาย : ผู้เล่น\nใช้แก้ไขสภาพคำสาปเช่น Silence/Chaos/Blind หากใช้กับศัตรูประเภท Undead จะทำให้ศัตรูติดสถานะ Chaos', NULL),
('MC_INCCARRY', 'Enlarge Weight Limit', 10, 'Passive', 'ทำให้ถือของได้มากขึ้น', '[Lv 1] : ทำให้ถือของได้หนักขึ้นอีก 200\n[Lv 2] : ทำให้ถือของได้หนักขึ้นอีก 400\n[Lv 3] : ทำให้ถือของได้หนักขึ้นอีก 600\n[Lv 4] : ทำให้ถือของได้หนักขึ้นอีก 800\n[Lv 5] : ทำให้ถือของได้หนักขึ้นอีก 1000\n[Lv 6] : ทำให้ถือของได้หนักขึ้นอีก 1200\n[Lv 7] : ทำให้ถือของได้หนักขึ้นอีก 1400\n[Lv 8] : ทำให้ถือของได้หนักขึ้นอีก 1600\n[Lv 9] : ทำให้ถือของได้หนักขึ้นอีก 1800\n[Lv10] : ทำให้ถือของได้หนักขึ้นอีก 2000'),
('MC_DISCOUNT', 'Discount', 10, 'Passive', 'Requirement : Enlarge Weight Limit 3\nสามารถซื้อสินค้าจากร้านของ NPC ได้ในราคาต่ำกว่าปกติ', '[Lv 1] : ลดราคา 7%\n[Lv 2] : ลดราคา 9%\n[Lv 3] : ลดราคา 11%\n[Lv 4] : ลดราคา 13%\n[Lv 5] : ลดราคา 15%\n[Lv 6] : ลดราคา 17%\n[Lv 7] : ลดราคา 19%\n[Lv 8] : ลดราคา 21%\n[Lv 9] : ลดราคา 23%\n[Lv10] : ลดราคา 24%'),
('MC_OVERCHARGE', 'Overcharge', 10, 'Passive', 'Requirement : Discount 3\nสามารถขายสินค้าที่ร้านของ NPC ได้ในราคาสูงกว่าปกติ', '[Lv 1] : เพิ่มราคา 7%\n[Lv 2] : เพิ่มราคา 9%\n[Lv 3] : เพิ่มราคา 11%\n[Lv 4] : เพิ่มราคา 13%\n[Lv 5] : เพิ่มราคา 15%\n[Lv 6] : เพิ่มราคา 17%\n[Lv 7] : เพิ่มราคา 19%\n[Lv 8] : เพิ่มราคา 21%\n[Lv 9] : เพิ่มราคา 23%\n[Lv10] : เพิ่มราคา 24%'),
('MC_PUSHCART', 'Pushcart', 10, 'Passive', 'Requirement : Enlarge Weight Limit 5\nสามารถใช้รถเข็นเพื่อใส่ Item ที่ต้องการขายได้ เมื่อใช้รถเข็นแล้วความเร็วในการเดินของตัวละครจะลดลง แต่ถ้ามี Push-Cart Level สูงขึ้น ความเร็วจะไม่ลดลงเมื่อมีรถเข็น Cart สามารถบรรทุก Item หนัก 8000 คุณสามารถซื้อรถเข็นได้ที่พนักงาน Kapra ราคา 800z และเปิดหน้าต่างจัดการกับรถเข็นด้วย Alt+W (ไม่สามารถใช้สิ่งของในรถเข็นได้โดยตรง)\nสามารถหา Cart ได้จาก Kafra Employees โดยใช้ Shortcut: Alt-W.\nItems ภายใน cart ไม่สามารถใช้งานได้ ต้องย้ายกลับมาช่องสัมภาระเสียก่อน', NULL),
('MC_IDENTIFY', 'Item Appraisal', 1, 'Active,Supportive', 'ใช้ตรวจสอบ Item ที่ยังไม่ทราบรายละเอียดได้ โดยที่ไม่ต้องมี Amplifiers (แว่นขยาย)', NULL),
('MC_VENDING', 'Vending', 10, 'Supportive', 'Requirement : Push Cart 3\nสามารถเปิดร้านค้าแผงลอยในทุกที่ทุกเวลา เช่น ทุ่ง หรือ Dungeon Item ส่วน Item ที่จะนำมาขายคือ Item ที่อยู่ในรถเข็นเท่านั้น และราคาสูงสุดของสินค้าก็คือ 99,990,000 Zeny\nจำนวนสินค้าที่สามารถขายได้จะเพิ่มขึ้นตามระดับเลเวลสกิล', NULL),
('MC_MAMMONITE', 'Mammonite', 10, 'Offensive', 'เป้าหมาย : ศัตรู\nโจมตีศัตรูด้วยเงิน Zeny', '[Lv 1] : ATK +150% ใช้เงิน 100 Zeny\n[Lv 2] : ATK +200% ใช้เงิน 200 Zeny\n[Lv 3] : ATK +250% ใช้เงิน 300 Zeny\n[Lv 4] : ATK +300% ใช้เงิน 400 Zeny\n[Lv 5] : ATK +350% ใช้เงิน 500 Zeny\n[Lv 6] : ATK +400% ใช้เงิน 600 Zeny\n[Lv 7] : ATK +450% ใช้เงิน 700 Zeny\n[Lv 8] : ATK +500% ใช้เงิน 800 Zeny\n[Lv 9] : ATK +550% ใช้เงิน 900 Zeny\n[Lv10] : ATK +600% ใช้เงิน 1,000 Zeny'),
('AC_OWL', 'Owl''s Eye', 10, 'Passive', 'เพิ่มค่า DEX Level ละ 1 DEX', '[Lv 1] : DEX + 1\n[Lv 2] : DEX + 2\n[Lv 3] : DEX + 3\n[Lv 4] : DEX + 4\n[Lv 5] : DEX + 5\n[Lv 6] : DEX + 6\n[Lv 7] : DEX + 7\n[Lv 8] : DEX + 8\n[Lv 9] : DEX + 9\n[Lv10] : DEX +10'),
('AC_VULTURE', 'Vulture''s Eye', 10, 'Passive', 'Requirement : Owl''s Eye 3\nRequirement : Owl''s Eye 3\nช่วยเพิ่มระยะยิงของธนูและอัตราความแม่นยำ(Hit)', '[Lv 1] : ระยะยิง +1 ช่อง HIT +1\n[Lv 2] : ระยะยิง +2 ช่อง HIT +2\n[Lv 3] : ระยะยิง +3 ช่อง HIT +3\n[Lv 4] : ระยะยิง +4 ช่อง HIT +4\n[Lv 5] : ระยะยิง +5 ช่อง HIT +5\n[Lv 6] : ระยะยิง +6 ช่อง HIT +6\n[Lv 7] : ระยะยิง +7 ช่อง HIT +7\n[Lv 8] : ระยะยิง +8 ช่อง HIT +8\n[Lv 9] : ระยะยิง +9 ช่อง HIT +9\n[Lv10] : ระยะยิง +10 ช่อง HIT +10'),
('AC_CONCENTRATION', 'Improve Concentration', 10, 'Supportive', 'Requirement : Vulture''s Eye 1\nเมื่อใช้ Skill นี้แล้วจะเพิ่มค่า AGI และ DEX ชั่วขณะในระยะเวลาการเกิดผลของ Skill และสามารถตรวจจับศัตรูที่ซ่อนตัวอยู่ภายในรัศมีได้', NULL),
('AC_DOUBLE', 'Double Strafe', 10, 'Offensive', 'Requirement : Vulture''s Eye 10\nเป้าหมาย : ศัตรู\nทำให้ Archer ยิงธนูพร้อมกันทีเดียว 2 ดอกใส่ศัตรูตัวเดียว Delay 0.1 วินาที', NULL),
('AC_SHOWER', 'Arrow Shower', 10, 'Offensive', 'Requirement : Double Strafe 5\nTarget : Enemy\nทำให้ Archer ยิงธนูพร้อมกันทีเดียว 25 ดอกใส่ศัตรูเป็นกลุ่ม กินบริเวณ 25 ช่อง และทำให้ศัตรูกระเด็นถอยไป 2 ช่อง  ไม่ต้องการเป้าหมาย', NULL),
('TF_DOUBLE', 'Double Attack', 10, 'Passive', 'เมื่อใช้อาวุธประเภทมีด จะทำให้โจมตีศัตรู 1 ครั้ง แต่โดน 2 ครั้ง มีความแม่นยำขึ้นเมื่อ Level skill สูงขึ้น  และทำให้การโจมตีด้วยมือซ้ายเมื่อใช้อาวุธประเภท Katar แรงขึ้น', NULL),
('TF_MISS', 'Improve Dodge', 10, 'Passive', 'เพิ่มอัตราการหลบหลีก', NULL),
('TF_STEAL', 'Steal', 10, 'Active,Supportive', 'เป้าหมาย : ศัตรู\nใช้ขโมย Item จากศัตรู Level ที่สูงขึ้นทำให้โอกาสที่จะขโมยสำเร็จมีสูงขึ้น', NULL),
('TF_HIDING', 'Hiding', 10, 'Supportive', 'Requirement : Steal 5\nความสามารถในการ ''ขุดและซ่อนตัวใต้โพรงดิน'' ทำให้ศัตรูมองไม่เห็น แต่สัตว์ประหลาดที่คุณสมบัติเป็น Dark, แมลง และหัวหน้าจะมองเห็นคุณได้ ในขณะที่ใช้ Hiding HP และ SP จะไม่เพิ่ม หากต้องการยกเลิก Hiding ให้ใช้ Hiding อีกครั้งหนึ่ง', NULL),
('TF_POISON', 'Envenom', 10, 'Offensive(Poison)', 'เป้าหมาย : ศัตรู\nโจมตีศัตรูด้วยยาพิษซึ่งในครั้งแรกที่ใช้จะทำให้ศัตรูเสีย HP ทันทีและหากศัตรูตัวนั้นๆถูกพิษ ตัวจะเปลี่ยนเป็นสีม่วงและ HP ของศัตรูจะลดลงอย่างต่อเนื่องจนเหลือ 1 แต่ไม่ตาย ใช้ไม่ได้ผลกับศัตรูประเภท Undead และหัวหน้า ความรุนแรงขึ้นอยู่กับ STR และ Level ของ Skill Envenom', NULL),
('TF_DETOXIFY', 'Detoxify', 1, 'Supportive(Poison)', 'Requirement : Envenom 3\nถอนพิษเป้าหมาย', NULL),
('NV_TRICKDEAD', 'Trick Dead', NULL, 'Supportive', 'Requirement : Complete quest, Novice Only\nแกล้งทำเป็นตายเพื่อหลบหลีกจากศัตรูร้ายรอบด้าน เมื่อกดใช้อีกครั้งจะเป็นการยกเลิกและมีโอกาศที่จะถูกยกเลิกเมื่อโดนโจมตี', NULL),
('NV_FIRSTAID', 'First Aid', NULL, 'Recovery', 'Requirement : Complete quest\nใช้ 3 SP เพื่อฟื้นพลัง 5 HP', NULL),
('SM_MOVINGRECOVERY', 'Moving HP Recovery', NULL, 'Passive', 'Requirement : Complete quest\nทำให้สามารถฟื้นค่า HP ได้แม้จะเดินอยู่ ทว่าจะฟื้นค่า HP แค่ 25% ของ HP recovery และ HP recovery จะไม่มีผลต่อความสามารถนี้ด้วย', NULL),
('SM_FATALBLOW', 'Fatal Blow', NULL, 'Passive', 'Requirement : Complete quest\nมีโอกาสในการสร้างความมึนงงให้ศัตรูเมื่อใช้ความสามารถ Bash เลเวล 6 ขึ้นไป โอกาสในการสร้างความมึนงงขึ้นอยู่กับเลเวลของ Bash', NULL),
('SM_AUTOBERSERK', 'Auto Berserk', NULL, 'Passive', 'Requirement : Complete quest\nเมื่อกดใช้งานสกิลนี้ จะทำให้ผู้ใช้เกิดอาการบ้าคลั่ง ติดผล Provoke Lv.10 เมื่อค่า HP ลดลงต่ำกว่า 25% ของ HP ปกติ ในขณะนั้น', NULL),
('AC_MAKINGARROW', 'Arrow Craft', NULL, 'Active,Supportive', 'Requirement : Complete quest\nเป้าหมาย : ไอเท็ม\nเปลี่ยนไอเท็มเป้าหมายให้เป็นลูกธนู ประเภทของลูกธนูที่ได้และจำนวนจะขึ้นอยู่กับประเภทของไอเท็มเป้าหมาย', NULL),
('AC_CHARGEARROW', 'Charged Arrow', NULL, 'Offensive', 'Requirement : Complete quest\nเป้าหมาย : ศัตรู\nรั้งสายธนูจนสุดเพื่อเพิ่มความรุนแรงให้แก่ลูกธนู เป้าหมายจะถูกกระแทกถอยไป 4 ช่องเมื่อถูกโจมตีด้วยความสามารถนี้', NULL),
('TF_SPRINKLESAND', 'Sprinkle Sand', NULL, 'Offensive(Earth)', 'Requirement : Complete quest\nเป้าหมาย : ศัตรู\nโจมตีโดยการซัดทรายบนพื้นดิน เมื่อใช้ความสามารถนี้จะเพิ่มค่าความเสียหาย 130% จากการโจมตีปกติ และมีโอกาสทำให้ศัตรูตาบอดได้ในขณะเดียวกัน', NULL),
('TF_BACKSLIDING', 'Back Slide', NULL, 'Supportive', 'Requirement : Complete quest\nเคลื่อนที่ไปด้านหลังเพื่อหลบเลี่ยงอันตรายจากศัตรูโดยปลอดภัย', NULL),
('TF_PICKSTONE', 'Find Stone', NULL, 'Active,Supportive', 'Requirement : Complete quest\nเป้าหมาย : พื้นดิน\nหยิบหินขึ้นมาจากพื้นดิน', NULL),
('TF_THROWSTONE', 'Stone Fling', NULL, 'Offensive', 'Requirement : Complete quest\nเป้าหมาย : ศัตรู\nสร้างความเสียหาย Ignore Target defense 50  ด้วยก้อนหิน ความสามารถนี้ต้องใช้หิน (stone) และโอกาศที่จะศัตรูจะติด Stun และ Darkness', NULL),
('MC_CARTREVOLUTION', 'Cart Revolution', NULL, 'Offensive', 'Requirement : Complete quest\nเป้าหมาย : ศัตรู\nโจมตีศัตรูโดยใช้รถเข็น (cart) ทำให้ศัตรูรอบด้านถูกโจมตีไปด้วย ปกติจะสร้างความเสียหาย 150% ของค่าความเสียหายจากการโจมตีปกติ แต่น้ำหนักของ cart จะมีผลต่อค่าความเสียหาย', NULL),
('MC_CHANGECART', 'Change Cart', NULL, 'Supportive', 'Requirement : Complete quest\nเปลี่ยนรูปทรงของ cart ได้ 5 แบบ เพื่อให้เหมาะสมกับเลเวลของตัวละคร', NULL),
('MC_LOUD', 'Crazy Uproar', NULL, 'Active,Supportive', 'Requirement : Complete quest\nเป้าหมาย : ผู้ใช้\nร้องตะโกนเพื่อกระตุ้นตัวเอง เพิ่มค่า STR 4 เป็นระยะเวลา 5 นาที', NULL),
('AL_HOLYLIGHT', 'Holy Light', NULL, 'Offensive(Holy)', 'Requirement : Complete quest\nเป้าหมาย : ศัตรู\nเรียกลำแสงศักดิ์สิทธิ์มาขับไล่ความชั่วร้าย', NULL),
('MG_ENERGYCOAT', 'Energy Coat', NULL, 'Supportive', 'Requirement : Complete quest\nปกคลุมตัวเองด้วยพลังวิญญาณเพื่อลดค่าความเสียหายจากการโจมตีของศัตรูรอบด้าน ค่าของ SP ที่เหลืออยู่จะส่งผลต่อค่าความเสียหายที่ลดลงจากความสามารถนี้ ทว่ามันจะต้องใช้ SP มากขึ้นเรื่อยๆเมื่อถูกโจมตีต่อเนื่อง', NULL),
('ALL_RESURRECTION', 'Resurrection', 4, 'Active,Supportive', 'Requirement : Increase SP Recovery 4, Recovery 1\nเป้าหมาย : ผู้เล่นที่ตายไป\nใช้สำหรับฟื้นผู้เล่นอื่นที่ตาย', '[Lv 1] : ได้ HP 10% ของ Max HP\n[Lv 2] : ได้ HP 30% ของ Max HP\n[Lv 3] : ได้ HP 50% ของ Max HP\n[Lv 4] : ได้ HP 80% ของ Max HP'),
('KN_SPEARMASTERY', 'Spear Mastery', 10, 'Passive', 'เพิ่มพลังโจมตีเมื่อใช้อาวุธประเภท spear, พลังโจมตี +1 ทุกๆระดับเลเวลของสกิล มีผลเมื่อตัวละครอยู่บนสัตว์ขี่', '[Lv 1] : Atk +4\n[Lv 2] : Atk +8\n[Lv 3] : Atk +12\n[Lv 4] : Atk +16\n[Lv 5] : Atk +20\n[Lv 6] : Atk +24\n[Lv 7] : Atk +28\n[Lv 8] : Atk +32\n[Lv 9] : Atk +36\n[Lv10] : Atk +40'),
('KN_PIERCE', 'Pierce', 10, 'Offensive', 'Requirement : Spear Mastery 1\nเป้าหมาย : ศัตรู\nโจมตีใส่ศัตรูตัวเดียวหลายครั้งอย่างต่อเนื่อง จำนวนครั้งจะขึ้นอยู่กับขนาดของศัตรู\n[Small Monsters] : 1 hit\n[Medium Monsters] : 2 hits\n[Large Monsters] : 3 hits', NULL),
('KN_BRANDISHSPEAR', 'Brandish Spear', 10, 'Offensive', 'Requirement : Peco Peco Riding 1, Spear Stab 3\nเป้าหมาย : ศัตรู\nใช้หอกสร้างคลื่นพลังโจมตีเป็นบริเวณกว้าง สามารถโจมตีศัตรูได้ทีละหลายตัวพร้อมกัน จะใช้ได้ก็ต่อเมื่อขี่ Pecopeco เท่านั้น Level Skill ที่เพิ่มขึ้นจะทำให้การโจมตีกินบริเวณกว้างขึ้นด้วย', NULL),
('KN_SPEARSTAB', 'Spear Stab', 10, 'Offensive', 'Requirement : Pierce 5\nเป้าหมาย : ศัตรู\nแทงศัตรูด้วยหอกแล้วทำให้ศัตรูกระเด็นถอยหลัง 6 ช่อง สามารถแทงโดนทีละหลายตัวพร้อมกันได้ถ้าศัตรูยืนอยู่ซ้อนกัน', NULL),
('KN_SPEARBOOMERANG', 'Spear Boomerang', 5, 'Offensive', 'Requirement : Pierce 3\nเป้าหมาย : ศัตรู\nขว้างหอกออกไปโจมตีศัตรูที่อยู่ระยะไกล', NULL),
('KN_TWOHANDQUICKEN', 'Two Hand Quicken', 10, 'Active,Supportive', 'Requirement : Two handed sword Mastery 1\nเพิ่มความถี่ในการโจมตีของดาบสองมือขึ้นอีก 25% ยกเลิกสกิลด้วยการถอดดาบสองมือออก', '[Lv 1] : ระยะเวลา 30 วินาที ใช้ SP 14\n[Lv 2] : ระยะเวลา 60 วินาที ใช้ SP 18\n[Lv 3] : ระยะเวลา 90 วินาที ใช้ SP 22\n[Lv 4] : ระยะเวลา 120 วินาที ใช้ SP 26\n[Lv 5] : ระยะเวลา 150 วินาที ใช้ SP 30\n[Lv 6] : ระยะเวลา 180 วินาที ใช้ SP 34\n[Lv 7] : ระยะเวลา 210 วินาที ใช้ SP 38\n[Lv 8] : ระยะเวลา 240 วินาที ใช้ SP 42\n[Lv 9] : ระยะเวลา 270 วินาที ใช้ SP 46\n[Lv10] : ระยะเวลา 300 วินาที ใช้ SP 50'),
('KN_AUTOCOUNTER', 'Counter Attack', 5, 'Offensive', 'Requirement : Two Handed Sword Mastery 1\nเป้าหมาย : ศัตรู\nขณะที่กำลังใช้ Counter Attack Knight ของคุณจะป้องกันการโจมตีระยะประชิดตัวได้ทุกชนิด พร้อมทั้งจะโจมตีสวนกลับ การโจมตีจะเป็น Critical ทุกครั้ง', NULL),
('KN_BOWLINGBASH', 'Bowling Bash', 10, 'Offensive', 'Requirement : Bash 10, Magnum Break 3 Two Hand Sword Mastery 5\nเป้าหมาย : ศัตรู\nโจมตีศัตรูด้วย Skill นี้แล้วจะทำให้ศัตรูตัวนั้นกระเด็นไปกระแทกศัตรูตัวอื่นไปเรื่อยๆและเสีย HP ทุกตัว', NULL),
('KN_RIDING', 'Peco Peco Riding', 1, 'Passive', 'Requirement : Endure 1\nสามารถขี่ Pecopeco ที่เชื่องแล้วได้ และเมื่อขี่ Pecopeco แล้วจะทำให้วิ่งเร็วขึ้น สามารถแบกของเพิ่มขึ้น ได้ 1000', NULL),
('KN_CAVALIERMASTERY', 'Cavalier Mastery', 5, 'Passive', 'Requirement : Peco Peco Riding 1\nเพิ่มความเร็วในการโจมตีเมื่อขี่ Pecopeco หากไม่เรียนรู้ Skill นี้ ความเร็วในการโจมตีเมื่อขี่ Pecopeco ก็จะเป็นครึ่งหนึ่งของที่ไม่ได้ขี่ Pecopeco', NULL),
('PR_MACEMASTERY', 'Mace Mastery', 10, 'Passive', 'เพิ่มพลังโจมตีเมื่อใช้อาวุธประเภทกระบอง โดยพลังโจมตีที่เพิ่มมานี้จะเป็น Ignore Target Defence', '[Lv 1] : ATK +3\n[Lv 2] : ATK +6\n[Lv 3] : ATK +9\n[Lv 4] : ATK +12\n[Lv 5] : ATK +15\n[Lv 6] : ATK +18\n[Lv 7] : ATK +21\n[Lv 8] : ATK +24\n[Lv 9] : ATK +27\n[Lv10] : ATK +30'),
('PR_IMPOSITIO', 'Impositio Manus', 5, 'Active,Supportive', 'เป้าหมาย : ผู้เล่น\nใช้เพิ่มพลังโจมตีของอาวุธในช่วงเวลา 1 นาที', '[Lv 1] : ATK + 5 ใช้ SP 13\n[Lv 2] : ATK +10 ใช้ SP 16\n[Lv 3] : ATK +15 ใช้ SP 19\n[Lv 4] : ATK +20 ใช้ SP 22\n[Lv 5] : ATK +25 ใช้ SP 25'),
('PR_SUFFRAGIUM', 'Suffragium', 3, 'Active,Supportive', 'Requirement : Impositio Manus 2\nเป้าหมาย : ผู้เล่น\nใช้ลดเวลาของการร่ายเวทมนตร์ลง ใช้กับตัวเองไม่ได้ และมีผลกับการร่ายเวทย์เพียงครั้งเดียว', '[Lv 1] : ลดเวลา 15% ระยะเวลา 30 วินาที ใช้ SP 8\n[Lv 2] : ลดเวลา 30% ระยะเวลา 20 วินาที ใช้ SP 8\n[Lv 3] : ลดเวลา 45% ระยะเวลา 10 วินาที ใช้ SP 8'),
('PR_ASPERSIO', 'Aspersio', 5, 'Active,Supportive', 'Requirement : Aqua Benedicta 1, Impositio Manus 3\nเป้าหมาย : ผู้เล่น\nใช้น้ำมนต์ที่สร้างมาจาก Aqua Benedicta เพื่อเปลี่ยนอาวุธให้เป็นอาวุธศักดิ์สิทธิ์ ใช้กับตัวเองไม่ได้ ต้องการ : 1 Holy Water', '[Lv 1] : ระยะเวลา 60 วินาที ใช้ SP 14\n[Lv 2] : ระยะเวลา 90 วินาที ใช้ SP 18\n[Lv 3] : ระยะเวลา 120 วินาที ใช้ SP 22\n[Lv 4] : ระยะเวลา 150 วินาที ใช้ SP 26\n[Lv 5] : ระยะเวลา 180 วินาที ใช้ SP 30'),
('PR_BENEDICTIO', 'B.S. Sacramenti', 1, 'Blessing', 'Requirement : Aspersio 5, Gloria 3\nเป้าหมาย : พื้นดิน\nBenedictio Sanctissimi Sacramenti (หมายถึงการให้พรในพิธีศักดิ์สิทธิ์) เปลี่ยนเกราะธรรมดาเป็นเกราะศักดิ์สิทธิ์ให้ทุกคนที่อยู่รอบๆตัวคุณ จะต้องมี Acloyte หรือ Priest ยืนอยู่ข้างซ้ายและขวาของผู้ร่ายจึงจะใช้ได้\nThis skill requires จำเป็นต้องมี Priest 2 คนด้านซ้ายและขวา ซึ่งอยู่ใน party เดียวกัน.', NULL),
('PR_SANCTUARY', 'Sanctuary', 10, 'Supportive', 'Requirement : Heal 1\nเป้าหมาย : พื้นดิน\nสร้างพื้นที่ขนาดใหญ่สำหรับฟื้นค่า HP พร้อมกันทีละหลายๆคน ถ้าศัตรูประเภท Undead เข้ามาในพื้นที่นี้ก็จะเป็นการลด HP แทน เสีย Blue Gemstone 1 เม็ด', NULL),
('PR_SLOWPOISON', 'Slow Poison', 4, 'Supportive', 'เป้าหมาย : ผู้เล่น\nทำให้ HP ที่ลดลงเรื่อยๆจากอาการพิษหยุดลงชั่วคราว', NULL),
('PR_STRECOVERY', 'Recovery', 1, 'Active,Supportive', 'เป้าหมาย : ผู้เล่น\nช่วยรักษาสถานะที่ผิดปรกติร้ายแรงของผู้เล่น เช่น เป็น Undead, Frozen, Stun Stone Curse Status Recovery สามารถใช้ในอีกรูปแบบหนึ่งได้คือทำให้ศัตรูประเภท Undead ตาบอด โดยการเลือกใช้ Skill Status Recovery และกด Shift ค้างไว้แล้วจึงเลือกไปที่ตัวศัตรูเพื่อใช้', NULL),
('PR_KYRIE', 'Kyrie Eleison', 10, 'Eulogy', 'Requirement : Angellus 2\nสร้างเกราะที่ป้องกันได้ทั้งการโจมตีระยะใกล้และไกลให้ผู้เล่น 1 คนเป็นเวลา 120 วินาที', '[Lv 1] : HP ของเกราะ = 12% ของ MAX HP หรือป้องกันได้ 5 ครั้ง ใช้ SP 25\n[Lv 2] : HP ของเกราะ = 14% ของ MAX HP หรือป้องกันได้ 6 ครั้ง ใช้ SP 25\n[Lv 3] : HP ของเกราะ = 16% ของ MAX HP หรือป้องกันได้ 6 ครั้ง ใช้ SP 25\n[Lv 4] : HP ของเกราะ = 18% ของ MAX HP หรือป้องกันได้ 7 ครั้ง ใช้ SP 25\n[Lv 5] : HP ของเกราะ = 20% ของ MAX HP หรือป้องกันได้ 7 ครั้ง ใช้ SP 25\n[Lv 6] : HP ของเกราะ = 22% ของ MAX HP หรือป้องกันได้ 8 ครั้ง ใช้ SP 30\n[Lv 7] : HP ของเกราะ = 24% ของ MAX HP หรือป้องกันได้ 8 ครั้ง ใช้ SP 30\n[Lv 8] : HP ของเกราะ = 26% ของ MAX HP หรือป้องกันได้ 9 ครั้ง ใช้ SP 30\n[Lv 9] : HP ของเกราะ = 28% ของ MAX HP หรือป้องกันได้ 9 ครั้ง ใช้ SP 30\n[Lv10] : HP ของเกราะ = 30% ของ MAX HP หรือป้องกันได้ 10 ครั้ง ใช้ SP 40'),
('PR_MAGNIFICAT', 'Magnificat', 5, 'Eulogy', 'เพิ่มความเร็วการฟื้น SP 2 เท่าให้กับสมาชิกทุกคนใน Party', NULL),
('PR_GLORIA', 'Gloria', 5, 'Eulogy', 'Requirement : Kyrie Eleison 4, Magnificat 3\nเพิ่ม LUK ให้กับสมาชิกทุกคนใน Party อีก 30', NULL),
('PR_LEXDIVINA', 'Lex Divina', 10, 'Exorcism', 'Requirement : Ruwach 1\nเป้าหมาย : ศัตรู\nทำให้ศัตรูไม่สามารถใช้ Skill ได้ชั่วขณะหนึ่ง', NULL),
('PR_TURNUNDEAD', 'Turn Undead', 10, 'Exorcism', 'Requirement : Resurrection 1, Lex Divina 3\nเป้าหมาย : ศัตรู\nใช้สำหรับโจมตี Undead เท่านั้น หากสำเร็จศัตรูตัวนั้นจะตายกันที Level ที่สูงขึ้นทำให้โอกาสสำเร็จสูงขึ้น', NULL),
('PR_LEXAETERNA', 'Lex Aeterna', 1, 'Active,Supportive', 'Requirement : Lex Divina 5\nเป้าหมาย : ศัตรู\nทำให้การโจมตีครั้งที่ต่อเนื่องหลังการใช้ Lex Aeterna รุนแรงขึ้นเป็น 2 เท่า ใช้ไม่ได้ผลกับศัตรูที่ติดสถานะ Frozen หรือ Stone อยู่', NULL),
('PR_MAGNUS', 'Magnus Exorcismus', 10, 'Exorcism', 'Requirement : Turn Undead 3, Lex Aeterna 1, Safety Wall 1\nเป้าหมาย : พื้นดิน\nสร้าง Grand Cross ขนาดใหญ่ใช้สำหรับโจมตีศัตรูประเภท Undead และ Dark เท่านั้น ใช้ Blue Gemstone 1 เม็ด', NULL),
('WZ_FIREPILLAR', 'Fire Pillar', 10, 'Offensive(Fire)', 'Requirement : Fire Wall 1\nProperty : Fire\nวางกับดักไฟ จะเกิดพายุไฟขนาด 3*3 ช่องเมื่อศัตรูมาเหยียบและกับดักนี้จะหายไปเมื่อไม่มีใครมาเหยียบ', NULL),
('WZ_SIGHTRASHER', 'Sightrasher', 10, 'Offensive(Fire)', 'Requirement : Sight 1, Lightning Bolt 1\nสามารถใช้ Sight ในการโจมตีได้รอบทิศทาง ต้องร่ายสกิล Sight ก่อนที่จะใช้สกิลนี้', NULL),
('WZ_FIREIVY', 'Fire Ivy', NULL, 'จู่โจม(ไฟ)', 'เป้าหมาย : พื้นดิน\nเรียกเถาวัลย์แห่งไฟ', NULL),
('WZ_METEOR', 'Meteor Storm', 10, 'Offensive(Fire)', 'Requirement : Thunder Storm 1, Sightrasher 2\nเป้าหมาย : พื้นดิน\nเรียกอุกกาบาตหลายดวงจากฟ้าลงมาโจมตีศัตรูเป็นกลุ่ม มีโอกาสทำให้ศัตรูติด Stun', NULL),
('WZ_JUPITEL', 'Jupitel Thunder', 10, 'Offensive(Lightning)', 'Requirement : Napalm Beat 1, Lightning Bolt 1\nเป้าหมาย : ศัตรู\nยิงลูกบอลที่ทำจากไฟฟ้าใส่ทำให้ศัตรูได้รับบาดเจ็บ และทำให้ศัตรูกระเด็นไปไกลได้อีกด้วย', NULL),
('WZ_VERMILION', 'Lord of Vermilion', 10, 'จู่โจม(สายฟ้า)', 'Requirement : Thunder Storm 1, Jupitel Thunder 5\nเป้าหมาย : พื้นดิน\nโจมตีศัตรูด้วยสายฟ้าขนาดมหึมาเป็นบริเวณกว้าง มีโอกาสทำให้ศัตรูตาบอด หากเลเวลสกิลสูงขึ้นการร่ายสกิลจะเร็วยิ่งขึ้น', NULL),
('WZ_WATERBALL', 'Waterball', 5, 'Offensive(Ice)', 'Requirement : Cold Bolt 1, Lightning Bolt 1\nเป้าหมาย : ศัตรู\nปล่อย Aqua Ball ใส่ศัตรู 1 ตัว จะใช้ได้ต่อเมื่ออยู่ในน้ำหรืออยู่ใกล้น้ำเท่านั้น Level ที่สูงขึ้นจะทำให้ Skill Waterball รุนแรงขึ้น', NULL),
('WZ_ICEWALL', 'Icewall', 10, 'Supportive(Ice)', 'Requirement : Stone Curse 1, Frost Diver 1\nเป้าหมาย : พื้นดิน\nสร้างกำแพงน้ำแข็งยาว 5 ช่องขึ้นหน้าผู้ร่าย ศัตรูจะเดินผ่านกำแพงนี้ไม่ได้', NULL),
('WZ_FROSTNOVA', 'Frost Nova', 10, 'Offensive(Ice)', 'Requirement : Frost Diver 1, Ice Wall 1\nTarget : Player\nโจมตี รอบตัวผู้ร่าย 5 x 5 ช่อง มีผลทำให้ศัตรูเสียพลังและอาจติดสถานะ Frozen เมื่อ Level ของ Skill เพิ่มขึ้น Delay จะลดลง โดย Dex มีผลต่อ Delay พื้นฐานด้วย', NULL),
('WZ_STORMGUST', 'Storm Gust', 10, 'Offensive(Ice)', 'Requirement : Frost Diver 1, Jupitel 3\nเป้าหมาย : พื้นดิน\nทำให้เกิดพายุหิมะขึ้นในบริเวณกว้าง ศัตรูที่ถูกพายุหิมะนี้จะได้รับบาดเจ็บ และแข็งเป็นน้ำแข็ง', NULL),
('WZ_EARTHSPIKE', 'Earth Spike', 5, 'Offensive(Earth)', 'Requirement : Stone Curse 1\nRequirement : Stone Curse 1\nRequirement : Seismic Weapon 1\nเป้าหมาย : ศัตรู\nสร้างหอกจากหินบนพิ้นดิน ขึ้นมาแทงศัตรู', NULL),
('WZ_HEAVENDRIVE', 'Heaven''s Drive', 5, 'Offensive(Earth)', 'Requirement : Earth Spike 3\nRequirement : Earth Spike 3\nRequirement : Earth Spike 3\nเป้าหมาย : พื้นดิน\nสร้างหอกจากพื้นดินในพื้นที่ที่ตั้งเอาไว้ โดยจะสร้าง damage ให้กับศัตรูที่อยู่ในพื้นที่นั้น', NULL),
('WZ_QUAGMIRE', 'Quagmire', 5, 'Supportive (Earth)', 'Requirement : Heaven''s Drive 1\nเป้าหมาย : พื้นดิน\nเปลี่ยนพื้นดินขนาด 25 ช่องให้เป็นโคลน ศัตรูที่ติดอยู่ในบึงนี้ จะเคลื่อนทีช้าลง และเสีย AGI,DEX, AGI และ DEX ของเป้าหมายจะไม่ลดลงต่ำกว่า 50 สำหรับ monsters, สำหรับผู้เล่น ผลของสกิลจะลดลงครึ่งหนึ่งขงอ monsters', NULL),
('WZ_ESTIMATION', 'Sense', 1, 'Active,Supportive', 'เป้าหมาย : ศัตรู\nใช้ตรวจสอบรายละเอียดของศัตรู เช่น HP/SP ขนาด ประเภท ธาตุ เป็นต้น ให้แก่ผู้ใช้ และสมาชิกภายใน Party', NULL),
('BS_IRON', 'Iron Tempering', 5, 'Passive', 'สามารถสร้าง Iron ได้ Level ที่สูงขึ้นทำให้โอกาสสำเร็จสูงขึ้น', NULL),
('BS_STEEL', 'Steel Tempering', 5, 'Passive', 'Requirement : Iron Tempering 1\nสามารถสร้าง Steel ได้ Level ที่สูงขึ้นทำให้โอกาสสำเร็จสูงขึ้น', NULL),
('BS_ENCHANTEDSTONE', 'Enchanted Stone Craft', 5, 'Passive', 'Requirement : Iron Tempering 1\nสามารถสร้างหินธาตุที่ใช้สำหรับตีอาวุธได้ Level ที่สูงขึ้นทำให้โอกาสสำเร็จสูงขึ้น', NULL),
('BS_ORIDEOCON', 'Research Oridecon', 5, 'Passive', 'Requirement : Enchanted Stone Craft 1\nเพิ่มโอกาสสำเร็จในการสร้างอาวุธที่ใช้ Oridecon เป็นวัตถุดิบ Level ที่สูงขึ้นทำให้โอกาสสำเร็จสูงขึ้น', NULL),
('BS_DAGGER', 'Smith Dagger', 3, 'Passive', 'สามารถสร้างอาวุธประเภทมีดได้ Level ที่สูงขึ้นทำให้โอกาสสำเร็จสูงขึ้น', NULL),
('BS_SWORD', 'Smith Sword', 3, 'Passive', 'Requirement : Smith Dagger 1\nสามารถสร้างอาวุธประเภทดาบได้ Level ที่สูงขึ้นทำให้โอกาสสำเร็จสูงขึ้น', NULL),
('BS_TWOHANDSWORD', 'Smith Two-handed Sword', 3, 'Passive', 'Requirement : Smith Sword 1\nสามารถสร้างอาวุธประเภทดาบ 2 มือได้ Level ที่สูงขึ้นทำให้โอกาสสำเร็จสูงขึ้น', NULL),
('BS_AXE', 'Smith Axe', 3, 'Passive', 'Requirement : Smith Sword 2\nสามารถสร้างอาวุธประเภทขวานได้ Level ที่สูงขึ้นทำให้โอกาสสำเร็จสูงขึ้น', NULL),
('BS_MACE', 'Smith Mace', 3, 'Passive', 'Requirement : Smith Brass Knuckle 1\nสามารถสร้างอาวุธประเภทกระบองได้ Level ที่สูงขึ้นทำให้โอกาสสำเร็จสูงขึ้น', NULL),
('BS_KNUCKLE', 'Smith Brass Knuckle', 3, 'Passive', 'Requirement : Smith Dagger 1\nสามารถสร้างอาวุธประเภทสนับมือได้ Level ที่สูงขึ้นทำให้โอกาสสำเร็จสูงขึ้น', NULL),
('BS_SPEAR', 'Smith Spear', 3, 'Passive', 'Requirement : Smith Dagger 2\nสามารถสร้างอาวุธประเภทหอกได้ Level ที่สูงขึ้นทำให้โอกาสสำเร็จสูงขึ้น', NULL),
('BS_HILTBINDING', 'Hilt Binding', 1, 'Passive', 'STR +1, ATK +4 เพิ่มระยะเวลาของสกิล Adrenaline Rush, Power Thrust และ Weapon Perfection ขึ้น 10%', NULL),
('BS_FINDINGORE', 'Ore Discovery', 1, 'Passive', 'Requirement : Hilt Binding 1, Steel Tempering 1\nเพิ่มโอกาสในพบแร่ต่างๆจากสัตว์ประหลาด', NULL),
('BS_WEAPONRESEARCH', 'Weaponry Research', 10, 'Passive', 'Requirement : Hilt Binding 1\nเพิ่ม ATK/HIT และโอกาสสำเร็จในการสร้างอาวุธทุกชนิด', NULL),
('BS_REPAIRWEAPON', 'Repair Weapon', 1, 'Supportive', 'Requirement : Weaponry Research\nเป้าหมาย : อาวุธ\nใช้สำหรับซ่อมแซมอาวุธ', NULL),
('BS_SKINTEMPER', 'Skin Tempering', 5, 'Passive', 'เพิ่มพลังป้องกันต่อธาตุ Fire และ Neutral ขึ้นตามระดับเลเวลสกิล', '[Lv 1] : Fire +5%, Neutral +1%\n[Lv 2] : Fire +10%, Neutral +2%\n[Lv 3] : Fire +15%, Neutral +3%\n[Lv 4] : Fire +20%, Neutral +4%\n[Lv 5] : Fire +25%, Neutral +5%'),
('BS_HAMMERFALL', 'Hammerfall', 5, 'Active,Supportive', 'เป้าหมาย : พื้นดิน\nใช้ฆ้อนขนาดยักษ์ทุบลงพื้น ทำให้ศัตรูมึนงง กินบริเวณ 25 ช่อง', NULL),
('BS_ADRENALINE', 'Adrenaline Rush', 5, 'Active,Supportive', 'Requirement : Hammerfall 2\nเพิ่มความเร็วในการโจมตีให้กับอาวุธประเภท Axe/Mace ของตนเองและสมาชิกใน Party อีก 25%', NULL),
('BS_WEAPONPERFECT', 'Weapon Perfection', 5, 'Active,Supportive', 'Requirement : Adrenaline Rush, Weaponry Research 2\nเพิ่มพลังโจมตีของอาวุธทุกชนิดของตัวเองและสมาชิกใน Party ให้เป็น 100% สำหรับศัตรูทุกขนาด', NULL),
('BS_OVERTHRUST', 'Power Thrust', 5, 'Active,Supportive', 'Requirement : Adrenaline Rush 3\nเพิ่มพลังโจมตีของอาวุธ โดยมีอัตราการเสี่ยงที่อาวุธจะเสียหาย', '[Lv 1] : ATK +5% ความเสี่ยง 0.1% ระยะเวลา 20 วินาที ใช้ SP 18\n[Lv 2] : ATK +10% ความเสี่ยง 0.1% ระยะเวลา 40 วินาที ใช้ SP 16\n[Lv 3] : ATK +15% ความเสี่ยง 0.1% ระยะเวลา 50 วินาที ใช้ SP 14\n[Lv 4] : ATK +20% ความเสี่ยง 0.1% ระยะเวลา 60 วินาที ใช้ SP 12\n[Lv 5] : ATK +25% ความเสี่ยง 0.1% ระยะเวลา 100 วินาที ใช้ SP 10'),
('BS_MAXIMIZE', 'Maximize Power', 5, 'Active,Supportive', 'Requirement : Weapon Perfection 3, Power Thrust 2\nทำให้การโจมตีเป็นระดับแรงที่สุดเท่าที่เป็นไปได้เสมอเหมือนกับ Cirtical แต่ Maximize Power จะหักลบ DEF ของศัตรูด้วย  และระหว่างที่ใช้จะเสีย SP ไปเรื่อยๆ', NULL),
('HT_SKIDTRAP', 'Skid Trap', 5, 'Active,Hidden Trap', 'เป้าหมาย : พื้นดิน\nวางกับดักที่ทำให้ศัตรูลื่นไปในทิศที่ลูกศรชี้ ต้องมี1 Trap (กับดัก)ในการใช้งาน', '[Lv 1] : ไถลไป 6 ช่อง ระยะเวลา 300 วินาที\n[Lv 2] : ไถลไป 7 ช่อง ระยะเวลา 240 วินาที\n[Lv 3] : ไถลไป 8 ช่อง ระยะเวลา 180 วินาที\n[Lv 4] : ไถลไป 9 ช่อง ระยะเวลา 120 วินาที\n[Lv 5] : ไถลไป 10 ช่อง ระยะเวลา 60 วินาที'),
('HT_LANDMINE', 'Land Mine', 5, 'Trap(Hiding)', 'เป้าหมาย : พื้นดิน\nติดตั้งกับดักที่จะระเบิดเมื่อศัตรูเหยียบถูก ต้องมี1 Trap (กับดัก) ในการใช้งาน', '[Lv 1] : ความรุนแรง 50% ระยะเวลา 65 วินาที ใช้ SP 20\n[Lv 2] : ความรุนแรง 75% ระยะเวลา 50 วินาที ใช้ SP 20\n[Lv 3] : ความรุนแรง 100% ระยะเวลา 35 วินาที ใช้ SP 20\n[Lv 4] : ความรุนแรง 125% ระยะเวลา 20 วินาที ใช้ SP 20\n[Lv 5] : ความรุนแรง 150% ระยะเวลา 5 วินาที ใช้ SP 20\nสถานะ Cast Delay 3 วินาที'),
('HT_ANKLESNARE', 'Ankle Snare', 5, 'Trap(Hiding)', 'Requirement : Skid Trap 1\nเป้าหมาย : พื้นดิน\nติดตั้งกับดักที่จะทำให้ศัตรูเคลื่อนที่ไม่ได้ระยะเวลาหนึ่ง ผลของสกิลขึ้นกับ Agi ของเป้าหมาย ต้องมี1 Trap (กับดัก) ในการใช้งาน', NULL),
('HT_SHOCKWAVE', 'Shockwave Trap', 5, 'Active,Hidden Trap', 'Requirement : Ankle Snare 1\nเป้าหมาย : พื้นดิน\nติดตั้งกับดักที่จะดูด SP ทั้งหมดของศัตรู ต้องมี2 Traps (กับดัก)ในการใช้งาน', '[Lv 1] : ระยะเวลา 200 วินาที SP -20% ใช้ SP 45\n[Lv 2] : ระยะเวลา 160 วินาที SP -35% ใช้ SP 45\n[Lv 3] : ระยะเวลา 120 วินาที SP -50% ใช้ SP 45\n[Lv 4] : ระยะเวลา 80 วินาที SP -65% ใช้ SP 45\n[Lv 5] : ระยะเวลา 40 วินาที SP -80% ใช้ SP 45'),
('HT_SANDMAN', 'Sandman', 5, 'Active,Hidden Trap', 'Requirement : Flasher 1\nเป้าหมาย : พื้นดิน\nติดตั้งกับดักที่จะทำให้ศัตรูที่เหยียบมันและศัตรูใกล้เคียงนอนหลับ ต้องมี2 Traps (กับดัก)ในการใช้งาน', '[Lv 1] : โอกาสทำให้ติดสถานะ Sleep 50% ระยะเวลา 150 วินาที ใช้ SP 12\n[Lv 2] : โอกาสทำให้ติดสถานะ Sleep 60% ระยะเวลา 120 วินาที ใช้ SP 12\n[Lv 3] : โอกาสทำให้ติดสถานะ Sleep 70% ระยะเวลา 90 วินาที ใช้ SP 12\n[Lv 4] : โอกาสทำให้ติดสถานะ Sleep 80% ระยะเวลา 60 วินาที ใช้ SP 12\n[Lv 5] : โอกาสทำให้ติดสถานะ Sleep 90% ระยะเวลา 30 วินาที ใช้ SP 12'),
('HT_FLASHER', 'Flasher', 5, 'Active,Hidden Trap', 'Requirement : Skid Trap 1\nเป้าหมาย : พื้นดิน\nติดตั้งกับดักที่จะทำให้ศัตรูตาบอดโดยการปล่อยแสง ต้องมี2 Traps (กับดัก)ในการใช้งาน', '[Lv 1] : ระยะเวลา 150 วินาที ใช้ SP 12\n[Lv 2] : ระยะเวลา 120 วินาที ใช้ SP 12\n[Lv 3] : ระยะเวลา 90 วินาที ใช้ SP 12\n[Lv 4] : ระยะเวลา 60 วินาที ใช้ SP 12\n[Lv 5] : ระยะเวลา 30 วินาที ใช้ SP 12'),
('HT_FREEZINGTRAP', 'Freezing Trap', 5, 'Hidden Trap', 'Requirement : Flasher 1\nเป้าหมาย : พื้นดิน\nติดตั้งกับดักที่จะทำให้ศัตรูเสีย HP พร้อมทั้งกลายเป็นน้ำแข็งด้วยเวทมนตร์ Frost Nova เมื่อศัตรูมาเหยียบ ต้องมี2 Traps (กับดัก)ในการใช้งาน', '[Lv 1] : ระยะเวลา 150 วินาที ใช้ SP 10\n[Lv 2] : ระยะเวลา 120 วินาที ใช้ SP 10\n[Lv 3] : ระยะเวลา 90 วินาที ใช้ SP 10\n[Lv 4] : ระยะเวลา 60 วินาที ใช้ SP 10\n[Lv 5] : ระยะเวลา 30 วินาที ใช้ SP 10'),
('HT_BLASTMINE', 'Blast Mine', 5, 'Trap(Visible)', 'Requirement : Sandman 1, Land Mine 1, Freezing Trap 1\nเป้าหมาย : พื้นดิน\nติดตั้งกับดักที่จะระเบิดเมื่อศัตรูมาเหยียบ กินบริเวณ 9 ช่อง ต้องมี1 Trap (กับดัก) ในการใช้งาน', '[Lv 1] : ระยะเวลา 10 วินาที ใช้ SP 10\n[Lv 2] : ระยะเวลา 8 วินาที ใช้ SP 10\n[Lv 3] : ระยะเวลา 6 วินาที ใช้ SP 10\n[Lv 4] : ระยะเวลา 4 วินาที ใช้ SP 10\n[Lv 5] : ระยะเวลา 2 วินาที ใช้ SP 10\nสถานะ Cast Delay 3 วินาที'),
('HT_CLAYMORETRAP', 'Claymore Trap', 5, 'Trap(Visible)', 'Requirement : Blast Mine 1, Shockwave Trap 1\nเป้าหมาย : พื้นดิน\nติดตั้งกับดักที่จะระเบิดเมื่อศัตรูมาเหยียบ กินบริเวณ 25 ช่อง ต้องมี2 Trap (กับดัก) ในการใช้งาน', '[Lv 1] : ระยะเวลา 20 วินาที ใช้ SP 15\n[Lv 2] : ระยะเวลา 40 วินาที ใช้ SP 15\n[Lv 3] : ระยะเวลา 60 วินาที ใช้ SP 15\n[Lv 4] : ระยะเวลา 80 วินาที ใช้ SP 15\n[Lv 5] : ระยะเวลา 100 วินาที ใช้ SP 15\nสถานะ Cast Delay 3 วินาที'),
('HT_REMOVETRAP', 'Remove Trap', 1, 'Active,Supportive', 'Requirement : Land mine 1\nRequirement : Double Strafe 5\nเป้าหมาย : กับดัก\nปลดกับดักที่ถูกติดตั้งไว้แล้ว เมื่อปลดแล้วจะได้รับ 1Trap (กับดัก)', NULL),
('HT_TALKIEBOX', 'Talkie Box', 1, 'Active,Hidden Trap', 'Requirement : Remove Trap 1, Shockwave Trap 1\nเป้าหมาย : พื้นดิน\nติดตั้งกับดักที่จะแสดงข้อความเมื่อมีคน (รวมถึงผู้เล่นและสมาชิก) เหยียบโดนมัน กำหนดเวลาคือ 600 วินาที และต้องมี 1 Trap (กับดัก) ในการใช้งาน', NULL),
('HT_BEASTBANE', 'Beastbane', 10, 'Passive', 'เพิ่มพลังโจมตีเมื่อต่อสู้กับ Monster ประเภท Animal และ Insect', '[Lv 1] : Atk +4\n[Lv 2] : Atk +8\n[Lv 3] : Atk +12\n[Lv 4] : Atk +16\n[Lv 5] : Atk +20\n[Lv 6] : Atk +24\n[Lv 7] : Atk +28\n[Lv 8] : Atk +32\n[Lv 9] : Atk +36\n[Lv10] : Atk +40'),
('HT_FALCON', 'Falconry Mastery', 1, 'Passive', 'Requirement : Beastbane 1\nทำให้จ้างนกเหยี่ยวจากสมาคม Hunter ได้', NULL),
('HT_STEELCROW', 'Steel Crow', 10, 'Passive', 'Requirement : Blitz Beat 5\nเพิ่มพลังโจมตีของเหยี่ยว', '[Lv 1] : ATK +6\n[Lv 2] : ATK +12\n[Lv 3] : ATK +18\n[Lv 4] : ATK +24\n[Lv 5] : ATK +30\n[Lv 6] : ATK +36\n[Lv 7] : ATK +42\n[Lv 8] : ATK +48\n[Lv 9] : ATK +54\n[Lv10] : ATK +60'),
('HT_BLITZBEAT', 'Blitz Beat', 5, 'Offensive', 'Requirement : Falconry Mastery 1\nเป้าหมาย : ศัตรู\nสั่งให้เหยี่ยวโจมตีศัตรู ซึ่งจะโจมตีในระยะ : 3+(เลเวลของความสามารถ Vulture''s Eye) เลเวลของสกิลเพิ่มผลของการโจมตีแบบอัตโนมัติของ Falcon เมื่อโจมตีด้วยอาวุธประเภท Bow', NULL),
('HT_DETECTING', 'Detecting', 4, 'Active,Supportive', 'Requirement : Improve Concentration 1, Falconry Mastery 1\nเป้าหมาย : พื้นดิน\nใช้ให้เหยี่ยวตรวจจับศัตรูที่ซ่อนอยู่', NULL),
('HT_SPRINGTRAP', 'Spring Trap', 5, 'Active,Supportive', 'Requirement : Remove Trap 1, Falconry Mastery 1\nเป้าหมาย : กับดัก\nใช้ให้เหยี่ยวทำลายกับดักที่ติดตั้งไว้', NULL),
('AS_RIGHT', 'Righthand Mastery', 5, 'Passive', 'เพิ่มพลังโจมตีให้กับอาวุธในมือขวา เมื่อใช้อาวุธ 2 ชนิด หากไม่มี Skill นี้ในขณะถืออาวุธ 2 ชนิด พลังโจมตีของอาวุธในมือขวาจะเป็น 50%', '[Lv 1] : ATK 60%\n[Lv 2] : ATK 70%\n[Lv 3] : ATK 80%\n[Lv 4] : ATK 90%\n[Lv 5] : ATK 100%'),
('AS_LEFT', 'Lefthand Mastery', 5, 'Passive', 'Requirement : Righthand Mastery 2\nเพิ่มพลังโจมตีให้กับอาวุธในมือซ้าย เมื่อใช้อาวุธ 2 ชนิด หากไม่มี Skill นี้ในขณะถืออาวุธ 2 ชนิด พลังโจมตีของอาวุธในมือซ้ายจะเป็น 30%', '[Lv 1] : ATK 40%\n[Lv 2] : ATK 50%\n[Lv 3] : ATK 60%\n[Lv 4] : ATK 70%\n[Lv 5] : ATK 80%'),
('AS_KATAR', 'Katar Mastery', 10, 'Passive', 'เพิ่มพลังโจมตีเมื่อใช้อาวุธประเภท Katar โดยพลังโจมตีที่เพิ่มมานี้จะเป็น', '[Lv 1] : ATK +3\n[Lv 2] : ATK +6\n[Lv 3] : ATK +9\n[Lv 4] : ATK +12\n[Lv 5] : ATK +15\n[Lv 6] : ATK +18\n[Lv 7] : ATK +21\n[Lv 8] : ATK +24\n[Lv 9] : ATK +27\n[Lv10] : ATK +30'),
('AS_CLOAKING', 'Cloaking', 10, 'Supportive', 'Requirement : Hiding 2\nทำให้เคลื่อนที่ได้ในโหมดล่องหน เมื่ออยู่ติดกำแพงจะเคลื่อนที่เร็วขึ้น แต่ถ้าไม่ได้อยู่ติดกำแพงจะเคลื่อนที่ช้าลง สามารถโจมตีเมื่ออยู่ในโหมดนี้ได้ตั้งแต่ Lv3 (เมื่อโจมตีใน Mode Cloak อัตรา Critical จะเพิ่มขึ้นเท่าตัว) เมื่อใช้สกิล อื่นจะเป็นการยกเลิก การ Cloak', NULL),
('AS_SONICBLOW', 'Sonic Blow', 10, 'Offensive', 'Requirement : Katar Mastery 4\nเป้าหมาย : ศัตรู\nใช้ Katar โจมตีต่อเนื่อง 8 ครั้ง ในบางครั้งจะทำให้ศัตรูมึนงงได้อีกด้วย ATK ที่นำมาเทียบคือในสภาวะที่ไม่มี Skill Katar Mastery และความรุนแรงขึ้นอยู่กับ STR และ Level ของ Skill Sonic Blow', NULL),
('AS_GRIMTOOTH', 'Grimtooth', 5, 'Offensive', 'Requirement : Cloaking 2, Sonic Blow 5\nเป้าหมาย : ศัตรู\nใช้โจมตีในขณะที่ใช้ Hiding อยู่ เมื่อเล็งไปที่ศัตรูแล้วศัตรูอื่นๆที่อยู่รอบๆศัตรูตัวที่คุณเล็งในบริเวณ 9 ช่องจะโดนโจมตีด้วย Grimtooth ด้วย', NULL),
('AS_ENCHANTPOISON', 'Enchant Poison', 10, 'Supportive(Poison)', 'Requirement : Envenom 1\nเป้าหมาย : ผู้เล่น\nเพิ่มคุณสมบัติพิษเข้าไปในอาวุธผู้เล่น', NULL),
('AS_POISONREACT', 'Poison React', 10, 'Supportive(Poison)', 'Requirement : Enchant Poison 3\nเป้าหมาย : ผู้เล่น\nหากถูกโจมตีด้วยธาตุ พิษ, ผู้ใช้จะสามารถ สะท้อนค่าความเสียหายกลับไปได้แทน ( มีผลแค่ 1 ครั้ง ) และเมื่อใช้งานสกิลอยู่, ผู้ใช้จะสะท้อนการโจมตีแบบไร้ธาตุกลับไปด้วยสกิล Envenom โดยอัตโนมัติ', NULL),
('AS_VENOMDUST', 'Venom Dust', 10, 'Supportive(Poison)', 'Requirement : Enchant Poison 5\nเป้าหมาย : พื้นดิน\nสร้างหมอกพิษที่มองไม่เห็นขึ้นเป็นบริเวณ 5 ช่อง ทำให้ศัตรูที่เดินเข้าสู่บริเวณนี้โดนพิษ ต้องมีRed Gemstoneในการใช้งาน', NULL),
('AS_SPLASHER', 'Venom Splasher', 10, 'Offensive(Poison)', 'Requirement : Poison React 5, Venom Dust 5\nเป้าหมาย : ศัตรู\nสกิลนี้จะใช้ได้ก็ต่อเมื่อ HP ของศัตรูเหลือน้อยกว่า 1/3 ของ Max HP เมื่อเป้าหมายถูกสกิลนี้แล้วจะระเบิดสร้างความเสียหายให้กับศัตรูโดยรอบ ใช้ 1 Red Gemstone', NULL),
('RG_SNATCHER', 'Snatcher', 10, 'Passive', 'Requirement : Steal 1\nเป้าหมาย : ผู้ใช้\nขโมยไอเท็มจากมอนสเตอร์ด้วยการโจมตีแบบปกติ โอกาสสำเร็จจะมีผลจากทักษะ Steal.', NULL),
('RG_STEALCOIN', 'Steal Coin', 10, 'Active,Supportive', 'Requirement : Snatcher 4\nเป้าหมาย : ศัตรู(ใช้กับผู้เล่นไม่ได้)\nขโมยเงิน Zeny จากมอสเตอร์ หากขโมยเงิน Zeny ได้สำเร็จจากมอนสเตอร์ตัวใด จะไม่สามารถขโมยซ้ำจากมอนสเตอร์ตัวนั้นได้อีก โอกาสในการทำสำเร็จและจำนวนเงินที่ขโมยได้จะขึ้นอยู่กับเลเวลของทักษะ', NULL),
('RG_BACKSTAP', 'Back Stab', 10, 'Offensive', 'Requirement : Steal Coin 4\nเป้าหมาย : ศัตรู\nสามารถใช้ทักษะนี้โจมตีศัตรูได้แม้จะมองเห็นแค่หลังของมัน ศัตรูจะไม่สามารถหลบหลีกการโจมตีจากทางด้านหลัง\nใช้ทักษะนี้ขณะซ่อนตัวได้ แต่ถ้าใช้จะเป็นการเปิดเผยตัว เมื่อใช้กับอาวุธประเภท Bow พลังโจมตีจะลดลงครึ่งหนึ่ง\nSkill สามารถใช้ได้ในขณะ hiding, แต่หลังจากใช้จะยกเลิกผลของ hiding', NULL),
('RG_TUNNELDRIVE', 'Tunnel Drive', 5, 'Passive', 'Requirement : Hiding 1\nเป้าหมาย : ผู้ใช้\nเคลื่อนที่ในขณะซ่อนตัว แต่จะทำได้ช้ากว่าปกติ', NULL),
('RG_RAID', 'Raid', 5, 'Active,Offensive', 'Requirement : Tunnel Drive 2, Back Stab 2\nขอบเขต : 9 ช่องรอบตัวผู้ใช้\nใช้ได้ในขณะซ่อนตัวเท่านั้น และเมื่อใช้จะเป็นการเปิดเผยตัว ทักษะนี้จะทำให้ศัตรูบาดเจ็บและอาจทำให้เกิดอาการมึนงงหรือตาบอดในระยะของสกิล เป้าหมายได้รับความเสียหายเพิ่มเติมจากเดิมทางกายภาพเพิ่มขึ้น 20% กับ Boss monster มีผลเพียง 10% เมื่อใช้ ผลของสถานะ Hiding จะถูกยกเลิก', NULL),
('RG_STRIPWEAPON', 'Strip Weapon', 5, 'Active,Supportive', 'Requirement : Strip Armor 5\nเป้าหมาย : ศัตรู\nปลดอาวุธศัตรู ถ้าใช้ทักษะนี้กับผู้เล่นเมื่ออยู่ในโหมด PVP อาวุธของผู้นั้นจะถูกปลดออกและใช้อาวุธไม่ได้ระยะหนึ่ง และถ้าใช้กับมอนสเตอร์ ค่า ATK ของมอนสเตอร์ตัวนั้นจะลดลง 25% ไประยะหนึ่ง\nโอกาสสำเร็จของทักษะนี้จะขึ้นอยู่กับเลเวลของทักษะ Strip Weapon และค่า DEX ของผู้ใช้', NULL),
('RG_STRIPSHIELD', 'Strip Shield', 5, 'Active,Supportive', 'Requirement : Strip Helm 5\nเป้าหมาย : ศัตรู\nปลดโล่ของศัตรู ถ้าใช้ทักษะนี้กับผู้เล่นเมื่ออยู่ในโหมด PVP โล่ของผู้นั้นจะถูกปลดออกและใช้โล่ไม่ได้ไประยะหนึ่ง และถ้าใช้กับมอนสเตอร์ ค่า DEF ของมอนสเตอร์ตัวนั้นจะลดลง 15% ในระยะหนึ่ง\nโอกาสสำเร็จของทักษะนี้จะขึ้นอยู่กับเลเวลของทักษะ Strip Shield และค่า DEX ของผู้ใช้', NULL),
('RG_STRIPARMOR', 'Strip Armor', 5, 'Active,Supportive', 'Requirement : Strip Shield 5\nเป้าหมาย : ศัตรู\nปลดเกราะของศัตรู ถ้าใช้ทักษะนี้กับผู้เล่นเมื่ออยู่ในโหมด PVP เกราะของผู้นั้นจะถูกปลดออกและใช้เกราะไม่ได้ไประยะหนึ่ง และถ้าใช้กับมอนสเตอร์ ค่า VIT ของมอนสเตอร์ตัวนั้นจะลดลง 40% ในระยะหนึ่ง\nโอกาสสำเร็จของทักษะนี้จะขึ้นอยู่กับเลเวลของทักษะ Strip Armor และค่า DEX ของผู้ใช้', NULL),
('RG_STRIPHELM', 'Strip Helm', 5, 'Active,Supportive', 'Requirement : Steal Coin 2\nเป้าหมาย : สัตรู\nปลดเครื่องป้องกันศีรษะของศัตรู ถ้าใช้ทักษะนี้กับผู้เล่นเมื่ออยู่ในโหมด PVP เครื่องป้องกันศีรษะของผู้นั้นจะถูกปลดออกและใช้ไม่ได้ไประยะหนึ่ง และถ้าใช้กับมอนสเตอร์ ค่า INT ของมอนสเตอร์ตัวนั้นจะลดลง 40% ในระยะหนึ่ง\nโอกาสสำเร็จของทักษะนี้จะขึ้นอยู่กับเลเวลของทักษะ Strip Helm และค่า DEX ของผู้ใช้', NULL),
('RG_INTIMIDATE', 'Intimidate', 5, 'Active', 'Requirement : Back Stab 4, Sightless Mind 5\nเป้าหมาย : ศัตรู\nโจมตีศัตรู และเคลื่อนย้าย(วาร์ป) ผู้โจมตีและศัตรูไปยังพื้นที่สุ่มในแผนที่นั้น โอกาสสำเร็จขึ้นอยู่กับเลเวลของผู้ใช้และเลเวลของศัตรู ไม่สามารถใช้กับ Boss ได้', NULL),
('RG_GRAFFITI', 'Graffiti', 1, 'Active,Supportive', 'Requirement : Flag Graffiti 5\nเป้าหมาย : พื้นที่\nในบริเวณพื้นที่ที่เลือก สามารถใส่ข้อความลงไปได้สูงสุด 20 ตัวอักษร\nหากไม่ลบข้อความเดิมออกก่อนจะไม่สามารถใส่ข้อความใหม่ลงไปได้ การใช้ทักษะนี้ต้องการ Extra-large Brush1อัน (ยังไม่มี)', NULL),
('RG_FLAGGRAFFITI', 'Flag Graffiti', 5, 'Active,Supportive', 'Requirement : Cleaner 1\nเป้าหมาย : ธง\nหากใช้ทักษะนี้กับธงของสมาคม(Guild) ข้อความที่เขียนลงไปจะแสดงบนธง\nรูปแบบของข้อความจะมีมากขึ้นตามเลเวลทักษะ การใช้ทักษะนี้ต้องการ Small-size Brush1อัน (ยังไม่มี)', NULL),
('RG_CLEANER', 'Cleaner', 1, 'Active,Supportive', 'Requirement : Ganster Paradise 1\nเป้าหมาย : ธง\nทำให้ภาพที่อยู่บนธงกลับเป็นปกติจากการเขียนข้อความลงไป การใช้ทักษะนี้ต้องการ Damp Rag1 อัน (ยังไม่มี)', NULL),
('RG_GANGSTER', 'Gangster Paradise', 1, 'Passive', 'Requirement : Strip Shield 3\nเมื่อนั่งลง และหากมี Rogue อื่นๆ นั่งอยู่ด้วยจะทำให้มอนสเตอร์ไม่เข้ามาโจมตี แต่ใช้การไม่ได้กับ Boss', NULL),
('RG_COMPULSION', 'Compulsion Discount', 5, 'Passive', 'Requirement : Ganster Paradise 1\nราคาสินค้าจะลดลงเมื่อซื้อของในร้านค้าของ NPC', '[Lv 1] : ลดราคา 9%\n[Lv 2] : ลดราคา 13%\n[Lv 3] : ลดราคา 17%\n[Lv 4] : ลดราคา 21%\n[Lv 5] : ลดราคา 25%'),
('RG_PLAGIARISM', 'Plagiarism', 10, 'Passive', 'Requirement : Intimadate 5\nระลึกได้และใช้ทักษะล่าสุดที่ทำการโจมตีไป เลเวลทักษะที่สามารถจดจำได้จะขึ้นอยู่กับเลเวลของทักษะนี้', NULL),
('AM_AXEMASTERY', 'Axe Mastery', 10, 'Passive', 'เพิ่มพลังโจมตีเมื่อใช้ ขวาน', '[Lv 1] : ATK + 3\n[Lv 2] : ATK + 6\n[Lv 3] : ATK + 9\n[Lv 4] : ATK +12\n[Lv 5] : ATK +15\n[Lv 6] : ATK +18\n[Lv 7] : ATK +21\n[Lv 8] : ATK +24\n[Lv 9] : ATK +27\n[Lv10] : ATK +30'),
('AM_LEARNINGPOTION', 'Learning Potion', 10, 'Passive', 'เพิ่มประสิทธิภาพของน้ำยาเมื่อใช้ และช่วยในการทำน้ำยา', NULL),
('AM_PHARMACY', 'Pharmacy', 10, 'Active,Supportive', 'Requirement : Learning Potion 5\nทำน้ำยาหรือยา การใช้ทักษะนี้ต้องการ Medicine Bowl1 อัน ในการทำน้ำยาจำเป็นต้องใช้ Creat Bookที่เกี่ยวข้องกัน', NULL),
('AM_DEMONSTRATION', 'Demonstration', 5, 'โจมตี(ไฟ)', 'Requirement : Pharmacy 4\nเป้าหมาย : พื้นที่\nโจมตีด้วย Fire Bottle บนพื้นที่เป้าหมายในชั่วระยะหนึ่ง ไฟที่เกิดจากทักษะนี้จะไม่ทำให้ศัตรูช้าลง และสร้างความเสียหายแก่อาวุธของศัตรู ทักษะนี้ต้องการ Fire Bottle1อัน', NULL),
('AM_ACIDTERROR', 'Acid Terror', 5, 'Active,Offensive', 'Requirement : Pharmacy 5\nเป้าหมาย : ศัตรู\nโจมตีศัตรูด้วย Acid Bottle และสร้างความเสียหายแก่เกราะของศัตรู ทักษะนี้ต้องการ Acid Bottle1อัน\nโอกาสในการสร้างความเสียหายแก่เกราะของศัตรูขึ้นอยู่กับเลเวลของทักษะ', NULL),
('AM_POTIONPITCHER', 'Potion Pitcher', 5, 'Active,Supportive', 'Requirement : Pharmacy 3\nเป้าหมาย : สมาชิกในทีมเดียวกัน 1 คน\nขว้างน้ำยาไปเพื่อเพิ่มพลังให้แก่สมาชิกใน Party/Guild และ Homunculus ประสิทธิภาพและชนิดของน้ำยาขึ้นอยู่กับเลเวลของทักษะ', '[Lv 1] : สามารถใช้ Red Potion\n[Lv 2] : สามารถใช้ Orange Potion\n[Lv 3] : สามารถใช้ Yellow Potion\n[Lv 4] : สามารถใช้ White Potion\n[Lv 5] : สามารถใช้ Blue Potion'),
('AM_CANNIBALIZE', 'Bio Cannibalize', 5, 'Supportive', 'Requirement : Prepare Potion 6\nเป้าหมาย : พื้นที่\nเรียก Monsterขึ้นมาบนพื้นที่เป้าหมายเพื่อโจมตีศัตรู จำนวน ชนิดและระยะเวลา ของ Monster ที่เรียกออกมาจะแตกต่างกันไปในแต่ละ Level  ทักษะนี้ต้องการ MenEater Plant Bottle1 อัน\nผู้ใช้สามารถเรียก monster ประเภทเดียวกันได้ครั้งเดียว, หากเลเวลสกิลต่ำ monster จะถูกเรียกมาหลายชนิด และ ที่ลเวล 5 จะเรียก monster แค่ตัวเดียว', NULL),
('AM_SPHEREMINE', 'Summon Marine Sphere', 5, 'Supportive', 'Requirement : Prepare Potion 2\nเป้าหมาย : พื้นที่\nเรียก Marine Sphereขึ้นมาบนพื้นที่เป้าหมาย Marine Sphere ที่เรียกขึ้นมานี้จะใช้ทักษะ Suicidal Attackเมื่อถูกโจมตี ทักษะนี้ต้องการ Marine Sphere Bottle1 อัน', NULL),
('AM_CP_WEAPON', 'Chemical Protection (Weapon)', 5, 'Active,Supportive', 'Requirement : Chemical Protection Armor 3\nเป้าหมาย : สมาชิกในทีมเดียวกัน 1 คน\nป้องกันอาวุธของผู้เล่นเป้าหมายไม่ให้เสียหาย ทักษะนี้ต้องการ Coating Bottle1 อัน\nระยะเวลาแสดงผลขึ้นอยู่กับเลเวลของทักษะ', NULL),
('AM_CP_SHIELD', 'Chemical Protection (Shield)', 5, 'Active,Supportive', 'Requirement : Chemical Protection Helm 3\nเป้าหมาย : สมาชิกในทีมเดียวกัน 1 คน\nป้องกันโล่ของผู้เล่นเป้าหมายไม่ให้เสียหาย ทักษะนี้ต้องการ Coating Bottle1 อัน\nระยะเวลาแสดงผลขึ้นอยู่กับเลเวลของทักษะ', NULL),
('AM_CP_ARMOR', 'Chemical Protection (Armor)', 5, 'Active,Supportive', 'Requirement : Chemical Protection Shield 3\nเป้าหมาย : สมาชิกในทีมเดียวกัน 1 คน\nป้องกันเกราะของผู้เล่นเป้าหมายไม่ให้เสียหาย ทักษะนี้ต้องการ Coating Bottle1 อัน\nระยะเวลาแสดงผลขึ้นอยู่กับเลเวลของทักษะ', NULL),
('AM_CP_HELM', 'Chemical Protection (Helm)', 5, 'Active,Supportive', 'Requirement : Pharmacy 2\nเป้าหมาย : สมาชิกในทีมเดียวกัน 1 คน\nป้องกันเครื่องป้องกันศีรษะของผู้เล่นเป้าหมายไม่ให้เสียหาย ทักษะนี้ต้องการ Coating Bottle1 อัน\nระยะเวลาแสดงผลขึ้นอยู่กับเลเวลของทักษะ', NULL),
('AM_BIOETHICS', 'Bioethics', NULL, 'Passive', 'Requirement : Complete quest\nทักษะนี้ไม่ให้ประสิทธิผลใด แต่เป็นจุดเริ่มต้นของทักษะในการสร้าง Homunculus แต่ทักษะ Bioethics นี้เป็นพื้นฐานที่จำเป็นอย่างยิ่งต่อผู้ที่ต้องการสร้างชีวิต.', NULL),
('AM_BIOTECHNOLOGY', 'Biotechnology', NULL, 'Passive', 'เรียนรู้ทฤษฎีพื้นฐานเกี่ยวกับการสร้างชีวิต เพิ่มโอกาสสำเร็จในการสร้างสิ่งมีชีวิตและเพิ่มค่า Max HP ของ Homunculus ที่สร้างขึ้น', NULL),
('AM_CREATECREATURE', 'Create Creature', NULL, 'Active,Supportive', 'สร้างไอเท็มมีชีวิต Germination Breedโอกาสในการทำสำเร็จขึ้นอยู่กับเลเวลของทักษะ', NULL),
('AM_CULTIVATION', 'Cultivation', NULL, 'Supportive', 'เลี้ยงดู ''Germination Breed'' ให้เติบโตเป็น Homunculus โอกาสสำเร็จหรือล้มเหลวจะมีอัตราคงที่ และพื้นฐานของโอกาสสำเร็จจะขึ้นอยู่กับเลเวลของทักษะ', NULL),
('AM_FLAMECONTROL', 'Flame Control', NULL, 'Passive', 'ควบคุมไฟด้วยทองเหลือง เพิ่มโอกาสสำเร็จของ Cultivation และเพิ่มความทนทานเมื่อถูกจู่โจมด้วยไฟ', NULL),
('AM_CALLHOMUN', 'Call Homunculus', 1, 'Active,Supportive', 'Requirement : Rest 1\nเรียก Homunculus ออกมาหรือให้กลับเข้าไป เมื่อใช้ทักษะนี้จะสามารถตรวจสอบสภาพของมันได้ และเมื่อเลือก Homunculus จะปรากฎตัวออกมาซึ่งจะใช้ค่า SP เล็กน้อย หากใช้ทักษะนี้เมื่อ Homunculus ปรากฎตัวอยู่ มันจะกลับเข้าไป', NULL),
('AM_REST', 'Rest', 1, 'Active,Supportive', 'Requirement : Bioethics 1\nให้ Homunculus พักผ่อน', NULL),
('AM_DRILLMASTER', 'DrillMaster', 10, 'Passive', 'เพิ่มพลังโจมตีของ Homunculus', '[Lv 1] : ATK +3\n[Lv 2] : ATK +6\n[Lv 3] : ATK +9\n[Lv 4] : ATK +12\n[Lv 5] : ATK +15\n[Lv 6] : ATK +18\n[Lv 7] : ATK +21\n[Lv 8] : ATK +24\n[Lv 9] : ATK +27\n[Lv10] : ATK +30'),
('AM_HEALHOMUN', 'Heal Homunculus', NULL, 'Active,Supportive', 'เป้าหมาย : Homunculus\nฟื้นพลัง HP ของ Homunculus อัตราการฟื้นพลังจะเหมือนกับทักษะ Healของ Acolyte', NULL),
('AM_RESURRECTHOMUN', 'Resurrection Homunculus', 5, 'Active,Supportive', 'Requirement : Call Homunculus 1\nเป้าหมาย : Homunculus\nชุบชีวิต Homunculus ที่ตาย', NULL),
('CR_TRUST', 'Faith', 10, 'Passive', 'เพิ่มค่า Max HP และทำให้ทนทานต่อการโจมตีแบบ Holy', NULL),
('CR_AUTOGUARD', 'Auto Guard', 10, 'Active,Supportive', 'ป้องกันการโจมตีทางกายในช่วงระยะเวลาที่กำหนด แต่จะตัวแข็งไป 0.3 วินาทีหลังการป้องกันด้วย Auto Guard\nทักษะนี้ใช้งานได้เมื่อถือโล่เท่านั้น และเมื่อไม่ถือโล่ประสิทธิผลที่เกิดขึ้นจะหายไปเช่นกัน ถ้าใช้ทักษะนี้อีกครั้งหลังจากที่ใช้ไปแล้ว จะเป็นการหยุดใช้ทักษะนี้', NULL),
('CR_SHIELDCHARGE', 'Shield Charge', 5, 'Active,Offensive', 'Requirement : Auto Guard 5\nเป้าหมาย : ศัตรู\nกระแทกศัตรูด้วยโล่ ทำให้ศัตรูกระเด็นไประยะหนึ่งและมีโอกาสทำให้ศัตรูมึนงงในอัตราที่กำหนด\nทักษะนี้ใช้งานได้เมื่อถือโล่เท่านั้น', NULL),
('CR_SHIELDBOOMERANG', 'Shield Boomerang', 5, 'Active,Offensive', 'Requirement : Shield Charge 3\nเป้าหมาย : ศัตรู\nทำให้ศัตรูบาดเจ็บด้วยการขว้างโล่\nพลังโจมตีจะขึ้นอยู่กับเลเวลของโล่และน้ำหนัก สามารถใช้ทักษะนี้ได้เมื่อถือโล่เท่านั้น', NULL),
('CR_REFLECTSHIELD', 'Reflect Shield', 10, 'Active,Supportive', 'Requirement : Shield Boomerang 3\nสะท้อนพลังโจมตีใส่ศัตรูในระยะใกล้\nสะท้อนพลังโจมตีทางกาย และสามารถใช้ทักษะนี้ได้เมื่อถือโล่เท่านั้น', NULL),
('CR_HOLYCROSS', 'Holy Cross', 10, 'Active,Offensive', 'Requirement : Faith 7\nเป้าหมาย : ศัตรู\nสร้างค่าความบาดเจ็บแก่ศัตรูสองครั้งซ้อนจากการโจมตีด้วย Holy Cross มีโอกาสทำให้ศัตรูตาบอดในอัตราที่กำหนด', NULL),
('CR_GRANDCROSS', 'Grand Cross', 10, 'Active,Offensive', 'Requirement : Faith 10, Holy Cross 6\nเป้าหมาย : พื้นที่\nสร้างคำพิพากษาศักดิ์สิทธิ์ด้วย Grand Cross ขึ้นรอบตัวผู้ใช้ โดยทำให้เกิดค่าความเสียหาย 20% ของค่า HP ที่เหลืออยู่\nเวทมนตร์จะไม่หยุดชะงักเมื่อผู้ใช้ถูกโจมตีในขณะร่ายเวทย์ มอนสเตอร์ประเภท Undead และ Devil ทั้งหมดที่ถูกโจมตีจะตาบอด ยกเว้น Boss', NULL),
('CR_DEVOTION', 'Devotion', 5, 'Active,Supportive', 'Requirement : Grand Cross 4, Reflect Shiled 5\nเป้าหมาย : สมาชิกในทีมเดียวกัน 1 คน ยกเว้นผู้ใช้\nย้ายค่าความบาดเจ็บที่เกิดขึ้นกับสมาชิกใน Party/Guild มาที่ตัวผู้ใช้ แต่ตัวละครเป้าหมายต้องมีเลเวลแตกต่างกับผู้ใช้น้อยกว่า 10 และผลที่เกิดขึ้นจะหายไปเมื่อผู้ใช้กับตัวละครเป้าหมายอยู่ไกลกัน\nไม่สามารถใช้ทักษะนี้กับ Crusader หรือ Paladon', NULL),
('CR_PROVIDENCE', 'Divine Providence', 5, 'Active,Supportive', 'Requirement : Divine Protection 5, Heal 5\nเป้าหมาย : ผู้เล่นที่เป็นมิตร ที่ไม่ใช่ Cruseder\nทำให้ทนทานต่อมอนสเตอร์ Demon และ Angel มากขึ้นด้วยพลังป้องกันศักดิ์สิทธิ์  ไม่สามารถใช้กับตัวเองได้', NULL),
('CR_DEFENDER', 'Defending Aura', 5, 'Supportive', 'Requirement : Shield Boomerang 1\nลดค่าความบาดเจ็บจำนวนมากที่เกิดจากการโจมตีระยะไกล ค่าความบาดเจ็บที่ลดลงจะขึ้นอยู่กับเลเวลของทักษะ และเมื่อใช้ทักษะนี้จะเคลื่อนที่และโจมตีช้าลง\nเมื่อทักษะนี้ยังมีผลอยู่และใช้ทักษะนี้อีกครั้งจะเป็นการเลิกใช้ทักษะนี้ สามารถใช้ทักษะนี้ได้เมื่อถือโล่เท่านั้น', NULL),
('CR_SPEARQUICKEN', 'Spear Quicken', 10, 'Active,Offensive', 'Requirement : Spear Mastery 10\nเพิ่มความเร็วในการโจมตีเมื่อใช้กับไอเทมประเภทหอก ความเร็วในการโจมตีและเวลาเกิดผลจะขึ้นอยู่กับเลเวลของทักษะ\nทักษะนี้ใช้งานได้เมื่อถือหอกเท่านั้น หากปลดหอกออก ผลที่เกิดขึ้นก็จะหายไปเช่นกัน', NULL),
('MO_IRONHAND', 'Iron Hand', 10, 'Passive', 'Requirement : Demon Bane 10, Divine Protection 10\nเพิ่มพลังโจมตีเมื่อใช้ Knuckle หรือมือเปล่า', '[Lv 1] : ATK +3\n[Lv 2] : ATK +6\n[Lv 3] : ATK +9\n[Lv 4] : ATK +12\n[Lv 5] : ATK +15\n[Lv 6] : ATK +18\n[Lv 7] : ATK +21\n[Lv 8] : ATK +24\n[Lv 9] : ATK +27\n[Lv10] : ATK +30'),
('MO_SPIRITSRECOVERY', 'Vigor Recovery', 5, 'Passive', 'Requirement : Stop Blade 2\nเมื่อนั่งลงจะฟื้นพลัง HP และ SP ทุก 10 วินาที หากน้ำหนักเกิน 50% จะฟื้นพลังได้ทุก 20 วินาที', NULL),
('MO_CALLSPIRITS', 'Vigor condensation', 5, 'Active,Supportive', 'Requirement : Iron Hand 2\nสร้าง Spirit Sphere เพื่อรวบรวมความแข็งแกร่ง พลังนี้จะติดตามและให้ผลแก่ผู้ใช้พลัง Spirit Sphere แต่ละลูกเพิ่ม ATK +3', NULL),
('MO_ABSORBSPIRITS', 'Spiritual Sphere Absorption', 1, 'Supportive', 'Requirement : Summon Spirit Sphere 5\nฟื้นค่า SP ด้วยการดูดพลังจาก Spirit Spheres และ 1 ม่านทรงกลมจะฟื้น 10 SP เมื่ออยู่ในโหมด PvP และ Guild War จะสามารถดูดพลัง Spirit Spheres ของ Monk อื่นๆได้ด้วย สามารถใช้ในการดูด SP ของ Monster ได้\nถ้าใช้กับ monsters, skill มีโอกาส 20% ที่จะมอบ SP ให้แก่ผู้ใช้ ขึ้นอยู่กับเลเวลของ monsters ไม่ได้ผลกับ Boss monsters และ WoE guardians.', NULL),
('MO_TRIPLEATTACK', 'Triple Attack', 10, 'Passive', 'Requirement : Dodge 5\nโจมตีสามครั้งซ้อนในอัตราที่กำหนด ถ้าเรียนรู้ทักษะ Chain Combo แล้ว หลังจากโจมตีด้วยทักษะนี้จะโจมตีต่อเนื่องด้วย Chain Combo', NULL),
('MO_BODYRELOCATION', 'Snap', 1, 'Supportive', 'Requirement : Spritual Cadence 2, Guillotine Fist 3, Mental Strength 3\nเป้าหมาย : พื้นที่\nเคลื่อนย้าย(วาร์ป) ไปยังพื้นที่ที่เลือก แต่ถ้ามีสิ่งกีดขวางระหว่างตัวละครกับพื้นที่ที่เลือก การใช้ทักษะนี้จะล้มเหลว.\nทักษะนี้ใช้การได้เมื่อมี 1 Spirit Sphere, แต่เมื่ออยู่ในสถานะ Vigor Explosion จะไม่ต้องใช้ Spirit Sphere อีกต่อไป', NULL),
('MO_DODGE', 'Dodge', 10, 'Passive', 'Requirement : Iron Hand 5, Vigor condensation 5\nเพิ่มอัตรา Flee', NULL),
('MO_INVESTIGATE', 'infiltration', 5, 'Active,Offensive', 'Requirement : Vigor condensation 5\nเป้าหมาย : ศัตรู\nทำให้ศัตรูบาดเจ็บภายในด้วยความแข็งแกร่ง สามารถทำให้ศัตรูที่มี DEF สูงบาดเจ็บได้มากขึ้น\nทักษะนี้ใช้การได้เมื่อมี 1 Spirit Sphere', NULL),
('MO_FINGEROFFENSIVE', 'Finger Offensive', 5, 'Active,Offensive', 'Requirement : Infiltration 3\nเป้าหมาย : ศัตรู\nโจมตีศัตรูที่อยู่ไกลด้วยกระสุนที่รวดเร็ว\nทักษะนี้ใช้การได้เมื่อมีผลของ Spirit Spheres เท่านั้น', NULL),
('MO_STEELBODY', 'Steel Body', 5, 'Active,Supportive', 'Requirement : Combo Finish 3\nในระยะเวลาเกิดผล ค่า DEF และ MDEF จะสูงขึ้น แต่ในช่วงเวลานั้นจะไม่สามารถใช้ทักษะอื่น และความเร็วในการเคลื่อนที่และโจมตีจะลดลง\nทักษะนี้ใช้การได้เมื่อมี 5 Spirit Spheres', NULL),
('MO_BLADESTOP', 'Stop Blade', 5, 'Active,Supportive', 'Requirement : Dodge 5\nหยุดการเคลื่อนไหวของศัตรูและตัวคุณเอง ในช่วงเวลานี้ทั้งคุณและศัตรูจะเคลื่อนที่ไม่ได้แต่หากฝ่ายใดเกิดตายขึ้นมา อีกฝ่ายจะเคลื่อนที่ได้ ถ้าทักษะนี้มีเลเวลสูง จะทำให้โจมตีศัตรูด้วยทักษะอื่นได้ในช่วงเวลาเกิดผล\nใช้กับ Boss ไม่ได้ และทักษะนี้ใช้การได้เมื่อมี 1 Spirit Spheres', '[Lv 1] : ระยะเวลา 20 วินาที\n[Lv 2] : ระยะเวลา 30 วินาที, ใช้ Finger Offecsive ได้\n[Lv 3] : ระยะเวลา 40 วินาที, ใช้ infiltration ได้\n[Lv 4] : ระยะเวลา 50 วินาที, ใช้ Chain Combo ได้\n[Lv 5] : ระยะเวลา 60 วินาที, ใช้ Asura Strike ได้\nใช้ Asura Strike ได้เมื่อมีผลของ Vigor Explosion เท่านั้น และต้องมี 4 Spirit Spheres'),
('MO_EXPLOSIONSPIRITS', 'Vigor Explosion', 5, 'Active,Supportive', 'Requirement : Vigor Absorption 1\nเพิ่มอัตราการโจมตีสูงสุด(Critical) ระยะหนึ่ง เมื่อใช้ทักษะนี้ ค่า SP ฟื้นอัตโนมัติจะลดลง 50%\nทักษะนี้ใช้การได้เมื่อมี 5 Spirit Spheres', NULL),
('MO_EXTREMITYFIST', 'Asura Strike', 5, 'Active,Offensive', 'Requirement : Vigor Explosion 3, Finger Offensive 3\nเป้าหมาย : ศัตรู\nทักษะนี้ใช้ได้เมื่อมีผลของ Vigor Explosion เท่านั้น ทำให้ศัตรูบาดเจ็บอย่างมากและ SP ที่เหลืออยู่จะหายไปทั้งหมด หลังจากใช้ทักษะนี้ผลของ Vigor Explosion จะหายไป\nหลังจากใช้ทักษะนี้ ค่า SP จะไม่ฟื้นอัตโนมัติ 10 วินาที และทักษะนี้ใช้การได้เมื่อมี 5 Spirit Spheres', NULL),
('MO_CHAINCOMBO', 'Chain Combo', 5, 'Active,Offensive', 'Requirement : Triple Attack 5\nเป้าหมาย : ศัตรู\nสามารถใช้ทักษะนี้ได้หลังจากใช้ Triple Attack จะทำให้สามารถโจมตีมอนสเตอร์ได้ 4 ครั้งซ้อน ถ้าศึกษาทักษะ Combo Finish จะสามารถระดมโจมตีต่อเนื่องได้หลังจากการโจมตี 4 ครั้งซ้อน', NULL),
('MO_COMBOFINISH', 'Combo Finish', 5, 'Active,Offensive', 'Requirement : Chain Combo 3\nเป้าหมาย : ศัตรู\nสามารถใช้ทักษะนี้ต่อเนื่องจาก Chain Combo ศัตรูจะกระเด็นไปด้านหลังและสร้างความเสียหายอย่างมากให้แก่ศัตรู ถ้าศึกษา Asura Strike และใช้งานได้แล้ว จะสามารถใช้งานต่อเนื่องจากทักษะนี้ได้\nหาก Asura Strike สามารถใ้ช้งานได้แล้ว, มันจะมี delay ของสกิลหลังจากใช้งาน\nสามารถใช้ทักษะ Asura Strike ต่อเนื่องจากทักษะนี้เท่านั้นเมื่อมีผลของ Vigor Explosion และต้องมี Spirit Spheres มากกว่า 4 ทักษะนี้ใช้การได้เมื่อมี 1 Spirit Spheres', NULL),
('SA_ADVANCEDBOOK', 'Advanced Book', 10, 'Passive', 'เพิ่มพลังโจมตีและความเร็วในการโจมตี เมื่อใช้หนังสือ(Book)', '[Lv 1] : ATK + 3, Aspd +0.5%\n[Lv 2] : ATK + 6, Aspd +1.0%\n[Lv 3] : ATK + 9, Aspd +1.5%\n[Lv 4] : ATK +12, Aspd +2.0%\n[Lv 5] : ATK +15, Aspd +2.5%\n[Lv 6] : ATK +18, Aspd +3.0%\n[Lv 7] : ATK +21, Aspd +3.5%\n[Lv 8] : ATK +24, Aspd +4.0%\n[Lv 9] : ATK +27, Aspd +4.5%\n[Lv10] : ATK +30, Aspd +5.0%'),
('SA_CASTCANCEL', 'Cast Cancel', 5, 'Active,Supportive', 'Requirement : Advanced Book 2\nใช้ทักษะนี้ระหว่างการร่ายเวทย์ หลังจากยกเลิกการร่ายเวทย์แล้วสามารถเคลื่อนที่ได้ พลัง SP ที่ใช้จะลดลงตามระดับของเลเวลทักษะ', NULL),
('SA_MAGICROD', 'Magic Rod', 5, 'Active,Supportive', 'Requirement : Advanced Book 4\nถ้ากะจังหวะถูกต้องและใช้เมื่อถูกโจมตีด้วยเวทมนตร์ของศัตรู จะไม่บาดเจ็บและดูดพลัง SP เวทมนตร์นั้นของศัตรู\nถ้าดูดพลัง Spell Breaker ของศัตรู ศัตรูจะเสียค่า SP 20%', NULL),
('SA_SPELLBREAKER', 'Spell Breaker', 5, 'Supportive', 'Requirement : Magic Rod 1\nเป้าหมาย : ศัตรู\nสามารถดูดค่า SP ของเวทมนตร์ศัตรูได้เมื่อศัตรูร่ายเวทย์ ทำให้เวทมนตร์ที่ศัตรูร่ายออกมาถูกยกเลิกไป, อีกทั้งลด HP ของศัตรูลง 2% และที่สกิลเลเวล 5 ครึ่งหนึ่งของค่ความเสียหายที่ศัตรูได้รับจะถูกเพิ่มให้กับผู้ร่าย โดยผลของการดูด HP นี้ไม่สามารถใช้กับ Boss monster หรือ WoE Guardians, และ สกิลนี้มีโอกาส 10% ที่จะหยุดการร่ายเวทย์ของ Boss monsters\nการดูด HP ไม่สามารถใช้กับ Boss monsters และ WoE Guardians ได้, แลัสกิลมีโอกาสเพียง 10% ที่จะยกเลิกเวทย์ของ Boss monster', NULL),
('SA_FREECAST', 'Free Cast', 10, 'Passive', 'Requirement : Cast Cancel 1\nสามารถโจมตีและเคลื่อนที่ได้ในขณะร่ายเวทย์ อัตราการเคลื่อนที่และโจมตีจะขึ้นอยู่กับเลเวลของทักษะ', NULL),
('SA_AUTOSPELL', 'Auto Spell', 10, 'Active,Supportive', 'Requirement : Free Cast 4\nเมื่อใช้ทักษะนี้ คุณจะสามารถใช้เวทมนตร์ได้โดยอัตโนมัติ 1 ชนิดในอัตราที่กำหนดโดยไม่ต้องร่ายเวทย์ เวทมนตร์ที่ร่ายอัตโนมัตินี้จะใช้ค่า SP 2/3 จากค่า SP ที่ใช้ปกติ\nไม่สามารถเลือกทักษะที่ยังไม่ได้ศึกษา', '[Lv 1] : Napalm Beat เลเวล 3\n[Lv 2] : Cold Bolt, Fire Bolt, Lightning Bolt เลเวล 1\n[Lv 3] : Cold Bolt, Fire Bolt, Lightning Bolt เลเวล 2\n[Lv 4] : Cold Bolt, Fire Bolt, Lightning Bolt เลเวล 3\n[Lv 5] : Soul Strike เลเวล 1\n[Lv 6] : Soul Strike เลเวล 2\n[Lv 7] : Soul Strike เลเวล 3\n[Lv 8] : Fire Ball เลเวล 1\n[Lv 9] : Fire Ball เลเวล 2\n[Lv10] : Frost Diver เลเวล 1\nเลเวลของทักษะที่เลือกจะเป็นแบบสุ่ม'),
('SA_FLAMELAUNCHER', 'Flame Launcher', 5, 'สนับสนุน(Fire)', 'Requirement : Fire Bolt 1, Advanced Book 5\nเป้าหมาย : สมาชิกใน Party\nทำให้อาวุธเป็นธาตุไฟ โอกาสล้มเหลวจะขึ้นอยู่กับเลเวลของทักษะ และหากล้มเหลวอาวุธจะแตก\nทักษะนี้ใช้งานได้เมื่อมี 1 Red Blood', NULL),
('SA_FROSTWEAPON', 'Frost Weapon', 5, 'Active,Supportive', 'Requirement : Cold Bolt 1, Advanced Book 5\nเป้าหมาย : สมาชิกใน Party\nทำให้อาาวุธเป็นธาตุน้ำ โอกาสล้มเหลวจะขึ้นอยู่กับเลเวลของทักษะ และหากล้มเหลวอาวุธจะแตก\nทักษะนี้ใช้งานได้เมื่อมี 1 Crystal Blue', NULL),
('SA_LIGHTNINGLOADER', 'Lightning Loader', 5, 'Active,Supportive', 'Requirement : Lightning Bolt 1, Advanced Book 5\nเป้าหมาย : สมาชิกใน Party\nทำให้อาวุธเป็นธาตุลม โอกาสล้มเหลวจะขึ้นอยู่กับเลเวลของทักษะ และหากล้มเหลวอาวุธจะแตก\nทักษะนี้ใช้งานได้เมื่อมี 1 Wind of Verdure', NULL),
('SA_SEISMICWEAPON', 'Seismic Weapon', 5, 'Active,Supportive', 'Requirement : Stone Curse 1, Advanced Book 5\nเป้าหมาย : สมาชิกใน Party\nทำให้อาวุธเป็นธาตุดิน โอกาสล้มเหลวจะขึ้นอยู่กับเลเวลของทักษะ และหากล้มเหลวอาวุธจะแตก\nทักษะนี้ใช้งานได้เมื่อมี 1 Green Live', NULL),
('SA_DRAGONOLOGY', 'Dragonology', 5, 'Passive', 'Requirement : Advanced Book 9\nเพิ่มพลังโจมตี และเพิ่มความทนทานต่อมอนสเตอร์ Race Dragon โดยการศึกษาเกี่ยวกับมังกร', NULL),
('SA_VOLCANO', 'Volcano', 5, 'Supportive(Fire)', 'Requirement : Flame Launcher 2\nเป้าหมาย : พื้นที่\nเมื่อเข้ามาอยู่ในพื้นที่เป้าหมาย การโจมตีด้วยไฟจะรุนแรงขึ้น และค่า ATK ของทุกคนที่อยู่ในพื้นที่นั้นจะเพิ่มสูงขึ้น และใช้ Ice Wall บนพื้นที่นี้ไม่ได้ แต่ไม่สามารถใช้ทักษะอื่นๆ ของ Sage ที่ให้ผลบนพื้นที่ในพื้นที่เดียวกัน\nทักษะนี้ใช้งานได้เมื่อมี Yellow Gemstone', NULL),
('SA_DELUGE', 'Deluge', 5, 'Supportive', 'Requirement : Frost Weapon 2\nเป้าหมาย : พื้นที่\nเมื่อเข้ามาอยู่ในพื้นที่เป้าหมาย การโจมตีด้วยน้ำจะรุนแรงขึ้น และค่า Max HP ของทุกคนที่อยู่ในพื้นที่จะเพิ่มสูงขึ้น และบนพื้นที่นี้จะสามารถใช้ทักษะที่ใช้กับน้ำได้ด้วย(Water Ball, Aqua Benedicta)แต่ไม่สามารถใช้ทักษะอื่นๆ ของ Sage ที่ให้ผลบนพื้นที่ในพื้นที่เดียวกัน\nทักษะนี้ใช้งานได้เมื่อมี Yellow Gemstone', NULL),
('SA_VIOLENTGALE', 'Violent Gale', 5, 'Supportive', 'Requirement : Lightning Loader 2\nเป้าหมาย : พื้นที่\nเมื่อเข้ามาอยู่ในพื้นที่เป้าหมาย การโจมตีด้วยลมจะรุนแรงขึ้น และค่า Flee ของทุกคนที่อยู่ในพื้นที่จะเพิ่มสูงขึ้น และเมื่อใช้ Fire Wallบนพื้นที่นี้ ระยะเวลาของเวทย์นี้จะเป็น 1.5 เท่าจากปกติ แต่ไม่สามารถใช้ทักษะอื่นๆ ของ Sage ที่ให้ผลบนพื้นที่ในพื้นที่เดียวกัน\nทักษะนี้ใช้งานได้เมื่อมี Yellow Gemstone', NULL),
('SA_LANDPROTECTOR', 'Land Protector', 5, 'Active,Supportive', 'Requirement : Volcano 3, Deluge 3, Violent Gale 3\nเป้าหมาย : พื้นที่\nป้องกันเวทย์ที่ให้ผลบนพื้นที่ในพื้นที่นั้น ถ้ามีเวทย์รูปแบบนั้นร่ายลงบนพื้นที่เป้าหมาย เวทย์นั้นจะสลายไป แต่ไม่สามารถใช้ทักษะอื่นๆ ของ Sage ที่ให้ผลบนพื้นที่ในพื้นที่เดียวกัน\nทักษะนี้ใช้งานได้เมื่อมี 1 Yellow Gemstoneและ 1 Blue Gemstone', NULL),
('SA_DISPELL', 'Dispell', 5, 'Active,Supportive', 'Requirement : Spell Braker 3\nเป้าหมาย : ศัตรู\nสลายเวทย์จากศัตรูในอัตราที่กำหนด\nทักษะนี้ใช้งานได้เมื่อมี 1 Yellow Gemstone', NULL),
('SA_ABRACADABRA', 'Abracadabra', 10, '?', 'Requirement : Auto Spell 5, Dispell 1, Land Protector 1\nเป้าหมาย : ?\nใช้ทักษะด้วยการสุ่ม เลเวลของทักษะที่ได้จากการสุ่มจะขึ้นอยู่กับเลเวลของทักษะนี้\nทักษะนี้ใช้งานได้เมื่อมี 2 Yellow Gemstone', NULL),
('SA_MONOCELL', 'Mono Cell', NULL, 'Active,Offensive', 'เป้าหมาย : ศัตรู\nเสกให้เป้าหมายเป็น Poring ชั่วคราว\nหมายเหตุ : ใช้งานได้จากทักษะ Abracadabra เท่านั้น', NULL),
('SA_CLASSCHANGE', 'Class Change', NULL, 'Active,Offensive', 'เป้าหมาย : ศัตรู\nเสกให้เป้าหมายเป็น Boss มอนสเตอร์\nหมายเหตุ : ใช้งานได้จากทักษะ Abracadabra เท่านั้น', NULL),
('SA_SUMMONMONSTER', 'Summon Monster', NULL, 'Active,Offensive', 'เป้าหมาย : อัตโนมัติ\nให้ผลเช่นเดียวกับ Dead Branch\nหมายเหตุ : ใช้งานได้จากทักษะ Abracadabra เท่านั้น', NULL),
('SA_REVERSEORCISH', 'Reverse Orcish', NULL, 'Active,Offensive', 'เป้าหมาย : ผู้ใช้\nเสกให้หน้าของเป้าหมายเป็นหน้า Orc\nหมายเหตุ : ใช้งานได้จากทักษะ Abracadabra เท่านั้น', NULL),
('SA_DEATH', 'Death', NULL, 'Active,Offensive', 'เป้าหมาย : ศัตรู\nสังหารเป้าหมายทันที แต่จะไม่ได้รับ EXP และไอเท็มจากเป้าหมาย\nหมายเหตุ : ใช้งานได้จากทักษะ Abracadabra เท่านั้น', NULL),
('SA_FORTUNE', 'Fortune', NULL, 'Active,Offensive', 'เป้าหมาย : ศัตรู\nได้รับ Zeny โดยคำนวนจาก เลเวลของเป้าหมาย x 100\nหมายเหตุ : ใช้งานได้จากทักษะ Abracadabra เท่านั้น', NULL),
('SA_TAMINGMONSTER', 'Taming Monster', NULL, 'Active,Offensive', 'เป้าหมาย : ศัตรู\nถ้าเป้าหมายเป็นมอนสเตอร์ที่จับมาเลี้ยงได้ ก็จะจับได้\nหมายเหตุ : ใช้งานได้จากทักษะ Abracadabra เท่านั้น', NULL),
('SA_QUESTION', '?', NULL, 'Active,Offensive', 'เป้าหมาย : ศัตรู\nเป้าหมายจะแสดง ''?'' แค่นั้น\nหมายเหตุ : ใช้งานได้จากทักษะ Abracadabra เท่านั้น', NULL),
('SA_GRAVITY', 'Gravity', NULL, 'Active,Offensive', 'เป้าหมาย : ผู้ใช้\nผลที่เกิดจะแสดงขึ้นบนศีรษะเป็นสัญลักษณ์ GRAVITY Co., Ltd.\nหมายเหตุ : ใช้งานได้จากทักษะ Abracadabra เท่านั้น', NULL),
('SA_LEVELUP', 'Level Up', NULL, 'Active,Offensive', 'เป้าหมาย : ผู้ใช้\nเพิ่มเลเวลของตัวละคร\nหมายเหตุ : ใช้งานได้จากทักษะ Abracadabra เท่านั้น', NULL),
('SA_INSTANTDEATH', 'Instant Death', NULL, 'Active,Offensive', 'เป้าหมาย : ผู้ใช้\nหมดสติ ผลที่เกิดขึ้นจะเหมือนกับการตายทุกอย่างรวมถึงค่า EXP ที่ลดลงด้วย\nหมายเหตุ : ใช้งานได้จากทักษะ Abracadabra เท่านั้น', NULL),
('SA_FULLRECOVERY', 'Full Recovery', NULL, 'Active,Offensive', 'เป้าหมาย : ผู้ใช้\nฟื้นค่า HP และ SP, อาการติดพิษทุกอย่าง\nหมายเหตุ : ใช้งานได้จากทักษะ Abracadabra เท่านั้น', NULL),
('SA_COMA', 'Coma', NULL, 'Active,Offensive', 'เป้าหมาย : ผู้ใช้\nค่า HP และ SP จะเหลือ 1\nหมายเหตุ : ใช้งานได้จากทักษะ Abracadabra เท่านั้น', NULL),
('BD_ADAPTATION', 'Extemporaneousness', 1, 'Active,Supportive', 'หยุดเต้นและบรรเลงเพลง ไม่สามารถใช้กับทักษะ Encore', NULL),
('BD_ENCORE', 'Encore', 1, 'Active,Supportive', 'Requirement : Extemporaneousness 1\nเต้นและบรรเลงเพลงล่าสุด สามารถใช้ทักษะล่าสุดนั้นได้ด้วยการใช้ค่า SP เพียงครึ่งเดียวของการใช้ทักษะนั้นแบบปกติ', NULL),
('BD_LULLABY', 'Lullaby', 1, 'Ensemble Skill', 'Requirement : Whistle 10\nขอบเขต : 9 ช่องรอบตัวผู้ใช้\nในช่วงเวลาเกิดผล ศัตรูจะหลับชั่วขณะหนึ่ง ใช้ไม่ได้กับ Boss มอนสเตอร์', NULL),
('BD_RICHMANKIM', 'Rich Man Mr.Kim', 5, 'Ensemble Skill', 'Requirement : Invulnerable Siegfried 3\nขอบเขต : 9 ช่องรอบตัวผู้ใช้\nเมื่ออยู่ในบริเวณนี้จะได้รับค่า EXP จากมอนสเตอร์มากขึ้น ค่า EXP ที่ได้เพิ่มขึ้นจะขึ้นอยู่กับเลเวลของทักษะ', NULL),
('BD_ETERNALCHAOS', 'Eternal Chaos', 1, 'Ensemble Skill', 'Requirement : Loki''s Wail 1\nขอบเขต : 9 ช่องรอบตัวผู้ใช้\nค่า DEF ของผู้ที่อยู่ในขอบเขตจะเป็น 0 โดยจะส่งผลต่อ ศัตรูเท่านั้น ใน Guildwar ไม่ส่งผลต่อ Party เดียวกันใน PvP', NULL),
('BD_DRUMBATTLEFIELD', 'Drum Sound on Battlefield', 5, 'Ensemble Skill', 'Requirement : Idun''s Apple 10\nขอบเขต : 9 ช่องรอบตัวผู้ใช้\nค่า ATK และ DEF ของสมาชิกใน Party จะเพิ่มสูงขึ้นเมื่ออยู่ในขอบเขต', NULL),
('BD_RINGNIBELUNGEN', 'Ring of Nibelungen', 5, 'Ensemble Skill', 'Requirement : Drum Sound on Battlefield 3\nขอบเขต : 9 ช่องรอบตัวผู้ใช้\nเมื่ออยู่ในขอบเขตจะทำให้อาวุธ ของสมาชิกใน Party โจมตีได้รุนแรงขึ้น', NULL),
('BD_ROKISWEIL', 'Loki''s Wail', 1, 'Ensemble Skill', 'Requirement : Assassin Cross at Sunset 10\nขอบเขต : 9 ช่องรอบตัวผู้ใช้\nผู้ที่อยู่ในขอบเขตนี้จะไม่สามารถใช้ทักษะหรือเวทมนตร์ได้ แต่ไม่มีผลกับ Boss มอนสเตอร์', NULL),
('BD_INTOABYSS', 'Into The Abyss', 1, 'Ensemble Skill', 'Requirement : Lullaby 1\nขอบเขต : 9 ช่องรอบตัวผู้ใช้\nเมื่ออยู่ในขอบเขต สมาชิก Party สามารถใช้ทักษะได้โดยไม่ต้องใช้ตัวช่วยกระตุ้น (Gemstone) หรือกับดัก', NULL),
('BD_SIEGFRIED', 'Invulnerable Siegfried', 5, 'Ensemble Skill', 'Requirement : Bragi''s Poem 10\nขอบเขต : 9 ช่องรอบตัวผู้ใช้\nเมื่ออยู่ในขอบเขต สมาชิก Party จะทนทานต่อการโจมตีธาตุ และ สถานะผิดปรกติต่างๆ', '[Lv 1] : ทนทานต่อการโจมตีธาตุ 60% ทนทานต่อสถานะผิดปรกติ 10%\n[Lv 2] : ทนทานต่อการโจมตีธาตุ 65% ทนทานต่อสถานะผิดปรกติ 20%\n[Lv 3] : ทนทานต่อการโจมตีธาตุ 70% ทนทานต่อสถานะผิดปรกติ 30%\n[Lv 4] : ทนทานต่อการโจมตีธาตุ 75% ทนทานต่อสถานะผิดปรกติ 40%\n[Lv 5] : ทนทานต่อการโจมตีธาตุ 80% ทนทานต่อสถานะผิดปรกติ 50%'),
('BD_RAGNAROK', '', NULL, NULL, NULL, NULL),
('BA_MUSICALLESSON', 'Musical Lesson', 10, 'Passive', 'เพิ่มพลังโจมตีเมื่อใช้เครื่องดนตรี และเพิ่มประสิทธิภาพให้กับทักษะดนตรี เล่นดนตรี', '[Lv 1] : ATK +3\n[Lv 2] : ATK +6\n[Lv 3] : ATK +9\n[Lv 4] : ATK +12\n[Lv 5] : ATK +15\n[Lv 6] : ATK +18\n[Lv 7] : ATK +21\n[Lv 8] : ATK +24\n[Lv 9] : ATK +27\n[Lv 10] : ATK +30'),
('BA_MUSICALSTRIKE', 'Musical Strike', 5, 'Active,Offensive', 'Requirement : Musical Lesson 3\nเป้าหมาย : ศัตรู\nยิงลูกธนูที่แข็งแกร่งด้วยเครื่องดนตรี สามารถใช้ได้ในระหว่างใช้ทักษะเล่นดนตรี\nทักษะนี้ใช้งานได้ในขณะที่ใช้เครื่องดนตรีเท่านั้น คุณสมบัติในการโจมตีจะขึ้นอยู่กับชนิดของลูกธนู', NULL),
('BA_DISSONANCE', 'Dissonance', 5, 'Active,Offensive', 'Requirement : Extemporaneousness 1, Musical Lesson 1\nขอบเขต : 7 ช่องรอบตัวผู้ใช้\nเมื่ออยู่ในขอบเขต มอนสเตอร์จะบาดเจ็บตามอัตราที่กำหนดในทุกช่วงเวลาที่กำหนด เป็นเวลา 30 วินาที', NULL),
('BA_FROSTJOKE', 'Frost Joker', 5, 'Offensive', 'Requirement : Encore 1\nขอบเขต : ทั้งหน้าจอ\nศัตรูที่ปรากฎตัวอยู่ในหน้าจอจะถูกแช่แข็ง อัตราการแช่แข็งจะขึ้นอยู่กับเลเวลของทักษะ สมาชิก Party จะได้รับผลในอัตราต่ำ', NULL),
('BA_WHISTLE', 'Whistle', 10, 'Active,Supportive', 'Requirement : Dissonance 3\nขอบเขต : 9 ช่องรอบตัวผู้ใช้\nเพิ่มค่า Flee และ Perfect Dodge ของผู้เล่นและอัตราการหลบหลีกจะสมบูรณ์เมื่ออยู่ในขอบเขตนี้ เป็นเวลา 60 วินาที', NULL),
('BA_ASSASSINCROSS', 'Assassin Cross at Sunset', 10, 'Active,Supportive', 'Requirement : Dissonance 3\nขอบเขต : 9 ช่องรอบตัวผู้ใช้\nเพิ่มความเร็วในการโจมตีของผู้เล่นเมื่ออยู่ในขอบเขต แต่จะไม่มีผลกับผู้เล่นที่ใช้ทักษะ Two Hand Quicken และ Adrenalin หรือโจมตีระยะไกล', NULL),
('BA_POEMBRAGI', 'Bragi''s Poem', 10, 'Active,Supportive', 'Requirement : Dissonance 3\nขอบเขต : 9 ช่องรอบตัวผู้ใช้\nเมื่ออยู่ในขอบเขตนี้ จะลดระยะเวลาในการร่ายเวทย์ของผู้เล่น และทำให้เวทย์มีผลนานขึ้น', NULL),
('BA_APPLEIDUN', 'Idun''s Apple', 10, 'Active,Supportive', 'Requirement : Dissonance 3\nขอบเขต : 7x7 ช่องรอบตัวผู้ใช้\nเพิ่มค่า MaxHP และฟื้นค่า HP ให้แก่ผู้เล่นที่เป็นมิตรในอัตราและช่วงเวลาที่กำหนด เมื่ออยู่ในขอบเขตนี้', NULL),
('DC_DANCINGLESSON', 'Dancing Lesson', 10, 'Passive', 'เพิ่มพลังโจมตีเมื่อใช้ Whip และเพิ่มประสิทธิภาพให้กับทักษะเล่นดนตรี ทักษะเต้น', '[Lv 1] : ATK +3\n[Lv 2] : ATK +6\n[Lv 3] : ATK +9\n[Lv 4] : ATK +12\n[Lv 5] : ATK +15\n[Lv 6] : ATK +18\n[Lv 7] : ATK +21\n[Lv 8] : ATK +24\n[Lv 9] : ATK +27\n[Lv 10] : ATK +30'),
('DC_THROWARROW', 'Dart Arrow', 5, 'Active,Offensive', 'Requirement : Dancing Lesson 3\nเป้าหมาย : ศัตรู\nรวมพลังไว้ที่ลูกธนูและแขว้งด้วยแส้(Whip) สามารถใช้ได้ในระหว่างใช้ทักษะเล่นดนตรี\nทักษะนี้ใช้งานได้ในขณะที่ใช้แส้เท่านั้น คุณสมบัติในการโจมตีจะขึ้นอยู่กับชนิดของลูกธนู', NULL),
('DC_UGLYDANCE', 'Ugly Dance', 5, 'Active,Offensive', 'Requirement : Extemporaneousness 1, Dancing Lesson 1\nขอบเขต : 7x7 ช่องรอบตัวผู้ใช้\nสร้างความเสียหายให้แก่ค่า SP ของศัตรูในช่วงเวลาที่กำหนดเมื่ออยู่ในขอบเขต', NULL),
('DC_SCREAM', 'Scream', 5, 'Active,Offensive', 'Requirement : Encore 1\nขอบเขต : 9 ช่องรอบตัวผู้ใช้\nศัตรูทั้งหมดที่อยู่ในหน้าจอจะมึนงง(Stun) โอกาสในการทำให้ศัตรูมึนงงจะขึ้นอยู่กับเลเวลของทักษะ สมาชิกใน Party มีโอกาสถูกทำให้มึนงงในอัตราต่ำ', NULL),
('DC_HUMMING', 'Humming', 10, 'Active,Supportive', 'Requirement : Ugly Dance 3\nขอบเขต : 7x7 ช่องรอบตัวผู้ใช้\nเพิ่มความแม่นยำของผู้เล่นเมื่ออยู่ในขอบเขต', NULL),
('DC_DONTFORGETME', 'Don''t Forget Me', 10, 'Active,Supportive', 'Requirement : Ugly Dance 3\nขอบเขต : 7x7 ช่องรอบตัวผู้ใช้\nทำให้ศัตรูเคลื่อนที่และโจมตีช้าลงเมื่ออยู่ในขอบเขต แต่ถ้าพวกเขาอยู่ในสภาวะการเคลื่อนที่เร็วและโจมตีเร็ว สภาวะเหล่านั้นจะหายไป', NULL),
('DC_FORTUNEKISS', 'Kiss of Fortune', 10, 'Active,Supportive', 'Requirement : Ugly Dance 3\nขอบเขต : 7x7 ช่องรอบตัวผู้ใช้\nเพิ่มอัตราการโจมตีสูงสุด(Critical) ของผู้เล่นเมื่ออยู่ในขอบเขต', NULL),
('DC_SERVICEFORYOU', 'Service For You', 10, 'Active,Supportive', 'Requirement : Ugly Dance 3\nขอบเขต : 7x7 ช่องรอบตัวผู้ใช้\nเพิ่มค่า MaxSP ของผู้เล่นที่เป็นมิตรและลดการใช้พลัง SP ของพวกเขาเมื่ออยู่ในขอบเขตนี้', NULL),
('KN_CHARGEATK', 'Charge Attack', NULL, 'Offensive', 'Requirement : Complete quest\nTarget : Enemy\nพุ่งเข้าโจมตีศัตรูจากระยะไกลแต่จะใช้เวลาเล็กน้อยก่อนเริ่มโจมตี\nระยะทางมีผลต่อความรุนแรง แต่จะทำให้ใช้เวลาก่อนโจมตีนานขึ้น', NULL),
('CR_SHRINK', 'Shrink', NULL, 'Assist', 'Requirement : Complete quest\nเมื่อใช้สกิล auto-guard มีโอกาสทำให้ผู้เล่นกระเด็นออกไป 2 ช่อง เมื่อทำการโจมตี ระยะเวลา 5 นาที ถ้ากดใช้ซ้ำจะเป็นการยกเลิกสกิล\nสกิล auto-guard เลเวล 1 มีโอกาส 5% และทุกๆ เลเวลสกิลจะเพิ่มขึ้น 5% จนถึงเลเวล 10 มีโอกาสสูงสุด 50% ที่จะทำให้ศัตรูกระเด็นออกไป', NULL),
('AS_SONICACCEL', 'Sonic Acceleration', NULL, 'Passive', 'Requirement : Complete quest\nเพิ่มความแม่นยำของสกิล Sonic Blow 50%, และเพิ่มความรุนแรง 10%', NULL),
('AS_VENOMKNIFE', 'Venom Knife', NULL, 'Attack', 'Requirement : Complete quest\nTarget : Enemy\nสามารถใช้ได้เมื่อถือ ''Venom Knife'' เท่านั้น\nขว้าง 1 ''Venom Knife'' ไปยังศัตรู มีโอกาสสูงที่ทำให้ศัตรูติดพิษ', NULL),
('RG_CLOSECONFINE', 'Close Confine', NULL, 'Attack', 'Requirement : Complete quest\nTarget : Enemy\nหยุดศัตรูเป็นเวลา 15 วินาที โดยที่ทั้งคู่จะไม่สามารถเคลื่อนที่ได้', NULL),
('WZ_SIGHTBLASTER', 'Sight Blaster', NULL, 'Attack', 'Requirement : Complete quest\nTarget : Yourself\nเรียกลูกไฟมาปกป้องผู้ร่ายเป็นเวลา 2 นาที\nถ้าถูกโจมตีด้วยเวทมนตร์ ผู้ทำการโจมตีจะได้รับความเสียหายเช่นกันและถูกทำให้กระเด็น โดยที่ลูกไฟจะหายไปเมื่อถูกโจมตี\nใน Guild War ผู้เล่นจะไม่ถูกทำให้กระเด็น', NULL),
('SA_CREATECON', 'Create Elemental Converter', NULL, 'Assist', 'Requirement : Complete quest\nสร้างไอเท็ม ''Converter'' ธาตุไฟ, ธาตุดิน, ธาตุลม หรือธาตุน้ำ\nFire-Elemental Converter: 3 Scorpion Tail + 1 Empty Scroll\nEarth-Elemental Converter: 3 Horn + 1 Empty Scroll\nWind-Elemental Converter: 3 Rainbow Shell + 1 Empty Scroll\nWater-Elemental Converter: 3 Snail''s Shell + 1 Empty Scroll', NULL),
('HT_PHANTASMIC', 'Phantasmic Arrow', NULL, 'Attack', 'Requirement : Complete quest\nTarget : Enemy\nโจมตีศัตรูด้วยลูกธนูลวงตา แม้ว่าจะไม่สวมใส่ลูกธนูก็สามารถใช้ได้\nพลังโจมตี 150% เมื่อโจมตีโดนศัตรูจะกระเด็นออกไป 3 ช่อง', NULL),
('BA_PANGVOICE', 'Pang Voice', NULL, 'Attack', 'Requirement : Complete quest\nTarget : Enemy\nตะโกนใส่ศัตรู ทำให้ติดสถานะ Chaos ไม่สามารถใช้กับมอนเตอร์ประเภท Boss ได้', NULL),
('DC_WINKCHARM', 'Wink of Charm', NULL, 'Assist', 'Requirement : Complete quest\nTarget : Enemy\nหว่านเสนห์ให้กับศัตรู ทำให้ไม่สามารถโจมตีได้ 10 วินาที\nเลเวลของตัวละครมากกว่ามอนเตอร์จะส่งผลต่อโอกาสในการติดสถานะ Chaos แต่ถ้าใช้กับผู้เล่นโอกาสจะลดลง\nใช้ได้กับมอนเตอร์ประเภท Demi-humans, Angels, และ Demon เท่านั้น ไม่สามารถใช้กับมอนเตอร์ประเภท Boss ได้', NULL),
('BS_UNFAIRLYTRICK', 'Unfair Trick', NULL, 'Passive', 'Requirement : Complete quest\nลด Zeny ที่เสียในการใช้สกิล Mammonite 10%', NULL),
('PR_REDEMPTIO', 'Redemptio', NULL, 'Assist', 'Requirement : Complete quest\nTarget : All Party Members\nยอมตายเพื่อชุบเพื่อนในปาร์ตี้ที่ตายทั้งหมดในระยะหน้าจอขึ้นมา ผู้ที่ถูกชุบจะได้รับ HP 50%\nยิ่งชุบเพื่อนได้มาก ค่า EXP ที่เสียก็จะน้อยลง\nจะไม่สามารถใช้สกิลนี้ได้หาก EXP น้อยกว่า 1%', NULL),
('MO_BALKYOUNG', 'Ki Explosion', NULL, 'Attack', 'Requirement : Complete quest\nTarget : Enemy\nรวบรวมพลังไว้ที่ฝ่ามือแล้วทำการโจมตีศัตรูใกล้ๆ ตัว\nสร้างความเสียหาย 300% damage มอนเตอร์ที่อยู่ใกล้จะถูกทำให้ถอยห่างออกไป 2 ช่องและ Stun 2 วินาที ใช้ HP เล็กน้อยในการร่าย', NULL),
('BS_GREED', 'Greed', NULL, 'Assist', 'Requirement : Complete quest\nTarget : รอบเป้าหมายระยะ 2 ช่อง\nเมื่อใช้สกิลนี้แล้ว ไอเทมรอบๆ ตัวในระยะ 2 ช่องจะถูกเก็บไปยัง inventory โดยอัติโนมัติ\nไม่สามารถใช้ในเมือง, Guild War หรือ PvP ได้', NULL),
('MO_KITRANSLATION', 'Ki Translation', NULL, 'Assist', 'Requirement : Complete quest\nTarget : One Party Member\nถ่ายโอน 1 Spirit Sphere ให้กับเพื่อนในปาร์ตี้', NULL),
('SA_ELEMENTGROUND', 'Elemental Change (Earth)', NULL, 'Attack', 'Requirement : Complete quest\nTarget : Enemy\nเปลี่ยนธาตุมอนเตอร์เป้าหมายเป็นธาตุดิน', NULL),
('SA_ELEMENTFIRE', 'Elemental Change (Fire)', NULL, 'Attack', 'Requirement : Complete quest\nTarget : Enemy\nเปลี่ยนธาตุมอนเตอร์เป้าหมายเป็นธาตุไฟ', NULL),
('SA_ELEMENTWIND', 'Elemental Change (Wind)', NULL, 'Attack', 'Requirement : Complete quest\nTarget : Enemy\nเปลี่ยนธาตุมอนเตอร์เป้าหมายเป็นธาตุลม', NULL),
('SA_ELEMENTWATER', 'Elemental Change (Water)', NULL, 'Attack', 'Requirement : Complete quest\nTarget : Enemy\nเปลี่ยนธาตุมอนเตอร์เป้าหมายเป็นธาตุน้ำ', NULL),
('HT_POWER', 'Beast Strafing', NULL, 'Attack', 'Requirement : Double Strafe 10, Soul status\nTarget : Enemy\nโจมตีด้วย Double strafing เมื่อเป้าหมายเป็น Brute class\nความเสียหายขึ้นอยู่กับค่า STR', NULL),
('KN_ONEHAND', 'Sword Quicken', NULL, 'Supportive', 'Requirement : Two Hand Quicken 10, Soul status\nเพิ่มความเร็วในการโจมตีเมื่อใช้ One-Hand Sword\nASPD จะเพิ่มเฉพาะเวลาที่ใช้ One-Hand Sword,\nเมื่อถอดอาวุธออกผลของสกิลจะหายไป\nสถานะของ ASPD potion จะถูกยกเลิกเมื่อใช้สกิลนี้\nแต่จะสามารถใช้ potion ใหม่ได้', NULL),
('AM_TWILIGHT1', 'Twilight Pharmacy', NULL, 'Supportive', 'Requirement : Pharmacy 10, Soul status\nใช้ SP 200 ทำให้สามารถสร้าง White Potion ได้ 200 ขวด ในอัตราเร็ว 0.005 วินาทีต่อขวด\nสกิลนี้ไม่สามารถใช้ได้ในกรณีที่ส่วนผสมไม่พอสำหรับสร้าง White Potion 200 ขวด\nโอกาสในการผสมสำเร็จขึ้นกับสกิล Pharmacy แต่ไม่ขึ้นกับค่า DEX ใช้เวลาในการร่าย 3 วินาที\nโปรดระวังในกรณีที่ถือ White Potion เกินกว่า 200 ขวด มีโอกาสที่ขั้นตอนการผสมจะล้มเหลว', NULL),
('AM_TWILIGHT2', 'Twilight Pharmacy', NULL, 'Supportive', 'Requirement : Pharmacy 10, Soul status\nSkill นี้ใช้เรียก guardian angel ของ Super Novice\nใช้ SP 200 ทำให้สามารถสร้าง White Potion ได้ 200 ขวด ในอัตราเร็ว 0.005 วินาทีต่อขวด\nสกิลนี้ไม่สามารถใช้ได้ในกรณีที่ส่วนผสมไม่พอสำหรับสร้าง White Potion 200 ขวด\nโอกาสในการผสมสำเร็จขึ้นกับสกิล Pharmacy แต่ไม่ขึ้นกับค่า DEX ใช้เวลาในการร่าย 3 วินาที\nมีโอกาสที่ Ranking จะขึ้นดีกว่าปกติ.', NULL),
('AM_TWILIGHT3', 'Twilight Pharmacy', NULL, 'Supportive', 'Requirement : Pharmacy 10, Soul status\nSkill that is obtained from the guardian angel of taekwon ประเภท\nใช้ SP 200 ทำให้สามารถสร้าง Alcolhol ได้ 100,  Fire Bottle 50 และ Acid Bottle 50\nจำเป็นจะต้องมีส่วนผสมเพียงพอสำหรับสร้าง Alcolhol 100,  Acid bottle 50 และ\nTransparent Cloth 50 + Empty Bottle 50 จึงจะสามารถใช้สกิลนี้ได้', NULL),
('BS_ADRENALINE2', 'Adrenaline All', NULL, 'Supportive', 'Requirement : Adrenaline Rush 5, Soul status\nอาวุธทุกประเภทจะได้รับผลของสกิล Anderline Rush ยกเว้นจาก Bows\nไม่สามารถใช้ได้กับสกิลที่มีผลแบบเดียวกัีน\nอย่างเช่น Adrenaline Rush, One Hand Quicken, Two Hand Quicken, Spear Quicken, Impressive Riff,\nระยะเวลา : 150 วินาที,  ใช้ SP : 64', NULL),
('LK_AURABLADE', 'Aura Blade', 5, 'Support', 'Requirement : Bash 5, Magnum Brake 5, Two Hand Sword Mastery 5\nเพิ่มพลัง Aura ให้กับอาวุธ ทำให้อาวุธมีพลังโจมตีสูงขึ้น\nโดยไม่คิดค่าความแม่นยำของผู้ใช้ (Accuracy) และยังมอบความเสียหายให้แก่เป้าหมาย', '[Lv 1] : Damage +20\n[Lv 2] : Damage +40\n[Lv 3] : Damage +60\n[Lv 4] : Damage +80\n[Lv 5] : Damage +100'),
('LK_PARRYING', 'Parry', 10, 'Support', 'Requirement : Provoke 5, Two Hand Sword Mastery 10, Two Hand Quicken 3\nBlock การโจมตีของศัตรูด้วย Two Handed Sword. เมื่อเกิดผล, ผู้ใช้จะไม่ได้รับผลจากการโจมตีครั้งนั้น\nใช้กับ  Two Handed sword.', '[Lv 1] : Block Chance +23%\n[Lv 2] : Block Chance +26%\n[Lv 3] : Block Chance +29%\n[Lv 4] : Block Chance +32%\n[Lv 5] : Block Chance +35%\n[Lv 6] : Block Chance +38%\n[Lv 7] : Block Chance +41%\n[Lv 8] : Block Chance +44%\n[Lv 9] : Block Chance +47%\n[Lv10] : Block Chance +50%'),
('LK_CONCENTRATION', 'Spear Dynamo', 5, 'Support', 'Requirement : Increase HP Recovery 5, Spear mastery 5, Pecopeco Riding 1\nเมื่อใช้ Skill นี้จะเพิ่ม Hit พลังโจมตี และให้ผลของ Endure ในเวลาเดียวกัน แต่ในระหว่างใช้ Def ของผู้ใช้จะลดลง', '[Lv 1] : Hit +10%, ATK +5%, DEF -5%\n[Lv 2] : Hit +20%, ATK +10%, DEF -10%\n[Lv 3] : Hit +30%, ATK +15%, DEF -15%\n[Lv 4] : Hit +40%, ATK +20%, DEF -20%\n[Lv 5] : Hit +50%, ATK +25%, DEF -25%'),
('LK_TENSIONRELAX', 'Relax', 1, 'Support', 'Requirement : Provoke 5, Increase HP recovery 10, Endure 3\nเพิ่มอัตราการฟื้นคืน Hp เร็วขึ้นในขณะที่นั่ง\nเมื่อยืนขึ้น ใช้ Item หรือ Skill ผลของ Skill นี้จะถูกยกเลิก', NULL),
('LK_BERSERK', 'Frenzy', 1, 'Supportive', 'Requirement : Lord Knight Job Level มากกว่า 50\nเพิ่ม max  HP, ความเร็วในการเคลื่อนที่ พลังโจมตี  แต่ Skill นี้จะลดค่า Flee และพลังป้องกัน.\nแต่ผู้ใช้ Skill นี้จะทำได้แค่เคลื่อนไหวและโจมตีเท่านั้น ไม่สามารถใช้ Skill หรือรับการฟื้นพลังใดๆ ทั้งจาก Skill และ Item เมื่อเข้าอยู่ในสถานะ Frenzy เลือดจะลดลงเรื่อยๆ\nเมื่อใช้ Skill นี้ HP/SP จะไม่ฟื้นคืนตามธรรมชาติ เป็นเวลา 5 นาที หลังจากหมดผลของสกิล', NULL),
('LK_SPIRALPIERCE', 'Clashing Spiral', 5, 'Offensive', 'Requirement : Spear Mastery 5, Pierce 5, Peco Peco Riding 1, Spear Stab 5\nโจมตีด้วยอาวุธหลายครั้งไปที่ศัตรู\nเลเวลของสกิล และ น้ำหนักของอาวุธ ส่งผลต่อพลังโจมตี\nถ้าโจมตีโดน ศัตรูจะหยุดนิ่ง 1 วินาที ใช้ได้เมื่อสวมใส่ spear, one hand sword, หรือ two hand sword เท่านั้น', NULL),
('LK_HEADCRUSH', 'Traumatic Blow', 5, 'Active', 'Requirement : Spear Mastery 9, Peco Peco Riding 1\nโจมตี Monster และส่งผลให้ศัตรูเลือดไหลไม่หยุด เมื่อโดนโจมตีด้วยท่านี้และติดผลอาการเลือดไหลไม่หยุด ศัตรูจะเสียพลังไปเรื่อยๆ เป็นระยะเวลาหนึ่ง', '[Lv 1] : ATK 140%\n[Lv 2] : ATK 180%\n[Lv 3] : ATK 220%\n[Lv 4] : ATK 260%\n[Lv 5] : ATK 300%'),
('LK_JOINTBEAT', 'Vital Strike', 10, 'Offensive', 'Requirement : Spear Mastery 9, Peco Peco Riding 1, Cavalier Mastery 3, Traumatic Blow 3\nต้องใช้ อาวุธประเภท Spear โจมตีจุดอ่อนของศัตรู ทำให้เกิดสถานะผิดปรกติ\nLevel Skill ที่เพิ่มขึ้นจะเพิ่มพลังโจมตีและอัตราสำเร็จของการเกิดสถานะผิดปรกติ', '[Lv 1] : ATK 60%\n[Lv 2] : ATK 70%\n[Lv 3] : ATK 80%\n[Lv 4] : ATK 90%\n[Lv 5] : ATK 100%\n[Lv 6] : ATK 110%\n[Lv 7] : ATK 120%\n[Lv 8] : ATK 130%\n[Lv 9] : ATK 140%\n[Lv10] : ATK 150%'),
('HP_ASSUMPTIO', 'Assumption', 5, 'Support', 'Requirement : Angellus 1, Increase SP Recovery 3, Impositio Manus 3\nลด Damage ที่ได้จากศัตรู เพิ่มพลังป้องกันให้แก่เป้าหมาย 100%\nไม่สามารถใช้ร่วมกับ  Kyrie Eleison ได้, ในเขต PvP และ Guild war Zone Damage พลังป้องกันจะเพิ่มขึ้นเพียง 35% เท่านั้น', '[Lv 1] : ระยะเวลา 20 วินาที\n[Lv 2] : ระยะเวลา 40 วินาที\n[Lv 3] : ระยะเวลา 60 วินาที\n[Lv 4] : ระยะเวลา 80 วินาที\n[Lv 5] : ระยะเวลา 100 วินาที'),
('HP_BASILICA', 'Basilica', 5, 'Support', 'Requirement : Gloria 2, Increase SP Recovery 1, Kyrie Eleison 3\nป้องกันการโจมตีทั้งหมดที่มีเข้ามาใน อาณาเขตของ Skill นี้ รวมทั้งการโจมตีทั้งหมดภายในอาณาเขตของ Skill นี้\nต้องการ 1 Blue Gemstone, 1 Yellow Gemstone, 1 Red Gemstone and 1 Holy Water.\nไม่สามารถใช้กับ Monster ระดับ Boss ได้ ไม่สามารถใช้ใน Guildwar ได้ ถ้ามีสิ่งกีดขวางในระยะการใช้ Skill จะไม่สามารถใช้ Skill นี้ได้', '[Lv 1] : 20 Sec Duration\n[Lv 2] : 25 Sec Duration\n[Lv 3] : 30 Sec Duration\n[Lv 4] : 35 Sec Duration\n[Lv 5] : 40 Sec Duration'),
('HP_MEDITATIO', 'Meditation', 10, 'Passive', 'Requirement : Increase SP Recovery 5, Lex Divina 5, Aspersio 3\nเพิ่มอัตราการฟื้น SP และ max SP\nและเพิ่มความสามารถของ Skill heal', '[Lv 1] : Maximum SP +1%, SP Recovery + 3%\n[Lv 2] : Maximum SP +2%, SP Recovery  + 6%\n[Lv 3] : Maximum SP +3%, SP Recovery  + 9%\n[Lv 4] : Maximum SP +4%, SP Recovery + 12%\n[Lv 5] : Maximum SP +5%, SP Recovery + 15%\n[Lv 6] : Maximum SP +6%, SP Recovery  + 18%\n[Lv 7] : Maximum SP +7%, SP Recovery  + 21%\n[Lv 8] : Maximum SP +8%, SP Recovery + 24%\n[Lv 9] : Maximum SP +9%, SP Recovery + 27%\n[Lv10] : Maximum SP +10%, SP Recovery + 30%'),
('HP_MANARECHARGE', 'Optimize Mana', 5, NULL, 'Requirement : Mace Mastery 10, Demon Bane 10\nลดค่า SP ในการใช้ skill', '[Lv 1] : 4%\n[Lv 2] : 8%\n[Lv 3] : 12%\n[Lv 4] : 16%\n[Lv 5] : 20%'),
('HW_MAGICCRASHER', 'Stave Crasher', 1, 'Active', 'Requirement : Increase SP Recovery 1\nสร้าง Damage แบบไร้ธาตุแก่ศัตรู 1 คน Damage ที่ได้นั้นจะคิดจาก Defense ของศัตรูและ Magic Attack ของผู้ใช้', NULL),
('HW_MAGICPOWER', 'Mystical Amplification', 10, 'Support', 'เพิ่มพลังโจมตีเวทย์ให้กับผู้ใช้เป็นระยะเวลาหนึ่ง', '[Level 1] : MATK + 5%\n[Level 2] : MATK +10%\n[Level 3] : MATK +15%\n[Level 4] : MATK +20%\n[Level 5] : MATK +25%\n[Level 6] : MATK +30%\n[Level 7] : MATK +35%\n[Level 8] : MATK +40%\n[Level 9] : MATK +45%\n[Level 10] : MATK +50%'),
('HW_GANBANTEIN', 'Ganbantein', 1, NULL, 'Requirement : Sense 1, Ice Wall 1\nยกเลิก ground magic รอบพื้นที่ 3*3 จากจุดที่ใช้\nใช้ 1 Blue Gemstone และ 1 Yellow Gemstone สำหรับการร่าย\nถ้าใช้สกิลนี้บนพื้นที่ Magnetic Earth จะส่งผลให้พื้นที่ 3*3 รอบจุดที่ใช้ถูกยกเลิกผลของ Magnetic Earth\nไอเท็มและสกิลต่างๆ ที่ช่วยลดการใช้ Gem Stone ไม่มีผลต่อสกิลนี้\ndelay 2 วินาที', NULL),
('HW_GRAVITATION', 'Gravitational Field', 5, NULL, 'Requirement : Quagmire 1, Stave Crasher 1, Mystical Amplification 10\nใช้ 1 Blue Gemstone เพื่อเพิ่มแรงโน้มถ่วงในพื้นที่ 5*5 รอบจุดที่ใช้\nทุกๆ วินาที ศัตรูที่อยู่ในพื้นที่จะได้รับความเสียหายแบบไม่คิดค่าพลังป้องกัน\nขณะร่ายจะไม่สามารถขยับได้ สกิลนี้ยังส่งผลให้การเคลื่อนที่และความเร็วในการโจมตีของเป้าหมายลดลง\nและสามารถสร้างความเสียหายกับ Boss ได้แต่ไม่ส่งผลให้ Boss เคลื่อนที่และโจมตีช้าลง\ndelay 2 วินาที', '[Lv 1] : 600 Damage/0.5 วินาที, Speed -5%, ระยะเวลา 5 วินาที\n[Lv 2] : 700 Damage/0.5 วินาที, Speed -10%, ระยะเวลา 6 วินาที\n[Lv 3] : 800 Damage/0.5 วินาที, Speed -15%, ระยะเวลา 7 วินาที\n[Lv 4] : 900 Damage/0.5 วินาที, Speed -20%, ระยะเวลา 8 วินาที\n[Lv 5] : 1000 Damage/0.5 วินาที, Speed -25%, ระยะเวลา 9 วินาที'),
('HW_NAPALMVULCAN', 'Napalm Vulcan', 5, 'Active(Psychokinesis)', 'Requirement : Napalm Beat 5\nเป้าหมาย : ศัตรู\nโจมตีไปที่ศัตรูในระยะไกลเป็นจำนวนหลายครั้ง ศัตรูมีโอกาสติด Curse\nLevel Skill ที่เพิ่มขึ้นจะทำให้จำนวนครั้งของการโจมตีมากขึ้น', NULL),
('HW_SOULDRAIN', 'Soul Drain', 10, 'Passive', 'Requirement : Increase SP Recovery 5, Soul Strike 7\nเพิ่ม max SP และเพิ่ม Sp ในทุกครั้งที่กำจัดศัตรู ปริมาณ SP ที่ได้จากการกำจัดศัตรูขึ้นอยู่กับ Level ของศัตรู', '[Lv 1] : MAXSP +2%\n[Lv 2] : MAXSP +4%\n[Lv 3] : MAXSP +6%\n[Lv 4] : MAXSP +8%\n[Lv 5] : MAXSP +10%\n[Lv 6] : MAXSP +12%\n[Lv 7] : MAXSP +14%\n[Lv 8] : MAXSP +16%\n[Lv 9] : MAXSP +18%\n[Lv10] : MAXSP +20%'),
('PA_PRESSURE', 'Gloria Domini', 5, 'Offensive', 'Requirement : Endure 5, Faith 5, Shield Charge 2\nเรียกกางเขนขนาดยักษ์มาจู่โจมศัตรู\nพลังโจมตีของท่านี้ไม่ได้คิดจากพลังป้องกันหรือพลังโจมตี แต่มีพลังรุนแรงและคงที่ตาม Skill Level,Skill นี้ไม่อาจถูกยกเลิกหรือขัดขวางได้ ไม่ว่าวิธีใด ผู้ที่โดนท่านี้จะเสีย Sp บางส่วน', '[Lv 1] : Damage 800\n[Lv 2] : Damage 1100\n[Lv 3] : Damage 1400\n[Lv 4] : Damage 1700\n[Lv 5] : Damage 2000'),
('PA_SACRIFICE', 'Martyr''s Reckoning', 5, 'Active', 'Requirement : Endure 1, Devotion 3\nสละ HP ของผู้ใช้เพื่อสร้างความเสียหายอย่างรุนแรง โดยจะใช้ 9% ของ Max HP\nสามารถโจมตีได้ 5 ครั้งหลังจากใช้ Skill', '[Lv 1] : Damage*1\n[Lv 2] : Damage*1.1\n[Lv 3] : Damage*1.2\n[Lv 4] : Damage*1.3\n[Lv 5] : Damage*1.4'),
('PA_GOSPEL', 'Battle Chant', 10, 'Support', 'Requirement : Faith 8, Divine Protection 3, Demon Bane 5\nRange : 7 ช่อง around the caster\nท่วงทำนองที่จะนำผลทางด้านลบสู่ศัตรูนำผลทางด้านบวกสู่พวกพ้อง\nมีผลต่อทุกคนในระยะของ Skill\nผลของสกิลจะถูกยกเลิกหากผู้ใช้ไม่สามารถร่ายสกิล Battle Chant ได้', NULL),
('CH_PALMSTRIKE', 'Raging Palm Strike', 5, 'Active', 'Requirement : Iron Hand 7, Absorption 5\nโจมตีศัตรูโดยใช้ฝ่ามือ มี Delay 1 วินาทีก่อนที่ Skill จะเกิด Damage ขึ้น เมื่อใช้งาน จะผลักศัตรูออกไปด้านหลัง\nใช้ได้ในสถานะ Vigor Explosion เท่านั้น', '[Lv 1] : ATK 300%\n[Lv 2] : ATK 400%\n[Lv 3] : ATK 500%\n[Lv 4] : ATK 600%\n[Lv 5] : ATK 700%'),
('CH_TIGERFIST', 'Glacier Fist', 5, 'Active', 'Requirement : Iron Hand 5, Triple Attack 5, Combo Finish 3\nCombo ที่ใช้ได้ หลังจากท่า Combo Finish\nศัตรูที่โดนโจมตีจะหยุดนิ่งเป็นระยะเวลาหนึ่ง\nต้องการ 1 Spirit Spheres', '[Lv 1] : ATK +140%, Freezing Chance 20%\n[Lv 2] : ATK +240%, Freezing Chance 30%\n[Lv 3] : ATK +340%, Freezing Chance 40%\n[Lv 4] : ATK +440%, Freezing Chance 50%\n[Lv 5] : ATK +540%, Freezing Chance 60%'),
('CH_CHAINCRUSH', 'Chain Crush Combo', 10, 'Offensive', 'Requirement : Iron Hand 5, Absorption 5, Glacier Fist 2\nCombo ที่จะใช้ได้หลังจากท่า Glacier Fist.\nใช้ 2 Spirit Spheres เพื่อเพิ่มพลังโจมตี, หลังจากใช้ท่านี้ สามารถใช้ท่า Asura Strike ต่อได้\nแต่ถ้าใช้  Asura Strike แล้ว , จะไม่สามารถใช้ Chain Crush Combo หรือ Glacier Fist ได้', '[Lv 1] : ATK +500%\n[Lv 2] : ATK +600%\n[Lv 3] : ATK +700%\n[Lv 4] : ATK +800%\n[Lv 5] : ATK +900%\n[Lv 6] : ATK +1000%\n[Lv 7] : ATK +1100%\n[Lv 8] : ATK +1200%\n[Lv 9] : ATK +1300%\n[Lv10] : ATK +1400%'),
('CH_SOULCOLLECT', 'Zen', 1, 'Support', 'Requirement : Fury 5\n5 Spirit Spheress จะถูกเรียกออกมาด้วยการใช้ Skill นี้', NULL),
('PF_DOUBLECASTING', 'Lucky Cast', 5, NULL, 'Requirement : Auto Spell 1\nContenst : ทำให้มีโอกาสร่าย Bolt skills ใดๆ สองครั้งซ้อน', '[Lv 1] : โอกาส 40%, ระยะเวลา 90 วินาที\n[Lv 2] : โอกาส 50%, ระยะเวลา 90 วินาที\n[Lv 3] : โอกาส 60%, ระยะเวลา 90 วินาที\n[Lv 4] : โอกาส 70%, ระยะเวลา 90 วินาที\n[Lv 5] : โอกาส 80%, ระยะเวลา 90 วินาที'),
('PF_HPCONVERSION', 'Indulge', 5, 'Support', 'Requirement : Increase SP Recovery 1, Magic Rod 1\nใช้ 10 % ของ HP เพื่อเปลี่ยนเป็น SP', '[Lv 1] : SP ฟื้นคืนเท่ากับ HP ที่เสีย + 10 %\n[Lv 2] : SP ฟื้นคืนเท่ากับ HP ที่เสีย + 20 %\n[Lv 3] : SP ฟื้นคืนเท่ากับ HP ที่เสีย + 30 %\n[Lv 4] : SP ฟื้นคืนเท่ากับ HP ที่เสีย + 40 %\n[Lv 5] : SP ฟื้นคืนเท่ากับ HP ที่เสีย + 50 %'),
('PF_SOULCHANGE', 'Soul Exhale', 1, 'Support', 'Requirement : Magic rod 3, Spell Braker 2\nแลกเปลี่ยน Sp ของผู้ใช้กับเป้าหมาย ไม่สามารถทำให้ Sp เกินกว่า Max Sp ของใครได้', NULL),
('PF_SOULBURN', 'Soul Siphon', 5, 'Active', 'Requirement : Cast Cancel 5, Magic Rod 3, Dispell 3\nดูด Sp ของเป้าหมายมาเป็นของตนเอง\nที่ Level 5 จะทำให้ผู้ที่เป็นเป้าหมาย เสียพลังเท่ากับ 2 เท่าของ SP ที่เหลืออยู่\nแต่ถ้า Skill พลาด ผู้ใช้จะเป็นผู้ได้รับผลการเสียพลังเอง มี Cooldown time 15 วินาที, สามารถใช้ได้ใน WoE (Guild War) battles และ PvP zones เท่านั้น', '[Lv 1] : อัตราสำเร็จ 40%\n[Lv 2] : อัตราสำเร็จ 50%\n[Lv 3] : อัตราสำเร็จ 60%\n[Lv 4] : อัตราสำเร็จ 70%\n[Lv 5] : อัตราสำเร็จ 70%'),
('PF_MINDBREAKER', 'Mind Breaker', 5, 'Support', 'Requirement : Increase SP Recovery 3, Soul Siphon 2\nทำให้ศัตรูสับสน\nเมื่อใช้ท่านี้ จะทำให้ศัตรูพลังป้องกันเวทย์ลดลง แต่พลังโจมตีเวทย์สูงขึ้น', '[Lv 1] : เป้าหมาย MATK +20%, MDEF -12%\n[Lv 2] : เป้าหมาย MATK +40%, MDEF -24%\n[Lv 3] : เป้าหมาย MATK +60%, MDEF -36%\n[Lv 4] : เป้าหมาย MATK +80%, MDEF -48%\n[Lv 5] : เป้าหมาย MATK +100%, MDEF -60%'),
('PF_MEMORIZE', 'Foresight', 1, 'Support', 'Requirement : Advanced Book 5, Free Cast 5, Auto Spell 1\nลดเวลาร่ายของ Skill 5 Skills\nไม่มีข้อกำหนดด้านระยะเวลของ Skill โดย Skill นี้จะหายไปเมื่อ ผู้ใช่ตายหรือใช้เวทย์ครบ 3 ครั้ง\nDex ไม่ส่งผลต่อเวลาร่ายของท่านี้ ระยะเวลาร่ายคือ 5 วินาที', NULL),
('PF_FOGWALL', 'Blinding Mist', 1, 'Support', 'Requirement : Voilent Gale 2, Deluge 2\nสร้างกำแพงหมอกขนาด 5*3ที่จะส่งผลให้ตัวละครและ Monster ติด Blind\nารโจมตีระยะไกลหรือเวทย์มนทั้งหมดที่โจมตีเข้ามาจะมีโอกาส Miss\nSkill นี้จะส่งผลถึงเฉพาะ Monster ในพื้นที่ทั่วไป และส่งผลใน Mode PVP กับผู้เล่น', NULL),
('PF_SPIDERWEB', 'Fiber Lock', 1, 'Support', 'Requirement : Dragonology 4\nยิง Spider Web ไปติดยังเป้าหมาย สามารถยิงได้ครั้งละ 2 อัน\nSpider Web จะติดอยู่เป็นเวลา 8 วินาที แต่ การโจมตีด้วย Property Fire  สามารถลบล้างผลของ Skill นี้ได้\nผู้ที่ติด Spider Web จะได้รับ Damage จาก Property Fire  * 2.5 เท่า, จำเป็นต้องใช้ ไอเทม : 1 Cobweb', NULL),
('ASC_METEORASSAULT', 'Meteor Assault', 10, 'Active', 'Requirement : Katar Mastery 5, Right Hand Mastery 3, Sonic Blow 5, Soul Destroyer 1\nโจมตีศํตรูรอบๆตัวผู้ใช้ 5*5 ช่อง มีผลทำให้ศํตรูอาจะติดสถานะผิดปรกติ', '[Lv 1] : ATK 80%\n[Lv 2] : ATK 120%\n[Lv 3] : ATK 160%\n[Lv 4] : ATK 200%\n[Lv 5] : ATK 240%\n[Lv 6] : ATK 280%\n[Lv 7] : ATK 320%\n[Lv 8] : ATK 360%\n[Lv 9] : ATK 400%\n[Lv10] : ATK 440%'),
('ASC_CDP', 'Create Deadly Poison', 1, 'Support', 'Requirement : Envenom 10, Detoxify 1, Enchant Poison 5\nสร้าง Deadly Poison ขึ้นจาก วัตถุดิบต่างๆ\nโดยมี. 1 Venom Canine,1 Cactus Needle, 1 Bee Sting,1 Poison Spore, 1 Karvodailnirol, 1 Berserk Potion และ 1 Empty Bottle\nDEX และ LUK ของผู้ใช้ส่งผลต่ออัตราการสำเร็จของการสร้าง Item นี้ ถ้าพลาด ผู้สร้างจะเสียพลัง 25% จาก MaxHP\nถ้า assassin Cross ดื่มยานี้เข้าไปจะทำให้ผู้ดื่มติดพิษแต่จะเพิ่ม Attack Speed', NULL),
('ASC_KATAR', 'Advanced Katar Mastery', 5, 'Passive', 'Requirement : Double Attack 5, Katar Mastery 7\nเพิ่มพลังโจมตีให้กับอาวุธประเภท Katar', '[Lv 1] : ATK +12%\n[Lv 2] : ATK +14%\n[Lv 3] : ATK +16%\n[Lv 4] : ATK +18%\n[Lv 5] : ATK +20%'),
('ASC_EDP', 'Enchant Deadly Poison', 5, 'Support', 'Requirement : Create Deadly Poison 1\nส่งผลต่อเพิ่มพลังโจมตีให้อาวุธ ต้องการ Deadly Poison 1 ขวด\nเมื่อโจมตีเป้าหมายมีโอกาสติดพิษและ Hp จะลดลงอย่างต่อเนื่อง\nสำหรับ Monster ระดับ Boss จะไม่มีผลการติดพิษ', NULL),
('ASC_BREAKER', 'Soul Destroyer', 10, 'Active', 'Requirement : Double Attack 5, Envenom 5, Cloaking 3, Enchant Poison 6\nโจมตีเป้าหมายโดยคำนวนพลังจากทั้งพลัง physical defense และ magic defense อย่างละครึ่ง\nพลังโจมตีคิดจาก Attack และ Int ของผู้โจมตี', NULL),
('SN_SIGHT', 'Falcon Eyes', 10, 'Support', 'Requirement : Owl''s Eye 10, Vulture''s Eye 10,  Improve Concentration 10, Falconry Mastery 1\nเพิ่ม +5 แก่ทุก Statusเพิ่ม Hit Damage และ Critical', '[Lv 1] : Hit +3%, Damage +2%, Critical +1\n[Lv 2] : Hit +6%, Damage +4%, Critical +2\n[Lv 3] : Hit +9%, Damage +6%, Critical +3\n[Lv 4] : Hit +12%, Damage +8%, Critical +4\n[Lv 5] : Hit +15%, Damage +10%, Critical +5\n[Lv 6] : Hit +18%, Damage +12%, Critical +6\n[Lv 7] : Hit +21%, Damage +14%, Critical +7\n[Lv 8] : Hit +24%, Damage +16%, Critical +8\n[Lv 9] : Hit +27%, Damage +18%, Critical +9\n[Lv10] : Hit +30%, Damage +20%, Critical +10'),
('SN_FALCONASSAULT', 'Falcon Assault', 5, 'Offensive', 'Requirement : Vulture''s Eye 5,  Falconry Mastery 1, Blitz Beat  5, Steel Crow 3\nโจมตีเป้าหมายคนเดียวด้วย Falcon อย่างรุนแรง', NULL),
('SN_SHARPSHOOTING', 'Focused Arrow Strike', 5, 'Offensive', 'Requirement : Double Strafe 5,  Improve Concentration 10\nโจมตีไปยังจุดๆ หนึ่ง\nสร้างพลังโจมตีอย่างรุนแรงต่อศัตรูในเส้นทางการโจมตี\nเป็นการโจมตีแบบ Critical Attack ซึ่งคำนวนจาก Critical Attack Rate +20 ของผู้ใช้', '[Lv 1] : ATK +150%\n[Lv 2] : ATK +200%\n[Lv 3] : ATK +250%\n[Lv 4] : ATK +300%\n[Lv 5] : ATK +350%'),
('SN_WINDWALK', 'Wind Walker', 10, 'Support', 'Requirement : Improve Concentration 9\nเพิ่มอัตราการเคลื่อนที่และการหลบหลีกของ Party และผู้ใช้\nไม่สามารถใช้ร่วมกับ Skill ที่เพิ่มความเร็วอื่นๆ ได้\nและ Skill ที่ลดความเร็วจะส่งผลให้ยกเลิกท่านี้', NULL),
('WS_MELTDOWN', 'Shattering Strike', 10, 'Support', 'Requirement : Skin Tempering 3, Hilt Binding 1, Weaponry Research 5, Power Thrust 3\nในระยะเวลาของ Skill การโจมตีของผู้ใช้ Skill นี้ มีโอกาสทำลายเกราะ หรืออาวุธของศัตรู\nถ้าใช้กับ Monster โอกาสที่จะลดพลังป้องกันหรือพลังโจมตีของศัตรู', '[Lv 1] : ระยะเวลา 15 วินาที\n[Lv 2] : ระยะเวลา 20 วินาที\n[Lv 3] : ระยะเวลา 25 วินาที\n[Lv 4] : ระยะเวลา 30 วินาที\n[Lv 5] : ระยะเวลา 35 วินาที\n[Lv 6] : ระยะเวลา 40 วินาที\n[Lv 7] : ระยะเวลา 45 วินาที\n[Lv 8] : ระยะเวลา 50 วินาที\n[Lv 9] : ระยะเวลา 55 วินาที\n[Lv10] : ระยะเวลา 60 วินาที'),
('WS_CREATECOIN', '', NULL, NULL, NULL, NULL),
('WS_CREATENUGGET', '', NULL, NULL, NULL, NULL),
('WS_CARTBOOST', 'Cart Boost', 1, 'Support', 'Requirement : Push Cart 5, Hilt Binding 1, Cart Revolution 1, Change Cart 1\nเพิ่มความเร็วการเคลื่อนที่ให้กับผู้ใช้ เมื่อใส่ Cart\nSkill ที่มีผลลดความเร็ว จะไม่ส่งผลต่อ Skill นี้', NULL),
('WS_SYSTEMCREATE', '', NULL, NULL, NULL, NULL),
('ST_CHASEWALK', 'Stealth', 5, 'Support', 'Requirement : Hiding 5, Tunnel Drive 3\nเมื่อใช้ Skill นี้ ผู้ร่ายจะเคลื่อนไหวได้อย่างช้าๆ เมื่อ Hiding ซึ่งสกิลนี้จะไม่ถูกจับโดยสกิล Improve Concentration, Sight or Ruwach\nและเวทย์มนต์ที่ลงพื้นทั้งหมด จะส่งผลต่อผู้ที่ใช้ Skill นี้ เมื่อเคลื่อนไหว ด้วยท่านี้ จะมีรอยเท้าทิ้งไว้ในเส้นทางที่เดินผ่าน\nใช้กับแมลง Demon หรือ Boss Monster ไม่ได้ เมื่อใช้ Skill นี้ แล้วเวลาผ่านไประยะหนึ่ง ตัวละครจะได้รับ Bonus Str\nสามารถใช้ใน Guildwar ได้ แต่จะเสีย SP มากกว่าปรกติ 5 เท่า', '[Level 1] : ความเร็วในการเคลื่อนที่ลดลง 70%, ใช้ Sp  12 ต่อ 10 วินาที , +1 STR  หลังจากผ่านไป 10 วินาที\n[Level 2] : ความเร็วในการเคลื่อนที่ลดลง 75%, ใช้ Sp  14 ต่อ 10 วินาที, +2 STR  หลังจากผ่านไป 10 วินาที\n[Level 3] : ความเร็วในการเคลื่อนที่ลดลง 80%, ใช้ Sp  16 ต่อ 10 วินาที , +4 STR  หลังจากผ่านไป 10 วินาที\n[Level 4] : ความเร็วในการเคลื่อนที่ลดลง 85%, ใช้ Sp  18 ต่อ 10 วินาที, +8 STR  หลังจากผ่านไป 10 วินาที\n[Level 5] : ความเร็วในการเคลื่อนที่ลดลง 90%, ใช้ Sp  20 ต่อ 10 วินาที , +16 STR  หลังจากผ่านไป 10 วินาที'),
('ST_REJECTSWORD', 'Counter Instinct', 5, 'Support', 'มีผลกับศัตรูที่ใช้อาวุธประเภท Sword\nกันการโจมตีจากศัตรู 3 ครั้งโดยจะเสียเพลังแค่ครึ่งเดียว\nเมื่อใช้กับ Monster จะส่งผลสะท้อนพลังโจมตีกลับไปหา ศัตรูครึ่งหนึ่ง', '[Lv 1] : อัตราสะท้อนกลับ 15%\n[Lv 2] : อัตราสะท้อนกลับ 30%\n[Lv 3] : อัตราสะท้อนกลับ 45%\n[Lv 4] : อัตราสะท้อนกลับ 60%\n[Lv 5] : อัตราสะท้อนกลับ 75%'),
('ST_STEALBACKPACK', '', NULL, NULL, NULL, NULL),
('CR_ALCHEMY', '', NULL, NULL, NULL, NULL),
('CR_SYNTHESISPOTION', '', NULL, NULL, NULL, NULL),
('CG_ARROWVULCAN', 'Arrow Vulcan', 10, 'Active', 'Requirement : Double Strafe 5, Arrow Shower 5, Musical Strike 1\nโจมตีด้วยลูกธนูนับไม่ถ้วนใส่เป้าหมาย Bard ต้องใช้ Musical Instrument และ Dancer ต้องใช้ Whip จึงจะใช้ Skill นี้ได้', '[Lv 1] : ATK 300%\n[Lv 2] : ATK 400%\n[Lv 3] : ATK 500%\n[Lv 4] : ATK 600%\n[Lv 5] : ATK 700%\n[Lv 6] : ATK 800%\n[Lv 7] : ATK 900%\n[Lv 8] : ATK 1000%\n[Lv 9] : ATK 1100%\n[Lv10] : ATK 1200%'),
('CG_MOONLIT', 'Sheltering Bliss', 5, 'Ensemble Skill', 'Requirement : Improve Concentration 5, Musical Lesson(Dance Lesson) 7\nสร้างพื้นที่ 5*5 รอบๆตัวผู้ร่าย โดยจะไม่มีใครสามารถเข้ามาในบริเวณดังกล่าวได้\nแต่พื้นที่นี้ป้องการเข้ามาเท่านั้นไม่ได้ป้องกันการโจมตีจากภายนอกเข้ามา ถ้ามีสิ่งกีดขวางในระยะของ Skill จะไม่สามารถใช้ Skill ได้', '[Lv 1] : ระยะเวลา 20 วินาที\n[Lv 2] : ระยะเวลา 25 วินาที\n[Lv 3] : ระยะเวลา 30 วินาที\n[Lv 4] : ระยะเวลา 35 วินาที\n[Lv 5] : ระยะเวลา 40 วินาที'),
('CG_MARIONETTE', 'Marionette Control', 1, 'Support', 'Requirement : Improve Concentration 10, Musical Lesson(Dance Lesson) 5\nส่ง Stat ทุก Stat ของผู้ร่ายไปให้สมาชิกของ Party ที่เป็นเป้าหมาย โดยสมาชิกของ Party จะได้รับ Stat ครึ่งหนึ่ง แต่ Stat รวมที่ได้นั้นจะต้องไม่เกิน 99\nถ้าสมาชิก Party อยู่ห่างผู้ใช้เกิน 7 ช่อง Skill จะถูกยกเลิก', NULL),
('ST_FULLSTRIP', 'Full Strip', 5, 'Support', 'Requirement : Strip Weapon 5\nเป้าหมาย : ศัตรู\nปลด Equipment 4 ชนิดภายในการใช้ Skill 1 ครั้ง(Weapon,Helm,Armor,Shield)\nผู้ใช้ต้องมี Dex ที่สูงเพื่อให้อัตราความสำเร็จสูง', '[Lv 1] : อัตราสำเร็จ 7%\n[Lv 2] : อัตราสำเร็จ 9%\n[Lv 3] : อัตราสำเร็จ 11%\n[Lv 4] : อัตราสำเร็จ 13%\n[Lv 5] : อัตราสำเร็จ 15%'),
('ST_PRESERVE', 'Preserve', 1, 'Support', 'Requirement : Intimidate 10\nผู้ใช้ Skill นี้จะไม่โดน Skill intimidated เป็นเวลา 10 นาที', NULL),
('WS_WEAPONREFINE', 'Upgrade Weapon', 10, 'Craft', 'Requirement : Weaponry Research 10\nRefine weapon items.\nSkill นี้ Dex และ Luk ไม่ส่งผลต่ออัตราความสำเร็จ\nแต่ขึ้นอยู่กับ Job Lv ของผู้ใช้งาน\nที่ Job Level  50 ผู้ใช้จะมีอัตราสำเร็จเท่ากับ NPC\nที่ Job Level  60 ผู้ใช้จะมีอัตราสำเร็จมากกว่า NPC 5 %\nที่ Job Level  70 ผู้ใช้จะมีอัตราสำเร็จมากกว่า NPC 10 %\nหากล้มเหลว ไอเทมจะถูกทำลาย\nUpgrading level 1 weapon ต้องการ Phracon.\nUpgrading level 2 weapon ต้องการ Emvertacon.\nUpgrading level 3,4 weapon ต้องการ Oridecon.', '[Lv 1] : สามารถ Upgrade อาวุธได้ถึง +1\n[Lv 2] : สามารถ Upgrade อาวุธได้ถึง +2\n[Lv 3] : สามารถ Upgrade อาวุธได้ถึง +3\n[Lv 4] : สามารถ Upgrade อาวุธได้ถึง +4\n[Lv 5] : สามารถ Upgrade อาวุธได้ถึง +5\n[Lv 6] : สามารถ Upgrade อาวุธได้ถึง +6\n[Lv 7] : สามารถ Upgrade อาวุธได้ถึง +7\n[Lv 8] : สามารถ Upgrade อาวุธได้ถึง +8\n[Lv 9] : สามารถ Upgrade อาวุธได้ถึง +9\n[Lv10] : สามารถ Upgrade อาวุธได้ถึง +10'),
('CR_SLIMPITCHER', 'Slim Potion Pitcher', 10, NULL, 'Requirement : Potion Pitcher 5\nใช้ Slim Potion ในการเพิ่มพลังให้ Party ในระยะ 7*7\nจากจุดศูนย์กลาง', '[Lv 1] : Potion มีผลมากขึ้น  110%  [Red]\n[Lv 2] : Potion มีผลมากขึ้น  120%  [Red]\n[Lv 3] : Potion มีผลมากขึ้น  130%  [Red]\n[Lv 4] : Potion มีผลมากขึ้น  140%  [Red]\n[Lv 5] : Potion มีผลมากขึ้น  150%  [Red]\n[Lv 6] : Potion มีผลมากขึ้น  160% [Yellow]\n[Lv 7] : Potion มีผลมากขึ้น  170% [Yellow]\n[Lv 8] : Potion มีผลมากขึ้น  180% [Yellow]\n[Lv 9] : Potion มีผลมากขึ้น  190% [Yellow]\n[Lv10] : Potion มีผลมากขึ้น  200% [White]'),
('CR_FULLPROTECTION', 'Full Chemical Protection', 5, 'Support', 'Requirement : Chemical Protection(Weapon, Shield, Armor, Helm) 5\nSkill นี้จะป้องกัน Equipment 4 อย่างจากความเสียหายหรือถูกปลด (Weapon,Helm,Armor,Shield)\nต้องการ : 1 Glistening Coat', '[Lv 1] : ระยะเวลา 120 วินาที\n[Lv 2] : ระยะเวลา 240 วินาที\n[Lv 3] : ระยะเวลา 360 วินาที\n[Lv 4] : ระยะเวลา 480 วินาที\n[Lv 5] : ระยะเวลา 600 วินาที'),
('WS_CARTTERMINATION', 'Cart Termination', 10, NULL, 'Requirement : Mammonite 10, Hammer Fall 5, Cart Boost  1\nใช้ได้เฉพาะเวลาที่อยู่ในสถานะ Cart Boost เท่านั้น\nใช้ Zeny จำนวนหนึ่งในการโจมตี และมีโอกาสทำให้เป้าหมาย Stun\nSkill level และน้ำหนักของรถเข็นมีผลต่อค่าความรุนแรงในการโจมตี', '[Lv 1] : ใช้ 600z,โอกาศติดสถานะ [Stun]  5%\n[Lv 2] : ใช้ 700z,โอกาศติดสถานะ [Stun] 10%\n[Lv 3] : ใช้ 800z,โอกาศติดสถานะ [Stun] 15%\n[Lv 4] : ใช้ 900z,โอกาศติดสถานะ [Stun] 20%\n[Lv 5] : ใช้ 1,000z,โอกาศติดสถานะ [Stun] 25%\n[Lv 6] : ใช้ 1,100z,โอกาศติดสถานะ [Stun] 30%\n[Lv 7] : ใช้ 1,200z,โอกาศติดสถานะ [Stun] 35%\n[Lv 8] : ใช้ 1,300z,โอกาศติดสถานะ [Stun] 40%\n[Lv 9] : ใช้ 1,400z,โอกาศติดสถานะ [Stun] 45%\n[Lv10] : ใช้ 1,500z,โอกาศติดสถานะ [Stun] 50%'),
('PA_SHIELDCHAIN', 'Shield Chain', 5, NULL, 'Requirement : Shield Boomerang 5\nโจมตี 5 เป้าหมายขณะที่ใช้โล่\nค่าความแม่นยำ, สถานะต่างๆ และน้ำหนักโล่ของผู้ร่ายมีผลต่อค่าความเสียหายที่เกิดขึ้น\ndelay 1 วินาที และ ระยะการร่าย 4 ช่อง', '[Lv 1] : Basic ATK + 30%, Damage Success Chance +20\n[Lv 2] : Basic ATK + 60%, Damage Success Chance +20\n[Lv 3] : Basic ATK + 90%, Damage Success Chance +20\n[Lv 4] : Basic ATK + 120%, Damage Success Chance +20\n[Lv 5] : Basic ATK + 150%, Damage Success Chance +20'),
('WS_OVERTHRUSTMAX', 'Power Thrust Max', 5, NULL, 'Requirement : Power Thrust 5\nเพิ่มพลังโจมตีให้กับอาวุธของผู้ร่ายด้วย zeny\nไม่สามารถใช้สกิลได้หากร่ายข้างผู้อื่น\nมีโอกาส 0.1% ที่อาวุธจะเสียหายทุกครั้งที่โจมตีเป้าหมาย', '[Lv 1] : ATK+20%, ใช้ 3,000z\n[Lv 2] : ATK+40%, ใช้ 3,500z\n[Lv 3] : ATK+60%, ใช้ 4,000z\n[Lv 4] : ATK+80%, ใช้ 4,500z\n[Lv 5] : ATK+100%, ใช้ 5,000z'),
('CG_LONGINGFREEDOM', 'Longing for Freedom', 5, NULL, 'Requirement : Marionette Control  1, Unchained Serenade(Ugly Dance) 3, Music Lesson(Dance Lesson) 10\nทำให้ Gypsy และ Minstrel สามารถเคลื่อนที่ในขณะที่ใช้สกิลคู่ได้ แต่ไม่สามารถเคลื่อนที่ออกนอกกรอบของสกิลที่ใช้ได้\nถ้าคนใดคนหนึ่งออกนอกพื้นที่, ตายหรือใช้สกิลคู่อื่น สกิลนี้จะถูกยกเลิกทันที\nใช้ 3 SP ทุก 3 วินาที ผู้ร่ายสามารถโจมตีและใช้สกิลอื่นได้ยกเว้นสกิลคู่\nผลของสกิล Longing for Freedom จะถูกยกเลิก\nเมื่อ Gypsy หรือ Minstrel ออกจาก\nระยะของสกิล, ตาย, หรือใ้้ช้สกิลเพลงอื่นๆ\nไม่สามารถใช้สกิลเพลงอิ่นได้ในเวลาเดียวกัน', '[Lv 1] : สามารถเคลื่นที่ได้และความเร็วในการโจมตีเป็น 60% ของปกติ\n[Lv 2] : สามารถเคลื่นที่ได้และความเร็วในการโจมตีเป็น 70% ของปกติ\n[Lv 3] : สามารถเคลื่นที่ได้และความเร็วในการโจมตีเป็น 80% ของปกติ\n[Lv 4] : สามารถเคลื่นที่ได้และความเร็วในการโจมตีเป็น 90% ของปกติ\n[Lv 5] : สามารถเคลื่นที่ได้และความเร็วในการโจมตีเป็นปกติ'),
('CG_HERMODE', 'Hermod''s Staff', 5, NULL, 'Requirement : Improve Concentration 10, Music Lesson(Dance Lesson) 10\nสร้างพื้นที่ขนาด 7*7 ใช้ได้เฉพาะบริเวณจุดวาร์ปภายในบริเวณปราสาทกิลด์วอร์\nยกเลิกเวทย์ทั้งหมดที่ได้รับทุกคนยกเว้น Berserk และทำให้ไม่สามารถร่ายเวทย์หรือใช้สกิลใดๆ ได้ในพื้นที่ของสกิลนี้\nป้องกันเวทย์ทั้งหมดเมื่ออยู่ในพื้นที่ (เช่นเดียวกับ Golden Bug Card) เฉพาะผู้ร่ายเท่านั้นที่สามารถใช้เวทย์หรือสกิลได้ในพื้นที่\nเมื่อออกจากพื้นที่สกิลจะสามารถร่ายเวทย์หรือใช้สกิลได้ตามปกติ มีผลเฉพาะกิลด์เดียวกันและพันธมิตร', '[Lv 1] : ระยะเวลา 10 วินาที\n[Lv 2] : ระยะเวลา 20 วินาที\n[Lv 3] : ระยะเวลา 30 วินาที\n[Lv 4] : ระยะเวลา 40 วินาที\n[Lv 5] : ระยะเวลา 50 วินาที'),
('CG_TAROTCARD', 'Tarot Card of Fate', 5, NULL, 'Requirement : Improve Concentration 10, Unchained Serenade(Ugly Dance) 3\nสาปเป้าหมายแบบสุ่มจากผลของไพ่ 1 ใน 14 ใบ\nSkill level จะเพิ่มโอกาสในการร่ายสำเร็จ delay 3 วินาที', '[Lv 1] : โอกาสสำเร็จ 8%\n[Lv 2] : โอกาสสำเร็จ 16%\n[Lv 3] : โอกาสสำเร็จ 24%\n[Lv 4] : โอกาสสำเร็จ 32%\n[Lv 5] : โอกาสสำเร็จ 40%'),
('CR_ACIDDEMONSTRATION', 'Acid Demonstration', 10, NULL, 'Requirement : Demonstration 5, Acid Terror 5\nขว้าง 1 Fire Bottle และ 1 Acid Bottle ไปยังเป้าหมายในเวลาเดียวกัน\nค่า INTของผู้ร่าย VIT ของเป้าหมายและ skill level มีผลต่อค่าความรุนแรง\nเมื่อใช้กับผู้เล่น ผลของสกิลจะลดลง 50 %\nแต่มีโอกาสที่จะทำให้ Weapon และ Armor ของเป้าหมายเสียหาย', '[Lv 1] Weapon + Armor มีโอกาสเสียหาย 1%\n[Lv 2] Weapon + Armor มีโอกาสเสียหาย 2%\n[Lv 3] Weapon + Armor มีโอกาสเสียหาย 3%\n[Lv 4] Weapon + Armor มีโอกาสเสียหาย 4%\n[Lv 5] Weapon + Armor มีโอกาสเสียหาย 5%\n[Lv 6] Weapon + Armor มีโอกาสเสียหาย 6%\n[Lv 7] Weapon + Armor มีโอกาสเสียหาย 7%\n[Lv 8] Weapon + Armor มีโอกาสเสียหาย 8%\n[Lv 9] Weapon + Armor มีโอกาสเสียหาย 9%\n[Lv10] Weapon + Armor มีโอกาสเสียหาย 10%'),
('CR_CULTIVATION', 'Plant Cultivation', 2, NULL, 'เรียก Mushroom และ Plant จาก Mushroom Spores และ Stems.\nมีโอกาสสำเร็จ 50%\nไม่สามารถใช้งานได้ใน WoE (Guild War)', '[Lv 1] : Mushroom Cultivation (Requires Mushroom Spores)\n[Lv 2] : Plant Cultivation(Requires Stems)'),
('WE_MALE', 'I''ll Save You', NULL, NULL, 'สกิลที่ใช้ได้กับคนรักของตนเท่านั้น\nเสียสละ HP ของตนเพื่อเพิ่ม HP ให้กับคนรัก\nผู้ใช้สกิลนี้จะเสีย HP 10% จาก HP สูงสุดของตนเองไม่สามารถใช้สกิลนี้ได้เมื่อเมื่อ HP ต่ำกว่า 10%', NULL),
('WE_FEMALE', 'Undying Love', NULL, NULL, 'สกิลที่ใช้ได้กับคนรักของตนเท่านั้น\nผู้ใช้สกิลนี้จะเสีย SP 10% จาก SP สูงสุดของตนเองไม่สามารถใช้สกิลนี้ได้เมื่อเมื่อ SP ต่ำกว่า 10%\nและผู้รับจะได้ Sp 10 % ของ Max Sp ของตน', NULL),
('WE_CALLPARTNER', 'Romantic Rendezvous', NULL, NULL, 'และคู่รักของท่านต้องสวมแหวนนี้อยู่เพื่อแสดงถึงความรัก จึงจะสามารถใช้สกิลนี้ได้สำเร็จ\nสกิลนี้ไม่สารมารถใช้ได้ในบางพื้นที่ (แผนที่ Guild War)', NULL),
('ITM_TOMAHAWK', 'Tomahawk Throwing', NULL, NULL, 'โยนtomahawk เพื่อโจมตีศัตรูที่อยู่ระยะไกล', NULL),
('WE_BABY', 'Mom, Dad, I love you!', NULL, 'Support', 'ตัวละครพ่อและแม่ของตัวละครที่ร่ายจะไม่เสีย EXP เมื่อตาย\nการร่ายสกิลใช้ SP 10% ของ Max SP', NULL),
('WE_CALLPARENT', 'Mom, Dad, I miss you!', NULL, 'Support', 'ตัวละครลูกเรียกตัวละครพ่อและแม่มาหา', NULL),
('WE_CALLBABY', 'Come to me, honey~', NULL, 'Support', 'ตัวละครพ่อและแม่เรียกตัวละครลูกมาหา', NULL),
('TK_RUN', 'Run', 10, 'Move and Passive', 'เมื่อไม่สวมใส่อาวุธและใช้สกิลนี้เลเวลที่ 1-7 และหยุดกระทันหันจะได้รับโบนัส STR เพิ่มขึ้นเป็นเวลา 150 วินาที\nเมื่อสวมใส่อาวุธค่าโบนัสที่ได้รับจะถูกยกเลิก พลังในการเตะจะเพิ่มขึ้น 10 เมื่อไม่สวมใส่อาวุธ และจะเพิ่มขึ้นทุกๆ เลเวลสกิล\nสกิล Run จะถูกยกเลิกเมื่อผู้ใช้ทำการสวมใส่อาวุธ\nแต่ละเลเวลของสกิล Run จะเพิ่มความรุนแรงที่โจมตีด้วยมือเปล่าขึ้น +10', '[Lv 1] ใช้เวลาร่าย: 6 วินาที,  ใช้ SP : 100\n[Lv 2] ใช้เวลาร่าย: 5 วินาที,  ใช้ SP : 90\n[Lv 3] ใช้เวลาร่าย: 4 วินาที,  ใช้ SP : 80\n[Lv 4] ใช้เวลาร่าย: 3 วินาที,  ใช้ SP : 70\n[Lv 5] ใช้เวลาร่าย: 2 วินาที,  ใช้ SP : 60\n[Lv 6] ใช้เวลาร่าย: 1 วินาที,  ใช้ SP : 50\n[Lv 7] ใช้เวลาร่าย: 0 วินาที,  ใช้ SP : 40\n[Lv 8] ใช้เวลาร่าย: 0 วินาที,  ใช้ SP : 30\n[Lv 9] ใช้เวลาร่าย: 0 วินาที,  ใช้ SP : 20\n[Lv 10] ใช้เวลาร่าย: 0 วินาที,  ใช้ SP : 10'),
('TK_READYSTORM', 'Ready Storm', 1, 'Preparation', 'Requirement : Storm Kick 1\nเมื่อโจมตีถูกศัตรู มีโอกาส 15% ที่จะติดสถานะท่าเตรียม Ready Storm\nอาชีพ Soullinker ไม่สามารถใช้ได้', '[Lv 1] ใช้เวลาร่าย: 0 วินาที,  ใช้ SP : 1'),
('TK_STORMKICK', 'Storm Kick', 7, 'Attack', 'สามารถใช้ได้เมื่ออยู่ในสถานะท่าเตรียม Ready Storm\nโจมตีศัตรูในพื้นที่ 5x5 ช่องรอบตัวผู้ร่าย', '[Lv 1] ใช้ SP : 14, 180%\n[Lv 2] ใช้ SP : 12, 200%\n[Lv 3] ใช้ SP : 10, 220%\n[Lv 4] ใช้ SP : 8, 240%\n[Lv 5] ใช้ SP : 6, 260%\n[Lv 6] ใช้ SP : 4, 280%\n[Lv 7] ใช้ SP : 2, 300%'),
('TK_READYDOWN', 'Ready Down', 1, 'Preparation', 'Requirement : Down Kick 1\nเมื่อโจมตีถูกศัตรู มีโอกาส 15% ที่จะติดสถานะท่าเตรียม Ready Down\nอาชีพ Soullinker ไม่สามารถใช้ได้', '[Lv 1] ใช้เวลาร่าย: 0 วินาที, ใช้ SP : 1'),
('TK_DOWNKICK', 'Down Kick', 7, 'Attack', 'สามารถใช้ได้เมื่ออยู่ในสถานะท่าเตรียม Ready Down\nสร้างความเสียหายและติดสถานะ stun  3 วินาทีแก่ศัตรู', '[Lv 1] ใช้ SP : 14,  180%\n[Lv 2] ใช้ SP : 12,  200%\n[Lv 3] ใช้ SP : 10,  220%\n[Lv 4] ใช้ SP : 8,  240%\n[Lv 5] ใช้ SP : 6,  260%\n[Lv 6] ใช้ SP : 4,  280%\n[Lv 7] ใช้ SP : 2,  300%'),
('TK_READYTURN', 'Ready Turn', 1, 'Preparation', 'Requirement : Turn Kick 1\nเมื่อโจมตีถูกศัตรู มีโอกาส 15% ที่จะติดสถานะท่าเตรียม Ready Turn\nอาชีพ Soullinker ไม่สามารถใช้ได้', '[Lv 1] ใช้เวลาร่าย: 0 วินาที ใช้ SP : 1'),
('TK_TURNKICK', 'Turn Kick', 7, 'Attack', 'สามารถใช้ได้เมื่ออยู่ในสถานะท่าเตรียม Ready Turn\nสร้างความเสียหายให้กับศัตรูเพียงตัวเดียว แต่จะทำให้ศัตรูที่อยู่ใกล้ๆ กันกระเด็นออกไป', '[Lv 1] ใช้ SP : 14, 220%\n[Lv 2] ใช้ SP : 12, 250%\n[Lv 3] ใช้ SP : 10, 280%\n[Lv 4] ใช้ SP : 8, 310%\n[Lv 5] ใช้ SP : 6, 340%\n[Lv 6] ใช้ SP : 4, 370%\n[Lv 7] ใช้ SP : 2, 400%'),
('TK_READYCOUNTER', 'Ready Counter', 1, 'Preparation', 'Requirement : Counter Kick 1\nเมื่อโจมตีถูกศัตรู มีโอกาส 20% ที่จะติดสถานะท่าเตรียม Ready Counter\nอาชีพ Soullinker ไม่สามารถใช้ได้', '[Lv 1] ใช้เวลาร่าย: 0 วินาที ใช้ SP : 1'),
('TK_COUNTER', 'Counter Kick', 7, 'Attack', 'สามารถใช้ได้เมื่ออยู่ในสถานะท่าเตรียม Ready Counter\nสร้างความเสียหาย 100% กับศัตรู', '[Lv 1] ใช้ SP : 14, 220%\n[Lv 2] ใช้ SP : 12, 250%\n[Lv 3] ใช้ SP : 10, 280%\n[Lv 4] ใช้ SP :  8, 310%\n[Lv 5] ใช้ SP :  6, 340%\n[Lv 6] ใช้ SP :  4, 370%\n[Lv 7] ใช้ SP :  2, 400%'),
('TK_DODGE', 'Dodge', 1, 'Preparation', 'Requirement : Jump Kick 7\nมีโอกาส 20% ที่จะหลบการโจมตีระยะไกลของศัตรูอย่างสมบูรณ์ เมื่ออยู่ในสถานะนี้จะสามารถโจมตีกลับไปยังศัตรูที่สู้ประชิดตัวได้\nWhen caster is in Spurt status (after performing Lv 7 Sprint or higher), Tumbling will also block other kinds of attacks.', '[Lv 1] ใช้เวลาร่าย: 0 วินาที,  ใช้ SP : 1'),
('TK_JUMPKICK', 'Flying Kick', 7, 'Offensive', 'กระโดดและโจมตีศัตรูจากระยะไกล\nเมื่อใช้สกิลนี้ในสถานะ Dodge ค่าความเสียหายจะเพิ่มขึ้นตามเลเวลของตัวละคร\nอาชีพ Soul Linker ไม่สามารถใช้ได้ สามารถยกเลิกสถานะสกิลต่างๆ ของ Taekwondo ฝ่ายศัตรูได้\n(สถานะ Soul ทั้งหมด, One-Hand Quicken, all Anderline Rush, Kaahi, Kaite, Berserk Potion)\nแต่จะไม่ยกเลิกสกิลหากตัวละครนั้นมีสถานะ Auto-Protection เมื่อใช้สกิล Jump Kick ระหว่างวิ่ง\nค่าความเสียหายจะเพิ่มขึ้นตาม Base เลเวลของตัวละคร หากใช้ในระหว่างได้รับโบนัส STR จากสกิล Run ค่าโบนัสก็จะถูกนำมาคิดเพิ่มด้วย\nHowever, Stalkers can protect themselves from this positive status removal effect with their Preserve skill.', '[Lv 1] ใช้ SP : 70, 40%\n[Lv 2] ใช้ SP : 60, 50%\n[Lv 3] ใช้ SP : 50, 60%\n[Lv 4] ใช้ SP : 40, 70%\n[Lv 5] ใช้ SP : 30, 80%\n[Lv 6] ใช้ SP : 20, 90%\n[Lv 7] ใช้ SP : 10, 100%'),
('TK_HPTIME', 'Peaceful Break', 10, 'Passive', 'เมื่อมีอาชีพ Taekwondo นั่งติดกัน จะสามารถฟื้น HP ได้แม้ว่าน้ำหนักจะเกิน 50%\nและอัตราการฟื้นตัวจะเร็วขึ้นตามค่า VIT\nถ้าพิมพ์ ''/doridori''', '[Lv 1] ฟื้นค่า HP : 30\n[Lv 2] ฟื้นค่า HP : 60\n[Lv 3] ฟื้นค่า HP : 90\n[Lv 4] ฟื้นค่า HP : 120\n[Lv 5] ฟื้นค่า HP : 150\n[Lv 6] ฟื้นค่า HP : 180\n[Lv 7] ฟื้นค่า HP : 210\n[Lv 8] ฟื้นค่า HP : 240\n[Lv 9] ฟื้นค่า HP : 270\n[Lv 10] ฟื้นค่า HP : 300'),
('TK_SPTIME', 'Happy Break', 10, 'Passive', 'เมื่อมีอาชีพ Taekwondo นั่งติดกัน จะสามารถฟื้น sp ได้เร็วขึ้น โดยอัตราการฟื้นตัวจะขึ้นอยู่กับค่า Int\nพิมพ์ /doridori สามารถเพิ่มความเร็วในการฟื้น SP ได้และจะได้รับสถานะ Happy 30 นาที ใช้ SP 10 ซึ่งจะทำให้\nมีโอกาสได้รับ Earth Scroll 10% ที่จะได้ Earth Scroll เลเวล 1 และ 1% ที่จะได้ Earth Scroll เลเวล 10\nขณะอยู่ในสถานะนี้, มีโอกาสเล็กน้อยที่จะใช้ Earth Spike spell scroll,\nซึ่งโอกาสมี 10% ที่จะใช้ Skill Level 1, และ มีโอกาส 1% ที่จะใช้ Skill Level 10\nใช้งาน Earth Spike scroll ในขณะอยู่ในสถานะนี้ จะใช้ SP เพียง 10', '[Lv 1] อัตราการฟื้น SP : 3\n[Lv 2] อัตราการฟื้น SP : 6\n[Lv 3] อัตราการฟื้น SP : 9\n[Lv 4] อัตราการฟื้น SP : 12\n[Lv 5] อัตราการฟื้น SP : 15\n[Lv 6] อัตราการฟื้น SP : 18\n[Lv 7] อัตราการฟื้น SP : 21\n[Lv 8] อัตราการฟื้น SP : 24\n[Lv 9] อัตราการฟื้น SP : 27\n[Lv10] อัตราการฟื้น SP : 30'),
('TK_POWER', 'Power', 5, 'Passive', 'เพิ่มพลังโจมตีตามจำนวนผู้เล่นในปาร์ตี้ที่อยู่ในแผนที่เดียวกัน\nเมื่อโจมตีปกติ  ค่าความเสียหาย = (100 x % ที่เพิ่มขึ้น) + (100% ค่าความเสียหายปกติ)', '[Lv 1] ค่าความเสียหายที่เพิ่มขึ้น 2%\n[Lv 2] ค่าความเสียหายที่เพิ่มขึ้น 4%\n[Lv 3] ค่าความเสียหายที่เพิ่มขึ้น 6%\n[Lv 4] ค่าความเสียหายที่เพิ่มขึ้น 8%\n[Lv 5] ค่าความเสียหายที่เพิ่มขึ้น 10%'),
('TK_SEVENWIND', 'Seven Wind', 7, 'Supportive', 'Requirement : Peaceful Break 5, Happy Break 5, Kihop 5\nเปลี่ยนธาตุการโจมตี เป็นเวลา 5 นาที', '[Lv 1] Earth (ใช้ SP : 20)\n[Lv 2] Wind  (ใช้ SP : 20)\n[Lv 3] Water (ใช้ SP : 20)\n[Lv 4] Fire  (ใช้ SP : 20)\n[Lv 5] Mind  (ใช้ SP : 50)\n[Lv 6] Darkness (ใช้ SP : 50)\n[Lv 7] Holy  (ใช้ SP : 50)'),
('TK_HIGHJUMP', 'High Jump', 5, 'Movement', 'สามารถกระโดดข้ามสิ่งกีดขวางต่างๆ ได้ ถ้าพื้นที่ที่กำหนดสามารถเดินได้\nไม่สามารถใช้ได้ในกิลด์วอร์และแผนที่ที่ไม่อนุญาติให้ใช้ Wing of Fly\nHigh Jump ไม่สามารถใช้ได้ในบริเวณที่ Fly Wings ไม่แสดงผล, ยกเว้น WoE (Guild War) maps\nHigh Jump เพิ่มระยะเวลาการร่ายสกิล Urgent Call ขึ้นสองเท่า', '[Lv 1] ใช้เวลาร่าย: 5 วินาที ระยะในการกระโดด: 2 ช่อง\n[Lv 2] ใช้เวลาร่าย: 4 วินาที ระยะในการกระโดด: 4 ช่อง\n[Lv 3] ใช้เวลาร่าย: 3 วินาที ระยะในการกระโดด: 6 ช่อง\n[Lv 4] ใช้เวลาร่าย: 2 วินาที ระยะในการกระโดด: 8 ช่อง\n[Lv 5] ใช้เวลาร่าย: 1 วินาที ระยะในการกระโดด: 10 ช่อง'),
('SG_FEEL', 'Feelings of Sun, Moon and Star', 3, 'Register', 'เมื่อใช้สกิลนี้ แผนที่ที่ตัวละครอยู่จะถูกลงทะเบียนเป็นแผนที่พิเศษ\nแผนที่ลงทะเบียนไม่สามารถเปลี่ยนแปลงได้\nเมื่อทำการลงทะเบียนแล้ว จะมีข้อความแสดงการลงทะเบียนแผนที่ปรากฎ', '[Lv 1] ลงทะเบียน Sun''s location\n[Lv 2] ลงทะเบียน Moon''s location\n[Lv 3] ลงทะเบียน Star''s location'),
('SG_SUN_WARM', 'Warmth of Sun', 3, 'Attack', 'Requirement : Feelings of Sun, Moon and Star 1\nสามารถใช้สกิลนี้ได้เฉพาะพื้นที่ Sun''s location\nสร้างความเสียหายและทำให้ศัตรูกระเด็นถอยหลัง บริเวณรอบตัวผู้ร่าย\nทุกการโจมตีใช้ 2 SP และสถานะจะถูกยกเลิกเมื่อตัวละครมี SP ไม่พอ\nไม่สร้างความเสียหายให้กับมอนเตอร์ประเภทกึ่งมนุษย์ แต่จะไม่เสียค่า SP', '[Lv 1] ระยะเวลา : 10 วินาที,  ใช้ SP : 20\n[Lv 2] ระยะเวลา : 20 วินาที,  ใช้ SP : 20\n[Lv 3] ระยะเวลา : 60 วินาที,  ใช้ SP : 20'),
('SG_MOON_WARM', 'Warmth of Moon', 3, 'Attack', 'Requirement : Feelings of Sun, Moon and Star 2\nสามารถใช้สกิลนี้ได้เฉพาะพื้นที่ Moon''s location\nสร้างความเสียหายและทำให้ศัตรูกระเด็นถอยหลัง บริเวณรอบตัวผู้ร่าย\nทุกการโจมตีใช้ 2 SP และสถานะจะถูกยกเลิกเมื่อตัวละครมี SP ไม่พอ\nไม่สร้างความเสียหายให้กับมอนเตอร์ประเภทกึ่งมนุษย์ แต่จะไม่เสียค่า SP', '[Lv 1] ระยะเวลา : 10 วินาที,  ใช้ SP : 20\n[Lv 2] ระยะเวลา : 20 วินาที,  ใช้ SP : 20\n[Lv 3] ระยะเวลา : 60 วินาที,  ใช้ SP : 20'),
('SG_STAR_WARM', 'Warmth of Star', 3, 'Attack', 'Requirement : Feelings of Sun, Moon and Star 3\nสามารถใช้สกิลนี้ได้เฉพาะพื้นที่ Star''s location\nสร้างความเสียหายและทำให้ศัตรูกระเด็นถอยหลัง บริเวณรอบตัวผู้ร่าย\nทุกการโจมตีใช้ 2 SP และสถานะจะถูกยกเลิกเมื่อตัวละครมี SP ไม่พอ\nไม่สร้างความเสียหายให้กับมอนเตอร์ประเภทกึ่งมนุษย์ แต่จะไม่เสียค่า SP', '[Lv 1] ระยะเวลา : 10 วินาที,  ใช้ SP : 10\n[Lv 2] ระยะเวลา : 20 วินาที,  ใช้ SP : 10\n[Lv 3] ระยะเวลา : 60 วินาที,  ใช้ SP : 10'),
('SG_SUN_COMFORT', 'Comfort of Sun', 4, 'Supportive', 'Requirement : Feelings of Sun, Moon and Star 1\nสามารถใช้ได้เฉพาะแผนที่ Sun''s location ในวันแห่ง Sun (วันคู่)\nค่าพลังป้องกันเพิ่มขึ้นตามเลเวลของตัวละคร, ค่า DEX และค่า LUK\nWhen using, any change on DEF cancels the skill.', '[Lv 1] ใช้ SP : 70, ระยะเวลา : 80 วินาที\n[Lv 2] ใช้ SP : 60, ระยะเวลา : 160 วินาที\n[Lv 3] ใช้ SP : 50, ระยะเวลา : 240 วินาที\n[Lv 4] ใช้ SP : 40, ระยะเวลา : 320 วินาที'),
('SG_MOON_COMFORT', 'Comfort of Moon', 4, 'Supportive', 'Requirement : Feelings of Sun, Moon and Star 2\nสามารถใช้ได้เฉพาะแผนที่ Moon''s location ในวันแห่ง Moon (วันคี่)\nอัตราการหลบหลีกจะเพิ่มขึ้นตามเลเวลของตัวละคร, ค่า DEX และค่า LUK', '[Lv 1] ใช้ SP : 70, ระยะเวลา : 80 วินาที\n[Lv 2] ใช้ SP : 60, ระยะเวลา : 160 วินาที\n[Lv 3] ใช้ SP : 50, ระยะเวลา : 240 วินาที\n[Lv 4] ใช้ SP : 40, ระยะเวลา : 320 วินาที'),
('SG_STAR_COMFORT', 'Comfort of Star', 4, 'Supportive', 'Requirement : Feelings of Sun, Moon and Star 3\nสามารถใช้ได้เฉพาะแผนที่ Star''s location ในวันแห่ง Star (หารด้วย 5 ลงตัว)\nความเร็วในการโจมตีจะเพิ่มขึ้นตามเลเวลของตัวละคร, ค่า DEX และค่า LUK', '[Lv 1] ใช้ SP : 70, ระยะเวลา : 80 วินาที\n[Lv 2] ใช้ SP : 60, ระยะเวลา : 160 วินาที\n[Lv 3] ใช้ SP : 50, ระยะเวลา : 240 วินาที\n[Lv 4] ใช้ SP : 40, ระยะเวลา : 320 วินาที'),
('SG_HATE', 'Hatred of Sun, Moon and Star', 3, 'Register', 'สกิลนี้สามารถลงทะเบียนได้เฉพาะมอนเตอร์เท่านั้น\nมอนเตอร์ที่ลงทะเบียนจะไม่สามารถเปลี่ยนได้\nหลังจากใช้สกิลแล้ว มอนเตอร์ที่ถูกลงทะเบียนจะถูกแสดงขึ้นมา', '[Lv 1] ลงทะเบียน hate of Sun (สามารถใช้ได้กับมอนเตอร์ขนาดเล็กเท่านั้น)\n[Lv 2] ลงทะเบียน hate of Moon (สามารถใช้ได้กับมอนเตอร์ขนาดกลางที่มี HP ตั้งแต่ 6000 ขึ้นไปเท่านั้น)\n[Lv 3] ลงทะเบียน hate of Star (สามารถใช้ได้กับมอนเตอร์ขนาดใหญ่ที่มี HP ตั้งแต่ 20000 ขึ้นไปเท่านั้น)\nการลงทะเบียนสถานะประเภทกับเป้าหมาย เมื่อกำหนดแล้วขนาดและค่า HP จะไม่ถูกนำมาพิจารณา'),
('SG_SUN_ANGER', 'Wrath of Sun', 3, 'Passive', 'Requirement : Hatred of Sun, Moon and Star 1\nพลังในการโจมตีจะเพิ่มขึ้นเมื่อต่อสู้กับมอนเตอร์ประเภท Sun\nค่าพลังโจมตีที่เพิ่มขึ้นนั้นขึ้นอยู่กับเลเวลของตัวละคร, เลเวลของ skill, ค่า  LUK และค่า DEX', NULL),
('SG_MOON_ANGER', 'Wrath of Moon', 3, 'Passive', 'Requirement : Hatred of Sun, Moon and Star 2\nพลังในการโจมตีจะเพิ่มขึ้นเมื่อต่อสู้กับมอนเตอร์ประเภท Moon\nค่าพลังโจมตีที่เพิ่มขึ้นนั้นขึ้นอยู่กับเลเวลของตัวละคร, เลเวลของ skill, ค่า  LUK และค่า DEX^0000', NULL),
('SG_STAR_ANGER', 'Wrath of Star', 3, 'Passive', 'Requirement : Hatred of Sun, Moon and Star 3\nพลังในการโจมตีจะเพิ่มขึ้นเมื่อต่อสู้กับมอนเตอร์ประเภท Star\nค่าพลังโจมตีที่เพิ่มขึ้นนั้นขึ้นอยู่กับเลเวลของตัวละคร, เลเวลของ skill, ค่า  LUK และค่า DEX^0000', NULL),
('SG_SUN_BLESS', 'Blessing of Sun', 5, 'Passive', 'Requirement : Feelings of Sun, Moon and Star 1, Hatred of Sun, Moon and Star 1\nในวันแห่ง Sun (วันคู่), ค่าประสบการณ์ที่ได้รับจะเพิ่มขึ้นเมื่อกำจัดมอนเตอร์ประเภท Sun', '[Lv 1] ค่าประสบการณ์เพิ่มขึ้น : 10%\n[Lv 2] ค่าประสบการณ์เพิ่มขึ้น : 20%\n[Lv 3] ค่าประสบการณ์เพิ่มขึ้น : 30%\n[Lv 4] ค่าประสบการณ์เพิ่มขึ้น : 40%\n[Lv 5] ค่าประสบการณ์เพิ่มขึ้น : 50%'),
('SG_MOON_BLESS', 'Blessing of Moon', 5, 'Passive', 'Requirement : Feelings of Sun, Moon and Star 2, Hatred of Sun, Moon and Star 2\nในวันแห่ง Moon (วันคี่), ค่าประสบการณ์ที่ได้รับจะเพิ่มขึ้นเมื่อกำจัดมอนเตอร์ประเภท Moon', '[Lv 1] ค่าประสบการณ์เพิ่มขึ้น : 10%\n[Lv 2] ค่าประสบการณ์เพิ่มขึ้น : 20%\n[Lv 3] ค่าประสบการณ์เพิ่มขึ้น : 30%\n[Lv 4] ค่าประสบการณ์เพิ่มขึ้น : 40%\n[Lv 5] ค่าประสบการณ์เพิ่มขึ้น : 50%'),
('SG_STAR_BLESS', 'Blessing of Star', 5, 'Passive', 'Requirement : Feelings of Sun, Moon and Star 3, Hatred of Sun, Moon and Star 3\nในวันแห่ง Star (หารด้วย 5 ลงตัว), ค่าประสบการณ์ที่ได้รับจะเพิ่มขึ้นเมื่อกำจัดมอนเตอร์ประเภท Star', '[Lv 1] ค่าประสบการณ์เพิ่มขึ้น : 20%\n[Lv 2] ค่าประสบการณ์เพิ่มขึ้น : 40%\n[Lv 3] ค่าประสบการณ์เพิ่มขึ้น : 60%\n[Lv 4] ค่าประสบการณ์เพิ่มขึ้น : 80%\n[Lv 5] ค่าประสบการณ์เพิ่มขึ้น : 100%'),
('SG_DEVIL', 'Devil of Sun, Moon and Star', 10, 'Passive', 'Requirement : Job level 50\nสกิลนี้จะสามารถใช้ได้เมื่อ JOB เลเวล 50,\nเมื่อใช้แล้วจะมองไม่เห็นพื้นที่รอบข้างคล้ายกับการติดสถานะ  blind\nแนะนำว่าไม่ควรใช้ ถ้าเป็นไปได้', '[Lv 1] ความเร็วในการโจมตีเพิ่มขึ้น : 3%\n[Lv 2] ความเร็วในการโจมตีเพิ่มขึ้น : 6%\n[Lv 3] ความเร็วในการโจมตีเพิ่มขึ้น : 9%\n[Lv 4] ความเร็วในการโจมตีเพิ่มขึ้น : 12%\n[Lv 5] ความเร็วในการโจมตีเพิ่มขึ้น : 15%\n[Lv 6] ความเร็วในการโจมตีเพิ่มขึ้น : 18%\n[Lv 7] ความเร็วในการโจมตีเพิ่มขึ้น : 21%\n[Lv 8] ความเร็วในการโจมตีเพิ่มขึ้น : 24%\n[Lv 9] ความเร็วในการโจมตีเพิ่มขึ้น : 27%\n[Lv 10] ความเร็วในการโจมตีเพิ่มขึ้น : 30%'),
('SG_FRIEND', 'Friend of Sun, Moon and Star', 3, 'Passive', 'เมื่อใช้สกิล Counter โอกาสที่อาชีพ Monk ในปาร์ตี้จะใช้สกิล Triple Blows จะเพิ่มขึ้น\nและเมื่ออาชีพ Monk ในปาร์ตี้ใช้สกิล The Way of the Dragon โอกาสในการใช้สกิล Taekwon Master จะเพิ่มขึ้น', '[Lv 1] เพิ่มขึ้น : 100%\n[Lv 2] เพิ่มขึ้น : 150%\n[Lv 3] เพิ่มขึ้น : 200%'),
('SG_KNOWLEDGE', 'Knowledge of Sun, Moon and Star', 10, 'Passive', 'For those who think designating of area and monster is too complicated.\nAllocating Skill Points to Taekwon Boy or Girl Job skills will facilitate playing.\nรายละเอียด : เพิ่มน้ำหนักในการถือของเมื่ออยู่ในพื้นที่ Sun, Moon, หรือ Star\nเมื่อได้รับผลของสกิลที่จำกัดพื้นที่การมองเห็น ถ้าผู้เล่นนั่งลงและใช้สกิลนี้\nจะสามารถทำให้มองได้ไกลขึ้น', '[Lv 1] เพิ่มน้ำหนักในการถือของ : 10%\n[Lv 2] เพิ่มน้ำหนักในการถือของ : 20%\n[Lv 3] เพิ่มน้ำหนักในการถือของ : 30%\n[Lv 4] เพิ่มน้ำหนักในการถือของ : 40%\n[Lv 5] เพิ่มน้ำหนักในการถือของ : 50%\n[Lv 6] เพิ่มน้ำหนักในการถือของ : 60%\n[Lv 7] เพิ่มน้ำหนักในการถือของ : 70%\n[Lv 8] เพิ่มน้ำหนักในการถือของ : 80%\n[Lv 9] เพิ่มน้ำหนักในการถือของ : 90%\n[Lv 10] เพิ่มน้ำหนักในการถือของ : 100%'),
('SG_FUSION', 'Fusion of Sun, Moon and Star', NULL, 'Awakening', 'Requirement : Knowledge of Sun, Moon and Star 9, Soul status\nสามารถปลุกพลังสถานะต่างๆ ที่ซ่อนอยู่ในจิตใจเป็นเวลา 10 นาที\nทำให้มีผลเพิ่มค่าความแม่นยำขึ้น 100% (Accuracy) และไม่คิดค่าพลังป้องกัน\nและเพิ่ม Movement Speed อีกด้วย แต่อย่างไรก็ตาม 2% ของ HP จะลดลงเมื่อทำการโจมตี\nไปยัง monsters และ 8% หากการโจมตีนั้นเป็นการโจมตีใส่ผู้เล่น ภายในสถานะนี้,\nหากผู้ร่ายมี HP อยู่ต่ำกว่า 20% ของค่า Max HP ผู้ร่ายจะตายลงทันที', NULL),
('SL_ALCHEMIST', 'Soul of Alchemist', 5, 'Supportive', 'รวบรวมจิตใจที่ทรงพลังของ Alchemist และเสริมพลังให้กับเพื่อนร่วมทีม\nสกิล Potion Pitcher จะได้รับความสามารถเพิ่มขึ้น (ขึ้นกับเลเวลของตัวละครที่ใช้)\nสามารถที่จะใช้สกิล Berserk Pitcher และ Twilight', '[Lv 1] ใช้ SP : 460, ระยะเวลา : 150 วินาที\n[Lv 2] ใช้ SP : 360, ระยะเวลา : 200 วินาที\n[Lv 3] ใช้ SP : 260, ระยะเวลา : 250 วินาที\n[Lv 4] ใช้ SP : 160, ระยะเวลา : 300 วินาที\n[Lv 5] ใช้ SP : 60, ระยะเวลา : 350 วินาที'),
('AM_BERSERKPITCHER', 'Berserk Pitcher', NULL, 'Supportive', 'Requirement : Soul status\nบังคับให้ผู้เล่นที่เลเวลมากกว่า 85 ดื่ม Berserk Potion\nใช้ 2 Berserk Potions เมื่อทำการใช้สกิล\nค่า ASPD จะเพิ่มขึ้นแต่ระยะเวลาจะอยู่สั้นกว่าปกติครึ่งหนึ่ง', NULL),
('SL_MONK', 'Soul of Monk', 5, 'Supportive', 'รวบรวมจิตใจที่ทรงพลังของ Monk และเสริมพลังให้กับเพื่อนร่วมทีม\nเมื่อผู้เล่นใช้สกิล Combo finish ในการคอมโบ ค่าความเสียหายจะกระจายออกไป 5*5 ช่อง\nค่า SP ในการใช้สกิลจะลดลง\nสามารถฟื้น SP ได้เมื่ออยู่ในสถานะ Vigor Explosion', '[Lv 1] ใช้ SP : 460, ระยะเวลา : 150วินาที\n[Lv 2] ใช้ SP : 360, ระยะเวลา : 200วินาที\n[Lv 3] ใช้ SP : 260, ระยะเวลา : 250วินาที\n[Lv 4] ใช้ SP : 160, ระยะเวลา : 300วินาที\n[Lv 5] ใช้ SP : 60, ระยะเวลา : 350วินาที'),
('SL_STAR', 'Soul of Taekwon Master', 5, 'Supportive', 'รวบรวมจิตใจที่ทรงพลังของ Taekwon Master\nและเสริมพลังให้กับเพื่อนร่วมทีม\nทำให้สามารถใช้สกิล Fusion of Sun, Moon and Star ได้', '[Lv 1] ใช้ SP : 460, ระยะเวลา : 150วินาที\n[Lv 2] ใช้ SP : 360, ระยะเวลา : 200วินาที\n[Lv 3] ใช้ SP : 260, ระยะเวลา : 250วินาที\n[Lv 4] ใช้ SP : 160, ระยะเวลา : 300วินาที\n[Lv 5] ใช้ SP : 60, ระยะเวลา : 350วินาที'),
('SL_SAGE', 'Soul of Sage', 5, 'Supportive', 'รวบรวมจิตใจที่ทรงพลังของ Sage และเสริมพลังให้กับเพื่อนร่วมทีม\nเมื่อใช้สกิล Auto Spell สาย Bolt ใดก็ตามจะทำให้สามารถใช้เลเวลสูงสุดของสกิล Bolt ได้', '[Lv 1] ใช้ SP : 460, ระยะเวลา : 150วินาที\n[Lv 2] ใช้ SP : 360, ระยะเวลา : 200วินาที\n[Lv 3] ใช้ SP : 260, ระยะเวลา : 250วินาที\n[Lv 4] ใช้ SP : 160, ระยะเวลา : 300วินาที\n[Lv 5] ใช้ SP : 60, ระยะเวลา : 350วินาที'),
('SL_CRUSADER', 'Soul of Crusader', 5, 'Supportive', 'รวบรวมจิตใจที่ทรงพลังของ Crusader และเสริมพลังให้กับเพื่อนร่วมทีม\nเมื่อสกิลนี้มีผลอยู่, สามารถใช้สกิล Shield Boomerang\nโดยลด cool time ลงครึ่งหนึ่ง, และโจมตีเป้าหมายโดยไม่ miss', '[Lv 1] ใช้ SP : 460, ระยะเวลา : 150วินาที\n[Lv 2] ใช้ SP : 360, ระยะเวลา : 200วินาที\n[Lv 3] ใช้ SP : 260, ระยะเวลา : 250วินาที\n[Lv 4] ใช้ SP : 160, ระยะเวลา : 300วินาที\n[Lv 5] ใช้ SP : 60, ระยะเวลา : 350วินาที'),
('SL_SUPERNOVICE', 'Soul of Super Novice', 5, 'Supportive', 'Requirement : Soul of Taekwon Master 1\nรวบรวมจิตใจที่ทรงพลังของ Super Novice และเสริมพลังให้กับเพื่อนร่วมทีม\nเมื่อตัวละครเลเวล 90 ขึ้นไป จะสามารถสวมใส่ Headgear ได้ทุกส่วน\nมีโอกาสเล็กน้อยที่จะได้รับการปกป้องของนางฟ้าจากความตาย\nเมื่อตัวละครเลเวล 96 ขึ้นไป จะสามารถถืออาวุธเลเวล 4 ได้\nSword,  Dagger,  Axe,  Mace และ Staff ได้', '[Lv 1] ใช้ SP : 460, ระยะเวลา : 150วินาที\n[Lv 2] ใช้ SP : 360, ระยะเวลา : 200วินาที\n[Lv 3] ใช้ SP : 260, ระยะเวลา : 250วินาที\n[Lv 4] ใช้ SP : 160, ระยะเวลา : 300วินาที\n[Lv 5] ใช้ SP : 60, ระยะเวลา : 350วินาที'),
('SL_KNIGHT', 'Soul of Knight', 5, 'Supportive', 'Requirement : Soul of Crusader 1\nรวบรวมจิตใจที่ทรงพลังของ Knight และเสริมพลังให้กับเพื่อนร่วมทีม\nเมื่อผู้เล่นมีสกิล Two Hand Quicken เลเวล 10 จะสามารถใช้สกิล One Hand Quicken ได', '[Lv 1] ใช้ SP : 460, ระยะเวลา : 150วินาที\n[Lv 2] ใช้ SP : 360, ระยะเวลา : 200วินาที\n[Lv 3] ใช้ SP : 260, ระยะเวลา : 250วินาที\n[Lv 4] ใช้ SP : 160, ระยะเวลา : 300วินาที\n[Lv 5] ใช้ SP : 60, ระยะเวลา : 350วินาที'),
('SL_WIZARD', 'Soul of Wizard', 5, 'Supportive', 'Requirement : Soul of Sage 1\nรวบรวมจิตใจที่ทรงพลังของ Wizard และเสริมพลังให้กับเพื่อนร่วมทีม\nใช้เวทมนตร์ต่างๆ ได้โดยไม่ต้องใช้ Gemstone, เมื่อได้รับ Soul of Wizard จะสามารถใช้สกิลได้โดยไม่ต้องใช้ gemstone , SP ที่ใช้และระยะเวลาร่ายเพิ่มขึ้น 50%\nหากผู้เล่นถือไอเท็ม Crystal Piece ไว้ระหว่างอยู่ในสถานะ Soul สามารถป้องกันการสะท้อนเวทมนตร์จากสกิล Kaite ได้โดยจะเสีย Crystal Pieces แทน', '[Lv 1] ใช้ SP : 460, ระยะเวลา : 150วินาที\n[Lv 2] ใช้ SP : 360, ระยะเวลา : 200วินาที\n[Lv 3] ใช้ SP : 260, ระยะเวลา : 250วินาที\n[Lv 4] ใช้ SP : 160, ระยะเวลา : 300วินาที\n[Lv 5] ใช้ SP : 60, ระยะเวลา : 350วินาที'),
('SL_PRIEST', 'Soul of Priest', 5, 'Supportive', 'Requirement : Soul of Monk 1\nรวบรวมจิตใจที่ทรงพลังของ Priest\nและเสริมพลังให้กับเพื่อนร่วมทีม\nSP ในการใช้สกิล Holy Light เพิ่มขึ้น 500%\nความรุนแรงของสกิล Holy Light แรงขึ้น 500%', '[Lv 1] ใช้ SP : 460, ระยะเวลา : 150วินาที\n[Lv 2] ใช้ SP : 360, ระยะเวลา : 200วินาที\n[Lv 3] ใช้ SP : 260, ระยะเวลา : 250วินาที\n[Lv 4] ใช้ SP : 160, ระยะเวลา : 300วินาที\n[Lv 5] ใช้ SP : 60, ระยะเวลา : 350วินาที'),
('SL_BARDDANCER', 'Soul of Bard and Dancer', 5, 'Supportive', 'รวบรวมจิตใจที่ทรงพลังของ Bard และ Dancer และเสริมพลังให้กับเพื่อนร่วมทีม\nสกิลคู่จะได้รับประสิทธิภาพมากขึ้น\nการเคลื่อนที่เร็วขึ้นในการใช้สกิล  Whistle and Humming,  Assassin Cross of Sunset , Forget Me Not,\nA Poem of Bragi และ Fortune''s Kiss สกิล Apple of Idun และ At Your Service ส่งผลร่วมกันได้\nSP ที่ใช้ในการ link สกิลเพิ่มขึ้น 50 %', '[Lv 1] ใช้ SP : 460, ระยะเวลา : 150วินาที\n[Lv 2] ใช้ SP : 360, ระยะเวลา : 200วินาที\n[Lv 3] ใช้ SP : 260, ระยะเวลา : 250วินาที\n[Lv 4] ใช้ SP : 160, ระยะเวลา : 300วินาที\n[Lv 5] ใช้ SP : 60, ระยะเวลา : 350วินาที'),
('SL_ROGUE', 'Soul of Rogue', 5, 'Supportive', 'Requirement : Soul of Assassin 1\nรวบรวมจิตใจที่ทรงพลังของ Rogue และเสริมพลังให้กับเพื่อนร่วมทีม\nเพิ่มความเร็วในการเคลื่อนที่ของสกิล Stealth และได้รับค่า STR เพิ่มขึ้นตามระยะเวลาของสกิล\nRogue ที่ได้รับพลังนี้จะไม่ได้รับผลของสกิล Dispell และจะได้รับ HP, SP จากโพชั่นที่สร้างโดย\nTop 10 Ranking Alchemist เพิ่มขึ้น', '[Lv 1] ใช้ SP : 460, ระยะเวลา : 150วินาที\n[Lv 2] ใช้ SP : 360, ระยะเวลา : 200วินาที\n[Lv 3] ใช้ SP : 260, ระยะเวลา : 250วินาที\n[Lv 4] ใช้ SP : 160, ระยะเวลา : 300วินาที\n[Lv 5] ใช้ SP : 60, ระยะเวลา : 350วินาที'),
('SL_ASSASIN', 'Soul of Assassin', 5, 'Supportive', 'รวบรวมจิตใจที่ทรงพลังของ Assassin\nและเสริมพลังให้กับเพื่อนร่วมทีม\nความแรงของสกิล Sonic Blow เพิ่มขึ้น 100% Delay time ลดลง\nในกิลด์วอร์ Sonic Blow แรงขึ้น 25% และ Delay time ไม่ลดลง\nใช้ Sonic Blow จะเพิ่ม SP ที่ใช้ขึ้น 100%', '[Lv 1] ใช้ SP : 460, ระยะเวลา : 150วินาที\n[Lv 2] ใช้ SP : 360, ระยะเวลา : 200วินาที\n[Lv 3] ใช้ SP : 260, ระยะเวลา : 250วินาที\n[Lv 4] ใช้ SP : 160, ระยะเวลา : 300วินาที\n[Lv 5] ใช้ SP : 60, ระยะเวลา : 350วินาที'),
('SL_BLACKSMITH', 'Soul of Blacksmith', 5, 'Supportive', 'Requirement : Soul of Alchemist 1\nรวบรวมจิตใจที่ทรงพลังของ Blacksmith\nและเสริมพลังให้กับเพื่อนร่วมทีม\nเมื่ออัพสกิล Adrenaline Rush เลเวล 5\nอาวุธทุกประเภทจะได้ผลของสกิล Anderline Rush ยกเว้นประเภท Bow\nค่า ASPD จะไม่ทับซ้อนในกรณีที่ใช้สกิล Two-Handed Quicken, Anderline Rush, One-Hand Quicken,\nThe Devil of the Sun, Moon and Star, Spear-Quicken, Comfort of Star.', '[Lv 1] ใช้ SP : 460, ระยะเวลา : 150วินาที\n[Lv 2] ใช้ SP : 360, ระยะเวลา : 200วินาที\n[Lv 3] ใช้ SP : 260, ระยะเวลา : 250วินาที\n[Lv 4] ใช้ SP : 160, ระยะเวลา : 300วินาที\n[Lv 5] ใช้ SP : 60, ระยะเวลา : 350วินาที'),
('SL_HUNTER', 'Soul of Hunter', 5, 'Supportive', 'Requirement : Soul of Bard and Dancer 1\nรวบรวมจิตวิญญาณที่ทรงพลัง\nของเหล่าฮันเตอร์ชื่อดังในอดีต และเปลี่ยนเป็นพลังความสามารถให้\nกับตัวละครฮันเตอร์ที่ต้องการ ปรับเปลี่ยนสกิล Beast Bane ให้มีผลตามค่า STR ของตัวละคร', '[Lv 1] ใช้ SP : 460, ระยะเวลา : 150วินาที\n[Lv 2] ใช้ SP : 360, ระยะเวลา : 200วินาที\n[Lv 3] ใช้ SP : 260, ระยะเวลา : 250วินาที\n[Lv 4] ใช้ SP : 160, ระยะเวลา : 300วินาที\n[Lv 5] ใช้ SP : 60, ระยะเวลา : 350วินาที'),
('SL_SOULLINKER', 'Soul of Soullinker', 5, 'Supportive', 'Requirement : Soul of Taekwon Master 1\nรวบรวมจิตใจที่ทรงพลังของ Soullinker\nและเสริมพลังให้กับเพื่อนร่วมทีม\nเวทมนตร์ประเภท ''Ka'' ใช้ได้กับ Soullinker เท่านั้น สกิลนี้ไม่สามารถใส่ให้กับอาชีพอื่นได้', '[Lv 1] ใช้ SP : 460, ระยะเวลา : 150วินาที\n[Lv 2] ใช้ SP : 360, ระยะเวลา : 200วินาที\n[Lv 3] ใช้ SP : 260, ระยะเวลา : 250วินาที\n[Lv 4] ใช้ SP : 160, ระยะเวลา : 300วินาที\n[Lv 5] ใช้ SP : 60, ระยะเวลา : 350วินาที'),
('SL_KAIZEL', 'Kaizel', 7, 'Supportive', 'Requirement : Soul of Priest 1\nเวทมนตร์ประเภท ''Ka'' ใช้ได้กับ Soullinker เท่านั้น\nค่า DEX ไม่มีผลต่อเวลาร่าย, เมื่อตายจะถูกชุบในทันทีและได้รับสกิล Kyrie Elipson เป็นเวลา 2 วินาที\nระยะเวลา 30 นาที ผลของสกิลจะถูกยกเลิกเมื่อตัวละครถูกชุบขึ้นแล้วครั้งหนึ่ง สกิลนี้ไม่สามารถใช้ในระบบ Guild War', '[Lv 1] ใช้เวลาร่าย: 4.5 วินาที. ใช้ SP : 120,  ค่า HP ที่ได้รับหลังจากชุบ : 10%\n[Lv 2] ใช้เวลาร่าย: 4วินาที,  ใช้ SP :110,  ค่า HP ที่ได้รับหลังจากชุบ : 20%\n[Lv 3] ใช้เวลาร่าย: 3.5วินาที,  ใช้ SP :100,  ค่า HP ที่ได้รับหลังจากชุบ : 30%\n[Lv 4] ใช้เวลาร่าย: 3วินาที,  ใช้ SP :90,  ค่า HP ที่ได้รับหลังจากชุบ : 40%\n[Lv 5] ใช้เวลาร่าย: 3.5วินาที,  ใช้ SP :80,  ค่า HP ที่ได้รับหลังจากชุบ : 50%\n[Lv 6] ใช้เวลาร่าย: 3วินาที,  ใช้ SP :70,  ค่า HP ที่ได้รับหลังจากชุบ : 60%\n[Lv 7] ใช้เวลาร่าย: 2.5วินาที,  ใช้ SP :60,  ค่า HP ที่ได้รับหลังจากชุบ : 70%'),
('SL_KAAHI', 'Kaahi', 7, 'Supportive', 'Requirement : Soul of Priest 1, Soul of Monk 1, Soul of Crusader 1\nเวทมนตร์ประเภท ''Ka'' ใช้ได้กับ Soullinker เท่านั้น\nเมื่อถูกโจมตี (ยกเว้นการโจมตีจากสกิล) ระหว่างที่ใช้สกิลนี้อยู่ ค่า SP จะถูกใช้เป็นค่าฟื้น HP\nสกิลนี้จะไม่ทำงานหาก HP เต็ม\nSP ที่ใช้ในการฟื้นพลังต่อครั้ง : 5 ~ 35\nHP ที่ได้รับต่อการฟื้นพลังต่อครั้ง : 200 ~ 1400', NULL),
('SL_KAUPE', 'Kaupe', 3, 'Supportive', 'Requirement : Soul of Assassin 1, Soul of Rogue 1\nเวทมนตร์ประเภท ''Ka'' ใช้ได้กับ Soullinker เท่านั้น\nหลบการโจมตีระยะประชิดในอัตราคงที่\nระยะเวลา 10 นาที และผลของสกิลจะหายไปเมื่อตัวละครหลบการโจมตีได้ 1 ครั้ง', '[Lv 1] อัตราการหลบ: 33% (ใช้ SP : 20)\n[Lv 2] อัตราการหลบ: 66% (ใช้ SP : 30)\n[Lv 3] อัตราการหลบ: 100% (ใช้ SP : 40)'),
('SL_KAITE', 'Kaite', 7, 'Supportive', 'Requirement : Soul of Wizard 1, Soul of Sage 1\nเวทมนตร์ประเภท ''Ka'' ใช้ได้กับ Soullinker เท่านั้น\nสะท้อนการโจมตีจากเวทมนตร์เกือบทั้งหมดรวมถึงการฟื้นพลังด้วยเวทมนตร์ (Heal)ไปยังผู้ร่าย\nในกรณีที่สะท้อนการฟื้นพลังด้วยเวทมนตร์ (Heal)ผู้ร่ายจะไม่ได้รับผลการฟื้นพลังจากการสะท้อน\nไม่สามารถสะท้อนเวทมนตร์จากมอนเตอร์ระดับสูงหรือ Boss ได้\nแต่สามารถสะท้อนเวทมนตร์ทั้งหมดจากผู้เล่นได้โดยไม่คำนึงถึงเลเวล และสกิลนี้ไม่สามารถใช้พร้อมกับสกิล Assumption ได้\nKaite ไม่สามารถใช้ได้กับ Asumptio, และจะทำให้โดนโจมตีทางกายภาพแรงขึ้น 400%\nการสะท้อนกลับมีโอกาส 50%, และ Ground Magic ไม่สามารถสะท้อนกลับได้', '[Lv 1] ใช้เวลาร่าย:6วินาที, การสะท้อนกลับ : 1 ครั้ง, ระยะเวลา : 1 นาที\n[Lv 2] ใช้เวลาร่าย:5.5วินาที, การสะท้อนกลับ : 1 ครั้ง, ระยะเวลา : 2 นาที\n[Lv 3] ใช้เวลาร่าย:5วินาที, การสะท้อนกลับ : 1 ครั้ง, ระยะเวลา : 3 นาที\n[Lv 4] ใช้เวลาร่าย:4.5วินาที, การสะท้อนกลับ : 1 ครั้ง, ระยะเวลา : 4 นาที\n[Lv 5] ใช้เวลาร่าย:4วินาที, การสะท้อนกลับ : 2 ครั้ง, ระยะเวลา : 5 นาที\n[Lv 6] ใช้เวลาร่าย:3.5วินาที, การสะท้อนกลับ : 2 ครั้ง, ระยะเวลา : 6 นาที\n[Lv 7] ใช้เวลาร่าย:3วินาที, การสะท้อนกลับ : 2 ครั้ง, ระยะเวลา : 10 นาที'),
('SL_KAINA', 'Kaina', 7, 'Passive', 'Requirement : Happy Break 1\nผลของสกิล Happy Break และ Max SP เพิ่มขึ้น\nลดค่า SP 3% ในการใช้สกิล Estin, Estern, Esma เมื่อตัวละครเลเวล 70\nลด 5% เมื่อตัวละครเลเวล 80 และลด 7% เมื่อตัวละครเลเวล 90', '[Lv 1] ผลของสกิล Happy Break +40%,  MAX SP +30\n[Lv 2] ผลของสกิล Happy Break +50%,  MAX SP +60\n[Lv 3] ผลของสกิล Happy Break +60%,  MAX SP +90\n[Lv 4] ผลของสกิล Happy Break +70%,  MAX SP +120\n[Lv 5] ผลของสกิล Happy Break +80%,  MAX SP +150\n[Lv 6] ผลของสกิล Happy Break +90%,  MAX SP +180\n[Lv 7] ผลของสกิล Happy Break +100%,  MAX SP +210'),
('SL_STIN', 'Estin', 7, 'Magic Attack', 'Requirement : Soul of Wizard\nเวทมนตร์ประเภท ''Es'' ใช้กับมอนเตอร์\nสร้างความเสียหายให้กับมอนเตอร์ขนาดเล็กและทำให้ถอยห่างออกไป 2 ช่อง\nไม่สร้างความเสียหายให้กับมอนเตอร์ขนาดกลางและขนาดใหญ่แต่ยังคงทำให้ถอยห่างออกไป\nผลของสกิล Seven Wind ถูกนำมาคิดด้วย\nใช้เวลาในการร่าย 3 วินาที เช่นเดียวกับสกิล Esma', '[Lv 1] Damage 10% (ใช้ SP :  18)\n[Lv 2] Damage 20% (ใช้ SP :  20)\n[Lv 3] Damage 30% (ใช้ SP :  22)\n[Lv 4] Damage 40% (ใช้ SP :  24)\n[Lv 5] Damage 50% (ใช้ SP :  26)\n[Lv 6] Damage 60% (ใช้ SP :  28)\n[Lv 7] Damage 70% (ใช้ SP :  30)'),
('SL_STUN', 'Estun', 7, 'Magic Attack', 'Requirement : Soul of Wizard\nเวทมนตร์ประเภท ''Es'' ใช้กับมอนเตอร์\nสร้างความเสียหายให้กับมอนเตอร์ขนาดกลางและทำให้ stun 2 วินาที\nสำหรับมอนเตอร์ขนาดเล็กและขนาดใหญ่จะได้รับความเสียหายเท่านั้น\nผลของสกิล Seven Wind ถูกนำมาคิดด้วย\nที่สกิล Lv.7, ใช้เวลาในการร่าย 3 วินาที เช่นเดียวกับสกิล Esma', '[Lv 1] Damage 5% (ใช้ SP : 18)\n[Lv 2] Damage 10% (ใช้ SP : 20)\n[Lv 3] Damage 15% (ใช้ SP : 22)\n[Lv 4] Damage 20% (ใช้ SP : 24)\n[Lv 5] Damage 25% (ใช้ SP : 26)\n[Lv 6] Damage 30% (ใช้ SP : 28)\n[Lv 7] Damage 35% (ใช้ SP : 30)'),
('SL_SMA', 'Esma', 10, 'Magic Attack', 'Requirement : Estin 7, Estun 7\nเวทมนตร์ประเภท ''Eske'' ใช้กับมอนเตอร์\nผลของสกิล Seven Wind ถูกนำมาคิดด้วย\nจะร่ายได้ก็ต่อเมื่ออยู่ในสถานะ Es\n1 Hit Damage เท่ากับ (40+LV)%,\nLV คือเลเวลของตัวละครผู้ร่าย', '[Lv 1] :8 SP, 1 Blast\n[Lv 2] :16 SP, 2 Blasts\n[Lv 3] :24 SP, 3 Blasts\n[Lv 4] :32 SP, 4 Blasts\n[Lv 5] :40 SP, 5 Blasts\n[Lv 6] :48 SP, 6 Blasts\n[Lv 7] :56 SP, 7 Blasts\n[Lv 8] :64 SP, 8 Blasts\n[Lv 9] :72 SP, 9 Blasts\n[Lv10] :80 SP, 10 Blasts'),
('SL_SWOO', 'Eswoo', 7, 'Status Magic', 'Requirement : Soul of Priest 1\nเวทมนตร์ประเภท ''Es'' ใช้กับมอนเตอร์\nย่อขนาดและความเร็วของมอนเตอร์ให้ลดลง\nเมื่อใช้กับมอนเตอร์ประเภท Boss ผลของสกิลจะเป็น  1/5 ของผลปกติ\nเมื่อใช้สกิล Eswoo ซ้ำกับมอนเตอร์ที่ได้รับสถานะนี้อยู่แล้ว ผลของสถานะจะถูกยกเลิกกลายเป็น stun ทันที', '[Lv 1] ระยะเวลา :  1 วินาที (ใช้ SP : 75)\n[Lv 2] ระยะเวลา :  2 วินาที (ใช้ SP : 65)\n[Lv 3] ระยะเวลา :  3 วินาที (ใช้ SP : 55)\n[Lv 4] ระยะเวลา :  4 วินาที (ใช้ SP : 45)\n[Lv 5] ระยะเวลา :  5 วินาที (ใช้ SP : 35)\n[Lv 6] ระยะเวลา :  6 วินาที (ใช้ SP : 25)\n[Lv 7] ระยะเวลา :  7 วินาที (ใช้ SP : 15)'),
('SL_SKE', 'Eske', 3, 'Status Magic', 'Requirement : Soul of Knight\nเวทมนตร์ประเภท ''Es'' ที่สามารถใช้กับมอนสเตอร์ได้เท่านั้น\nลดพลังป้องกันของ มอนสเตอร์ ลงครึ่งนึงและเพิ่มพลังโจมตีของมอนสเตอร์ขึ้น 4 เท่า\nอยู่ในสถานะที่สามารถร่าย Esma ได้เป็นระยะเวลา 3 วินาที', '[Lv 1] ใช้เวลาร่าย: 3 วินาที, ระยะเวลา : 10 วินาที (ใช้ SP : 45)\n[Lv 2] ใช้เวลาร่าย: 2 วินาที, ระยะเวลา : 20 วินาที (ใช้ SP : 30)\n[Lv 3] ใช้เวลาร่าย: 1 วินาที, ระยะเวลา : 30 วินาที (ใช้ SP : 15)'),
('SL_SKA', 'Eska', 3, 'Status Magic', 'Requirement : Soul of Monk 1\nเวทมนตร์ประเภท ''Es'' ใช้กับมอนเตอร์\nเปลี่ยนมอนเตอร์ให้อยู่ในสถานะ Physical Immune', '[Lv 1] ใช้เวลาร่าย: 3 วินาที ระยะเวลา : 10 วินาที (ใช้ SP : 100)\n[Lv 2] ใช้เวลาร่าย: 2 วินาที ระยะเวลา : 20 วินาที (ใช้ SP : 80)\n[Lv 3] ใช้เวลาร่าย: 1 วินาที ระยะเวลา : 30 วินาที (ใช้ SP : 60)'),
('TK_MISSION', 'Taekwon Mission', 1, 'Ranking (/taekwon)', 'Requirement : Kihop 5\nไม่สามารถใช้ได้เมื่อเปลี่ยนอาชีพเป็น Taekwon Master หรือ Soullinker\nเมื่อกดใช้สกิล ชื่อมอนเตอร์เป้าหมายจะปรากฎขึ้น\nผู้เล่นจะได้รับ 1 คะแนน เมื่อกำจัดเป้าหมายครบ 100\nชื่อมอนเตอร์เป้าหมายจะถูกสุ่มขึ้น (ยกเว้นมอนเตอร์ประเภท Mini Boss และ Boss)\nเมื่อค่าประสบการณ์ภารกิจเหลือ 0% มีโอกาสเล็กน้อยที่มอนเตอร์เป้าหมายจะเปลี่ยน\nถ้าผู้เล่นติดอันดับ 1 ใน 10 ของอาชีพ Taekwondo และมีสกิล Storm Kick,  Turn Kick,  Down Kick หรือ Counter Kick,\nผู้เล่นจะสามารถใช้สกิลต่อเนื่องกันได้\nตัวอย่างเช่น: Storm Kick>Turn Kick>Down Kick\nผู้ที่ครองตำแหน่งแชมป์และเลเวล 90 ขึ้นไป ค่า MAX HP และ MAX SP จะเพิ่มขึ้น 3 เท่าและสามารถใช้สกิลทั้งหมดของ Taekwondo Boy/ Girl ได้', NULL),
('SL_HIGH', '1st level professions'' soul', 5, 'Supportive', 'Requirement : Soul of Super Novice 5\nเรียกจิตแห่งอาชีพแรกทั้งหมด เพื่อยืมพลังของอาชีพแรกทั้งหมดมาใช้\nso that they can lend their powers to their successors.\nค่าที่ได้รับขึ้นอยู่กับเลเวลตัวละคร โดย Stat Bonus สูงสุดจะไม่มากเกินกว่า + 50', '[Lv 1] ใช้ SP : 460, ระยะเวลา : 150 วินาที\n[Lv 2] ใช้ SP : 360, ระยะเวลา : 200 วินาที\n[Lv 3] ใช้ SP : 260, ระยะเวลา : 250 วินาที\n[Lv 4] ใช้ SP : 160, ระยะเวลา : 300 วินาที\n[Lv 5] ใช้ SP : 60, ระยะเวลา : 350 วินาที'),
('GS_GLITTERING', 'Coin Flip', 5, 'Supportive', 'โยนเหรียญ ถ้าออกหัวจะได้รับ 1 coin และถ้าออกก้อยจะเสีย 1 coin สะสมได้สูงสุด 10 coins สกิลเลเวลมีผลทำให้ออกหัวบ่อยขึ้น ใช้ 1 zeny ต่อการร่ายสกิล 1 ครั้ง', NULL),
('GS_FLING', 'Coin Fling', 1, 'Offensive', 'Requirement : Coin Flip 1\nใช้ coins ในการโจมตีเป้าหมายและลดพลังป้องกัน สามารถใช้ได้สูงสุด 5 coins ค่าพลังป้องกันที่ลดขึ้นอยู่กับจำนวน coin ที่ใช้', NULL),
('GS_TRIPLEACTION', 'Triple Action', 1, 'Offensive', 'Requirement : Coin Flip 1\nใช้ 1 coin เพื่อโจมตี 3 ครั้งใส่มอนเตอร์', NULL),
('GS_BULLSEYE', 'Bull''s Eye', 1, 'Offensive', 'Requirement : Coin Flip 5\nเพิ่มความเสียหายให้กับมอนเตอร์ประเภท Demi-Human หรือ Brute สกิลนี้ต้องใช้ 1 coin โดยสร้างความเสียหาย 500% ของความเสียหายปกติและมีโอกาสติดสถานะ Coma 0.1% สถานะ Coma จะไม่มีผลกับ Boss', NULL),
('GS_MADNESSCANCEL', 'Last Stand', 1, 'Supportive', 'Requirement : Coin Flip 4\nใช้ 1 Coin เพื่อสร้างสถานะ Last Stand โดยจะได้รับ ATK  +100 และ +20% Attack Speed แต่จะอยู่แค่ 15 วินาที ไม่สามารถใช้ร่วมกับสกิล Gunslinger''s Panic ได้\nทักษะนี้ไม่สามารถใช้กับ Gunslinger''s Panic, Hot Barrel, Platinum Altar ได้', NULL),
('GS_ADJUSTMENT', 'Gunslinger''s Panic', 1, 'Supportive', 'Requirement : Coin Flip 4\nใช้ 2 coins เพื่อสร้างสถานะ Panic ให้กับ Gunslinger ทำให้ความแม่นยำ -30 แต่ +30 Flee Rate และได้รับความเสียหายจากระยะไกลลดลง 20% เป็นเวลา 20 วินาที ไม่สามารถใช้ร่วมกับสกิล Last Stand ได้', NULL),
('GS_INCREASING', 'Increase Accuracy', 1, 'Supportive', 'Requirement : Coin Flip 2\nใช้ 4 coins เพื่อเพิ่ม +20 Accuracy, +4 DEX และ +4 AGI เป็นเวลา 1 นาที', NULL),
('GS_MAGICALBULLET', 'Magicial Bullet', 1, 'Supportive', 'Requirement : Coin Flip 1\nใช้ 1 Coin เพื่อยิงกระสุนเวทย์มนตร์ สร้างความเสียหายเวทย์เพิ่มเติมเป็นเวลา 30 วินาที', NULL),
('GS_CRACKER', 'Cracker', 1, 'Supportive', 'Requirement : Coin Flip 1\nใช้ 1 coin ในการยิงเพื่อทำให้ศัตรูติดสถานะ Stun โอกาสในการติด Stun จะเพิ่มขึ้นถ้ายิงใกล้ๆ เป้าหมาย', NULL),
('GS_SINGLEACTION', 'Single Action', 10, 'Passive', 'สกิลพิเศษสำหรับ Gunslinger เพื่อเพิ่มความไวและความแม่นยำในการยิง ค่าดังกล่าวขึ้นกับสกิลเลเวล', '[Level 1] : ความแม่นยำ +2, Attack Speed + 1%\n[Level 2] : ความแม่นยำ +4, Attack Speed + 1%\n[Level 3] : ความแม่นยำ +6, Attack Speed + 2%\n[Level 4] : ความแม่นยำ +8, Attack Speed + 2%\n[Level 5] : ความแม่นยำ +10, Attack Speed + 3%\n[Level 6] : ความแม่นยำ +12, Attack Speed + 3%\n[Level 7] : ความแม่นยำ +14, Attack Speed + 4%\n[Level 8] : ความแม่นยำ +16, Attack Speed + 4%\n[Level 9] : ความแม่นยำ +18, Attack Speed + 5%\n[Level 10] : ความแม่นยำ +20, Attack Speed + 5%'),
('GS_SNAKEEYE', 'Snake Eyes', 10, 'Passive', 'เพิ่มความสามารถในการใช้อาวุธประเภท Gun ระยะโจมตีและความแม่นยำเพิ่มขึ้น', '[Level 1] : ความแม่นยำ +1, ระยะโจมตี : +1\n[Level 2] : ความแม่นยำ +2, ระยะโจมตี : +2\n[Level 3] : ความแม่นยำ +3, ระยะโจมตี : +3\n[Level 4] : ความแม่นยำ +4, ระยะโจมตี : +4\n[Level 5] : ความแม่นยำ +5, ระยะโจมตี : +5\n[Level 6] : ความแม่นยำ +6, ระยะโจมตี : +6\n[Level 7] : ความแม่นยำ +7, ระยะโจมตี : +7\n[Level 8] : ความแม่นยำ +8, ระยะโจมตี : +8\n[Level 9] : ความแม่นยำ +9, ระยะโจมตี : +9\n[Level 10] : ความแม่นยำ +10, ระยะโจมตี : +10'),
('GS_CHAINACTION', 'Chain Action', 10, 'Passive', 'Requirement : Single Action 1\nสร้างโอกาสที่จะยิงกระสุน 2 นัดเข้าใส่เป้าหมายในครั้งเดียวเมื่อใช้อาวุธประเภท Pistol โอกาสในการยิงกระสุน 1 นัดขึ้นกับสกิลเลเวล', NULL),
('GS_TRACKING', 'Tracking', 10, 'Offensive', 'Requirement : Single Action 5\nเล็งยิงไปที่เป้าหมายอย่างตั้งใจ ระยะเวลาในการร่ายและค่าความเสียหายจะเพิ่มขึ้นตามสกิลเลเวล ต้องใช้อาวุธประเภท Pistol หรือ Rifle', '[Level 1] : ATK 300%, ระยะเวลาร่าย : 0.6 วินาที\n[Level 2] : ATK 400%, ระยะเวลาร่าย : 0.7 วินาที\n[Level 3] : ATK 500%, ระยะเวลาร่าย : 0.8 วินาที\n[Level 4] : ATK 600%, ระยะเวลาร่าย : 0.9 วินาที\n[Level 5] : ATK 700%, ระยะเวลาร่าย : 1.0 วินาที\n[Level 6] : ATK 800%, ระยะเวลาร่าย : 1.1 วินาที\n[Level 7] : ATK 900%, ระยะเวลาร่าย : 1.2 วินาที\n[Level 8] : ATK 1000%, ระยะเวลาร่าย : 1.3 วินาที\n[Level 9] : ATK 1100%, ระยะเวลาร่าย : 1.4 วินาที\n[Level 10] : ATK 1200%, ระยะเวลาร่าย : 1.5 วินาที'),
('GS_DISARM', 'Disarm', 5, 'Offensive', 'Requirement : Tracking 7\nเล็งไปที่อาวุธของศัตรูเพื่อทำลายอาวุธ เป้าหมายต้องไม่เกินระยะ 9 ช่อง โอกาสในการสำเร็จขึ้นอยู่กับเลเวลของสกิล ถ้าใช้กับมอนเตอร์ ATK ของมอนเตอร์จะลดลง 25% ไม่สามารถใช้กับ Boss ได้ ต้องใช้อาวุธประเภท Pistol หรือ Rifle', NULL),
('GS_PIERCINGSHOT', 'Wounding Shot', 5, 'Offensive', 'Requirement : Tracking 5\nสร้างความเสียหายโดยไม่คิดพลังป้องกัน มีโอกาสทำให้ศัตรูติดสถานะ Bleeding\nต้องใช้อาวุธประเภท Pistol หรือ Rifle และหากใช้คู่กับ Rifle ค่าความเสียหายจะเพิ่มมากขึ้น', '[Level 1] : ATK 220% (280%), โอกาสติด Bleeding: 3%\n[Level 2] : ATK 240% (310%), โอกาสติด Bleeding: 6%\n[Level 3] : ATK 260% (340%), โอกาสติด Bleeding: 9%\n[Level 4] : ATK 280% (370%), โอกาสติด Bleeding: 12%\n[Level 5] : ATK 300% (400%), โอกาสติด Bleeding: 15%'),
('GS_RAPIDSHOWER', 'Trigger Happy Shot', 10, 'Offensive', 'Requirement : Chain Action 3\nยิงกระสุน 5 อย่างรวดเร็วไปที่เป้าหมาย ต้องใช้อาวุธประเภท Pistol และใช้กระสุน 1 นัดต่อครั้ง', '[Level 1] : ATK 550%\n[Level 2] : ATK 600%\n[Level 3] : ATK 650%\n[Level 4] : ATK 700%\n[Level 5] : ATK 750%\n[Level 6] : ATK 800%\n[Level 7] : ATK 850%\n[Level 8] : ATK 900%\n[Level 9] : ATK 950%\n[Level 10] : ATK 1000%'),
('GS_DESPERADO', 'Desperado', 10, 'Offensive', 'Requirement : Trigger Happy Shot 5\nยิงปืนอย่างบ้าคลั่งใส่ศัตรูสร้างความเสียหายได้สูงสุด 10 เป้าหมายภายใน 7 ช่องรอบตัวผู้ร่าย\nจำเป็นต้องถืออาวุธประเภท Pistol และใช้กระสุน 10 ลูกต่อครั้ง', '[Level 1] : ATK 100%\n[Level 2] : ATK 150%\n[Level 3] : ATK 200%\n[Level 4] : ATK 250%\n[Level 5] : ATK 300%\n[Level 6] : ATK 350%\n[Level 7] : ATK 400%\n[Level 8] : ATK 450%\n[Level 9] : ATK 500%\n[Level 10] : ATK 550%'),
('GS_GATLINGFEVER', 'Gatling Fever', 10, 'Supportive', 'Requirement : Trigger Happy Shot 7, Desperado 5\nเมื่ออยู่ในสถานะ Gatling Fever จะได้รับ Attack Speed และ Damage เพิ่ม แต่ค่า Flee Rate และ ความเร็วในการเคลื่อนที่ ลดลง เมื่อใช้สกิลซ้ำจะเป็นการยกเลิกสถานะ ต้องใช้อาวุธประเภท Gatling Gun', '[Level 1] : Damage +30, Attack Speed +1%, Flee Rate -5, เป็นเวลา 30 วินาที\n[Level 2] : Damage +40, Attack Speed +2%, Flee Rate -10, เป็นเวลา 45 วินาที\n[Level 3] : Damage +50, Attack Speed +3%, Flee Rate -15, เป็นเวลา 60 วินาที\n[Level 4] : Damage +60, Attack Speed +4%, Flee Rate -20, เป็นเวลา 75 วินาที\n[Level 5] : Damage +70, Attack Speed +5%, Flee Rate -25, เป็นเวลา 90 วินาที\n[Level 6] : Damage +80, Attack Speed +6%, Flee Rate -30, เป็นเวลา 105 วินาที\n[Level 7] : Damage +90, Attack Speed +7%, Flee Rate -35, เป็นเวลา 120 วินาที\n[Level 8] : Damage +100, Attack Speed +8%, Flee Rate -40, เป็นเวลา 135 วินาที\n[Level 9] : Damage +110, Attack Speed +9%, Flee Rate -45, เป็นเวลา 150 วินาที\n[Level 10] : Damage +120, Attack Speed +10%, Flee Rate -50, เป็นเวลา 165 วินาที'),
('GS_DUST', 'Crowd Control Shot', 10, 'Offensive', 'Requirement : Single Action 5\nยิงกระสุนออกไปในระยะประชิดทำให้ศัตรูกระเด็นออกไป 5 ช่อง ต้องใช้อาวุธประเภท Shotgun', '[Level 1] : ATK 150%\n[Level 2] : ATK 200%\n[Level 3] : ATK 250%\n[Level 4] : ATK 300%\n[Level 5] : ATK 350%\n[Level 6] : ATK 400%\n[Level 7] : ATK 450%\n[Level 8] : ATK 500%\n[Level 9] : ATK 550%\n[Level 10] : ATK 600%'),
('GS_FULLBUSTER', 'Full Blast', 10, 'Offensive', 'Requirement : Crowd Control Shot 3\nยิงลูกปลายทั้งหมดไปที่ศัตรู มีโอกาสทีให้ผู้ใช้ติดสถานะ Blind ต้องใช้อาวุธประเภท Shotgun ใช้กระสุน 2 ลูก', '[Level 1] : ATK 400%\n[Level 2] : ATK 500%\n[Level 3] : ATK 600%\n[Level 4] : ATK 700%\n[Level 5] : ATK 800%\n[Level 6] : ATK 900%\n[Level 7] : ATK 1000%\n[Level 8] : ATK 1100%\n[Level 9] : ATK 1200%\n[Level 10] : ATK 1300%'),
('GS_SPREADATTACK', 'Spread Shot', 10, 'Offensive', 'Requirement : Single Action 5\nมันกระจายกระสุนไปทั่วพื้นที่ขนาดใหญ่ สามารถใช้ได้เมื่อติดตั้ง Shotgun หรือ Grenade Launcher และกินกระสุน 5 นัดเมื่อใช้สกิล', '[Level 1] : ATK 230%, ขอบเขต: 3*3 ช่อง\n[Level 2] : ATK 260%, ขอบเขต : 3*3 ช่อง\n[Level 3] : ATK 290%, ขอบเขต : 3*3 ช่อง\n[Level 4] : ATK 320%, ขอบเขต : 5*5 ช่อง\n[Level 5] : ATK 350%, ขอบเขต : 5*5 ช่อง\n[Level 6] : ATK 380%, ขอบเขต : 5*5 ช่อง\n[Level 7] : ATK 410%, ขอบเขต : 7*7 ช่อง\n[Level 8] : ATK 440%, ขอบเขต : 7*7 ช่อง\n[Level 9] : ATK 470%, ขอบเขต : 7*7 ช่อง\n[Level 10] : ATK 500%, ขอบเขต : 9*9 ช่อง'),
('GS_GROUNDDRIFT', 'Gunslinger Mine', 10, 'Offensive', 'Requirement : Spread Shot 7\nใช้ปืนใหญ่สร้างกับระเบิดจะระเบิดเมื่อศัตรูเข้าใกล้ ชนิดของลูกระเบิดที่ใช้มีผลต่อสกิล จำเป็นต้องถืออาวุธประเภทปืนใหญ', '[Level 1] : 220% Atk, เป็นเวลา 3 วินาที\n[Level 2] : 240% Atk, เป็นเวลา 6 วินาที\n[Level 3] : 260% Atk, เป็นเวลา 9 วินาที\n[Level 4] : 280% Atk, เป็นเวลา 12 วินาที\n[Level 5] : 300% Atk, เป็นเวลา 15 วินาที\n[Level 6] : 320% Atk, เป็นเวลา 18 วินาที\n[Level 7] : 340% Atk, เป็นเวลา 21 วินาที\n[Level 8] : 360% Atk, เป็นเวลา 24 วินาที\n[Level 9] : 380% Atk, เป็นเวลา 27 วินาที\n[Level 10] : 400% Atk, เป็นเวลา 30 วินาที'),
('NJ_TOBIDOUGU', 'Dagger Throwing Practice', 10, 'Passive', 'เพิ่มพลังโจมตีของอาชีพ Ninja สายดาวกระจาย\nเมื่อใช้สกิล Throw Shuriken, Throw Kunai, Throw Huuma Shuriken จะเพิ่มเท่ากับ Damge แต่ละเลเวลสกิล', '[Lv 1] : Damage +3\n[Lv 2] : Damage +6\n[Lv 3] : Damage +9\n[Lv 4] : Damage +12\n[Lv 5] : Damage +15\n[Lv 6] : Damage +18\n[Lv 7] : Damage +21\n[Lv 8] : Damage +24\n[Lv 9] : Damage +27\n[Lv10] : Damage +30'),
('NJ_SYURIKEN', 'Throw Shuriken', 10, 'กายภาพระยะไกล', 'Requirement : Dagger Throwing Practice 1\nเป้าหมาย : เป้าหมาย 1 ตัว\nปา Shuriken ที่ติดตั้งอยู่ออกไป 1 ea เพื่อสร้าง Damage ให้แก่เป้าหมาย\nใช้ Shuriken ที่ติดตั้งอยู่ 1 ea ระยะโจมตีพื้นฐาน 9  ช่อง', '[Lv 1] : ATK 105%\n[Lv 2] : ATK 110%\n[Lv 3] : ATK 115%\n[Lv 4] : ATK 120%\n[Lv 5] : ATK 125%\n[Lv 6] : ATK 130%\n[Lv 7] : ATK 135%\n[Lv 8] : ATK 140%\n[Lv 9] : ATK 145%\n[Lv10] : ATK 150%'),
('NJ_KUNAI', 'Throw Kunai', 5, 'กายภาพระยะไกล', 'Requirement : Throw Shuriken 5\nเป้าหมาย : เป้าหมาย 1 ตัว\nปา Kunai ที่ติดตั้งอยู่ออกไป 1 ea เพื่อสร้าง Damage ให้แก่เป้าหมาย\nใช้ Shuriken ที่ติดตั้งอยู่ 1 ea โจมตีเป็นธาตุตาม Kunai ที่ใช้', '[Lv 1] : ATK 100%\n[Lv 2] : ATK 200%\n[Lv 3] : ATK 300%\n[Lv 4] : ATK 400%\n[Lv 5] : ATK 500%'),
('NJ_HUUMA', 'Throw Huuma Shuriken', 5, 'กายภาพระยะไกล', 'Requirement : Dagger Throwing Practice 5, Throw Kunai 5\nเป้าหมาย : เป้าหมาย 1 ตัว\nปา Shuriken ขนาดใหญ่ออกไป เพื่อโจมตีเป้าหมายและบริเวณโดยรอบ\nระยะโจมตีของสกิลมีผลจะเพิ่มขึ้นตามเลเวลสกิล และไม่ถูกขัดการร่าย แม้ว่าจะถูกโจมตีระหว่างร่าย', '[Lv 1] : ATK 200% / ขอบเขต : 3 X 3\n[Lv 2] : ATK 450% / ขอบเขต : 3 X 3\n[Lv 3] : ATK 700% / ขอบเขต : 3 X 3\n[Lv 4] : ATK 950% / ขอบเขต : 5 X 5\n[Lv 5] : ATK1200% / ขอบเขต : 5 X 5'),
('NJ_ZENYNAGE', 'Throw Coins', 10, 'Special Attack(ระยะไกล)', 'Requirement : Dagger Throwing Practice 10, Throw Huuma Shuriken 5\nเป้าหมาย : เป้าหมาย 1 ตัว\nปาเงินออกไป เพื่อสร้าง Damage ที่มองข้ามพลังป้องกันของฝ่ายตรงข้ามเท่ากับจำนวนเงินที่ปาออกไป\nแต่สำหรับ Player จะลดความเสียหายเหลือ 1/3 และสำหรับ Boss จะลดความเสียหายเหลือครึ่งหนึ่งของจำนวนเงินที่ปาออกไป', '[Lv 1] : จำนวนที่ใช้ 500~1000zeny\n[Lv 2] : จำนวนที่ใช้ 1000~2000zeny\n[Lv 3] : จำนวนที่ใช้ 1500~3000zeny\n[Lv 4] : จำนวนที่ใช้ 2000~4000zeny\n[Lv 5] : จำนวนที่ใช้ 2500~5000zeny\n[Lv 6] : จำนวนที่ใช้ 3000~6000zeny\n[Lv 7] : จำนวนที่ใช้ 3500~7000zeny\n[Lv 8] : จำนวนที่ใช้ 4000~8000zeny\n[Lv 9] : จำนวนที่ใช้ 4500~9000zeny\n[Lv10] : จำนวนที่ใช้ 5000~10000zeny'),
('NJ_TATAMIGAESHI', 'Flip Tatami', 5, 'กายภาพระยะใกล้', 'เป้าหมาย : ระยะของสกิล\nโจมตีศัตรูโดยการพลิกเสื่อทาทามิทั้ง 4 ด้านรอบตัวเอง\nศัตรูที่โดนเสื่อทาทามิ จะกระเด็นไป 5 ช่อง ผลของสกิล Pneuma จะทำงานบริเวณที่ร่ายเป็นเวลา 3 วินาที', '[Lv 1] : ระยะโจมตี 1 ช่อง, ATK 110%\n[Lv 2] : ระยะโจมตี 2 ช่อง, ATK 120%\n[Lv 3] : ระยะโจมตี 2 ช่อง, ATK 130%\n[Lv 4] : ระยะโจมตี 3 ช่อง, ATK 140%\n[Lv 5] : ระยะโจมตี 3 ช่อง, ATK 150%'),
('NJ_KASUMIKIRI', 'Haze Slasher', 10, 'กายภาพระยะใกล้', 'Requirement : Shadow Leap 1\nเป้าหมาย : เป้าหมาย 1 ตัว\nในขณะที่ทำการโจมตีเป้าหมาย หากโจมตีถูกเป้าหมายจะซ่อนตัวเองทันทีโดยอัตโนมัติ\nในระหว่างที่อยู่ในสถานะ Hiding จะเสีย SP ต่อเนื่องทุก ๆ ระยะเวลาหนึ่ง', '[Lv 1] : ATK 120%\n[Lv 2] : ATK 140%\n[Lv 3] : ATK 160%\n[Lv 4] : ATK 180%\n[Lv 5] : ATK 200%\n[Lv 6] : ATK 220%\n[Lv 7] : ATK 240%\n[Lv 8] : ATK 260%\n[Lv 9] : ATK 280%\n[Lv10] : ATK 300%'),
('NJ_SHADOWJUMP', 'Shadow Leap', 5, 'Supportive', 'Requirement : Flip Tatami 1\nเป้าหมาย : พื้น 1 ช่อง\nใช้ได้เมื่ออยู่ในสถานะ Hiding\nเคลื่อนย้ายไปยังช่องที่กำหนดในพริบตา หากเคลื่อนที่ สถานะ Hiding จะถูกยกเลิก\nไม่สามารถเคลื่อนที่ได้ แต่สามารถเคลื่อนย้ายไปยังช่องที่อยู่เกินกว่าระยะที่จะสามารถทำการโจมตีระยะไกล เช่น การโจมตีด้วย Shuriken, Arrow ได้', '[Lv 1] : ระยะเคลื่อนที่ : 6 ช่อง\n[Lv 2] : ระยะเคลื่อนที่ : 7 ช่อง\n[Lv 3] : ระยะเคลื่อนที่ : 8 ช่อง\n[Lv 4] : ระยะเคลื่อนที่ : 9 ช่อง\n[Lv 5] : ระยะเคลื่อนที่ :10 ช่อง'),
('NJ_KIRIKAGE', 'Shadow Slash', 5, 'กายภาพระยะใกล้', 'Requirement : Haze Slasher 5\nเป้าหมาย : เป้าหมาย 1 ตัว\nใช้ได้เมื่ออยู่ในสถานะ Hiding\nเข้าถึงตัวในชั่วพริบตาแล้วสร้างความเสียหายให้แก่เป้าหมายที่่อยู่ในระยะที่สามารถใช้สกิล Shadow Leap ได้\nสถานะ Hiding จะถูกยกเลิกในเวลาเดียวกับที่ใช้สกิล, มีโอกาสเกิด Critical Damage ตามโอกาสที่จำเพาะของสกิล', '[Lv 1] : ATK 200%, โอกาสเกิด Critical 30%\n[Lv 2] : ATK 350%, โอกาสเกิด Critical 35%\n[Lv 3] : ATK 500%, โอกาสเกิด Critical 40%\n[Lv 4] : ATK 650%, โอกาสเกิด Critical 45%\n[Lv 5] : ATK 800%, โอกาสเกิด Critical 50%'),
('NJ_UTSUSEMI', 'Cicada Skin Shed', 5, 'Supportive', 'Requirement : Shadow Leap 5\nเป้าหมาย : ตัวผู้ร่าย\nเมื่อใช้สกิล ผู้ร่ายจะอยู่ในสถานะ [Cicada Skin Shed] หากอยู่ในสถานะดังกล่าว เมื่อถูกโจมตี จะสามารถหลบการโจมตีได้โดยอัตโนมัติและถอยหลัง 6 ช่องในเวลาเดียวกัน\nเมื่อได้รับการโจมตีเป็นจำนวนครั้งที่กำหนดแล้ว สถานะจะถูกยกเลิก', '[Lv 1] : ระยะเวลา 20 วินาที, ได้รับการโจมตี 1 ครั้ง\n[Lv 2] : ระยะเวลา 30 วินาที, ได้รับการโจมตี 1 ครั้ง\n[Lv 3] : ระยะเวลา 40 วินาที, ได้รับการโจมตี 2 ครั้ง\n[Lv 4] : ระยะเวลา 50 วินาที, ได้รับการโจมตี 2 ครั้ง\n[Lv 5] : ระยะเวลา 60 วินาที, ได้รับการโจมตี 3 ครั้ง'),
('NJ_BUNSINJYUTSU', 'Mirror Image', 10, 'Supportive', 'Requirement : Shadow Slash 3, Ninja Aura 1, Cicada Skin Shed 4\nเป้าหมาย : ตัวผู้ร่าย\nสามารถใช้ได้เมื่ออยู่ในสถานะ [Ninja Aura] เท่านั้น\nใช้ Shadow Orb 1 ea เพื่อสร้างร่างเงาของตนเอง\nสามารถใช้ร่างเงาเพื่อหลบการโจมตีทั่วไปได้เท่ากับจำนวนหนึ่ง แต่ไม่สามารถหลบการโจมตีเวทมนตร์ได้', '[Lv 1] : หลบได้ 1 ครั้ง, ระยะเวลา 60 วินาที\n[Lv 2] : หลบได้ 1 ครั้ง, ระยะเวลา 80 วินาที\n[Lv 3] : หลบได้ 2 ครั้ง, ระยะเวลา 100 วินาที\n[Lv 4] : หลบได้ 2 ครั้ง, ระยะเวลา 120 วินาที\n[Lv 5] : หลบได้ 3 ครั้ง, ระยะเวลา 140 วินาที\n[Lv 6] : หลบได้ 3 ครั้ง, ระยะเวลา 160 วินาที\n[Lv 7] : หลบได้ 4 ครั้ง, ระยะเวลา 180 วินาที\n[Lv 8] : หลบได้ 4 ครั้ง, ระยะเวลา 200 วินาที\n[Lv 9] : หลบได้ 5 ครั้ง, ระยะเวลา 220 วินาที\n[Lv10] : หลบได้ 5 ครั้ง, ระยะเวลา 240 วินาที'),
('NJ_NINPOU', 'Ninja Mastery', 10, 'Passive', 'เมื่อหยุดอยู่กับที่ด้วยสกิล Ninja Mastery, จะฟื้นฟู SP เพิ่มเติม ทุก ๆ 10 วินาที ซึ่งจะเพิ่มขึ้นจากค่าพื้นฐานเป็นอัตราที่กำหนดโดยขึ้นอยู่กับ MaxSP\nจะไม่ทำการฟื้นฟูหากอยู่ในระหว่างการเคลื่อนที่หรืออยู่ในระหว่างที่ถูก Penalty จากการที่ปริมาณ HP/SP ที่เหลืออยู่ไม่สามารถทำการฟื้นฟู', '[Lv 1] : SP + (3 + 0.2% ของ MSP) ทุก ๆ 10 วินาที\n[Lv 2] : SP + (6 + 0.4% ของ MSP) ทุก ๆ 10 วินาที\n[Lv 3] : SP + (9 + 0.6% ของ MSP) ทุก ๆ 10 วินาที\n[Lv 4] : SP +(12 + 0.8% ของ MSP) ทุก ๆ 10 วินาที\n[Lv 5] : SP +(15 + 1.0% ของ MSP) ทุก ๆ 10 วินาที\n[Lv 6] : SP +(18 + 1.2% ของ MSP) ทุก ๆ 10 วินาที\n[Lv 7] : SP +(21 + 1.4% ของ MSP) ทุก ๆ 10 วินาที\n[Lv 8] : SP +(24 + 1.6% ของ MSP) ทุก ๆ 10 วินาที\n[Lv 9] : SP +(27 + 1.8% ของ MSP) ทุก ๆ 10 วินาที\n[Lv10] : SP +(30 + 2.0% ของ MSP) ทุก ๆ 10 วินาที'),
('NJ_KOUENKA', 'Flaming Petals', 10, 'เวทมนตร์', 'Requirement : Ninja Mastery 1\nเป้าหมาย : เป้าหมาย 1 ตัว\nสร้าง Damage เวทมตร์ธาตุไฟเท่ากับ 90% ของ MATK แก่เป้าหมายด้วยกลีบดอกไม้ไฟ', '[Lv 1] : โจมตี 1 ครั้ง\n[Lv 2] : โจมตี 2 ครั้ง\n[Lv 3] : โจมตี 3 ครั้ง\n[Lv 4] : โจมตี 4 ครั้ง\n[Lv 5] : โจมตี 5 ครั้ง\n[Lv 6] : โจมตี 6 ครั้ง\n[Lv 7] : โจมตี 7 ครั้ง\n[Lv 8] : โจมตี 8 ครั้ง\n[Lv 9] : โจมตี 9 ครั้ง\n[Lv10] : โจมตี 10 ครั้ง'),
('NJ_KAENSIN', 'Blaze Shield', 10, 'เวทมนตร์', 'Requirement : Blaze Shield 5\nเป้าหมาย : ระยะของสกิล\nใช้ Flame Stone 1 ea ทำให้เกิดพายุเพลิงในบริเวณ 5X5 รอบตนเองเพื่อสร้างความเสียหายเวทมนตร์ธาตุไฟเป็น 50% ของ MATK ให้แก่เป้าหมายที่อยู่ในขอบเขต\nระยะเวลาสกิลคือ 20 วินาที และจะหายไปหลังจากโจมตีครบจำนวนครั้งสูงสุดที่จะโจมตีได้\nแต่ช่องที่เป็นตำแหน่งของผู้ใช้สกิล จะไม่มีดอกไม้ไฟเกิดขึ้น', '[Lv 1] : โจมตี 5 ครั้งต่อ 1 ช่อง\n[Lv 2] : โจมตี 5 ครั้งต่อ 1 ช่อง\n[Lv 3] : โจมตี 6 ครั้งต่อ 1 ช่อง\n[Lv 4] : โจมตี 6 ครั้งต่อ 1 ช่อง\n[Lv 5] : โจมตี 7 ครั้งต่อ 1 ช่อง\n[Lv 6] : โจมตี 7 ครั้งต่อ 1 ช่อง\n[Lv 7] : โจมตี 8 ครั้งต่อ 1 ช่อง\n[Lv 8] : โจมตี 8 ครั้งต่อ 1 ช่อง\n[Lv 9] : โจมตี 9 ครั้งต่อ 1 ช่อง\n[Lv10] : โจมตี 9 ครั้งต่อ 1 ช่อง'),
('NJ_BAKUENRYU', 'Exploding Dragon', 5, 'เวทมนตร์', 'Requirement : Ninja Mastery 10, Blaze Shield 7\nเป้าหมาย : เป้าหมาย 1 ตัว\nใช้ Flame Stone 1 ea เพื่อสร้างความเสียหายเวทมนตร์ธาตุไฟต่อเป้าหมายและบริเวณโดยรอบในพื้นที่ 5X5', '[Lv 1] : MATK 300%\n[Lv 2] : MATK 450%\n[Lv 3] : MATK 600%\n[Lv 4] : MATK 750%\n[Lv 5] : MATK 900%'),
('NJ_HYOUSENSOU', 'Freezing Spear', 10, 'เวทมนตร์', 'Requirement : Ninja Mastery 1\nเป้าหมาย : เป้าหมาย 1 ตัว\nทำการโจมตีเป้าหมายโดยการขว้างหอกน้ำแข็งที่สร้างจากพื้นดินออกไป เพื่อสร้าง Damage เวทมนตร์ธาตุน้ำเป็น 70% ของ MATK', '[Lv 1] : โจมตี 3 ครั้ง\n[Lv 2] : โจมตี 4 ครั้ง\n[Lv 3] : โจมตี 5 ครั้ง\n[Lv 4] : โจมตี 6 ครั้ง\n[Lv 5] : โจมตี 7 ครั้ง\n[Lv 6] : โจมตี 8 ครั้ง\n[Lv 7] : โจมตี 9 ครั้ง\n[Lv 8] : โจมตี 10 ครั้ง\n[Lv 9] : โจมตี 11 ครั้ง\n[Lv10] : โจมตี 12 ครั้ง'),
('NJ_SUITON', 'Watery Evasion', 10, 'เวทมนตร์', 'Requirement : Freezing Spear 5\nเป้าหมาย : ระยะของสกิล\nใช้ Ice Stone 1 ea เพื่อสร้างแอ่งน้ำบนพื้น\nลด AGI และความเร็วเคลื่อนที่ของเป้าหมายที่เข้ามาในขอบเขตลงครึ่งหนึ่ง\nภายในระยะสกิล จะสามารถใช้สกิล Water Ball และ Aqua Benedicta ได้ ซึ่งหากใช้สกิลดังกล่าว ระยะของ Watery Evasion จะถูกลดลงเท่ากับระยะโจมตีของสกิลนั้น ๆ\nหากใช้สกิล Freezing Spear กับเป้าหมายที่อยู่ภายในระยะสกิล จะทำให้ Damage ที่ทำเพิ่มขึ้น\nผู้ใช้สกิลและผู้เล่นอาชีพนินจาคนอื่นจะไม่ถูกลด AGI และความเร็วเคลื่อนที่ภายในระยะสกิล', '[Lv 1] : ระยะโจมตี : 3X3, ระยะเวลา : 15 วินาที, AGI-0\n[Lv 2] : ระยะโจมตี : 3X3, ระยะเวลา : 20 วินาที, AGI-3\n[Lv 3] : ระยะโจมตี : 3X3, ระยะเวลา : 25 วินาที, AGI-3\n[Lv 4] : ระยะโจมตี : 5X5, ระยะเวลา : 30 วินาที, AGI-3\n[Lv 5] : ระยะโจมตี : 5X5, ระยะเวลา : 35 วินาที, AGI-5\n[Lv 6] : ระยะโจมตี : 5X5, ระยะเวลา : 40 วินาที, AGI-5\n[Lv 7] : ระยะโจมตี : 7X7, ระยะเวลา : 45 วินาที, AGI-5\n[Lv 8] : ระยะโจมตี : 7X7, ระยะเวลา : 50 วินาที, AGI-8\n[Lv 9] : ระยะโจมตี : 7X7, ระยะเวลา : 55 วินาที, AGI-8\n[Lv10] : ระยะโจมตี : 9X9, ระยะเวลา : 60 วินาที, AGI-8'),
('NJ_HYOUSYOURAKU', 'Snow Flake Draft', 5, 'เวทมนตร์', 'Requirement : Ninja Mastery 10, Watery Evasion 7\nเป้าหมาย : ระยะของสกิล\nใช้ Ice Stone 1 ea เพื่อปล่อยก้อนน้ำแข็งขนาดมหึมาลงมาจากท้องฟ้า\nสร้าง Damage เวทมนตร์ธาตุน้ำแก่เป้าหมายที่อยู่ในพื้นที่ 7X7 รอบตัวผู้ใช้สกิลและทำให้มีโอกาสติด [สถานะ : Frozen]\nโอกาสในการติดสถานะ Frozen และระยะเวลาที่ติดจะเปลี่ยนแปลงไปตามเลเวล, MDEF, และ LUK ของเป้าหมาย', '[Lv 1] : MATK 300%, โอกาสติด Frozen : 20%\n[Lv 2] : MATK 450%, โอกาสติด Frozen : 30%\n[Lv 3] : MATK 600%, โอกาสติด Frozen : 40%\n[Lv 4] : MATK 750%, โอกาสติด Frozen : 50%\n[Lv 5] : MATK 900%, โอกาสติด Frozen : 60%'),
('NJ_HUUJIN', 'Wind Blade', 10, 'เวทมนตร์', 'Requirement : Ninja Mastery 1\nเป้าหมาย : เป้าหมาย 1 ตัว\nปล่อยคมสุญญากาศออกมาเพื่อทำ Damage เวทมนตร์ธาตุลมแก่เป้าหมายเป็น 150% ของ MATK', '[Lv 1] : โจมตี 1 ครั้ง\n[Lv 2] : โจมตี 2 ครั้ง\n[Lv 3] : โจมตี 2 ครั้ง\n[Lv 4] : โจมตี 3 ครั้ง\n[Lv 5] : โจมตี 3 ครั้ง\n[Lv 6] : โจมตี 4 ครั้ง\n[Lv 7] : โจมตี 4 ครั้ง\n[Lv 8] : โจมตี 5 ครั้ง\n[Lv 9] : โจมตี 5 ครั้ง\n[Lv10] : โจมตี 6 ครั้ง'),
('NJ_RAIGEKISAI', 'Lightning Jolt', 5, 'เวทมนตร์', 'Requirement : Wind Blade 5\nเป้าหมาย : พื้น 1 ช่อง\nใช้ Wind Stone 1 ea เพื่อทำ Damage เวทมนตร์ธาตุลมในบริเวณโดยรอบโดยการฟาดสายฟ้าลงสู่ช่องที่กำหนด', '[Lv 1] : MATK 200%, ระยะโจมตี : 3X3\n[Lv 2] : MATK 300%, ระยะโจมตี : 3X3\n[Lv 3] : MATK 400%, ระยะโจมตี : 5X5\n[Lv 4] : MATK 500%, ระยะโจมตี : 5X5\n[Lv 5] : MATK 600%, ระยะโจมตี : 7X7'),
('NJ_KAMAITACHI', 'First Wind', 5, 'เวทมนตร์', 'Requirement : Ninja Mastery 10, Lightning Jolt 5\nเป้าหมาย : เป้าหมาย 1 ตัว\nใช้ Wind Stone 1 ea ในการเรียกคมวายุให้พุ่งเป็นเส้นตรงจากตำแหน่งของตนเองไปสู่ทิศทางของเป้าหมายเพื่อสร้าง Damage เวทมนตร์ธาตุลมให้แก่เป้าหมาย', '[Lv 1] : MATK 200%, ระยะสกิล : 5 ช่อง\n[Lv 2] : MATK 300%, ระยะสกิล : 6 ช่อง\n[Lv 3] : MATK 400%, ระยะสกิล : 7 ช่อง\n[Lv 4] : MATK 500%, ระยะสกิล : 8 ช่อง\n[Lv 5] : MATK 600%, ระยะสกิล : 9 ช่อง'),
('NJ_NEN', 'Ninja Aura', 5, 'Supportive', 'Requirement : Ninja Mastery 5\nเป้าหมาย : ตัวผู้ร่าย\nรวบรวมพลังภายในแล้วเปลี่ยนให้เป็นสีแดง เมื่ออยู่ในสถานะ Ninja Aura จะทำให้ INT และ STR เพิ่มขึ้น\nเมื่อใช้สกิล จะสูญเสีย 5% ของ MHP\nต้องอยู่ในสถานะ Ninja Aura เพื่อที่จะใช้สกิล Mirror Image หรือ Killing Strike, เมื่อใช้สกิล Mirror Image หรือ Killing Strike จะทำให้สถานะถูกยกเลิก', '[Lv 1] : STR, INT +1, ระยะเวลา: 30 วินาที\n[Lv 2] : STR, INT +2, ระยะเวลา: 45 วินาที\n[Lv 3] : STR, INT +3, ระยะเวลา: 60 วินาที\n[Lv 4] : STR, INT +4, ระยะเวลา: 75 วินาที\n[Lv 5] : STR, INT +5, ระยะเวลา: 90 วินาที'),
('NJ_ISSEN', 'Killing Strike', 10, 'Special Attack(ระยะไกล)', 'Requirement : Dagger Throwing Practice 7, Shadow Slash 5, Ninja Aura 1\nเป้าหมาย : เป้าหมาย 1 ตัว\nสามารถใช้ได้เมื่ออยู่ในสถานะ Ninja Aura เท่านั้น\nใช้ HP ที่เหลืออยู่ของตนเอง เพื่อสร้างสุดยอด Damage ทางกายภาพระยะไกลในนัดเดียว\nยิ่งมี HP เหลืออยู่มากเท่าไหร่ ก็จะยิ่งทำให้สร้าง Damage ได้สูงมากเท่านั้น, เมื่อใช้สกิล จะทำให้ HP เหลือ 1%\nหากอยู่ในสถานะ Mirror Image จำนวนครั้งในการโจมตีและ Damage จะเพิ่มขึ้นตามจำนวนร่างเงา', NULL),
