('RK_ABUNDANCE', '', NULL, NULL, NULL, NULL),
('RK_PHANTOMTHRUST', 'Phantom Thrust', 5, 'Offensive', 'Requirement : Brandish Spear 2\nสามารถใช้สกิลนี้ได้เมื่อสวมใส่อาวุธประเภท หอก เท่านั้น ช่วยดึงเป้าหมายที่อยู่ไกลเข้าหาตัวได้ สามารถใช้กับผู้เล่นในปาร์ตี้เดียวกันได้้', '[Level 1] : ระยะของสกิล5 ช่อง / พลังโจมตี 50%\n[Level 2] : ระยะของสกิล6 ช่อง / พลังโจมตี 100%\n[Level 3] : ระยะของสกิล7 ช่อง / พลังโจมตี 150%\n[Level 4] : ระยะของสกิล8 ช่อง / พลังโจมตี 200%\n[Level 5] : ระยะของสกิล9 ช่อง / พลังโจมตี 250%'),
('GC_VENOMIMPRESS', 'Venom Impression', 5, 'Active / Debuff', 'Requirement : Enchant Poison 3\nลดพลังป้องกันต่อธาตุพิษ ของเป้าหมายลง ระยะสกิล 10 ช่อง', '[Level 1] : ลดพลังป้องกันธาตุพิษลง 10%\n[Level 2] : ลดพลังป้องกันธาตุพิษลง 20%\n[Level 3] : ลดพลังป้องกันธาตุพิษลง 30%\n[Level 4] : ลดพลังป้องกันธาตุพิษลง 40%\n[Level 5] : ลดพลังป้องกันธาตุพิษลง 50%'),
('GC_CROSSIMPACT', 'Cross Impact', 5, 'Offensive', 'Requirement : Sonic Blow 10\nโจมตีเป้าหมายอย่างรวมเร็วเป็นจำนวน 7 ครั้ง ค่าความเสียหายขึ้นอยู่กับ Base Lv.ของผู้ใช้ ระยะโจมตี 3 ช่อง', '[Level 1] : ความเสียหาย 1100%\n[Level 2] : ความเสียหาย 1200%\n[Level 3] : ความเสียหาย 1300%\n[Level 4] : ความเสียหาย 1400%\n[Level 5] : ความเสียหาย 1500%'),
('GC_DARKILLUSION', 'Dark Illusion', 5, 'Active / Damage - Special', 'Requirement : Cross Impact 3\nเคลื่อนที่อย่างรวดเร็วไปยังเป้าหมายแล้วทำการโจมตี มีโอกาสเล็กน้อยที่จะใช้สกิล Cross Impact ต่อเนื่องจากสกิลนี้ ไม่สามารถใช้ได้ใน Siege map', '[Level 1] : ความเสียหาย 100% / ระยะสกิลสูงสุด 5 ช่อง\n[Level 2] : ความเสียหาย 100% / ระยะสกิลสูงสุด 6 ช่อง\n[Level 3] : ความเสียหาย 100% / ระยะสกิลสูงสุด 7 ช่อง\n[Level 4] : ความเสียหาย 100% / ระยะสกิลสูงสุด 8 ช่อง\n[Level 5] : ความเสียหาย 100% / ระยะสกิลสูงสุด 9 ช่อง'),
('GC_RESEARCHNEWPOISON', 'New Poison Research', 10, 'Passive', 'Requirement : Basic Skill of Guillotine Cross\nศึกษาการสร้างพิษชนิดใหม่ สกิลเลเวลที่สูงขึ้นจะเพิ่มโอกาสสำเร็จในการสร้าง และเพิ่มชนิดของพิษที่สร้างได้  โดยในการสร้างไอเทมพิษแต่ละชนิด ต้องการไอเทมพื้นฐานก่อนจึงจะสร้างได้ซึ่งได้แก่ Medicine Bowl และ Poison Kit และสกิลนี้สามารถช่วยเพิ่มระยะเวลาของสกิืล Enchant Deadly Poison ได้ เลเวลละ 3 วินาที', '[Level 1] : โอกาศสำเร็จ 35% / Paralyze (Paralyzing Poison) - Poison Toad''s Skin 20 , Amoena 1\n[Level 2] : โอกาศสำเร็จ 40% / Pyrexia (Pyrexia Poison) - Anolian''s Skin 20 , Rantana 1\n[Level 3] : โอกาศสำเร็จ 45% / Death Hurt (Wound Polluting Poison) - Decayed Nail 25 , Seratum 1\n[Level 4] : โอกาศสำเร็จ 50% / Leech End (Leech Poison) - Scopolia 1, Nerium 1\n[Level 5] : โอกาศสำเร็จ 55% / Antidote (Detoxification) - Green Herb 2 , Blue Herb 1, White Herb 1\n[Level 6] : โอกาศสำเร็จ 60% / Venom Bleed (Weakening Poison) - Sticky Poison 10, Izidor 1\n[Level 7] : โอกาศสำเร็จ 65% / Magic Mushroom (Laughing Mushroom Poison) - Poison Spore 10, Makulata 1\n[Level 8] : โอกาศสำเร็จ 70% / Toxin (Paralyzing Poison) - Sticky Poison 10 , Nerium 1\n[Level 9] : โอกาศสำเร็จ 75% / Oblivion Curse - Heart Of Mermaid 10 , Izidor 1\n[Level 10] : โอกาศสำเร็จ 80% / -'),
('GC_CREATENEWPOISON', 'New Poison Creation', 1, 'Active', 'Requirement : New Poison Research 1\nใช้ในการผสมพิษชนิดใหม่ที่ได้ทำการค้นคว้ามา เมื่อกดผสมจะแสดงส่วนผสมที่ต้องการใช้ ตามพิษแต่ละชนิด', NULL),
('GC_ANTIDOTE', 'Anti Dote', 1, 'Active / Detoxification', 'Requirement : New Poison Research 5\nต้องการ Antidote ในการใช้สกิล จะเป็นการถอนพิษให้เป้าหมาย หรือตัวผู้ใช้ที่ได้รับผลจากพิษของ Guillotine Cross', NULL),
('GC_POISONINGWEAPON', 'Poisonous Weapon', 5, 'Active / Buff', 'Requirement : New Poison Research 1\nเคลือบอาวุธด้วยพิษของ Guillotine Cross เมื่อโจมตีมีโอกาสทำให้เป้าหมายติดพิษที่เคลือบเอาไว้', '[Level 1] : โอกาสติดพิษ 4%  / ระยะเวลา 60 วินาที\n[Level 2] : โอกาสติดพิษ 6%  / ระยะเวลา 120 วินาที\n[Level 3] : โอกาสติดพิษ 8%  / ระยะเวลา 180 วินาที\n[Level 4] : โอกาสติดพิษ 10%  / ระยะเวลา 240 วินาที\n[Level 5] : โอกาสติดพิษ 12%  / ระยะเวลา 300 วินาที'),
('GC_WEAPONBLOCKING', 'Weapon Blocking', 5, 'Active / Buff', 'Requirement : Lefthand Mastery 5\nมีโอกาสที่จะบล็อคการโจมตีทางกายภาพระยะใกล้อย่างสมบูรณ์ เมื่อการโจมตีถูกบล็อคสามารถกดใช้สกิล Counter Slash หรือ Weapon Crush ต่อได้ ระหว่างใช้สกิลนี้ SP จะลดลงเรื่อยๆ และการกดใช้อีก ครั้งจะเป็นการยกเลิกดผลของสกิล', '[Level 1] : โอกาสสำเร็จ 12% / ระยะเวลา 180 วินาที\n[Level 2] : โอกาสสำเร็จ 14% / ระยะเวลา 180 วินาที\n[Level 3] : โอกาสสำเร็จ 16% / ระยะเวลา 180 วินาที\n[Level 4] : โอกาสสำเร็จ 18% / ระยะเวลา 180 วินาที\n[Level 5] : โอกาสสำเร็จ 20% / ระยะเวลา 180 วินาที'),
('GC_COUNTERSLASH', 'Counter Slash', 5, 'Active / Buff', 'Requirement : Weapon Blocking 1\nเมื่อการโจมตีถูกสกัดด้วยสกิล Weapon Blocking จะสามารถกดใช้สกิลนี้โต้ตอบได้ สร้างความเสียหายแก่เป้าหมายในระยะ 3x3 ช่องโดยรอบ ความเสียหายของสกิลนี้ขึ้นอยู่กับค่า BaseLV, JobLV, และ AGI', '[Level 1] : พลังโจมตี 400%\n[Level 2] : พลังโจมตี 500%\n[Level 3] : พลังโจมตี 600%\n[Level 4] : พลังโจมตี 700%\n[Level 5] : พลังโจมตี 800%'),
('GC_WEAPONCRUSH', 'Weapon Crush', 5, 'Active / Debuff', 'Requirement : Weapon Blocking 1\nเมื่อการโจมตีถูกสกัดด้วยสกิล Weapon Blocking จะสามารถกดใช้สกิลนี้โต้ตอบได้ เมื่อใช้จะเป็นการปลดอาวุธเป้าหมาย เลเวลสกิลที่สูงขึ้นจะเพิ่มโอกาสสำเร็จและระยะเวลา', NULL),
('GC_VENOMPRESSURE', 'Venom Pressure', 5, 'Active / Buff', 'Requirement : Weapon Blocking 1, Poisoning Weapon 3\nเมื่อทำการเคลือบพิษที่อาวุธแล้ว จะมีโอกาสสูงที่จะทำให้เป้าหมายติดสถานะพิษที่เคลือบไว้ และเมื่อใช้ผลของสถานะ Poisoning Weapon จะหายไป', '[Level 1] : โอกาสติดพิษ 75% / Hit เพิ่มขึ้น +14\n[Level 2] : โอกาสติดพิษ 80% / Hit เพิ่มขึ้น +18\n[Level 3] : โอกาสติดพิษ 85% / Hit เพิ่มขึ้น +22\n[Level 4] : โอกาสติดพิษ 90% / Hit เพิ่มขึ้น +26\n[Level 5] : โอกาสติดพิษ 95% / Hit เพิ่มขึ้น +30'),
('GC_POISONSMOKE', 'Poisonous Smoke', 5, 'Active / Buff', 'Requirement : Venom Pressure 5 , Poisoning Weapon 5\nเมื่อทำการเคลือบพิษลงบนอาวุธ จะทำการสร้างควันพิษเป็นระยะ 5x5 ช่อง ทุกๆ 2 วินาทีจะทำให้เป้าหมายมีโอกาส 50% ที่จะติดพิษนั้นๆ และเมื่อใช้ผลของสถานะ Poisoning Weapon จะหายไป, ระยะของ 5 X 5 ช่อง', '[Level 1] : ระยะเวลา 10 วินาที\n[Level 2] : ระยะเวลา 12 วินาที\n[Level 3] : ระยะเวลา 14 วินาที\n[Level 4] : ระยะเวลา 16 วินาที\n[Level 5] : ระยะเวลา 18 วินาที'),
('GC_CLOAKINGEXCEED', 'Cloaking Exceed', 5, 'Active / Special', 'Requirement : Cloaking 3\nสกิลนี้จะต่างจาก Cloaking ปกติตรงที่สามารถซ่อนตัวจากเผ่าแมลงและปิศาจได้ และขณะใช้สกิลจะสามารถถูกโจมตีได้ 3 ครั้งโดยที่ไม่เปิดเผยตัว เลเวลสกิลที่สูงขึ้นจะเพิ่มความเร็วและจำนวนครั้งที่ถูกโจมตีโดยไม่เปิดเผยตัว', '[Level 1] : เสีย SP 9 หน่วยต่อวินาที : ความเร็วในการเคลื่อนที่ 100 % : สามารถรับการโจมตีได้ 1 ครั้ง\n[Level 2] : เสีย SP 8 หน่วยต่อวินาที : ความเร็วในการเคลื่อนที่ 110 % : สามารถรับการโจมตีได้ 1 ครั้ง\n[Level 3] : เสีย SP 7 หน่วยต่อวินาที : ความเร็วในการเคลื่อนที่ 120 % : สามารถรับการโจมตีได้ 2 ครั้ง\n[Level 4] : เสีย SP 6 หน่วยต่อวินาที : ความเร็วในการเคลื่อนที่ 130 % : สามารถรับการโจมตีได้ 2 ครั้ง\n[Level 5] : เสีย SP 5 หน่วยต่อวินาที : ความเร็วในการเคลื่อนที่ 140 % : สามารถรับการโจมตีได้ 3 ครั้ง'),
('GC_PHANTOMMENACE', 'Phantom Menace', 1, 'Active / Detecting', 'Requirement : Dark Illusion 5 , Cloaking Exceed 5\nโจมตีออกมาจากเงาสร้างความเสียหาย 300% แก่เป้าหมายในระยะ 7x7 ช่องและยกเลิกสถานะซ่อนตัวของเป้าหมายทุกตัวที่ถูกโจมตี', NULL),
('GC_HALLUCINATIONWALK', 'Hallucination Walk', 5, 'Active / Buff', 'Requirement : Phantom Menace 1\nเพิ่มความเร้วให้ผู้ใช้ชั่วขณะ ทำให้อัตราการหลบหลีกสูงขึ้นทั้งต่อการโจมตีทางกายภาพและเวทย์มนตร์ ต้องการ HP ในการใช้สกิล  เมื่อหมดผลของสกิล ความเร็วในการเคลื่อนไหวและโจมตีจะลดลงครึ่งนึง เป็นระยะเวลา 25 วินาที', '[Level 1] : อัตราการหลบหลีก + 50 : อัตราการหลบหลีกเวทย์มนตร์ 10 %\n[Level 2] : อัตราการหลบหลีก + 100 : อัตราการหลบหลีกเวทย์มนตร์ 20 %\n[Level 3] : อัตราการหลบหลีก + 150 : อัตราการหลบหลีกเวทย์มนตร์ 30 %\n[Level 4] : อัตราการหลบหลีก + 200 : อัตราการหลบหลีกเวทย์มนตร์ 40 %\n[Level 5] : อัตราการหลบหลีก + 250 : อัตราการหลบหลีกเวทย์มนตร์ 50 %'),
('GC_ROLLINGCUTTER', 'Rolling Cutter', 5, 'Active / Damage', 'Requirement : Sonic Blow 10\nใช้ได้เมื่อสวมใส่ Katar เท่านั้น, เมื่อกดใช้จะเป็นการโจมตีด้วย Katar หมุนเวียนในระยะ ส่งผลให้เป้าหมายในระยะได้รับความเสียหาย  ทุกครั้งที่การหมุนเวียนเกิดขึ้นจะเพิ่มค่า spinning count ซึ่งส่งผลต่อพลังโจมตีของสกิล Cross Ripper Slasher โดยที่ค่าดังกล่าวจะไม่เกิน 10', '[Level 1] : พลังโจมตี 100% / ระยะของสกิล 3 x 3 ช่อง\n[Level 2] : พลังโจมตี 150% / ระยะของสกิล 3 x 3 ช่อง\n[Level 3] : พลังโจมตี 200% / ระยะของสกิล 3 x 3 ช่อง\n[Level 4] : พลังโจมตี 250% / ระยะของสกิล 3 x 3 ช่อง\n[Level 5] : พลังโจมตี 300% / ระยะของสกิล 5 x 5 ช่อง'),
('GC_CROSSRIPPERSLASHER', 'Cross Ripper Slasher', 5, 'Active / Damage', 'Requirement : Rolling Cutter 1\nต้องการค่า spinning count ที่สะสมมาจากสกิล Rolling Cutter เป็นการหมุนใบมีดเพื่อโจมตีเป้าหมายอย่างรุนแรง ความเสียหายจะเพิ่มขึ้นตามจำนวนค่า Rotation Counter และ AGI หลังจากใช้สกิลนี้ค่าดังกล่าวจะเหลือ 0 ระยะของสกิล 7 ช่อง', '[Level 1] : พลังโจมตี 480% / ระยะของสกิล 9 ช่อง\n[Level 2] : พลังโจมตี 560% / ระยะของสกิล 10 ช่อง\n[Level 3] : พลังโจมตี 640% / ระยะของสกิล 11 ช่อง\n[Level 4] : พลังโจมตี 720% / ระยะของสกิล 12 ช่อง\n[Level 5] : พลังโจมตี 800% / ระยะของสกิล 13 ช่อง'),
('AB_JUDEX', 'Judex', 5, 'Holy Property Magic', 'Requirement : Turn Undead 1\nโจมตีศัตรูรอบเป้าหมาย 3x3 ช่อง ด้วยเวทย์มนตร์ธาตุศักดิ์สิทธิ์', '[Level 1] : MATK 300%\n[Level 2] : MATK 320%\n[Level 3] : MATK 340%\n[Level 4] : MATK 360%\n[Level 5] : MATK 400%'),
('AB_ANCILLA', 'Ancilla', 1, 'Create Ancilla', 'Requirement : Clementia 3\nสร้างหินเวทย์มนตร์ที่เรียกว่า ''Ancilla'' ใช้ SP 30% ในการสร้าง พกได้สูงสุด 3 ชิ้น ใช้ Blue Gemstone 1 ea ในการใช้สกิล', NULL),
('AB_ADORAMUS', 'Adoramus', 10, 'Holy Property Magic', 'Requirement : Judex 5, Ancilla 1, Magnus Exorcismus 1\nสร้างความเสียหายรอบตัวด้วยแสงศักดิ์สิทธิ์  ทำให้เป้าหมายตาบอด และ ลด AGI ของเป้าหมาย ต้องการ Blue Gemstone 1 ea ในการใช้สกิล แต่ถ้ามีตัวละคร Acolyte Class อยู่ใกล้ๆ จะไม่ต้องเสีย Blue Gemstone แต่จะใช้ SP สูงขึ้น', '[Level 1] : MATK 600%\n[Level 2] : MATK 700%\n[Level 3] : MATK 800%\n[Level 4] : MATK 900%\n[Level 5] : MATK 1000%\n[Level 6] : MATK 1100%\n[Level 7] : MATK 1200%\n[Level 8] : MATK 1300%\n[Level 9] : MATK 1400%\n[Level10] : MATK 1500%'),
('AB_CLEMENTIA', 'Clementia', 3, 'Supportive', 'Requirement : Blessing 1\nผู้เล่นในปาร์ตี้และผู้เล่นที่เป็นมิตรที่อยู่ในระยะจะได้รับผลของสกิล Blessing , โดยผลของสกิลเพิ่มขึ้นตาม Job Lv ของผู้ใช้', '[Level 1] : ระยะ 3 ช่อง / เป็นระยะเวลา 120 วินาที\n[Level 2] : ระยะ 7 ช่อง / เป็นระยะเวลา 180 วินาที\n[Level 3] : ระยะ 15 ช่อง / เป็นระยะเวลา 240 วินาที'),
('AB_CANTO', 'Cantocandidus', 3, 'Supportive', 'Requirement : Increase AGI 1\nผู้เล่นในปาร์ตี้และผู้เล่นที่เป็นมิตรที่อยู่ในระยะจะได้รับผลของสกิล Increase AGI , โดยผลของสกิลเพิ่มขึ้นตาม Job Lv ของผู้ใช้', '[Level 1] : ระยะ 3 ช่อง / เป็นระยะเวลา 120 วินาที\n[Level 2] : ระยะ 7 ช่อง / เป็นระยะเวลา 180 วินาที\n[Level 3] : ระยะ 15 ช่อง / เป็นระยะเวลา 240 วินาที'),
('AB_CHEAL', 'Coluseo Heal', 3, 'Heal', 'Requirement : Heal 1\nผู้เล่นในปาร์ตี้และผู้เล่นที่เป็นมิตรที่อยู่ในระยะจะได้รับผลการฟื้นฟู HP จากสกิล Heal , ผลของสกิลเพิ่มขึ้นตามจำนวนสมาชิกในปาร์ตี้', '[Level 1] : ระยะ 3 ช่อง\n[Level 2] : ระยะ 7 ช่อง\n[Level 3] : ระยะ 15 ช่อง'),
('AB_EPICLESIS', 'Epiclesis', 5, 'Summon', 'Requirement : Ancilla 1, Highness Heal 1\nเรียกต้นไม้แห่งชีวิตขึ้นมาเพื่อชุบชิวิตคนตายและฟื้นฟู HP/SP  มอนสเตอร์ประเภท Demon และ Undead จะได้รับความเสียหายเมื่อเข้ามาใกล้ต้นไม้นี้  [ ต้องการ Ancilla 1 ea + Holy Water 1 ea ]', '[Level 1] : Max HP เพิ่มขึ้น 5% / ฟื้นฟู HP 3% ต่อ 1 วินาที / ฟื้นฟู SP 2%\n[Level 2] : Max HP เพิ่มขึ้น 10% / ฟื้นฟู HP 3% ต่อ 1 วินาที / ฟื้นฟู SP 2%\n[Level 3] : Max HP เพิ่มขึ้น 15% / ฟื้นฟู HP 4% ต่อ 1 วินาที / ฟื้นฟู SP 3%\n[Level 4] : Max HP เพิ่มขึ้น 20% / ฟื้นฟู HP 4% ต่อ 1 วินาที / ฟื้นฟู SP 3%\n[Level 5] : Max HP เพิ่มขึ้น 25% / ฟื้นฟู HP 5% ต่อ 1 วินาที / ฟื้นฟู SP 4%'),
('AB_PRAEFATIO', 'Praefatio', 10, 'Supportive', 'Requirement : Kyrie Eleison 1\nสมาชิกทุกคนในปาร์ตี้จะได้รับผลของสกิล Kyrie Eleison , ผลของสกิลเพิ่มขึ้นตามจำนวนสมาชิกในปาร์ตี้', '[Level 1] : ป้องกันทั้งหมด 7 ครั้ง\n[Level 2] : ป้องกันทั้งหมด 8 ครั้ง\n[Level 3] : ป้องกันทั้งหมด 9 ครั้ง\n[Level 4] : ป้องกันทั้งหมด 10 ครั้ง\n[Level 5] : ป้องกันทั้งหมด 11 ครั้ง\n[Level 6] : ป้องกันทั้งหมด 12 ครั้ง\n[Level 7] : ป้องกันทั้งหมด 13 ครั้ง\n[Level 8] : ป้องกันทั้งหมด 14 ครั้ง\n[Level 9] : ป้องกันทั้งหมด 15 ครั้ง\n[Level10] : ป้องกันทั้งหมด 16 ครั้ง'),
('AB_ORATIO', 'Oratio', 10, 'Debuff', 'Requirement : Praefatio 5\nลดพลังป้องกันธาตุศักดิ์สิทธิ์ของเป้าหมายทั้งหน้าจอลง (โดนโจมตีด้วยธาตุศักดิ์สิทธิ์แรงขึ้น)', '[Level 1] : โอกาสสำเร็จ 45% / ลดพลังป้องกันธาตุศักดิ์สิทธิ์ลง 2%\n[Level 2] : โอกาสสำเร็จ 50% / ลดพลังป้องกันธาตุศักดิ์สิทธิ์ลง 4%\n[Level 3] : โอกาสสำเร็จ 55% / ลดพลังป้องกันธาตุศักดิ์สิทธิ์ลง 6%\n[Level 4] : โอกาสสำเร็จ 60% / ลดพลังป้องกันธาตุศักดิ์สิทธิ์ลง 8%\n[Level 5] : โอกาสสำเร็จ 65% / ลดพลังป้องกันธาตุศักดิ์สิทธิ์ลง 10%\n[Level 6] : โอกาสสำเร็จ 70% / ลดพลังป้องกันธาตุศักดิ์สิทธิ์ลง 12%\n[Level 7] : โอกาสสำเร็จ 75% / ลดพลังป้องกันธาตุศักดิ์สิทธิ์ลง 14%\n[Level 8] : โอกาสสำเร็จ 80% / ลดพลังป้องกันธาตุศักดิ์สิทธิ์ลง 16%\n[Level 9] : โอกาสสำเร็จ 85% / ลดพลังป้องกันธาตุศักดิ์สิทธิ์ลง 18%\n[Level10] : โอกาสสำเร็จ 90% / ลดพลังป้องกันธาตุศักดิ์สิทธิ์ลง 20%'),
('AB_LAUDAAGNUS', 'Laudaagnus', 4, 'Recover', 'Requirement : Recovery 1\nรักษาสถานะ Freeze, Stone, Dark, Frost, Cold, Burn ให้กับสมาชิกทั้งหมดภายในปาร์ตี้ และเพิ่มค่า VIT ให้แก่สมาชิกภายใน Party ด้วย', '[Level 1] : โอกาสสำเร็จ 50%\n[Level 2] : โอกาสสำเร็จ 60%\n[Level 3] : โอกาสสำเร็จ 70%\n[Level 4] : โอกาสสำเร็จ 80%'),
('AB_LAUDARAMUS', 'Laudaramus', 4, 'Recover', 'Requirement : Laudaagnus 2\nรักษาสถานะ Slience, Sleep, Stun, และ Deep Sleep จาก Mandragora Curse ให้กับสมาชิกทั้งหมดภายในปาร์ตี้ และเพิ่มค่า LUK ให้แก่สมาชิกภายใน Party ด้วย', '[Level 1] : โอกาสสำเร็จ 50%\n[Level 2] : โอกาสสำเร็จ 60%\n[Level 3] : โอกาสสำเร็จ 70%\n[Level 4] : โอกาสสำเร็จ 80%'),
('AB_EUCHARISTICA', 'Eucharistica', 10, 'Passive', 'Requirement : Epiclesis 1, Expiatio 1\nพิ่มพลังโจมตีและลดความเสียหายที่ได้รับจากมอนสเตอร์เผ่า Demon และ Undead', '[Level 1] : เพิ่มความเสียหาย  +1% /ลดความเสียหายลง 1%\n[Level 2] : เพิ่มความเสียหาย  +2% / ลดความเสียหายลง 2%\n[Level 3] : เพิ่มความเสียหาย  +3% / ลดความเสียหายลง 3%\n[Level 4] : เพิ่มความเสียหาย  +4% / ลดความเสียหายลง 4%\n[Level 5] : เพิ่มความเสียหาย +5% / ลดความเสียหายลง 5%\n[Level 6] : เพิ่มความเสียหาย  +6% / ลดความเสียหายลง 6%\n[Level 7] : เพิ่มความเสียหาย  +7% / ลดความเสียหายลง 7%\n[Level 8] : เพิ่มความเสียหาย  +8% / ลดความเสียหายลง 8%\n[Level 9] : เพิ่มความเสียหาย  +9% / ลดความเสียหายลง 9%\n[Level10] : เพิ่มความเสียหาย  +10% / ลดความเสียหายลง 10%'),
('AB_RENOVATIO', 'Renovatio', 1, 'Heal', 'Requirement : Coluseo Heal 3\nฟื้นฟู Hp 3 % เป็นเวลา 35 วินาที หากใช้กับ มอนสเตอร์ธาตุ Undead จะเป็นการสร้างความเสียหายแทน โดยเลเวลของผู้ใช้มีผลต่อความรุนแรง', NULL),
('AB_HIGHNESSHEAL', 'Highness Heal', 5, 'Heal', 'Requirement : Renovatio 1\nฟื้นฟู HP ให้แก่ 1 เป้าหมาย โดยอัตราฟื้นฟูจะสูงกว่า Heal', '[Level 1] : Heal แรงขึ้น 2x\n[Level 2] : Healแรงขึ้น 2.3x\n[Level 3] : Healแรงขึ้น 2.6x\n[Level 4] : Healแรงขึ้น 2.9x\n[Level 5] : Healแรงขึ้น 3.2x'),
('AB_CLEARANCE', 'Clearance', 5, 'Special', 'Requirement : Laudaramus 2\nยกเลิกสถานะผิดปกติและสกิลซัพพอร์ตทั้งหมดแก่สมาชิกในปาร์ตี้และศัตรูในหน้าจอ', '[Level 1] : โอกาสสำเร็จ 68%\n[Level 2] : โอกาสสำเร็จ 76%\n[Level 3] : โอกาสสำเร็จ 84%\n[Level 4] : โอกาสสำเร็จ 92%\n[Level 5] : โอกาสสำเร็จ 100%'),
('AB_EXPIATIO', 'Expiatio', 5, 'Supportive', 'Requirement : Oratio 5  Duple Light 5\nมอบพลังอันศักดิ์สิทธิ์ให้แก่อาวุธของเป้าหมาย ช่วยให้โจมตีเป้าหมายทางกายภาพระยะใกล้ โดยไม่คำนึงถึงพลังป้องกันบางส่วนของศัตรู', '[Level 1] : โจมตีทะลุพลังป้องกันของเป้าหมาย  5% / 150 วินาที\n[Level 2] : โจมตีทะลุพลังป้องกันของเป้าหมาย  10% / 180 วินาที\n[Level 3] : โจมตีทะลุพลังป้องกันของเป้าหมาย  15% / 210 วินาที\n[Level 4] : โจมตีทะลุพลังป้องกันของเป้าหมาย  20% / 240 วินาที\n[Level 5] : โจมตีทะลุพลังป้องกันของเป้าหมาย  25% / 270 วินาที'),
('AB_DUPLELIGHT', 'Duple Light', 10, 'Active', 'Requirement : Aspersio 1\nเมื่อโจมตีศัตรูในระยะใกล้ จะเรียกแสงศักดิ์สิทธิ์ 2 ดวง ออกมาช่วยโจมตี', '[Level 1] : สร้างความเสียหายทางกายภาพ 110% /MATK 220% / ระยะเวลา 90 วินาที\n[Level 2] : สร้างความเสียหายทางกายภาพ 120% /MATK 240% / ระยะเวลา 120 วินาที\n[Level 3] : สร้างความเสียหายทางกายภาพ 130% /MATK 260% / ระยะเวลา 150 วินาที\n[Level 4] : สร้างความเสียหายทางกายภาพ 140% /MATK 280% / ระยะเวลา 180 วินาที\n[Level 5] : สร้างความเสียหายทางกายภาพ 150% /MATK 300% / ระยะเวลา 210 วินาที\n[Level 6] : สร้างความเสียหายทางกายภาพ 160% /MATK 320% / ระยะเวลา 240 วินาที\n[Level 7] : สร้างความเสียหายทางกายภาพ 170% /MATK 340% / ระยะเวลา 270 วินาที\n[Level 8] : สร้างความเสียหายทางกายภาพ 180% /MATK 360% / ระยะเวลา 300 วินาที\n[Level 9] : สร้างความเสียหายทางกายภาพ 190% /MATK 380% / ระยะเวลา 330 วินาที\n[Level10] : สร้างความเสียหายทางกายภาพ 200% /MATK 400% / ระยะเวลา 360 วินาที'),
('AB_DUPLELIGHT_MELEE', '', NULL, NULL, NULL, NULL),
('AB_DUPLELIGHT_MAGIC', '', NULL, NULL, NULL, NULL),
('AB_SILENTIUM', 'Silentium', 5, 'Debuff', 'Requirement : Clearance 1\nศัตรูที่อยู่รอบเป้าหมายจะได้รับผลของ Lex Divina', '[Level 1] : ระยะ  9 x 9\n[Level 2] : ระยะ  11 x 11\n[Level 3] : ระยะ  13 x 13\n[Level 4] : ระยะ  15 x 15\n[Level 5] : ระยะ  17 x 17'),
('WL_WHITEIMPRISON', 'White Imprison', 5, 'Curse', 'Requirement : Soul Expansion 3\nผนึกเป้าหมายไว้ด้วยม่านเวทย์มนต์ ทำให้เป้าหมายไม่สามารถเคลื่อนไหวได้  โดยเมื่ออยู่ในสถานะนี้เป้าหมายจะไม่ได้รับความเสียหายจากธาตุต่างๆ ยกเว้นธาตุวิญญาณ และสกิลที่สร้างความเสียหายคงที่เช่น Gravitation Field , เมื่อสิ้นสุดสถานะ เป้าหมายที่ใช้สกิล จะเสีย HP ลงบางส่วน ไม่มีผลกับ Boss type', '[Level 1] : โอกาสสำเร็จ  50% / 10 วินาที\n[Level 2] : โอกาสสำเร็จ  60% / 12 วินาที\n[Level 3] : โอกาสสำเร็จ  70% / 14 วินาที\n[Level 4] : โอกาสสำเร็จ  80% / 16 วินาที\n[Level 5] : โอกาสสำเร็จ  90% / 18 วินาที'),
('WL_SOULEXPANSION', 'Soul Expansion', 5, 'Active / Damage', 'Requirement : Drain Life 1\nสร้างความเสียหายธาตุวิญญาณระยะไกล เมื่อเป้าหมายอยู่ในสถานะ White Imprison จะได้รับความเสียหาย 2 เท่า', '[Level 1] : สร้างความเสียหายธาตุวิญญาณ 500% ของ MATK\n[Level 2] : สร้างความเสียหายธาตุวิญญาณ 600% ของ MATK\n[Level 3] : สร้างความเสียหายธาตุวิญญาณ 700% ของ MATK\n[Level 4] : สร้างความเสียหายธาตุวิญญาณ 800% ของ MATK\n[Level 5] : สร้างความเสียหายธาตุวิญญาณ 900% ของ MATK'),
('WL_FROSTMISTY', 'Frost Misty', 5, 'Debuff', 'Requirement : Summon Waterball 1\nสร้างละอองหมอกเยือกแข็ง เป็นระยะ 15x15 ช่องทำให้เป้าหมายที่อยู่ในระยะได้รับความเสียหายและติดสถานะ Freezing  เมื่อเป้าหมายติดสถานะ ความเร็วในการเคลื่อนที่ลดลง, ความเร็วในการโจมตีลดลง, ระยะเวลาในการร่ายเวทย์จะเพิ่มขึ้น และลด Physical Defense ลง', '[Level 1] : โอกาสติดสถานะ Freezing 30%   / สร้างความเสียหายธาตุน้ำ  300% ของ MATK\n[Level 2] : โอกาสติดสถานะ Freezing 35%   / สร้างความเสียหายธาตุน้ำ  400% ของ MATK\n[Level 3] : โอกาสติดสถานะ Freezing 40%   / สร้างความเสียหายธาตุน้ำ  500% ของ MATK\n[Level 4] : โอกาสติดสถานะ Freezing 45%   / สร้างความเสียหายธาตุน้ำ  600% ของ MATK\n[Level 5] : โอกาสติดสถานะ Freezing 50%   / สร้างความเสียหายธาตุน้ำ  700% ของ MATK'),
('WL_JACKFROST', 'Jack Frost', 5, 'Debuff', 'Requirement : Frost Misty 2\nสร้างความเสียหายธาตุน้ำแก่ศัตรูที่อยู่ในสถานะ Freezing และหากเป้าหมายอยู่ในสถานะ frost จะสร้างค่าความเสียหาย และเปลี่ยนเป้าหมายให้ติดสถานะ Freezing', '[Level 1] : สร้างความเสียหายธาตุน้ำ 600% ของ MATK\n[Level 2] : สร้างความเสียหายธาตุน้ำ 700% ของ MATK\n[Level 3] : สร้างความเสียหายธาตุน้ำ 800% ของ MATK\n[Level 4] : สร้างความเสียหายธาตุน้ำ 900% ของ MATK\n[Level 5] : สร้างความเสียหายธาตุน้ำ 1000% ของ MATK'),
('WL_MARSHOFABYSS', 'Marsh Of Abyss', 5, 'Debuff', 'Requirement : Quagmire 1\nทำให้เป้าหมาย 1 เป้าหมายเหยียบย่ำอยู่บนบึงโคลนต้องสาป อัตราการหลบหลีก , ความเร็วในการเคลื่อนที่ และ Physical Defense ของเป้าหมายจะถูกลดลง, INT และ Job Level ของผู้ใช้มีผลต้องสกิล', '[Level 1] : ลดความเร็วในการเคลื่อนที่ -10%\n[Level 2] : ลดความเร็วในการเคลื่อนที่ -20%\n[Level 3] : ลดความเร็วในการเคลื่อนที่ -30%\n[Level 4] : ลดความเร็วในการเคลื่อนที่ -40%\n[Level 5] : ลดความเร็วในการเคลื่อนที่ -50%'),
('WL_RECOGNIZEDSPELL', 'Recognized Spell', 5, 'Buff', 'Requirement : Release 2 , Stasis 1, White Imprison 1\nทำให้ผู้ใช้สามารถเข้าใจเวทย์มนตร์ต่างๆ ได้มากยิ่งขึ้น ทำให้เวทย์มนตร์โจมตีออกมาเป็นค่าสูงสุด (Max MATK) ทุกครั้งที่ทำการโจมตีด้วยเวทย์มนตร์, เพิ่ม SP ในการใช้สกิล 25%', '[Level 1] : ระยะเวลา 60 วินาที\n[Level 2] : ระยะเวลา 90 วินาที\n[Level 3] : ระยะเวลา 120 วินาที\n[Level 4] : ระยะเวลา 150 วินาที\n[Level 5] : ระยะเวลา 180 วินาที'),
('WL_SIENNAEXECRATE', 'Sienna Execrate', 5, 'Curse', 'Requirement : Summon Stone 1\nทำให้ศัตรูที่อยู่รอบ ๆ เป้าหมายทั้งหมดติดสถานะ Stone ใช้ 2 Red Gemstone ในการใช้สกิล โอกาสสำเรจขึ้นอยู่กับ Job level ของผู้ใช้', '[Level 1] : โอกาสติดสถานะ 48% / 3 x 3 ช่อง / 10 วินาที\n[Level 2] : โอกาสติดสถานะ 56%  / 5 x 5 ช่อง / 12 วินาที\n[Level 3] : โอกาสติดสถานะ 64%  / 5 x 5 ช่อง / 14 วินาที\n[Level 4] : โอกาสติดสถานะ 72%  / 7 x 7 ช่อง / 16 วินาที\n[Level 5] : โอกาสติดสถานะ 80%  / 7 x 7 ช่อง / 18 วินาที'),
('WL_RADIUS', 'Radius', 3, 'Passive', 'Requirement : Warlock Basic Skill\nเพิ่มระยะของสกิล Warlock และช่วยเพิ่มความเร็วในการร่ายเล็กน้อย', '[Level 1] : ระยะของสกิล + 1 : ลดระยะเวลาในการร่าย 10%\n[Level 2] : ระยะของสกิล + 2 : ลดระยะเวลาในการร่าย 15%\n[Level 3] : ระยะของสกิล + 3 : ลดระยะเวลาในการร่าย 20%'),
('WL_STASIS', 'Stasis', 5, 'Curse', 'Requirement : Drain Life 1\nอากาศรอบตัวผู้ร่ายจะสั่นสะเทือน ทำให้เป้าหมายไม่สามารถใช้สกิลเวทย์มนตร์ได้ เช่นเดียวกันกับ Song skill และ Chorus skill', '[Level 1] : 20 วินาที / 19 x 19 ช่อง\n[Level 2] : 30 วินาที / 21 x 21 ช่อง\n[Level 3] : 40 วินาที / 23 x 23 ช่อง\n[Level 4] : 50 วินาที / 25 x 25 ช่อง\n[Level 5] : 60 วินาที / 27 x 27 ช่อง'),
('WL_DRAINLIFE', 'Drain Life', 5, 'Damage / Recover', 'Requirement : Radius 1\nสร้างความเสียหายทางเวทย์มนตร์ไร้ธาตุแก่เป้าหมาย และนำค่าความเสียหายมาเพิ่มเป็น HP ค่าความเสียหายขึ้นอยู่กับค่า INT ของผู้ใช้', '[Level 1] : สร้างความเสียหายไร้ธาตุ  600% / นำ 10% ของความเสียหายมาเพิ่ม HP / โอกาศสำเร็จ 75%\n[Level 2] : สร้างความเสียหายไร้ธาตุ  700% / นำ 15% ของความเสียหายมาเพิ่ม HP / โอกาศสำเร็จ 80%\n[Level 3] : สร้างความเสียหายไร้ธาตุ  800% / นำ 20% ของความเสียหายมาเพิ่ม HP / โอกาศสำเร็จ 85%\n[Level 4] : สร้างความเสียหายไร้ธาตุ  900% / นำ 25% ของความเสียหายมาเพิ่ม HP / โอกาศสำเร็จ 90%\n[Level 5] : สร้างความเสียหายไร้ธาตุ  1000% / นำ 30% ของความเสียหายมาเพิ่ม HP / โอกาศสำเร็จ 95%'),
('WL_CRIMSONROCK', 'Crimson Rock', 5, 'Active / Damage', 'Requirement : Summon Fireball 1\nเรียกอุกกาบาตขนาดยักษ์ลงมาจากท้องฟ้า เป้าหมายที่อยู่ในระยะจะได้รับความเสียหายธาตุไฟ แรงกระแทกจากอุกกาบาตจะส่งผลให้เกิดคลื่นความเสียหาย ทำให้เกิดความเสียหายได้เล็กน้อย มีโอกาสทำให้เป้าหมายติดสถานะ Stun', '[Level 1] : สร้างความเสียหายธาตุไฟ 1600%\n[Level 2] : สร้างความเสียหายธาตุไฟ 1900%\n[Level 3] : สร้างความเสียหายธาตุไฟ 2200%\n[Level 4] : สร้างความเสียหายธาตุไฟ 2500%\n[Level 5] : สร้างความเสียหายธาตุไฟ 2800%'),
('WL_HELLINFERNO', 'Hell Inferno', 5, 'Damage / Curse', 'Requirement : Crimson Rock 2\nเรียกไฟแห่งนรกออกมาโจมตีเป้าหมาย สร้างความเสียหายด้วยธาตุไฟ และ มืด, ทำให้เป้าหมายติดสถานะ Ignite จะทำให้ไฟลุกไหม้อยู่บนร่างกาย ซึ่งทำให้เกิดความเสียหายธาตุไฟอย่างต่อเนื่อง และลด MDEF ลง', '[Level 1] : Fire Property Damage 60% / Dark Property Magic Damage 240%\n[Level 2] : Fire Property Damage 120% / Dark Property Magic Damage 480%\n[Level 3] : Fire Property Damage 180% / Dark Property Magic Damage 720%\n[Level 4] : Fire Property Damage 240% / Dark Property Magic Damage 960%\n[Level 5] : Fire Property Damage 300% / Dark Property Magic Damage 1200%'),
('WL_COMET', 'Comet', 5, 'Damage / Curse', 'Requirement : Hell Inferno 3\nโจมตีเป้าหมายด้วยดาวหางจากอวกาศ ทำให้เกิดระเบิดครั้งใหญ่สร้างความเสียหาย 19x19 ช่อง  มีโอกาสทำให้เป้าหมายติดสถานะ Ignite ตลอดระยะเวลาของสกิล เป้าหมายที่อยู่บริเวณตรงกลาง จะได้รับความเสียหายมากที่สุด (ใช้ 2 Red Gemstone)  หากมี Warlock อยู่ใน party หรืออยู่ใกล้ๆ จะสามารถร่ายได้โดยไม่จำเป็นต้องใช้ Gem stone และจะไม่ลดค่าความเสียหาย ถึงแม้เป้าหมายจะไม่อยู่บริเวณตรงกลางของสกิล', '[Level 1] : Neutral property Magic Damage 1500% ~ 3000%\n[Level 2] : Neutral property Magic Damage 2000% ~ 3500%\n[Level 3] : Neutral property Magic Damage 2500% ~ 4000%\n[Level 4] : Neutral property Magic Damage 3000% ~ 4500%\n[Level 5] : Neutral property Magic Damage 3500% ~ 5000%'),
('WL_CHAINLIGHTNING', 'Chain Lightning', 5, 'Active / Damage', 'Requirement : Summon Ball Lightning 1\nโจมตีเป้าหมาย 1 เป้าหมาย ทำให้เป้าหมาย และศัตรูที่อยู่รอบๆ ได้รับความเสียหายของแบบสุ่มอย่างต่อเนื่อง หากมีเป้าหมายหลายตัว จะทำการสุ่มโจมตีเป้าหมาย แต่หากไม่มีเป้าหมายอยู่ใกล้อีก จะโจมตีเป้าหมายสุดท้าย มากกว่า 3 ครั้ง', '[Level 1] : สร้างความเสียหายธาตุลม 600%  / สุ่มโจมตี 5 ครั้ง\n[Level 2] : สร้างความเสียหายธาตุลม 700%  / สุ่มโจมตี 6 ครั้ง\n[Level 3] : สร้างความเสียหายธาตุลม  800%  / สุ่มโจมตี 7 ครั้ง\n[Level 4] : สร้างความเสียหายธาตุลม  900%  / สุ่มโจมตี 8 ครั้ง\n[Level 5] : สร้างความเสียหายธาตุลม  1000%  / สุ่มโจมตี 9 ครั้ง'),
('WL_EARTHSTRAIN', 'Earth Strain', 5, 'Damage / Debuff', 'Requirement : Sienna Execrate 2\nสร้างคลื่นสั่นสะเทือนเป็นวงกว้าง สร้างความเสียหายธาตุดินให้แก่เป้าหมาย ผลจากแรงสั่นสะเทือน จะทำให้อาวุธและหมวกของเป้าหมายถูกถอดออก ผลของสกิลขึ้นอยู่กับ Job level และ DEX', '[Level 1] : สร้างความเสียหายธาตุดิน  2100%  /  มีโอกาสปลดอาวุธและหมวก  6%\n[Level 2] : สร้างความเสียหายธาตุดิน  2200%  /  มีโอกาสปลดอาวุธและหมวก  14%\n[Level 3] : สร้างความเสียหายธาตุดิน  2300%  /  มีโอกาสปลดอาวุธ,หมวกและชุดเกราะ 24%\n[Level 4] : สร้างความเสียหายธาตุดิน  2400%  / มีโอกาสปลดอาวุธ,หมวก,ชุดเกราะและโล่ 36%\n[Level 5] : สร้างความเสียหายธาตุดิน  2500%  / มีโอกาสปลดอาวุธ,หมวก,ชุดเกราะ,โล่และเครื่องประดับ 50%'),
('WL_TETRAVORTEX', 'Tetra Vortex', 5, 'Damage / Debuff', 'Requirement : Jack Frost 5, Chain Lightning 5, Earth Strain 5, Hell Inferno 5\nเรียกพลังแห่งธาตุออกมาโจมตีศัตรู 4 ครั้ง ต้องการ Summon Ball 4 ลูกในการใช้งาน มีโอกาสทำให้เป้าหมายติดสถานะ Ignition, Freezing, Stun และ Bleeding', '[Level 1] : สร้างความเสียหายด้วยธาตุของ Summon Ball 1000% ของ MATK 4 Hit มีโอกาศทำให้ติดสถานะ Ignition, Freezing, Stun และ Bleeding\n[Level 2] : สร้างความเสียหายด้วยธาตุของ Summon Ball 1500% ของ MATK 4 Hit มีโอกาศทำให้ติดสถานะ Ignition, Freezing, Stun และ Bleeding\n[Level 3] : สร้างความเสียหายด้วยธาตุของ Summon Ball 2000% ของ MATK 4 Hit มีโอกาศทำให้ติดสถานะ Ignition, Freezing, Stun และ Bleeding\n[Level 4] : สร้างความเสียหายด้วยธาตุของ Summon Ball 2500% ของ MATK 4 Hit มีโอกาศทำให้ติดสถานะ Ignition, Freezing, Stun และ Bleeding\n[Level 5] : สร้างความเสียหายด้วยธาตุของ Summon Ball 3000% ของ MATK 4 Hit มีโอกาศทำให้ติดสถานะ Ignition, Freezing, Stun และ Bleeding'),
('WL_SUMMONFB', 'Call Fire Ball', 5, 'Active / Damage', 'Requirement : Meteor Storm 1\nSummon Fireballs สูงสุด 5 ลูก รอบตัวผู้ร่าย โดยใช้ SP อย่างต่อเนื่องในขณะที่ผลของ fireball ยังคงทำงานอยู่ เพิ่มค่าความเสียหายด้วยการใช้คู่กับ Release โดยขึ้นอยู่กับ Base Level และ Job Level ของผู้ใช้', '[Level 1] : สร้างความเสียหายธาติไฟ / ระยะเวลา 120 วินาที\n[Level 2] : สร้างความเสียหายธาติไฟ  / ระยะเวลา 160 วินาที\n[Level 3] : สร้างความเสียหายธาติไฟ  / ระยะเวลา 200 วินาที\n[Level 4] : สร้างความเสียหายธาติไฟ  / ระยะเวลา 240 วินาที\n[Level 5] : สร้างความเสียหายธาติไฟ  / ระยะเวลา 280 วินาที'),
('WL_SUMMONBL', 'Call Ball Lightning', 5, 'Active / Damage', 'Requirement : Lord Of Vermillion 1\nSummon Lighning ball สูงสุด 5 ลูก รอบตัวผู้ร่าย โดยใช้ SP อย่างต่อเนื่องในขณะที่ผลของ Lighning ball ยังคงทำงานอยู่ เพิ่มค่าความเสียหายด้วยการใช้คู่กับ Release โดยขึ้นอยู่กับ Base Level และ Job Level ของผู้ใช้', '[Level 1] : สร้างความเสียหายธาตุลม  / ระยะเวลา 120 วินาที\n[Level 2] : สร้างความเสียหายธาตุลม  / ระยะเวลา 160 วินาที\n[Level 3] : สร้างความเสียหายธาตุลม  / ระยะเวลา 200 วินาที\n[Level 4] : สร้างความเสียหายธาตุลม  / ระยะเวลา 240 วินาที\n[Level 5] : สร้างความเสียหายธาตุลม  / ระยะเวลา 280 วินาที'),
('WL_SUMMONWB', 'Call Water Ball', 5, 'Active / Damage', 'Requirement : Storm Gust 1\nSummon Water Ball สูงสุด 5 ลูก รอบตัวผู้ร่าย โดยใช้ SP อย่างต่อเนื่องในขณะที่ผลของ Water Ball ยังคงทำงานอยู่ เพิ่มค่าความเสียหายด้วยการใช้คู่กับ Release โดยขึ้นอยู่กับ Base Level และ Job Level ของผู้ใช้', '[Level 1] : สร้างความเสียหายธาตุน้ำ  / ระยะเวลา 120 วินาที\n[Level 2] : สร้างความเสียหายธาตุน้ำ  / ระยะเวลา 160 วินาที\n[Level 3] : สร้างความเสียหายธาตุน้ำ  / ระยะเวลา 200 วินาที\n[Level 4] : สร้างความเสียหายธาตุน้ำ  / ระยะเวลา 240 วินาที\n[Level 5] : สร้างความเสียหายธาตุน้ำ  / ระยะเวลา 280 วินาที'),
('WL_SUMMONSTONE', 'Call Stone', 5, 'Active / Damage', 'Requirement : Heaven''s Drive 1\nSummon Stones สูงสุด 5 ลูก รอบตัวผู้ร่าย โดยใช้ SP อย่างต่อเนื่องในขณะที่ผลของ Stones ยังคงทำงานอยู่ เพิ่มค่าความเสียหายด้วยการใช้คู่กับ Release โดยขึ้นอยู่กับ Base Level และ Job Level ของผู้ใช้', '[Level 1] : สร้างความเสียหายธาตุดิน  / ระยะเวลา 120 วินาที\n[Level 2] : สร้างความเสียหายธาตุดิน  / ระยะเวลา 160 วินาที\n[Level 3] : สร้างความเสียหายธาตุดิน  / ระยะเวลา 200 วินาที\n[Level 4] : สร้างความเสียหายธาตุดิน  / ระยะเวลา 240 วินาที\n[Level 5] : สร้างความเสียหายธาตุดิน  / ระยะเวลา 280 วินาที'),
('WL_RELEASE', 'Release', 2, 'Active / Special', 'Requirement : Warlock Basic Skill\nโจมตีเป้าหมาย 1 เป้าหมายด้วย Fire Ball, Water Ball, Lighning Ball, Stone ที่ผู้ใช้มี', '[Level 1] : โจมตีด้วย Magic Spheres บอล 1 ลูก\n[Level 2] : โจมตีด้วย Magic Spheres บอล ทั้งหมดที่มี'),
('WL_READING_SB', 'Reading Spell Book', 1, 'Active / Special', 'Requirement : Warlock Basic Skill\nWarlock ที่เรียนรู้ทักษะนี้ จะสามารถอ่านตำราเวทย์มนตร์ เพื่อหน่วงมนตราเอาไว้ และสามารถปลดปล่อยมันออกมาได้ด้วยสกิล Release จำนวนเวทย์มนต์ที่สามารถหน่วงไว้ได้ขึ้นอยู่กับเลเวลของสกิล Freezing Spell ไม่สามารถสะสมเวทย์มนตร์ที่ยังไม่ได้เรียนรู้', NULL),
('WL_FREEZE_SP', 'Freezing Spell', 5, 'Passive', 'Requirement : Warlock Basic Skill\nใช้ในการหน่วงเวทย์มนตร์ที่ได้จากสกิล Reading Spellbook  เลเวลสกิลที่สูงขึ้น จะสามารถหน่วงมนตราะต่างๆได้มากและหลากหลายขึ้น ในระหว่างที่หน่วงมนตราอยู่จะเสีย SP ตามประเภทและจำนวนของสกิลเวทย์มนตร์ที่สะสมไว้', NULL),
('RA_ARROWSTORM', 'Arrow Storm', 10, 'Active / Damage', 'Requirement : Aimed Bolt 5\nโจมตีศัตรู และเป้าหมายโดยรอบ ธนูทุกดอกจะพุ่งโจมตีเป้าหมายเหมือนพายุฝน ใช้ลูกธนู 10 ดอกในการใช้สกิล เลเวลของตัวละครมีผลต่อความแรงของสกิล', '[Level 1] : พลังโจมตี 1080% / ระยะของสกิล 7 x 7 ช่อง รอบเป้าหมาย\n[Level 2] : พลังโจมตี 1160% / ระยะของสกิล 7 x 7 ช่อง รอบเป้าหมาย\n[Level 3] : พลังโจมตี 1240% / ระยะของสกิล 7 x 7 ช่อง รอบเป้าหมาย\n[Level 4] : พลังโจมตี 1320% / ระยะของสกิล 7 x 7 ช่อง รอบเป้าหมาย\n[Level 5] : พลังโจมตี 1400% / ระยะของสกิล 7 x 7 ช่อง รอบเป้าหมาย\n[Level 6] : พลังโจมตี 1480% / ระยะของสกิล 9 x 9 ช่อง รอบเป้าหมาย\n[Level 7] : พลังโจมตี 1560% / ระยะของสกิล 9 x 9 ช่อง รอบเป้าหมาย\n[Level 8] : พลังโจมตี 1640% / ระยะของสกิล 9 x 9 ช่อง รอบเป้าหมาย\n[Level 9] : พลังโจมตี 1720% / ระยะของสกิล 9 x 9 ช่อง รอบเป้าหมาย\n[Level10] : พลังโจมตี 1800% / ระยะของสกิล 11 x 11 ช่อง รอบเป้าหมาย'),
('RA_FEARBREEZE', 'Fear Breeze', 5, 'Active toggle / Buff (To yourself)', 'Requirement : Camouflage 1, Arrow Storm 5\nเมื่อทำการโจมตีด้วยธนู มีโอกาสที่จำนวน Hit ในการโจมตีจะเพิ่มขึ้นในการยิงต่อ 1 ครั้ง ต้องการลูกธนูในการใช้งานตามจำนวน Hit ที่เกิดผล', '[Level 1] : จำนวนครั้งในการโจมตีเพิ่มขึ้น +1 / โอกาสที่ความสามารถแสดงผล  12%  / ระยะเวลา 60 วินาที\n[Level 2] : จำนวนครั้งในการโจมตีเพิ่มขึ้น +1 / โอกาสที่ความสามารถแสดงผล  12 %  / ระยะเวลา 90 วินาที\n[Level 3] : จำนวนครั้งในการโจมตีเพิ่มขึ้น +1 ~ +2  / โอกาสที่ความสามารถแสดงผล  21 % /ระยะเวลา 120 วินาที\n[Level 4] : จำนวนครั้งในการโจมตีเพิ่มขึ้น +1 ~ +3  / โอกาสที่ความสามารถแสดงผล  27 % / ระยะเวลา 150 วินาที\n[Level 5] : จำนวนครั้งในการโจมตีเพิ่มขึ้น +1 ~ +4  / โอกาสที่ความสามารถแสดงผล  30% / ระยะเวลา 180 วินาที'),
('RA_AIMEDBOLT', 'Aimed Bolt ', 10, 'Active / Damage', 'Requirement : Ankle Snare 5\nโจมตีเป้าหมายที่ไม่สามารถเคลื่อนที่ได้ ( ติดสถานะ Ankle Snare, Wug Bite, ฯลฯ ) อย่างรุนแรง ขนาดของเป้าหมายมีผลต่อจำนวน Hit ของสกิลนี้ หลังจากใช้สกิลนี้แล้ว ผลที่ทำให้เป้าหมายไม่สามารถเคลื่อนไหวได้จะหายไป ถ้าสวมใส่ลูกธนูไม่เพียงพอจะทำให้สกิลล้มเหลวได้', '[Level 1] : พลังโจมตี 550% , Hit 2 Small Size, 3 Medium Size, 4 Big Size\n[Level 2] : พลังโจมตี 600% , Hit 2 Small Size, 3 Medium Size, 4 Big Size\n[Level 3] : พลังโจมตี 650% , Hit 2 Small Size, 3 Medium Size, 4 Big Size\n[Level 4] : พลังโจมตี 700% , Hit 2 Small Size, 3 Medium Size, 4 Big Size\n[Level 5] : พลังโจมตี 750% , Hit 2 Small Size, 3 Medium Size, 4 Big Size\n[Level 6] : พลังโจมตี 800% , Hit 2 Small Size, 3 Medium Size, 4 Big Size\n[Level 7] : พลังโจมตี 850% , Hit 2 Small Size, 3 Medium Size, 4 Big Size\n[Level 8] : พลังโจมตี 900% , Hit 2 Small Size, 3 Medium Size, 4 Big Size\n[Level 9] : พลังโจมตี 950% , Hit 2 Small Size, 3 Medium Size, 4 Big Size\n[Level10] : พลังโจมตี 1000% , Hit 2 Small Size, 3 Medium Size, 4 Big Size'),
('RA_RANGERMAIN', 'Main Ranger', 10, 'Passive', 'Requirement : Ranger Basic Skill\nเพิ่มพลังโจมตีและลดความเสียหายที่ได้รับจากมอนสเตอร์ประเภท สัตว์, พืช และ ปลา', '[Level 1] : พลังโจมตี / ความต้านทานต่อมอนสเตอร์ดังกล่าว+ 5\n[Level 2] : พลังโจมตี / ความต้านทานต่อมอนสเตอร์ดังกล่าว+ 10\n[Level 3] : พลังโจมตี / ความต้านทานต่อมอนสเตอร์ดังกล่าว+ 15\n[Level 4] : พลังโจมตี / ความต้านทานต่อมอนสเตอร์ดังกล่าว+ 20\n[Level 5] : พลังโจมตี / ความต้านทานต่อมอนสเตอร์ดังกล่าว+ 25\n[Level 6] : พลังโจมตี / ความต้านทานต่อมอนสเตอร์ดังกล่าว+ 30\n[Level 7] : พลังโจมตี / ความต้านทานต่อมอนสเตอร์ดังกล่าว+ 35\n[Level 8] : พลังโจมตี / ความต้านทานต่อมอนสเตอร์ดังกล่าว+ 40\n[Level 9] : พลังโจมตี / ความต้านทานต่อมอนสเตอร์ดังกล่าว+ 45\n[Level10] : พลังโจมตี / ความต้านทานต่อมอนสเตอร์ดังกล่าว+ 50'),
('RA_DETONATOR', 'Detonator', 1, 'Active / Special', 'Requirement : Bomb Cluster 3\nทำให้กับดักที่อยู่ในระยะ 7 x 7 ช่อง ทำงานขึ้นในทันที สามารถใช้ร่วมกับสกิล Trap ของ Hunter ได้, ไม่สามารถใช้กับ Trap ของผู้อื่นได้', NULL),
('RA_ELECTRICSHOCKER', 'Electric Shock', 5, 'Active / Trap', 'Requirement : Shockwave Trap 5\nหากเป้าหมายเข้ามาในระยะ 3 x 3 ช่อง ของกับดัก จะทำให้เป้าหมายไม่สามารถเคลื่อนไหวได้ และเป้าหมายรอบๆด้วย (5 x 5 ช่อง) และลด SP เป้าหมายไปด้วย ในเวลาเดียวกัน ไม่สามารถใช้สกิล Remove Trap เพื่อปลดกับดักนี้ได้ ต้องการ 1 <Special Alloy Trap> ในการใช้สกิล  สามารถติดตั้งได้เพียง 3 อัน เท่านั้น', '[Level 1] : ลด SP ลงวินาทีละ 5% / ระยะเวลา 20 วินาที\n[Level 2] : ลด SP ลงวินาทีละ 10% / ระยะเวลา 22 วินาที\n[Level 3] : ลด SP ลงวินาทีละ 15% / ระยะเวลา 24 วินาที\n[Level 4] : ลด SP ลงวินาทีละ 20% / ระยะเวลา 26 วินาที\n[Level 5] : ลด SP ลงวินาทีละ 25% / ระยะเวลา 28 วินาที'),
('RA_CLUSTERBOMB', 'Bomb Cluster', 5, 'Active / Trap', 'Requirement : Trap Research 3\nสามารถใช้งานได้พร้อมกันสูงสุด 3 อัน สร้างความเสียหายกระจายออกจากจุดที่ติดตั้งใน 7 x 7 ช่อง สามารถใช้ร่วมกับ Detonator ได้ ไม่สามารถใช้สกิล Remove Trap เพื่อปลดกับดักนี้ได้  ต้องการ 1 <Special Alloy Trap> ในการใช้สกิล', '[Level 1] : ความเสียหาย 300% + ความเสียหายเพิ่มมากขึ้นตามจำนวน Trap / ระยะเวลา 15 วินาที\n[Level 2] : ความเสียหาย 400% + ความเสียหายเพิ่มมากขึ้นตามจำนวน Trap / ระยะเวลา 15 วินาที\n[Level 3] : ความเสียหาย 500% + ความเสียหายเพิ่มมากขึ้นตามจำนวน Trap / ระยะเวลา 15 วินาที\n[Level 4] : ความเสียหาย 600% + ความเสียหายเพิ่มมากขึ้นตามจำนวน Trap / ระยะเวลา 15 วินาที\n[Level 5] : ความเสียหาย 700% + ความเสียหายเพิ่มมากขึ้นตามจำนวน Trap / ระยะเวลา 15 วินาที'),
('RA_WUGMASTERY', 'Wug Mastery', 1, 'Active / Special', 'Requirement : Ranger Basic Skill\nRanger จะเป่าขลุ่ยเพื่อเรียกหมาป่าผู้ซื่อสัตย์ [Wug] ออกมา ในการเรียกออกมานั้นต้องใช้ไอเทม [Wolf Flute] ในการใช้สกิล เมื่อกดใช้สกิลอีกครั้ง จะเป็นการปล่อย Wug คืนสู่ธรรมชาติ', NULL),
('RA_WUGRIDER', 'Wug Rider', 3, 'Active / Special', 'Requirement : Wug Mastery 1\nRanger จะทำการขี่ Wug ที่เรียกออกมา เลเวลของสกิลที่สูงขึ้นจะช่วยเพิ่มความคล่องตัวและความเร็วในการเคลื่อนที่  ที่เรียกออกมา เลเวลของสกิลที่สูงขึ้นจะช่วยเพิ่มความคล่องตัวและความเร็วในการเคลื่อนที่ ไม่สามารถใช้ธนูโจมตีได้ จะสามารถใช้ได้เพียงสกิล ของ Wug และสกิล Trap บางชนิดเท่านั้น', NULL),
('RA_WUGDASH', 'Wug Dash', 1, 'Active / Special', 'Requirement : Wug Rider 1\nสามารถใช้ในขณะใช้สกิล Wug Rider เท่านั้น เมื่อกดใช้ Wug จะวิ่งตรงไปข้างหน้าเรื่อยๆ เมื่อกดใช้สกิลอีกครั้งหรือ ถ้าด้านหน้ามีศัตรู หรือ กำแพงมาขัดขวาง จะเป็นการหยุด แต่ถ้าอัพสกิล Wug Strike เป้าหมายที่มาขัดขวางจะได้รับความเสียหาย', NULL),
('RA_WUGSTRIKE', 'Wug Strike', 5, 'Active / Damage', 'Requirement : Wug Teeth 1\nสร้างความเสียหายแก่เป้าหมาย ความเสียหายจะเพิ่มขึ้นตามสกิลเลเวล', '[Level 1] : ความเสียหาย 200%\n[Level 2] : ความเสียหาย 400%\n[Level 3] : ความเสียหาย 600%\n[Level 4] : ความเสียหาย 800%\n[Level 5] : ความเสียหาย 1000%'),
('RA_WUGBITE', 'Wug Bite', 5, 'Active / Damage', 'Requirement : Wug Strike 1\nไม่สามารถใช้ได้ หากยังอยู่ในสกิล Wug Riding สร้างความเสียหายแก่เป้าหมายและทำให้เป้าหมายไม่สามารถเคลื่อนที่ได้ ผลสำเร็จของสกิลขึ้นอยู่กับ AGI ของเป้าหมาย', '[Level 1] : ความเสียหาย 600% / ระยะเวลา 1 วินาที + เพิ่มขึ้นตามเลเวลของสกิล Wug Teeth\n[Level 2] : ความเสียหาย 800% / ระยะเวลา 2 วินาที + เพิ่มขึ้นตามเลเวลของสกิล Wug Teeth\n[Level 3] : ความเสียหาย 1000% / ระยะเวลา 3 วินาที + เพิ่มขึ้นตามเลเวลของสกิล Wug Teeth\n[Level 4] : ความเสียหาย 1200% / ระยะเวลา 4 วินาที + เพิ่มขึ้นตามเลเวลของสกิล Wug Teeth\n[Level 5] : ความเสียหาย 1500% / ระยะเวลา 5 วินาที + เพิ่มขึ้นตามเลเวลของสกิล Wug Teeth'),
('RA_TOOTHOFWUG', 'Wug Teeth', 10, 'Passive', 'Requirement : Wug Mastery 1\nเพิ่มพลังโจมตีให้กับ Wug รวมถึงสกิลของ Wug ตามเลเวลของสกิล', '[Level 1] : พลังโจมตี + 30\n[Level 2] : พลังโจมตี + 60\n[Level 3] : พลังโจมตี + 90\n[Level 4] : พลังโจมตี + 120\n[Level 5] : พลังโจมตี + 150\n[Level 6] : พลังโจมตี + 180\n[Level 7] : พลังโจมตี + 210\n[Level 8] : พลังโจมตี + 240\n[Level 9] : พลังโจมตี + 270\n[Level10] : พลังโจมตี + 300'),
('RA_SENSITIVEKEEN', 'Keen Nose', 5, 'Active / Detect', 'Requirement : Wug Teeth 3\nเมื่อกดใช้ Wug จะทำการสำรวจรอบตัวเพื่อค้นหากับดักและศัตรูที่ซ่อนอยู่ เมื่อตรวจพบมีโอกาสที่จะใช้สกิล Wug Bite ใส่เป้าหมายที่ถูกตรวจพบ', '[Level 1] : ระยะ 7 x 7 / ความเสียหาย 150% /  มีโอกาสใช้สกิล  Wug Bite 8%\n[Level 2] : ระยะ 9 x 9 / ความเสียหาย 200% /  มีโอกาสใช้สกิล  Wug Bite 16%\n[Level 3] : ระยะ 11 x11 / ความเสียหาย 250% /  มีโอกาสใช้สกิล  Wug Bite 24%\n[Level 4] : ระยะ 13 x13 / ความเสียหาย 300% /  มีโอกาสใช้สกิล  Wug Bite 32%\n[Level 5] : ระยะ 15 x15 / ความเสียหาย 350% /  มีโอกาสใช้สกิล  Wug Bite 40%'),
('RA_CAMOUFLAGE', 'Camouflage', 5, 'Active / Buff (To yourself)', 'Requirement : Main Ranger 1\nทำการซ่อนตัวใกล้ๆกับกำแพง ทำให้มอนสเตอร์ไม่สามารถตรวจจับๆได้ (ยกเว้น Demon/Insect monsters) ขณะพรางตัวร่างกายจะมัวๆ ทำให้ความเสียหาย และโอกาสติด Critical สูงขึ้น เมื่อทำการโจมตี แต่พลังป้องกันจะลดลง กดใช้อีกครั้งจะเป็นการยกเลิกสถานะ ขณะทำการพรางตัวจะเสีย SP อย่างต่อเนื่อง เลเวลที่สูงขึ้นจะทำให้สามารถใช้งานนอกกำแพงได้', '[Level 1] : เสีย SP 6 หน่วยต่อวินาที : ไม่สามารถเคลื่อนไหวได้\n[Level 2] : เสีย SP 5 หน่วยต่อวินาที : ไม่สามารถเคลื่อนไหวได้\n[Level 3] : เสีย SP 4 หน่วยต่อวินาที : เคลื่อนไหวได้ 50% จากความเร็วปกติ\n[Level 4] : เสีย SP 3 หน่วยต่อวินาที : เคลื่อนไหวได้ 75% จากความเร็วปกติ\n[Level 5] : เสีย SP 2 หน่วยต่อวินาที : เคลื่อนไหวได้ 100% จากความเร็วปกติ'),
('RA_RESEARCHTRAP', 'Trap Research', 5, 'Passive', 'Requirement : Claymore Trap 1, Remove Trap 1\nเพิ่มความเสียหายให้กับสกิลกับดักของ Hunter และ Ranger เพิ่ม INT และ Max SP', '[Level 1] : ความเสียหาย +40 / INT +1 / MSP +220  /เพิ่มขอบเขตในการวาง Trap  +1\n[Level 2] : ความเสียหาย +80 / INT +2 / MSP +240  / เพิ่มขอบเขตในการวาง Trap  +1\n[Level 3] : ความเสียหาย +120 / INT +3 / MSP +260  / เพิ่มขอบเขตในการวาง Trap  +2\n[Level 4] : ความเสียหาย +160 / INT +4 / MSP +280  / เพิ่มขอบเขตในการวาง Trap  +2\n[Level 5] : ความเสียหาย +200 / INT +5 / MSP +300  / เพิ่มขอบเขตในการวาง Trap  +3'),
('RA_MAGENTATRAP', 'Magenta Trap', 1, 'Active / Trap', 'Requirement : Trap Research 1\nในระยะ 3 x 3 ช่อง เปลี่ยนเป้าหมายที่มาเหยียบกับดักให้เป็นธาตุไฟ ไม่มีผลกับมอนสเตอร์ระดับบอส และผู้เล่นทั่วไป (ระยะ 5 x 5 ช่อง) ใช้ไอเทม Special Alloy Trap 1 ea, Scarlet point 1 ea ในการใช้สกิล สามารถวางสกิลใส่เท้าของเป้าหมายได้ ใช้ได้สูงสุด 1 ครั้ง', NULL),
('RA_COBALTTRAP', 'Cobalt Trap', 1, 'Active / Trap', 'Requirement : Trap Research 1\nในระยะ 3 x 3 ช่อง เปลี่ยนเป้าหมายที่มาเหยียบกับดักให้เป็นธาตุน้ำ ไม่มีผลกับมอนสเตอร์ระดับบอส และผู้เล่นทั่วไป (ระยะ 5 x 5 ช่อง) ใช้ไอเทม Special Alloy Trap 1 ea, Indigo Point 1 ea ในการใช้สกิล สามารถวางสกิลใส่เท้าของเป้าหมายได้ ใช้ได้สูงสุด 1 ครั้ง', NULL),
('RA_MAIZETRAP', 'Maze Trap', 1, 'Active / Trap', 'Requirement : Trap Research 1\nในระยะ 3 x 3 ช่อง เปลี่ยนเป้าหมายที่มาเหยียบกับดักให้เป็นธาตุดิน ไม่มีผลกับมอนสเตอร์ระดับบอส และผู้เล่นทั่วไป (ระยะ 5 x 5 ช่อง) ใช้ไอเทม Special Alloy Trap 1 ea, Lime Green Point 1 ea ในการใช้สกิล สามารถวางสกิลใส่เท้าของเป้าหมายได้ ใช้ได้สูงสุด 1 ครั้ง', NULL),
('RA_VERDURETRAP', 'Verdure Trap', 1, 'Active / Trap', 'Requirement : Trap Research 1\nในระยะ 3 x 3 ช่อง เปลี่ยนเป้าหมายที่มาเหยียบกับดักให้เป็นธาตุลม ไม่มีผลกับมอนสเตอร์ระดับบอส และผู้เล่นทั่วไป (ระยะ 5 x 5 ช่อง) ใช้ไอเทม Special Alloy Trap 1 ea, Yellow Wish Point 1 ea ในการใช้สกิล สามารถวางสกิลใส่เท้าของเป้าหมายได้ ใช้ได้สูงสุด 1 ครั้ง', NULL),
('RA_FIRINGTRAP', 'Firing Trap', 5, 'Active / Trap', 'Requirement : Detonator 1\nเมื่อเป้าหมายเข้ามาในระยะ 3 x 3 ช่องรอบกับดัก มีโอกาสทำให้เป้าหมายติดสถานะ [Ignition] และกระจายไปรอบเป้าหมายในระยะ 5 x 5 ช่อง สกิลเลเวลทำให้โอกาสติดสูงขึ้น ต้องการ 1 <Special Alloy Trap> ในการใช้สกิล', '[Level 1] : โอกาสติดสถานะ 60%\n[Level 2] : โอกาสติดสถานะ 70%\n[Level 3] : โอกาสติดสถานะ 80%\n[Level 4] : โอกาสติดสถานะ 90%\n[Level 5] : โอกาสติดสถานะ 100%'),
('RA_ICEBOUNDTRAP', 'Ice Bound Trap', 5, 'Active / Trap', 'Requirement : Detonator 1\nเมื่อเป้าหมายเข้ามาในระยะ 3 x 3 ช่องรอบกับดัก มีโอกาสทำให้เป้าหมายติดสถานะ [Freezing] และกระจายไปรอบเป้าหมายในระยะ 5 x 5 ช่อง สกิลเลเวลทำให้โอกาสติดสูงขึ้น 1 <Special Alloy Trap> ในการใช้สกิล', '[Level 1] : โอกาสติดสถานะ 60%\n[Level 2] : โอกาสติดสถานะ 70%\n[Level 3] : โอกาสติดสถานะ 80%\n[Level 4] : โอกาสติดสถานะ 90%\n[Level 5] : โอกาสติดสถานะ 100%'),
('NC_MADOLICENCE', 'Madogear License', 5, 'Passive', 'Requirement : Mechanic Basic\nเป็นสกิลพื้นฐานในการสร้าง Madogear ช่วยเพิ่มความเสียหายของ Madogear ถ้าผู้เล่นไม่ได้เรียนรู้สกิลนี้ความเร้วของ Madogear จะลดลงครึ่งนึงจากความเร็วปกติ', '[Level 1] : ความเสียหายของ Madogear ATK +15  / ความเร็วในการเคลื่อนที่ลดลง 40%\n[Level 2] : ความเสียหายของ Madogear ATK +30  / ความเร็วในการเคลื่อนที่ลดลง 30%\n[Level 3] : ความเสียหายของ Madogear ATK +45  / ความเร็วในการเคลื่อนที่ลดลง 20%\n[Level 4] : ความเสียหายของ Madogear ATK +60  / ความเร็วในการเคลื่อนที่ลดลง 10%\n[Level 5] : ความเสียหายของ Madogear ATK +75  / ความเร็วในการเคลื่อนที่ลดลง 0%'),
('NC_BOOSTKNUCKLE', 'Knuckle Boost', 5, 'Active / Damage', 'Requirement : Madogear License 1\nปล่อยหมัดออกจาก Madogear สร้างความเสียหายระยะไกลแก่เป้าหมาย, ระยะโจมตี 11 ช่อง Damage ของสกิลสามารถเพิ่มขึ้นได้จากค่า DEX และ Base Level ของผู้ใช้', '[Level 1] : พลังโจมตี 300%\n[Level 2] : พลังโจมตี 400%\n[Level 3] : พลังโจมตี 500%\n[Level 4] : พลังโจมตี 600%\n[Level 5] : พลังโจมตี 700%'),
('NC_PILEBUNKER', 'Pile Bunker', 3, 'Active / Damage(Special)', 'Requirement : Knuckle Boost 2\nใช้แขนหนาๆ เจาะเข้าไปยังศัตรู มีโอกาสยกเลิก buff skills ของเป้าหมาย ต้องมีไอเทม < Pile Bunker > ในการใช้สกิล Damage ของสกิลสามารถเพิ่มขึ้นได้จากค่า STR และ Base Level ของผู้ใช้', '[Level 1] : โอกาสในการทำลาย Mdef ของเป้าหมาย 40%\n[Level 2] : โอกาสในการทำลาย Mdef ของเป้าหมาย 55%\n[Level 3] : โอกาสในการทำลาย Mdef ของเป้าหมาย 70%'),
('NC_VULCANARM', 'Vulcan Arm', 3, 'Active / Damage', 'Requirement : Knuckle Boost 2\nใช้ Madogear ในการโจมตีด้วยปืนที่มีลำกล้องขนาดใหญ่ ต้องการ 1 Vulcan Bullet ในการโจมตี ระยะโจมตี 13 ช่อง Damage ของสกิลสามารถเพิ่มขึ้นได้จากค่า DEX และ Base Level ของผู้ใช้', '[Level 1] : 1 เป้าหมาย และศัตรูในระยะ 3x3 / พลังโจมตี 70 %\n[Level 2] : 1 เป้าหมาย และศัตรูในระยะ 3x3 / พลังโจมตี 140 %\n[Level 3] : 1 เป้าหมาย และศัตรูในระยะ 3x3 / พลังโจมตี 210 %'),
('NC_FLAMELAUNCHER', 'Flame Launcher', 3, 'Active / Damage', 'Requirement : Vulcan Arm 1\nพ่นไฟลงบนพื้น สร้างความเสียหายธาตุไฟแก่ศัตรูที่อยู่ในบริเวณ และมีโอกาสทำให้ติดสถานะ [Ignition] ต้องการไอเทม 1 Fuel Canister และต้องสวมใส่ หรือมีไอเทม Flame Thrower ในการใช้สกิล การร่ายสกิลไม่สามารถถูกขัดขวางได้ , Damage ของสกิลสามารถเพิ่มขึ้นได้จาก Base Level ของผู้ใช้', '[Level 1] : สร้างความเสียหายธาตุไฟ 600 % / โอกาสในการติดสถานะ [Ignition] 30%\n[Level 2] : สร้างความเสียหายธาตุไฟ 900 % / โอกาสในการติดสถานะ [Ignition] 40%\n[Level 3] : สร้างความเสียหายธาตุไฟ 1200 % / โอกาสในการติดสถานะ [Ignition] 50%'),
('NC_COLDSLOWER', 'Cold Slower', 3, 'Active / Damage', 'Requirement : Vulcan Arm 3\nใช้ Magic Gear ในการสร้างความเย็น สร้างความเสียหายธาตุน้ำแก่เป้าหมายในบริเวณ และทำให้เป้าหมายติดสถานะ [Freezing] ต้องการไอเทม 1 Fuel Canister และไอเทม Liquid Cold Bullet ในการใช้สกิล การร่ายสกิลไม่สามารถถูกขัดขวางได้ , Damage ของสกิลสามารถเพิ่มขึ้นได้จาก Base Level ของผู้ใช้', '[Level 1] : สร้างความเสียหายธาตุน้ำ 600 % / ระยะ 5 x 5 ช่อง\n[Level 2] : สร้างความเสียหายธาตุน้ำ 900 % / ระยะ 7 x 7 ช่อง\n[Level 3] : สร้างความเสียหายธาตุน้ำ 1200 % / ระยะ 9 x 9 ช่อง'),
('NC_ARMSCANNON', 'Arm Cannon', 3, 'Active / Damage', 'Requirement : Flame Launcher 2 / Cold Slower 2\nปล่อยแขนของ Madogear ออกไป สร้างความเสียหายแก่เป้าหมายในบริเวณนั้น ความเสียหายจะลงเมื่อกลุ่มของเป้าหมายมีจำนวนมากขึ้น การร่ายสกิลไม่สามารถถูกขัดขวางได้ , Damage property เปลี่ยนแปลงตาม ชนิดของ cannon ball, Damage ของสกิลสามารถเพิ่มขึ้นได้จาก Base Level ของผู้ใช้ และแรงขึ้นหากโจมตีศัตรูขนาดเล็ก ต้องการ Fuel Canister และสวมใส่ Cannon Ball (ชนิดใดก็ได้ 1 ชนิด) อย่างละ 1 ea ในการใช้สกิล', '[Level 1] : พลังโจมตี 700% / 650% / 600%   / ระยะสกิล 9 ช่อง /   ระยะ 7 x 7 ช่อง\n[Level 2] : พลังโจมตี 1100% / 1000% / 900%   / ระยะสกิล 11 ช่อง /   ระยะ 5 x 5 ช่อง\n[Level 3] : พลังโจมตี 1500% / 1350% / 1200%   / ระยะสกิล 13 ช่อง /  ระยะ 3 x 3 ช่อง'),
('NC_ACCELERATION', 'Acceleration', 3, 'Active / Buff', 'Requirement : Madogear License 1\nเพิ่มความเร็วในการเคลื่อนที่ให้กับ Madogear ต้องมีไอเทม <Accelerator> ในการใช้สกิล และต้องการไอเทม Fuel Canister 1 ea', '[Level 1] : ระยะเวลา 60 วินาที\n[Level 2] : ระยะเวลา 90 วินาที\n[Level 3] : ระยะเวลา 120 วินาที'),
('NC_HOVERING', 'Hover', 1, 'Active / Buff', 'Requirement : Acceleration 1\nลอยสูงขึ้นจากพื้นทำให้ไม่ได้รับผลจากสกิลกับดัก และสกิลที่มีผลลงบนพื้นทั้งหลาย ต้องมีใส่ไอเทม <Hovering Booster> ในการใช้สกิล และต้องการไอเทม Fuel Canister 1 ea', '[Level 1] : ระยะเวลา 90 วินาที'),
('NC_F_SIDESLIDE', 'Front Slide', 1, 'Active / Movement', 'Requirement : Hover 1\nเคลื่อนที่ไปข้างหน้า 7 ช่องอย่างรวดเร็ว ต้องการไอเทม Fuel Canister 1 ea', NULL),
('NC_B_SIDESLIDE', 'Back Slide', 1, 'Active / Movement', 'Requirement : Hover 1\nเคลื่อนที่ถอยหลังไป 7 ช่องอย่างรวดเร็ว ต้องการไอเทม Fuel Canister 1 ea', NULL),
('NC_MAINFRAME', 'Remodel Mainframe', 4, 'Passive', 'Requirement : Madogear License 4\nปรับปรุง Madogear ให้มีพลังป้องกันสุงขึ้นและเพิ่มค่า Over Heat Limit ของ Magic Gear เมื่อ Magic Gear อยู่ในสถานะ Over Heat แล้วจะทำให้ Magic Gear ได้รับความเสียหายอย่างต่อ เนื่อง ซึ่งค่า Over Heat Limit ที่สูงขึ้นจะเพิ่มจุดที่ทำให้เกิดสถานะ Over Heat ให้สูงขึ้น', '[Level 1] : พลังป้องกัน +40 / Over Heat Limit + 200\n[Level 2] : พลังป้องกัน +60 / Over Heat Limit + 280\n[Level 3] : พลังป้องกัน +80 / Over Heat Limit + 360\n[Level 4] : พลังป้องกัน +100 / Over Heat Limit + 450'),
('NC_SELFDESTRUCTION', 'Suicidal Destruction', 3, 'Active / Damage', 'Requirement : Remodel Mainframe 2\nทำการระเบิดตัวเอง สร้างความเสียหายอย่างรุนแรงในวงกว้าง เมื่อใช้สกิลนี้จะสูญเสีย Madogear ไป และจะใช้ SP ที่มีอยู่ทั้งหมด ไม่สามารถขัดขวางการร่ายสกิลนี้ได้ ต้องการไอเทม Fuel Canister 3 ea และต้องมี ไอเทม <Suicidal Device> ในการใช้สกิล', '[Level 1] : ระยะสกิล 5 x 5 ช่อง\n[Level 2] : ระยะสกิล 7 x 7 ช่อง\n[Level 3] : ระยะสกิล 9 x 9 ช่อง'),
('NC_SHAPESHIFT', 'Shift Shape', 4, 'Active / Buff', 'Requirement : Remodel Mainframe 2\nทำการเปลี่ยนธาตุของ Madogear ต้องมีไอเทม Shape Shift ในการใช้สกิล และต้องการไอเทม Fuel Canister 2 ea / 1 Enchanted Stone และต้องมี ไอเทม <Shape Shifter> ในการใช้สกิล', '[Level 1] : เปลี่ยนเป็นธาตุ fire property / ต้องการไอเทม 3 Scarlet Point ในการใช้สกิล\n[Level 2] : เปลี่ยนเป็นธาตุ earth property / ต้องการไอเทม 3 Lime Green Point ในการใช้สกิล\n[Level 3] : เปลี่ยนเป็นธาตุ wind property / ต้องการไอเทม 3 Yellow Wish Point ในการใช้สกิล\n[Level 4] : เปลี่ยนเป็นธาตุ water property / ต้องการไอเทม 3 Indigo Point ในการใช้สกิล'),
('NC_EMERGENCYCOOL', 'Cool Emergency', 1, 'Active / Buff', 'Requirement : Suicidal Destruction 2\nทำให้ Madogear ที่อยู่ในสถานะ Over Heat เย็นลงได้ ต้องมีไอเทม Cooling System ในการใช้สกิล และต้องการไอเทม Fuel Canister 1 ea และต้องมี ไอเทม <Cooling Device> ในการใช้สกิล', NULL),
('NC_INFRAREDSCAN', 'Infra Red Scan', 1, 'Active / Detect / Debuff', 'Requirement : Shift Shape  2\nตรวจจับเป้าหมายที่ซ่อนตัวอยู่ในระยะ 15 x 15 ช่อง และมีโอกาส 30 % ที่จะลดอัตราการหลบหลีกของเป้าหมายลง เมื่อเข้ามาอยู่ในระยะของสกิล', NULL),
('NC_ANALYZE', 'Analyze', 3, 'Active / Debuff', 'Requirement : Infra Red Scan 1\nหาจุดอ่อนของเป้าหมาย ลดพลังป้องกันทั้งทางกายภาพและเวทย์มนตร์ของเป้าหมายลงเป็นระยะเวลา 20 วินาที ระยะของสกิล 9 ช่อง ต้องการไอเทม Fuel Canister 1 ea ในการใช้สกิล', '[Level 1] : พลังป้องกันลดลง 14%\n[Level 2] : พลังป้องกันลดลง 28%\n[Level 3] : พลังป้องกันลดลง 42%'),
('NC_MAGNETICFIELD', 'Magnetic Field', 3, 'Active / Debuff', 'Requirement : Cool Emergency 1\nสร้างสนามแม่เหล็กรอบๆตัว ทำให้เป้าหมายทั้งหมดไม่สามารถเคลื่อนที่ได้ ในระยะ 5x5 ช่องรวมถึงตัวผู้ร่ายสกิลด้วย ไม่มีผลกับเป้าหมายที่ได้รับผลจากสกิล Hovering ขณะใช้งานสกิลดังกล่าว SP จะลดลงอย่างต่อเนื่อง ต้องมีไอเทม Magnetic Field Generator ในการใช้สกิล หากผู้ที่ได้รับผลของสกิลนี้อยู่ โดนโจมตีด้วยธาตุดิน หรือ Quagmire ผลของสกิลจะถูกยกเลิกโดยทันที ต้องการไอเทม Fuel Canister 2 ea', '[Level 1] : ระยะเวล 4 วินาที : SP ลดลง 50 หน่วยต่อวินาที\n[Level 2] : ระยะเวล 6 วินาที : SP ลดลง 50 หน่วยต่อวินาที\n[Level 3] : ระยะเวล 8 วินาที : SP ลดลง 50 หน่วยต่อวินาที'),
('NC_NEUTRALBARRIER', 'Neutral Barrier', 3, 'Active / Buff', 'Requirement : Magnetic Field 2\nสร้างม่านพลังอันแข็งแกร่งรอบๆตัว ลดความเสียหายทางกายภาพและเวทย์มนตร์ในบริเวณดังกล่าว แต่ไม่สามารถลดความเสียหายระยะไกลได้ ต้องสวมใส่ไอเทม <Barrier Builder> ในการใช้สกิล และต้องการไอเทม Fuel Canister 1 ea', '[Level 1] : พลังป้องกันทางกายภาพและเวทย์มนตร์เพิ่มขึ้น 15% : ระยะเวลา 30 วินาที\n[Level 2] : พลังป้องกันทางกายภาพและเวทย์มนตร์เพิ่มขึ้น 20% : ระยะเวลา 45 วินาที\n[Level 3] : พลังป้องกันทางกายภาพและเวทย์มนตร์เพิ่มขึ้น 25% : ระยะเวลา 60 วินาที'),
('NC_STEALTHFIELD', 'Stealth Field', 3, 'Active / Buff', 'Requirement : Analyze 3 / Neutral Barrier 2\nสร้างพลังขึ้นรอบๆตัว ช่วยซ่อนตัวผู้เล่นที่เป็นมิตร [Cloaking] ในระยะของสกิล เป้าหมายที่ได้รับการซ่อนจะอยู่ในสถานะกึ่งหายตัว แต่จะไม่ได้รับความเสียหายจากการโจมตีทั้งกายภาพและเวทย์มนตร์ เมื่อใช้ สกิล ความเร็วในการเคลื่อนที่จะลดลง 20% และ SP จะลดลงอย่างต่อเนื่อง สามารถยกเลิกได้ด้วยการร่ายสกิลใหม่อีกครั้ง ต้องสวมใส่ไอเทม <Camouflage Generator> ในการใช้สกิลและต้องการไอเทม Fuel Canister 2 ea', '[Level 1] : ระยะของสกิล 3 x 3 ช่อง : ระยะเวลา 15 วินาที\n[Level 2] : ระยะของสกิล 3 x 3 ช่อง : ระยะเวลา 20 วินาที\n[Level 3] : ระยะของสกิล 3 x 3 ช่อง : ระยะเวลา 25 วินาท'),
('NC_REPAIR', 'Repair', 5, 'Active / Recovery', 'Requirement : Madogear License 2\nฟื้นฟูพลังของ Madogear ทั้งของตัวเองและของคนอื่น ต้องมีไอเทม Repair Kit ในการใช้สกิล และต้องการไอเทม Fuel Canister 1 ea ระยะของสกิล 5 ช่อง Magic Gear จะไม่ได้รับผลของสกิล Heal ต่างๆ', '[Level 1] : ฟื้นฟู HP 4 % จาก HP สูงสุด  / 1 Repair A\n[Level 2] : ฟื้นฟู HP 7 % จาก HP สูงสุด  / 1 Repair A\n[Level 3] : ฟื้นฟู HP 13 % จาก HP สูงสุด  / 1 Repair B\n[Level 4] : ฟื้นฟู HP 17 % จาก HP สูงสุด  / 1 Repair B\n[Level 5] : ฟื้นฟู HP 23 % จาก HP สูงสุด  / 1 Repair C'),
('NC_TRAININGAXE', 'Axe Mastery ', 10, 'Passive', 'Requirement : Mechanic Basic\nเพิ่มความเสียหายและความแม่นยำเมื่อใช้อาวุธประเภท Axe และ Maces (มีผลในขณะขับ Madogear ด้วย)', '[Level 1] : พลังโจมตี +5 / Hit +3\n[Level 2] : พลังโจมตี +10 / Hit +6\n[Level 3] : พลังโจมตี +15 / Hit +9\n[Level 4] : พลังโจมตี +20 / Hit +12\n[Level 5] : พลังโจมตี +25 / Hit +15\n[Level 6] : พลังโจมตี +30 / Hit +18\n[Level 7] : พลังโจมตี +35 / Hit +21\n[Level 8] : พลังโจมตี +40 / Hit +24\n[Level 9] : พลังโจมตี +45 / Hit +27\n[Level 10] : พลังโจมตี +50 / Hit +30'),
('NC_RESEARCHFE', 'Fire Earth Research ', 5, 'Passive', 'Requirement : Mechanic Basic\nศึกษาข้อมูลของมอนสเตอร์ธาตุไฟและมอนสเตอร์ธาตุดิน, ลดความเสียหายที่ได้รับและเพิ่มพลังโจมตีแก่มอนสเตอร์ดังกล่าว', '[Level 1] : เพิ่มความต้านทาน +10 / พลังโจมตี +10\n[Level 2] : เพิ่มความต้านทาน +20 / พลังโจมตี +20\n[Level 3] : เพิ่มความต้านทาน +30 / พลังโจมตี +30\n[Level 4] : เพิ่มความต้านทาน +40 / พลังโจมตี +40\n[Level 5] : เพิ่มความต้านทาน +50 / พลังโจมตี +50'),
('NC_AXEBOOMERANG', 'Axe Boomerang ', 5, 'Active / Damage', 'Requirement : Axe Mastery 1\nขว้างขวานออกไปเพื่อทำความเสียหายในระยะไกล ทำให้เป้าหมายกระเด็นออกไป, น้ำหนักของขวานมีผลต่อความเสียหายของสกิลนี้ ของสกิลสามารถเพิ่มขึ้นได้จาก Base Level ของผู้ใช้', '[Level 1] : พลังโจมตี 300% + น้ำหนักของขวาน / ระยะของสกิล 5 ช่อง\n[Level 2] : พลังโจมตี 350% + น้ำหนักของขวาน / ระยะของสกิล 6 ช่อง\n[Level 3] : พลังโจมตี 400% + น้ำหนักของขวาน / ระยะของสกิล 7 ช่อง\n[Level 4] : พลังโจมตี 450% + น้ำหนักของขวาน / ระยะของสกิล 8 ช่อง\n[Level 5] : พลังโจมตี 500% + น้ำหนักของขวาน / ระยะของสกิล 9 ช่อง'),
('NC_POWERSWING', 'Power Swing', 5, 'Active / Damage', 'Requirement : Axe Boomerang 3\nเหวี่ยงขวานไปยังศัตรู 1 เป้าหมาย มีโอกาสทำให้ติดสถานะ Stun, มีโอกาสที่จะใช้สกิล Axe Boomerang อัตโนมัติหลังจากใช้งานสกิลนี้ ความรุนแรงของสกิลสามารถเพิ่มขึ้นได้จาก STR , DEX และ Base Level ของผู้ใช้', '[Level 1] : พลังโจมตี 400%\n[Level 2] : พลังโจมตี 500%\n[Level 3] : พลังโจมตี 600%\n[Level 4] : พลังโจมตี 700%\n[Level 5] : พลังโจมตี 800%'),
('NC_AXETORNADO', 'Axe Tornado ', 5, 'Active / Damage', 'Requirement : Axe Mastery 1\nหมุนขวานไปรอบตัวด้วยความเร็วสูง สร้างความเสียหายแก่เป้าหมายโดยรอบ ค่า VIT ที่สูงขึ้นจะส่งผลให้ความเสียหายเพิ่มขึ้น ความรุนแรงของสกิลสามารถเพิ่มขึ้นได้หากสวมใส่อาวุธธาตุลม , รวมทั้งค่า VIT และ Base Level ของผู้ใช้ แต่จะใช้ HP ส่วนนึงในการร่ายสกิล', '[Level 1] : พลังโจมตี 300%, ระยะสกิล 5 x 5  ช่อง / ใช้ 20 HP ในการร่ายสกิล\n[Level 2] : พลังโจมตี 400%, ระยะสกิล 5 x 5  ช่อง / ใช้ 40 HP ในการร่ายสกิล\n[Level 3] : พลังโจมตี 500%, ระยะสกิล 7 x 7  ช่อง / ใช้ 60 HP ในการร่ายสกิล\n[Level 4] : พลังโจมตี 600%, ระยะสกิล 7 x 7  ช่อง / ใช้ 80 HP ในการร่ายสกิล\n[Level 5] : พลังโจมตี 700%, ระยะสกิล 7 x 7  ช่อง / ใช้ 100 HP ในการร่ายสกิล'),
('NC_SILVERSNIPER', 'FAW Silver Sniper', 5, 'Active / FAW Set', 'Requirement : Fire Earth Research 2\nติดตั้งอาวุธโจมตีระยะไกลอัตโนมัติ (FAW) ไว้บนพื้น สามารถติดตั้งได้สูงสุด 2 ครั้ง ต้องการไอเทม Steel 2 ea, Iron 1 ea, Mini Furnace 1 ea, Oridecon Hammer 1 ea ในการใช้สกิล', '[Level 1] : พลังโจมตี +0       / ระยะเวลา 20 วินาที\n[Level 2] : พลังโจมตี +200  / ระยะเวลา 30 วินาที\n[Level 3] : พลังโจมตี +400  / ระยะเวลา 40 วินาที\n[Level 4] : พลังโจมตี +800  / ระยะเวลา 50 วินาที\n[Level 5] : พลังโจมตี +1000  / ระยะเวลา 60 วินาที'),
('NC_MAGICDECOY', 'FAW Magic Decoy', 5, 'Active / FAW Set', 'Requirement : FAW Silver Sniper  2\nติดตั้งอาวุธโจมตีระยะไกลอัตโนมัติ (FAW) ซึ่งโจมตีด้วยเวทย์มนตร์ไว้บนพื้น สามารถติดตั้งได้สูงสุด 2 ครั้งต้องการไอเทม Steel 2 ea, Brigan 1 ea, Red Blood 2 ea, Crystal Blue 2 ea, Wind of Verdure 2 ea, Green Live 2 ea, Mini Furnace 1 ea, Oridecon Hammer 1 ea ในการใช้สกิล', '[Level 1] : MATK 300  / ระยะเวลา 20sec.\n[Level 2] : MATK 350  / ระยะเวลา 30sec.\n[Level 3] : MATK 400  / ระยะเวลา 40sec.\n[Level 4] : MATK 450  / ระยะเวลา 50sec.\n[Level 5] : MATK 500  / ระยะเวลา 60sec.'),
('NC_DISJOINT', 'FAW divest ', 1, 'Active / FAW Divest', 'Requirement : FAW Silver Sniper 1\nยกเลิกการติดตั้งอาวุธโจมตีระยะไกลอัตโนมัติ (FAW) สามารถใช้ในการยกเลิก FAW ของผู้อื่นได้', NULL),
('SC_FATALMENACE', 'Fatal Manace', 5, 'Active / Damage', 'Requirement : Snatch 5\nโจมตีเป้าหมาย 1 เป้าหมายและทำให้ศัตรูที่อยู่รอบเป้าหมาย ได้รับความเสียหายในบริเวณนั้น Teleport ออกไป เป้าหมายที่ไม่ได้รับความเสียหายจะไม่ถูก Teleport', '[Level 1] : พลังโจมตี 200% / HIT -30\n[Level 2] : พลังโจมตี 300% / HIT -25\n[Level 3] : พลังโจมตี 400% / HIT -20\n[Level 4] : พลังโจมตี 500% / HIT -15\n[Level 5] : พลังโจมตี 600% / HIT -10'),
('SC_REPRODUCE', 'Reproduce', 10, 'Active Toggle / Buff', 'Requirement : Intimidate 5\nระหว่างผลของความสามารถ จะสามารถเรียนสกิลที่ถูกใช้ใส่ได้ เมื่อกดใช้งานอีกครั้งจะเป็นยกเลิกผลสกิล แต่สกิลที่เรียนมาจะยังคงอยู่ สามารถเรียนได้สูงสุดครั้งละ 1 สกิลเท่านั้น สกิลเลเวลของสกิลที่เรียนะขึ้นอยู่กับเลเวลของสกิลนี้ และเลเวลของสกิลที่เป้าหมายใช้ โดยสกิลที่จดจำมา จะใช้ SP มากกว่าปกติ 2 เท่า', NULL),
('SC_AUTOSHADOWSPELL', 'Shadow Spell', 10, 'Active / Buff', 'Requirement : Reproduce 5\nเมื่อทำการจำสกิลเวทย์มนตร์ด้วย Plagarism หรือเรียนสกิลผ่านสกิล Reproduce จะสามารถใช้งานสกิลดังกล่าวอัตโนมัติแบบ Autospell ได้', '[Level 1] : โอกาศสำเร็จในการร่ายสกิล 28% / Activate Level 1 / ระยะเวลา 60 วินาที\n[Level 2] : โอกาศสำเร็จในการร่ายสกิล 26% / Activate Level 1 / ระยะเวลา 80 วินาที\n[Level 3] : โอกาศสำเร็จในการร่ายสกิล 24% / Activate Level 2 / ระยะเวลา 100 วินาที\n[Level 4] : โอกาศสำเร็จในการร่ายสกิล 22% / Activate Level 2 / ระยะเวลา 120 วินาที\n[Level 5] : โอกาศสำเร็จในการร่ายสกิล 20% / Activate Level 3 / ระยะเวลา 140 วินาที\n[Level 6] : โอกาศสำเร็จในการร่ายสกิล 18% / Activate Level 3 / ระยะเวลา 160 วินาที\n[Level 7] : โอกาศสำเร็จในการร่ายสกิล 16% / Activate Level 4 / ระยะเวลา 180 วินาที\n[Level 8] : โอกาศสำเร็จในการร่ายสกิล 14% / Activate Level 4 / ระยะเวลา 200 วินาที\n[Level 9] : โอกาศสำเร็จในการร่ายสกิล 12% / Activate Level 5 / ระยะเวลา 220 วินาที\n[Level 10] : โอกาศสำเร็จในการร่ายสกิล 15% / Activate Level 5 / ระยะเวลา 300 วินาที'),
('SC_SHADOWFORM', 'Shadow Formation', 5, 'Active / Debuff', 'Requirement : Stalk 3\nซ่อนตัวอยู่ที่เงาของเป้าหมาย สร้างความเสียหายแก่เจ้าของเงานั้นโดยตรง\nผลของสกิลจะสิ้นสุดลงเมื่อโจมตีครบตามที่กำหนด หรืออยู่ห่างจากเป้าหมายมากเกินไปในขณะอยู่ในเงา จะไม่สามารถโจมตี ใช้สกิล หรือไอเทมใดๆได้และมีโอกาสที่สกิลจะถูกยกเลิกด้วยสกิลตรวจจับต่างๆ', '[Level 1] : ได้รับความเสียหาย  5 ครั้งต่อวินาที / เสีย SP วินาทีละ  10 / ระยะเวลา 30 วินาที\n[Level 2] : ได้รับความเสียหาย  6 ครั้งต่อวินาที / เสีย SP วินาทีละ  9 / ระยะเวลา 40 วินาที\n[Level 3] : ได้รับความเสียหาย  7 ครั้งต่อวินาที / เสีย SP วินาทีละ  8 / ระยะเวลา 50 วินาที\n[Level 4] : ได้รับความเสียหาย  8 ครั้งต่อวินาที / เสีย SP วินาทีละ  7 / ระยะเวลา 60 วินาที\n[Level 5] : ได้รับความเสียหาย  9 ครั้งต่อวินาที / เสีย SP วินาทีละ  6 / ระยะเวลา 70 วินาที'),
('SC_TRIANGLESHOT', 'Triangle Shot', 10, 'Active / Damage', 'Requirement : Double Strafe 7\nโจมตีเป้าหมายด้วยธนู 3 ดอกในเวลาเดียวกัน ความแรงของสกิลเพิ่มขึ้นได้ด้วย AGI ของผู้ใช้ ต้องการลูกธนู 3 ดอกในการใช้สกิล มีโอกาสเล็กน้อยที่จะทำให้เป้าหมายกระเด็น', '[Level 1] : ระยะโจมตี 7 ช่อง / มีโอกาศ 2% ที่จะทำให้เป้าหมายกระเด็น\n[Level 2] : ระยะโจมตี 7 ช่อง / มีโอกาศ  3% ที่จะทำให้เป้าหมายกระเด็น\n[Level 3] : ระยะโจมตี 7 ช่อง / มีโอกาศ  4% ที่จะทำให้เป้าหมายกระเด็น\n[Level 4] : ระยะโจมตี 9 ช่อง / มีโอกาศ  5% ที่จะทำให้เป้าหมายกระเด็น\n[Level 5] : ระยะโจมตี 9 ช่อง / มีโอกาศ  6% ที่จะทำให้เป้าหมายกระเด็น\n[Level 6] : ระยะโจมตี 9 ช่อง / มีโอกาศ  7% ที่จะทำให้เป้าหมายกระเด็น\n[Level 7] : ระยะโจมตี 9 ช่อง / มีโอกาศ  8% ที่จะทำให้เป้าหมายกระเด็น\n[Level 8] : ระยะโจมตี 11 ช่อง / มีโอกาศ  9% ที่จะทำให้เป้าหมายกระเด็น\n[Level 9] : ระยะโจมตี 11 ช่อง / มีโอกาศ  10% ที่จะทำให้เป้าหมายกระเด็น\n[Level 10] : ระยะโจมตี 11 ช่อง / มีโอกาศ  11% ที่จะทำให้เป้าหมายกระเด็น'),
('SC_BODYPAINT', 'Body Painting', 5, 'Active / Debuff / Detect', 'Requirement : Shadow Chaser Basic\nฉีดสีสเปรย์ไปรอบๆตัว ทำให้เกิดควัน และสามารถมองเห็นเป้าหมายที่ซ่อนตัวอยู่ได้โจมตีเป้าหมายในระยะของการพ่นสีและทำให้เป้าหมายตาบอด [Blind] และลด ASPD ลง 25%', '[Level 1] : โอกาสตาบอด  55% / มีโอกาศลดความเร็วในการโจมตี 25% / ระยะเวลา 5 วินาที\n[Level 2] : โอกาสตาบอด  57% / มีโอกาศลดความเร็วในการโจมตี 30% / ระยะเวลา 7 วินาที\n[Level 3] : โอกาสตาบอด  59% / มีโอกาศลดความเร็วในการโจมตี 35% / ระยะเวลา 9 วินาที\n[Level 4] : โอกาสตาบอด  61% / มีโอกาศลดความเร็วในการโจมตี 40% / ระยะเวลา 11 วินาที\n[Level 5] : โอกาสตาบอด  63% / มีโอกาศลดความเร็วในการโจมตี 45% / ระยะเวลา 13 วินาที'),
('SC_INVISIBILITY', 'Invisibility', 5, 'Active / Buff', 'Requirement : Shadow Spell 7 / Deadly Infection 5 / Masquerade-Unlucky 3\nซ่อนตัวเองอย่างสมบูรณ์ สามารถโจมตีได้โดยไม่มีใครเห็น การโจมตีในสถานะนี้จะเป็นธาตุวิญญาณ Lv. 1 ในระหว่างการซ่อนตัว SP จะลดลงอย่างต่อเนื่อง ไม่สามารถใช้สกิล และไอเทมต่างๆได้ เมื่อ SP เหลือ 0 จะเป็นการยกเลิก ไม่รับผลของ detect skills และค่าความเสียหายต่างๆ', '[Level 1] : Critical +20% / ความเร็วในการโจมตีลดลง 40% / เสีย SP วินาทีละ 10%\n[Level 2] : Critical +40% / ความเร็วในการโจมตีลดลง 30% / เสีย SP วินาทีละ 8%\n[Level 3] : Critical +60% / ความเร็วในการโจมตีลดลง 20% / เสีย SP วินาทีละ 6%\n[Level 4] : Critical +80% / ความเร็วในการโจมตีลดลง 10% / เสีย SP วินาทีละ 4%\n[Level 5] : Critical +100% / ความเร็วในการโจมตีลดลง 0% / เสีย SP วินาทีละ 2%'),
('SC_DEADLYINFECT', 'Deadly Infection ', 5, 'Active / Buff', 'Requirement : Shadow Formation 3 / Shadow Spell 5\nเมื่อถูกโจมตี หรือโจมตีแล้วติดสถานะผิดปกติ จะโอนถ่ายสถานะผิดปกติทั้งหมดไปยังผู้ใช้ใส่ แต่ไม่ได้หมายความว่าจะเป็นการรักษาสถานะผิดปกติของตัวผู้ใช้', '[Level 1] : ระยะเวลา 10 วินาที / มีโอกาสโอนถ่ายสำเร็จ 40%\n[Level 2] : ระยะเวลา 15 วินาที / มีโอกาสโอนถ่ายสำเร็จ 50%\n[Level 3] : ระยะเวลา 20 วินาที / มีโอกาสโอนถ่ายสำเร็จ 60%\n[Level 4] : ระยะเวลา 25 วินาที / มีโอกาสโอนถ่ายสำเร็จ 70%\n[Level 5] : ระยะเวลา 30 วินาที / มีโอกาสโอนถ่ายสำเร็จ 80%'),
('SC_ENERVATION', 'Masquerade-Enervation ', 3, 'Active / Debuff', 'Requirement : Body Painting 1\nทำให้พลังโจมตีของเป้าหมายลดลง และทำให้เป้าหมายสูญเสีย Spirit Spheres ทั้งหมดต้องการไอเทม Makeover Brush และ Face Paint ในการใช้สกิล ผลของสกิลและโอกาสสำเร็จจะขึ้นอยู่กับเลเวลของเป้าหมาย ไม่มีผลกับ boss monster', '[Level 1] : พลังโจมตีลดลง 30%  / ระยะเวลา 10 วินาที\n[Level 2] : พลังโจมตีลดลง 40%  / ระยะเวลา 15 วินาที\n[Level 3] : พลังโจมตีลดลง 50%  / ระยะเวลา 20 วินาที'),
('SC_GROOMY', 'Masquerade-Groomy', 3, 'Active / Debuff', 'Requirement : Body Painting 1\nลดความเร็วในการเดินและความเร็วในการเคลื่อนที่ของเป้าหมาย ยกเลิกสถานะการขี่สัตว์ การเลี้ยง Q-Pet และโฮมูนคิวลัส ต้องการไอเทม Makeover Brush และ Face Paint ในการใช้สกิล ผลของสกิลและโอกาสสำเร็จจะขึ้นอยู่กับเลเวลของเป้าหมาย ไม่มีผลกับ boss monster', '[Level 1] : ความเร็วในการโจมตีลดลง 30% / HITลดลง 20%  / ระยะเวลา 10 วินาที\n[Level 2] : ความเร็วในการโจมตีลดลง 40% / HITลดลง 40%  / ระยะเวลา 15 วินาที\n[Level 3] : ความเร็วในการโจมตีลดลง 50% / HITลดลง 60%  / ระยะเวลา 20 วินาที'),
('SC_IGNORANCE', 'Masquerade-Ignorance', 3, 'Active / Debuff', 'Requirement : Body Painting 1\nทำให้เป้าหมายเสีย SP และอัตราการฟื้นฟุ SP ลดลงครึ่งนึงจากปกติ เมื่อใช้ใส่มอนสเตอร์ จะได้รับ SP ตามเลเวลของมอนสเอตร์ระหว่างที่เกิดผลเป้าหมายจะไม่สามารถใช้เวทย์มนตร์และสกิลต่างๆได้ ต้องการไอเทม 1 Face Paint ในการใช้สกิล ผลของสกิลและโอกาสสำเร็จจะขึ้นอยู่กับเลเวลของเป้าหมาย ไม่มีผลกับ Boss monster', '[Level 1] : SP ลดลง 100 / ระยะเวลา 10 วินาที\n[Level 2] : SP ลดลง 200 / ระยะเวลา 15 วินาที\n[Level 3] : SP ลดลง 300 / ระยะเวลา 20 วินาที'),
('SC_LAZINESS', 'Masquerade-Laziness', 3, 'Active / Debuff', 'Requirement : Masquerade-Enervation 1 / Groomy 1 / Ignorance 1\nลดความเร็วในการเคลื่อนที่ อัตราการหลบหลีก และเพิ่มระยะเวลาร่ายของเป้าหมายและเป้าหมายจะสกิลจะเสีย SP ตามสกิลเลเวล x 10 เมื่อยังได้รับผลของสกิลนี้ ต้องการไอเทม Makeover Brush และ Face Paint ในการใช้สกิล ผลของสกิลและโอกาสสำเร็จจะขึ้นอยู่กับเลเวลของเป้าหมาย ไม่มีผลกับ Boss monster', '[Level 1] : Flee ลดลง 10%  /  ระยะเวลาร่ายเพิ่มขึ้น  20%  / ระยะเวลา 10 วินาที\n[Level 2] : Flee ลดลง 20%  /  ระยะเวลาร่ายเพิ่มขึ้น  30%  / ระยะเวลา 15 วินาที\n[Level 3] : Flee ลดลง 30%  /  ระยะเวลาร่ายเพิ่มขึ้น  40%  / ระยะเวลา 20 วินาที'),
('SC_UNLUCKY', 'Masquerade-Unlucky', 3, 'Active / Debuff', 'Requirement : Masquerade-Laziness 1 / Weakness 1\nลดค่า Perfect Dodge และ Critical ของเป้าหมายลง ต้องการเงินจำนวนหนึ่งในการใช้สกิล เมื่อใช้สกิลจะสุ่มติดสถานะ Poison, Silence, Blind อย่างน้อย 1 อย่าง ผลของสกิลและโอกาสสำเร็จจะขึ้นอยู่กับเลเวลของเป้าหมาย ไม่มีผลกับ Boss monster', '[Level 1] : Critical ลดลง 10  / Perfect Dodge ลดลง 10  / ระยะเวลา 10 วินาที\n[Level 2] : Critical ลดลง 20  / Perfect Dodge ลดลง 20  / ระยะเวลา 15 วินาที\n[Level 3] : Critical ลดลง 30  / Perfect Dodge ลดลง 30  / ระยะเวลา 20 วินาที'),
('SC_WEAKNESS', 'Masquerade-Weakness', 3, 'Active / Debuff', 'Requirement : Masquerade-Enervation 1 / Groomy 1 / Ignorance 1\nลดค่า HP สูงสุดของเป้าหมายลง โล่ห์ และอาวุธ จะถูกปลดออก ขณะที่ได้รับผลจะไม่สามารถสวมใส่อาวุธและโลห์ได้ ต้องการไอเทม Face Paint ในการใช้สกิล ผลของสกิลและโอกาสสำเร็จจะขึ้นอยู่กับเลเวลของเป้าหมาย ไม่มีผลกับ Boss monster', '[Level 1] : MHP ลดลง 10%  / ระยะเวลา 10 วินาที\n[Level 2] : MHP ลดลง 20%  / ระยะเวลา 15 วินาที\n[Level 3] : MHP ลดลง 30%  / ระยะเวลา 20 วินาที'),
('SC_STRIPACCESSARY', 'Strip Accessory ', 5, 'Active / Debuff', 'Requirement : Divest Weapon 1\nทำการปลดเครื่องประดับทั้งสองของเป้าหมายออก ในระหว่างที่เกิดผลจะไม่สามารถสวมใส่เครื่องประดับได้เมื่อใช้กับมอนสเตอร์จะเป็นการลด Int, Dex, Luk ลง 20%', '[Level 1] : โอกาศสำเร็จ 14% / ระยะเวลา 60 วินาที\n[Level 2] : โอกาศสำเร็จ 16% / ระยะเวลา 60 วินาที\n[Level 3] : โอกาศสำเร็จ 18% / ระยะเวลา 60 วินาที\n[Level 4] : โอกาศสำเร็จ 20% / ระยะเวลา 60 วินาที\n[Level 5] : โอกาศสำเร็จ 22% / ระยะเวลา 60 วินาที'),
('SC_MANHOLE', 'Manhole ', 3, 'Active / Ground', 'Requirement : Piece 1\nสร้างหลุมดำเอาไว้ เป้าหมายที่ตกลงไปจะไม่สามารถทำอะไรได้ และ ไม่สามารถโจมตีใครได้ต้องการไอเทม Brush และ Paint Surface 1 ea', '[Level 1] : ระยะเวลา 5 วินาที\n[Level 2] : ระยะเวลา 10 วินาที\n[Level 3] : ระยะเวลา 15 วินาที'),
('SC_DIMENSIONDOOR', 'Dimension Door', 3, 'Active / Ground', 'Requirement : Manhole 1\nสร้างประตูเวทย์มนตร์ไว้ ทำการเทเลพอร์ตผู้เล่น และสมาชิกภายในปาร์ตี้ ไปในที่ต่างๆที่กำหนดไว้ต้องการไอเทม Brush และ Paint Surface 1 ea', '[Level 1] : ระยะเวลา 4 วินาที\n[Level 2] : ระยะเวลา 8 วินาที\n[Level 3] : ระยะเวลา 12 วินาที'),
('SC_CHAOSPANIC', 'Chaos Panic ', 3, 'Active / Ground', 'Requirement : Manhole 1\nวาดลายที่ดูมึนงงไว้ที่พื้น ซึ่งเป้าหมายที่เข้ามาจะไม่สามารถควบคุมทิศทางในการเคลื่อนที่ได้และเลือกเป้าหมายโจมตีแบบสุ่ม ต้องการไอเทม Brush และ Paint Surface 2 ea', '[Level 1] : ระยะเวลา 5 วินาที\n[Level 2] : ระยะเวลา 10 วินาที\n[Level 3] : ระยะเวลา 15 วินาที'),
('SC_MAELSTROM', 'Maelstrom', 3, 'Active / Ground', 'Requirement : Chaos Panic 3 / Masquerade-Unlucky 3\nวาดวงก้นหอยไว้ที่พื้น ซึ่งสามารถดูดเวทย์มนตร์ลงไปได้ และนำมาฟื้นฟู SP ให้แก่ผู้ใช้ ตามเลเวลของเวทย์มนตร์ต้องการไอเทม Brush และ Paint Surface 2 ea', '[Level 1] : ระยะเวลา 7 วินาที\n[Level 2] : ระยะเวลา 14 วินาที\n[Level 3] : ระยะเวลา 21 วินาที'),
('SC_BLOODYLUST', 'Bloody Lust ', 3, 'Active / Ground', 'Requirement : Dimension Door 3\nเมื่อเป้าหมายมาอยู่บนลายสีแดงนี้ จะได้รับผลของสกิล Berserk ต้องการไอเทม Brush และ Paint Surface 2 ea', '[Level 1] : ระยะเวลา 7 วินาที\n[Level 2] : ระยะเวลา 14 วินาที\n[Level 3] : ระยะเวลา 21 วินาที'),
('SC_FEINTBOMB', 'Feint Bomb', 3, 'Active / Ground', 'Requirement : Dimension Door 3\nสร้างร่างโคลนไว้ที่พื้น และตัวผู้ใช้จะถอยหลังไป 6 ช่องด้วย Back Slide และทำการหายตัว ซึ่งร่างโคลนจะทำการระเบิดตัวเอง ความเสียหายเพิ่มขึ้นได้ด้วย JobLV และ DEX ของผู้ใช้ สร้างความเสียหายเป็นวงกว้าง ต้องการไอเทม Brush และ Paint Surface 1 ea', '[Level 1] : ถอยหลัง 3 ช่อง\n[Level 2] : ถอยหลัง 6 ช่อง\n[Level 3] : ถอยหลัง 9 ช่อง'),
('LG_CANNONSPEAR', 'Cannon Spear', 5, 'Active / Damage', 'Requirement : Pinpoint Attack 1\nเป็นสกิลสำหรับอาวุธประเภทหอกเท่านั้น ผลของสกิลจะเป็นการโจมตีเป้าหมายทั้งหมดในแนวเส้นตรงยาว 11 ช่อง ความเสียหายเพิ่มขึ้นได้ด้วย BaseLV และ STR', '[Level 1] : พลังโจมตี 50%\n[Level 2] : พลังโจมตี 100%\n[Level 3] : พลังโจมตี 150%\n[Level 4] : พลังโจมตี 200%\n[Level 5] : พลังโจมตี 250%'),
('LG_BANISHINGPOINT', 'Banishing Point', 10, 'Active / Damage', 'Requirement : Spear Mastery 1\nเป็นสกิลสำหรับอาวุธประเภทหอกเท่านั้น เป็นการโจมตีระยะไกลขนาด 7 ช่อง ค่า Hit rate จะสูงขึ้นเมื่อ Lv ของสกิลสูงขึ้น และ Lv ของสกิล Bash มีผลต่อการเพิ่มค่าความเสียหายของสกิล', '[Level 1] : พลังโจมตี 50%\n[Level 2] : พลังโจมตี 110%\n[Level 3] : พลังโจมตี 150%\n[Level 4] : พลังโจมตี 200%\n[Level 5] : พลังโจมตี 250%\n[Level 6] : พลังโจมตี 300%\n[Level 7] : พลังโจมตี 350%\n[Level 8] : พลังโจมตี 400%\n[Level 9] : พลังโจมตี 450%\n[Level 10] : พลังโจมตี 500%'),
('LG_TRAMPLE', 'Trample', 3, 'Active / Special', 'Requirement : Royal Guard Basic\nเป็นการกระทืบเท้าส่งผลให้ Trap ทั้งหมดในบริเวณ 5 x 5 ช่องถูกทำลาย ยกเว้น Trap ที่สามารถระเบิดได้จะส่งผล Trap เกิดระเบิดขึ้นมา  โดยความแรงขึ้นอยู่กับ DEX และ AGI', '[Level 1] : โอกาศสำเร็จ 50%\n[Level 2] : โอกาศสำเร็จ 75%\n[Level 3] : โอกาศสำเร็จ 100%'),
('LG_SHIELDPRESS', 'Shield Press', 5, 'Active / Damage', 'Requirement : Smite 3\nเป็นสกิลสำหรับโล่ห์เท่านั้น จะเป็นการโจมตีเป้าหมายและ Stun ด้วยโล่ห์ โดยค่าความเสียหายขึ้นกับน้ำหนักของโล่ห์, การ upgrade และค่า Status ของผู้ใช้, โอกาสสำเร็จในการทำให้ติดสถานะ [Stun] ขึ้นอยู่กับ DEX และ job level ของผู้ใช้', '[Level 1] : โอกาสเกิด [Stun] 38%\n[Level 2] : โอกาสเกิด [Stun] 46%\n[Level 3] : โอกาสเกิด [Stun] 54%\n[Level 4] : โอกาสเกิด [Stun] 62%\n[Level 5] : โอกาสเกิด [Stun] 70%'),
('LG_REFLECTDAMAGE', 'Reflect Damage', 5, 'Active / Buff (To yourself)', 'Requirement : Shield Reflect 5\nเป็นสกิลสำหรับโล่ห์เท่านั้น เมื่อได้รับการโจมตีทางกายภาพและเวทมนต์ จะทำการสะท้อนค่าความเสียหายที่ได้รับไปรอบๆตัวผู้ใช้ ขณะที่ทำการใช้สกิล SP จะลดลงเรื่อยๆ และไม่สามารถใช้ร่วมกับสกิล Reflect Shield ได้ จำนวนค่าความเสียหายที่สะท้อนได้ ขึ้นอยู่กับ MHP ของผู้ใช้ และ มันสามารถเพิ่มขึ้นได้ถึง 1.5 เท่า โดย ขึ้นอยู่กับ Base Lv.', '[Level 1] : สะท้อน 20% ของความเสียหาย / โอกาสในการสะท้อนกลับ 40% / สะท้อนกลับได้จำนวน 30 ครั้ง\n[Level 2] : สะท้อน 25% ของความเสียหาย / โอกาสในการสะท้อนกลับ 50% / สะท้อนกลับได้จำนวน 35 ครั้ง\n[Level 3] : สะท้อน 30% ของความเสียหาย / โอกาสในการสะท้อนกลับ 60% / สะท้อนกลับได้จำนวน 40 ครั้ง\n[Level 4] : สะท้อน 35% ของความเสียหาย / โอกาสในการสะท้อนกลับ 70% / สะท้อนกลับได้จำนวน 45 ครั้ง\n[Level 5] : สะท้อน 40% ของความเสียหาย / โอกาสในการสะท้อนกลับ 80% / สะท้อนกลับได้จำนวน 50 ครั้ง'),
('LG_PINPOINTATTACK', 'Pinpoint Attack', 5, 'Active / Damage', 'Requirement : Banishing Point 5\nเป็นสกิลสำหรับอาวุธประเภทหอกเท่านั้น จะทำการพุ่งเข้าไปโจมตีจุดตายของเป้าหมายจากระยะไกล Lv ของสกิลจะส่งผลให้เกิดสถานะต่อเป้าหมายแตกต่างกันไป ค่าความเสียหายขึ้นกับค่า Agi ของผู้ใช้ และจะเป็นการโจมตีแบบ Critical 100%', '[Level 1] : พลังโจมตี 100% / ส่งผลให้เป้าหมายติดสถานะ  Bleeding effect\n[Level 2] : พลังโจมตี 200% / ส่งผลให้เป้าหมายติดสถานะ  Headgear destruction\n[Level 3] : พลังโจมตี 300% / ส่งผลให้เป้าหมายติดสถานะ  Shield destruction\n[Level 4] : พลังโจมตี 400% / ส่งผลให้เป้าหมายติดสถานะ  Armor destruction\n[Level 5] : พลังโจมตี 500% / ส่งผลให้เป้าหมายติดสถานะ  Weapon destruction'),
('LG_FORCEOFVANGUARD', 'Vanguard Force', 5, 'Active / Buff (To yourself)', 'Requirement : Royal Guard Basic\nขณะที่มีการใช้สกิล เมื่อได้รับการโจมตีทางกายภาพจะมีโอกาสเพิ่ม Rage Counter โดยจะถูกใช้โดยสกิล Rage Burst Attack และเมื่อใช้สกิล Rage Burst Attack แล้วจะถือเป็นการยกเลิกสกิล Force of Vanguard ขณะที่ใช้สกิล SP จะถูกลดลงไปเรื่อยๆ', '[Level 1] : มีโอกาส 20% ที่จะเพิ่ม Rage Counter เมื่อได้รับการโจมตี / สามารถเก็บ Rage Counter ได้สูงสุด: 7\n[Level 2] : มีโอกาส 32% ที่จะเพิ่ม Rage Counter เมื่อได้รับการโจมตี / สามารถเก็บ Rage Counter ได้สูงสุด: 9\n[Level 3] : มีโอกาส 44% ที่จะเพิ่ม Rage Counter เมื่อได้รับการโจมตี / สามารถเก็บ Rage Counter ได้สูงสุด: 11\n[Level 4] : มีโอกาส 56% ที่จะเพิ่ม Rage Counter เมื่อได้รับการโจมตี / สามารถเก็บ Rage Counter ได้สูงสุด: 13\n[Level 5] : มีโอกาส 68% ที่จะเพิ่ม Rage Counter เมื่อได้รับการโจมตี / สามารถเก็บ Rage Counter ได้สูงสุด: 15'),
('LG_RAGEBURST', 'Burst Attack', 1, 'Active / Damage', 'Requirement : Vanguard Force 1\nใช้ Rage Counter ทั้งหมดจากสกิล Vanguard Force ทำความเสียหายอย่างหนักแก่เป้าหมายเดียว โดยค่าความเสียหายเพิ่มขึ้นเมื่อมีจำนวนของ Rage Counter มากขึ้น', NULL),
('LG_SHIELDSPELL', 'Shield Spell', 3, 'Active / Special', 'Requirement : Shield Press 3 / Earth Drive 2\nเป็นสกิลสำหรับโล่ห์เท่านั้น ผลของสกิลจะเป็นการเพิ่มผลของเวทย์มนต์ตามค่าของพลังป้องกันทางกายภาพ, พลังป้องกันทางเวทมนต์และอัตราการ upgrade ของโล่ห์', '[Level 1] : เพิ่มผลของเวทมนต์ตามพลังป้องกันทางกายภาพของโล่ห์\n[Level 2] : เพิ่มผลของเวทมนต์ตามพลังป้องกันทางเวทมนต์ของโล่ห์\n[Level 3] : เพิ่มผลของเวทมนต์ตามอัตราการ upgrade ของโล่ห์'),
('LG_EXEEDBREAK', 'Exceed Break', 5, 'Active / Buff (To yourself)', 'Requirement : Banishing Point 3\nทำการสะสมพลังโจมตีเพื่อใช้ในการโจมตีอย่างหนักในครั้งต่อไป ค่า job level, เลเวลของอาวุธ และ น้ำหนักของอาวุธของผู้ใช้มีผลต่อค่า ความเสียหาย เมื่อผู้ใช้ได้รับการโจมตีทางกายภาพระยะใกล้จะเป็นการยกเลิกสกิลทันที ผลของสกิลไม่มีผลเพิ่มค่าความเสียหายของสกิลอื่น และเมื่อถูกใช้จะทำให้การเคลื่อนที่ช้าลง', '[Level 1] : พลังโจมตี 100%\n[Level 2] : พลังโจมตี 200%\n[Level 3] : พลังโจมตี 300%\n[Level 4] : พลังโจมตี 400%\n[Level 5] : พลังโจมตี 500%'),
('LG_OVERBRAND', 'Over Brand', 5, 'Active / Damage', 'Requirement : Moon Slasher 3 / Pinpoint Attack 1\nเป็นสกิลสำหรับอาวุธประเภทหอกเท่านั้น ทำการสร้างกางเขนขนาดยาว 6 ช่องและกว้าง 6 ช่อง เป้าหมายที่ได้รับค่าความเสียหายของสกิลจะกระเด็นออกไป หากการกระเด็นส่งผลให้กระทบกับกำแพง จะทำให้ได้รับความเสียหายเพิ่มเติม ความเสียหายจาก Piercing เพิ่มขึ้นได้จาก BaseLV และ Lv ของ Spear Quicken จะส่งผลต่อค่าความเสียหาย ความเสียหายของ Smashing เพิ่มขึ้นได้จาก BaseLV, STR และ DEX', '[Level 1] : พลังโจมตี Piercing 200% / พลังโจมตี Smashing  100%\n[Level 2] : พลังโจมตี Piercing  400% / พลังโจมตี Smashing  200%\n[Level 3] : พลังโจมตี Piercing  600% / พลังโจมตี Smashing  300%\n[Level 4] : พลังโจมตี Piercing  800% / พลังโจมตี Smashing  400%\n[Level 5] : พลังโจมตี Piercing  1000% / พลังโจมตี Smashing 500%'),
('LG_PRESTIGE', 'Prestige', 5, 'Active / Buff (To yourself)', 'Requirement : Trample 3\nทำการเพิ่มโอกาสที่จะหลบการโจมตีทางด้านเวทมนต์ และเพิ่มพลังป้องกันทางกายภาพ ค่า Status ของผู้ใช้ส่งผลต่ออัตราการหลบหนี และ Lv ของ Defending Aura จะช่วยเพิ่มพลังป้องกัน เมื่อทำการหลบหนีสำเร็จจะไม่ได้รับความเสียหายจากการโจมตี', '[Level 1] : ระยะเวลา 30 วินาที\n[Level 2] : ระยะเวลา 45 วินาที\n[Level 3] : ระยะเวลา 60 วินาที\n[Level 4] : ระยะเวลา 75 วินาที\n[Level 5] : ระยะเวลา 90 วินาที'),
('LG_BANDING', 'Banding', 5, 'Active / Buff (To yourself)', 'Requirement : Pinpoint Attack 3 / Burst Attack 1\nเมื่อมี Royal guard อยู่ใน party และใช้สกิลนี้ เมื่ออยู่ใกล้ Royal guard จะส่งผลให้พลังโจมตีและพลังป้องกันเพิ่มขึ้น และจะ Share HP กัน โดยขณะที่มีการใช้สกิลค่า SP จะลดลงตลอดเวลา และเมื่อมีการใช้อีกครั้งจะเป็นการยกเลิกผลของสกิล จำนวนสมาชิกใน party จะเพิ่มประสิทธิภาพของสกิล หากศัตรูเข้ามาใกล้ในขณะที่ผลของสกิลยังคงอยู่ มีโอกาสทำให้ติดสถานะ ''overawe'' ซึ่งทำให้ความเร็วในการเคลื่อนที่ลดลง base level และ Banding skill มีผลต่ออัตราสำเร็จของ ''overawe'' และ ระยะเวลาที่มากขึ้น', NULL),
('LG_MOONSLASHER', 'Moon Slasher', 5, 'Active / Damage', 'Requirement : Spear Mastery 1\nทำการโจมตีเป้าหมายทั้งหมดในรัศมี 3 ช่องรอบตัวผู้ใช้ โดยเมื่อเป้าหมายโดนโจมตีจะเป็นการบังคับให้เป้าหมายนั่งลง หากเป็นการใช้กับ Monster จะเป็นการหยุดการเคลื่อนที่ของเป้าหมาย 1~3 วินาทีแทน Lv ของสกิล Over Brand จะช่วยเพิ่มค่าความเสียหายของสกิล', '[Level 1] : พลังโจมตี 120% / โอกาศสำเร็จ 40%\n[Level 2] : พลังโจมตี 240% / โอกาศสำเร็จ 48%\n[Level 3] : พลังโจมตี 360% / โอกาศสำเร็จ 56%\n[Level 4] : พลังโจมตี 480% / โอกาศสำเร็จ 64%\n[Level 5] : พลังโจมตี 600% / โอกาศสำเร็จ 72%'),
('LG_RAYOFGENESIS', 'Genesis Ray', 5, 'Active / Damage', 'Requirement : Grand Cross 5\nทำการเรียกภูติและวิญญาณจากท้องฟ้าเพื่อทำการโจมตีเป้าหมายทั้งหมดในรัศมี 5 ช่องด้วยธาตุศักดิ์สิทธิ์ ต้องใช้ Royal guard ที่ใช้สกิล Banding อย่างน้อย 2 คน ค่าความเสียหายจะเพิ่มขึ้นตามจำนวนของ Royal guard ที่ใช้สกิล Banding เมื่อใช้กัน Monster ประเภท Undead และ Demon จะมีโอกาส 50% ที่จะตาบอด', '[Level 1] : พลังโจมตีทางกายภาพ 600% พลังโจมตีทางเวทย์มนตร์  300%  / เสีย HP ในการใช้สกิล 3%\n[Level 2] : พลังโจมตีทางกายภาพ 900% พลังโจมตีทางเวทย์มนตร์  600% / เสีย HP ในการใช้สกิล 6%\n[Level 3] : พลังโจมตีทางกายภาพ 1200% พลังโจมตีทางเวทย์มนตร์  900% / เสีย HP ในการใช้สกิล 9%\n[Level 4] : พลังโจมตีทางกายภาพ 1500% พลังโจมตีทางเวทย์มนตร์  1200% / เสีย HP ในการใช้สกิล 12%\n[Level 5] : พลังโจมตีทางกายภาพ 1800% พลังโจมตีทางเวทย์มนตร์  1500% / เสีย HP ในการใช้สกิล 15%'),
('LG_PIETY', 'Piety', 5, 'Active / Buff', 'Requirement : Faith 3\nทำการสละชุดเกราะของสมาชิกภายใน party ให้กับสมาชิกคนอื่นที่อยู่ใกล้กันด้วยธาตุศักดิ์สิทธิ์ ต้องใช้ Holy water 2 ขวด และสามารถใช้ได้กับตัวเอง', '[Level 1] : ระยะเวลา 60 วินาที\n[Level 2] : ระยะเวลา 80 วินาที\n[Level 3] : ระยะเวลา 100 วินาที\n[Level 4] : ระยะเวลา 120 วินาที\n[Level 5] : ระยะเวลา 140 วินาที'),
('LG_EARTHDRIVE', 'Earth Drive', 5, 'Active / Damage', 'Requirement : Reflect Damage 3\nทำการแกว่งโล่ห์และทำความเสียหายให้กับเป้าหมายทั้งหมดในระยะของสกิลด้วยธาตุดิน เป็นสกิลที่ร่ายลงพื้นมีผลกับศัตรูที่ซ่อนตัวอยู่ เป้าหมายที่ได้รับความเสียหายจะลดพลังป้องกันและความเร็วในการโจมตีลง 25%, Lv ของสกิลจะเพิ่มระยะเวลาที่จะลดพลังป้องกันและความเร็วในการโจมตี ค่าพลังโจมตีขึ้นกับน้ำหนักของโล่ห์ มีโอกาสเล็กน้อยทำให้โล่ห์ถูกทำลาย', '[Level 1] : ระยะโจมตี 3 x 3 ช่อง / ระยะเวลา ลดความเร็วในการโจมตีและพลังป้องกันลง 3 วินาที\n[Level 2] : ระยะโจมตี 3 x 3 ช่อง / ระยะเวลา ลดความเร็วในการโจมตีและพลังป้องกันลง 6 วินาที\n[Level 3] : ระยะโจมตี 5 x 5 ช่อง / ระยะเวลา ลดความเร็วในการโจมตีและพลังป้องกันลง 9 วินาที\n[Level 4] : ระยะโจมตี 5 x 5 ช่อง / ระยะเวลา ลดความเร็วในการโจมตีและพลังป้องกันลง 12 วินาที\n[Level 5] : ระยะโจมตี 7 x 7 ช่อง / ระยะเวลา ลดความเร็วในการโจมตีและพลังป้องกันลง 15 วินาที'),
('LG_HESPERUSLIT', 'Hesperus Lit', 5, 'Active / Damage', 'Requirement : Prestige 3 / Banding 3\nใช้ Royal guard ที่ใช้สกิล Banding อย่างน้อย 3 คน โดย Royal guard ทั้งหมดจะทำการโจมตีเป้าหมายเดียวกันในคราวเดียว จำนวนของ Royal guard ที่ใช้สกิล Banding จะส่งผลให้จำนวน Hit ที่เป้าหมายได้รับเพิ่มมากขึ้น เมื่อทำการใช้สกิล Royal guard คนอื่นๆจะถูกลด SP ลงครึ่งหนึ่งของทั้งหมดที่ต้องใช้', '[Level 1] : พลังโจมตี 120%\n[Level 2] : พลังโจมตี 240%\n[Level 3] : พลังโจมตี 360%\n[Level 4] : พลังโจมตี 480%\n[Level 5] : พลังโจมตี 600%'),
('LG_INSPIRATION', 'Inspiration', 5, 'Active / Buff (To yourself)', 'Requirement : Shield Spell 3 / Genesis Ray 4 / Piety 5\nเมื่อทำการใช้สกิล Inspiration ค่าความแม่นยำ, ค่า Status, ค่าพลังโจมตีและ HP สูงสุดจะเพิ่มขึ้น , Buff และสถานะผิกปกติทั้งหมดจะถูกยกเลิก , และสร้างเกราะป้องกัน Buff และสถานะผิกปกติทั้งหมดด้วย , แต่อย่างไรก็ตาม ขณะที่ใช้สกิล HP และ SP จะลดลงอย่างต่อเนื่อง และผู้ใช้ได้รับ Damage จากการโจมตีบางส่วน เมื่อ SP ลดลงเหลือ 0 จะเป็นการยกเลิกผลของสกิล และถ้า HP ลดลงเหลือ 0 ผู้ใช้จะตาย เมื่อใช้สกิลต้องเสียค่าประสบการณ์ 1% และไม่สามารถป้องกันการเสียค่าประสบการณ์ได้ ขณะที่ใช้สกิลไม่สามารถใช้สกิล Banding และ Prestige ได้', '[Level 1] : ระยะเวลา 30 วินาที\n[Level 2] : ระยะเวลา 45 วินาที\n[Level 3] : ระยะเวลา 60 วินาที\n[Level 4] : ระยะเวลา 75 วินาที\n[Level 5] : ระยะเวลา 90 วินาที'),
('SR_DRAGONCOMBO', 'Dragon Combo', 10, 'Active / Damage', 'Requirement : Raging Trifecta Blow 5\nจู่โจมเป้าหมาย ด้วยหมัดสองจังหวะอย่างรวดเร็ว มีโอกาสทำให้ศัตรูติด Stun , และสามารถใช้สกิล Fallen Empire ต่อเนื่องจาก สกิลนี้ได้', '[Level 1] : พลังโจมตี 140% /โอกาศติดสถานะ [Stun] 2%\n[Level 2] : พลังโจมตี 180% /โอกาศติดสถานะ [Stun] 3%\n[Level 3] : พลังโจมตี 220% /โอกาศติดสถานะ [Stun] 4%\n[Level 4] : พลังโจมตี 260% /โอกาศติดสถานะ [Stun] 5%\n[Level 5] : พลังโจมตี 300% /โอกาศติดสถานะ [Stun] 6%\n[Level 6] : พลังโจมตี 340% /โอกาศติดสถานะ [Stun] 7%\n[Level 7] : พลังโจมตี 380% /โอกาศติดสถานะ [Stun] 8%\n[Level 8] : พลังโจมตี 420% /โอกาศติดสถานะ [Stun] 9%\n[Level 9] : พลังโจมตี 460% /โอกาศติดสถานะ [Stun] 10%\n[Level 10] : พลังโจมตี 500% /โอกาศติดสถานะ [Stun] 11%'),
('SR_SKYNETBLOW', 'Sky Blow', 5, 'Active / Damage', 'Requirement : Dragon Combo 3\nหมุนตัวโจมตีรอบทิศ สร้างความเสียหายให้แก่เป้าหมายในบริเวณรอบตัว และผลักศัตรูถอยหลัง 3 ช่อง ค่า AGI ของผู้ใช้สามารถเพิ่มความรุนแรงของสกิลนี้ได้', '[Level 1] : พลังโจมตี 80%\n[Level 2] : พลังโจมตี 160%\n[Level 3] : พลังโจมตี 240%\n[Level 4] : พลังโจมตี 320%\n[Level 5] : พลังโจมตี 400%'),
('SR_EARTHSHAKER', 'Earth Shaker', 5, 'Active / Damage', 'Requirement : Dragon Combo 1 / Cursed Circle 1\nสร้างคลื่อนช๊อคลงสู่พื้นดิน สร้างความเสียหายแก่เป้าหมายในระยะ 11 x 11 ช่อง โดยเป้าหมายที่อยู่ในสถานะซ่อนตัว จะได้รับความเสียหายมากยิ่งขึ้น และเป้าหมายที่อยู่ในสถานะซ่อนตัวจะเผยตัวออกมาเมื่อได้รับความเสียหายจากสกิลนี้ [ ต้องการ 1 Spirit Sphere ในการใช้สกิลนี้ ]', '[Level 1] : ระยะ 3 x 3  ช่อง / พลังโจมตี 100%  / ศัตรูที่อยู่ในสถานะซ่อนตัว 300%\n[Level 2] : ระยะ 5 x 5  ช่อง / พลังโจมตี 150%  / ศัตรูที่อยู่ในสถานะซ่อนตัว 450%\n[Level 3] : ระยะ 7 x 7  ช่อง / พลังโจมตี 200%  / ศัตรูที่อยู่ในสถานะซ่อนตัว 600%\n[Level 4] : ระยะ 9 x 9  ช่อง / พลังโจมตี 250%  /ศัตรูที่อยู่ในสถานะซ่อนตัว  750%\n[Level 5] : ระยะ 11 x 11  ช่อง / พลังโจมตี 300%  / ศัตรูที่อยู่ในสถานะซ่อนตัว 900%'),
('SR_FALLENEMPIRE', 'Fallen Empire', 5, 'Active / Damage', 'Requirement : Dragon Combo 1\nใช้ไหล่และกำปั้น กระแทกศัตรูขึ้นสู่ด้านบน สร้างความเสียหายอย่างมากแก่ 1 เป้าหมาย ความเสียหายจะเพิ่มมากขึ้นตามน้ำหนักของเป้าหมาย , หลังได้รับความเสียหาย เป้าหมายจะไม่สามารถเคลื่อนไหวได้ชั่วเวลาหนึ่ง โดยสกิลนี้สามารถใช้ได้ต่อเนื่องจากสกิล Dragon Combo เท่านั้น และ เมื่อใช้สกิลนี้แล้วจะ สามารถใช้สกิล Tiger Cannon และ Gate of Hell ต่อเนื่องได้ [ ต้องการ 2 Spirit Sphere ในการใช้สกิลนี้ ]', '[Level 1] : พลังโจมตี 250% / เป้าหมายเคลื่อนไหวไม่ได้เป็นเวลา  0.5 วินาที\n[Level 2] : พลังโจมตี 400% / เป้าหมายเคลื่อนไหวไม่ได้เป็นเวลา  1 วินาที\n[Level 3] : พลังโจมตี 550% / เป้าหมายเคลื่อนไหวไม่ได้เป็นเวลา  1.5 วินาที\n[Level 4] : พลังโจมตี 700% / เป้าหมายเคลื่อนไหวไม่ได้เป็นเวลา  2 วินาที\n[Level 5] : พลังโจมตี 850% / เป้าหมายเคลื่อนไหวไม่ได้เป็นเวลา  2.5 วินาที'),
('SR_TIGERCANNON', 'Tiger Cannon', 10, 'Active / Damage', 'Requirement : Fallen Empire 3\nโจมตีเป้าหมายโดยใช้ Hp และ Sp ของตัวเอง ความรุนแรงของสกืลขึ้นอยู่กับ Hp และ Sp ของผู้ใช้ , สามารถใช้ได้เมื่ออยู่ในสถานะ Fury (Explosion Spirits) เท่านั้น หากใช้สกิลนี้ต่อเนื่องจากสกิล Fallen Empire จะสร้างความเสียหายได้มากขึ้น [ ต้องการ 2 Spirit Sphere ในการใช้สกิลนี้ ]', '[Level 1] : ระยะ 3 x 3  ช่อง / ต้องการ HP  12% / SP  6%\n[Level 2] : ระยะ 3 x 3  ช่อง / ต้องการ HP  14% / SP  7%\n[Level 3] : ระยะ 3 x 3  ช่อง / ต้องการ HP  16% / SP  8%\n[Level 4] : ระยะ 3 x 3  ช่อง / ต้องการ HP  18% / SP  9%\n[Level 5] : ระยะ 3 x 3  ช่อง / ต้องการ HP  20% / SP  10%\n[Level 6] : ระยะ 5 x 5  ช่อง / ต้องการ HP  22% / SP  11%\n[Level 7] : ระยะ 5 x 5  ช่อง / ต้องการ HP  24% / SP  12%\n[Level 8] : ระยะ 5 x 5  ช่อง / ต้องการ HP  26% / SP  13%\n[Level 9] : ระยะ 5 x 5  ช่อง / ต้องการ HP  28% / SP  14%\n[Level 10] : ระยะ 5 x 5  ช่อง / ต้องการ HP  30% / SP  15%'),
('SR_RAMPAGEBLASTER', 'Rampage Blast', 5, 'Active / Damage', 'Requirement : Earth Shaker 2\nโจมตีโดยใช้ Spirit Sphere ที่มีอยู่ทั้งหมด แก่เป้าหมาย ในรัศมี 7 x 7 ช่อง , ความรุนแรงของสกิลขึ้นอยู่กับจำนวน Spirit Sphere และ เลเวลของสกิล ความรุนแรงเพิ่มขึ้นหากผู้ใช้อยู่ในสถานะ Vigor Explosion', NULL),
('SR_CRESCENTELBOW', 'Crescent Elbow', 5, 'Active / Counterattack', 'Requirement : Sky Blow 1\nตั้งรับการโจมตีจากเป้าหมาย , สร้างความเสียหายและผลักถอยหลังออกไป , แต่เรายังจะได้รับความเสียหายอยู่ ยิ่ง Hp ของเป้าหมายสูง ความรุนแรงจะยิ่งเพิ่มขึ้น, Job level มีผลต่อสกิล ไม่สามารถใช้กับ Boss Monsters ได้[ ต้องการ 2 Spirit Sphere ในการใช้สกิลนี้ ]', '[Level 1] : โอกาศสำเร็จในการร่ายสกิล 55% / ระยะเวลา 3 วินาที\n[Level 2] : โอกาศสำเร็จในการร่ายสกิล 60% / ระยะเวลา 4 วินาที\n[Level 3] : โอกาศสำเร็จในการร่ายสกิล 65% / ระยะเวลา 5 วินาที\n[Level 4] : โอกาศสำเร็จในการร่ายสกิล 70% / ระยะเวลา 6 วินาที\n[Level 5] : โอกาศสำเร็จในการร่ายสกิล 75% / ระยะเวลา 7 วินาที'),
('SR_CURSEDCIRCLE', 'Cursed Circle', 5, 'Active / Special', 'Requirement : Root 2 / Gentle Touch-Silence 2\nสร้างพื้นที่แห่งมนตรา 5 x 5 ช่องรอบตัวผู้ใช้ เป้าหมายที่อยู่ในระยะจะไม่สามารถเคลื่อนที่ใช้สกิลหรือโจมตีได้หากผู้ใช้สกิลนี้ ใช้สกิลอื่น จะเป็นการยกเลิกผลของสกิลนี้ทันที  [ ต้องการ 1 Spirit Sphere ในการใช้สกิลนี้ ]', '[Level 1] : ระยะ 3 x 3  ช่อง / ระยะเวลา 3 วินาที\n[Level 2] : ระยะ 3 x 3  ช่อง / ระยะเวลา 4 วินาที\n[Level 3] : ระยะ 5 x 5  ช่อง / ระยะเวลา 5 วินาที\n[Level 4] : ระยะ 5 x 5  ช่อง / ระยะเวลา 6 วินาที\n[Level 5] : ระยะ 7 x 7  ช่อง / ระยะเวลา 7 วินาที'),
('SR_LIGHTNINGWALK', 'Lightning Walk', 5, 'Active Toggle / Special', 'Requirement : Wind Mill 1\nเมื่อถูกโจมตีด้วยการโจมตีทางกายภาพ ผู้ใช้สกิลนี้มีโอกาสที่จะป้องกันจากการโจมตีได้ 1 ครั้ง และกระโดดไปหาเป้าหมายที่โจมตีใส่โดยทันที เมื่อความสามารถของสกิลนี้ทำงาน จะเป็นการสิ้นสุดผลของสกิล', '[Level 1] : ระยะเวลาของสกิล 5 วินาที / โอกาศสำเร็จ 45%\n[Level 2] : ระยะเวลาของสกิล 6 วินาที / โอกาศสำเร็จ 50%\n[Level 3] : ระยะเวลาของสกิล 7 วินาที / โอกาศสำเร็จ 55%\n[Level 4] : ระยะเวลาของสกิล 8 วินาที / โอกาศสำเร็จ 60%\n[Level 5] : ระยะเวลาของสกิล 9 วินาที / โอกาศสำเร็จ 65%'),
('SR_KNUCKLEARROW', 'Knuckle Arrow', 5, 'Active / Damage', 'Requirement : Lightning Walk 3 / Rampage Blast 3\nเคลื่อนที่เข้าหาเป้าหมายและจู่โจม สร้างความเสียหายและทำให้เป้าหมายกระเด็นถอยหลังไป หากเป้าหมายกระเด็นถอยหลังไป และติดกำแพง เป้าหมายจะได้รับความเสียหายมากขึ้น [ ต้องการ 2 Spirit Sphere ในการใช้สกิลนี้ ]', '[Level 1] : พลังโจมตี 600% /หากเป้าหมายกระเด็นถอยหลัง + Damage  150% + Bonus เมื่อกระเด็นถอยหลังติดกำแพง\n[Level 2] : พลังโจมตี 700% /หากเป้าหมายกระเด็นถอยหลัง + Damage  300% + Bonus เมื่อกระเด็นถอยหลังติดกำแพง\n[Level 3] : พลังโจมตี 800% /หากเป้าหมายกระเด็นถอยหลัง + Damage  450% + Bonus เมื่อกระเด็นถอยหลังติดกำแพง\n[Level 4] : พลังโจมตี 900% /หากเป้าหมายกระเด็นถอยหลัง + Damage  600% + Bonus เมื่อกระเด็นถอยหลังติดกำแพง\n[Level 5] : พลังโจมตี 1000% /หากเป้าหมายกระเด็นถอยหลัง + Damage  750% + Bonus เมื่อกระเด็นถอยหลังติดกำแพง'),
('SR_WINDMILL', 'Wind Mill', 1, 'Active / Damage', 'Requirement : Cursed Circle 1\nจู่โจมด้วยลูกเตะต่ำ สร้างความเสียหายในระยะ 5 x 5 ช่อง และทำให้เป้าหมายนั่งลง หากใช้กับมอนสเตอร์จะมีโอกาสทำให้มอนสเตอร์ติดสถานะ Stun 1~4 วินาที , ไม่สามารถใช้กับ Boss Monsters ได้', NULL),
('SR_RAISINGDRAGON', 'Rising Dragon', 10, 'Active / Buff', 'Requirement : Rampage Blast 3 / Gentle Touch-Save 3\nปลดปล่อยจิตวิญญาณและสมาธิ , สามารถเรียก Spirit Sphere ได้มากขึ้น , เพิ่ม Max HP Max SP และ ASPD ในระหว่างผลของสกิลนี้ผู้ใช้จะอยู่ในสถานะ Fury (Explosion Spirits) , เมื่อใช้สกิลนี้ ผู้ใช้จะสูญเสีย HP ไปเรื่อยๆ และเมื่อ HP ของผู้ใช้เหลือน้อย จะเป็นการยกเลิกการใช้สกิลนี้ทันที', '[Level 1] : Max Spirit Spheres 6 / MHP, MSP 3% increase / ระยะเวลา 30 วินาที\n[Level 2] : Max Spirit Spheres 7 / MHP, MSP 4% increase / ระยะเวลา 45 วินาที\n[Level 3] : Max Spirit Spheres 8 / MHP, MSP 5% increase / ระยะเวลา 60 วินาที\n[Level 4] : Max Spirit Spheres 9 / MHP, MSP 6% increase / ระยะเวลา 75 วินาที\n[Level 5] : Max Spirit Spheres 10 / MHP, MSP 7% increase / ระยะเวลา 90 วินาที\n[Level 6] : Max Spirit Spheres 11 / MHP, MSP 8% increase / ระยะเวลา 105 วินาที\n[Level 7] : Max Spirit Spheres 12 / MHP, MSP 9% increase / ระยะเวลา 120 วินาที\n[Level 8] : Max Spirit Spheres 13 / MHP, MSP 10% increase / ระยะเวลา 135 วินาที\n[Level 9] : Max Spirit Spheres 14 / MHP, MSP 11% increase / ระยะเวลา 150 วินาที\n[Level 10] : Max Spirit Spheres 15 / MHP, MSP 12% increase / ระยะเวลา 165 วินาที'),
('SR_ASSIMILATEPOWER', 'Power Absorb', 1, 'Active / Special', 'Requirement : Spiritual Sphere Absorption 1, Power Implantation 1\nฟื้นฟู SP ของผู้ใช้ด้วย Spirit Spheres ทั้งหมดที่อยู่ในระยะ 5 x 5 ช่ิอง รวมถึง Spirit Sphere ของผู้ใช้เองด้วย', NULL),
('SR_POWERVELOCITY', 'Power Implantation', 1, 'Active / Special', 'Requirement : Summon Spirit Sphere 5\nเคลื่อนย้าย Spirit Spheres ทั้งหมดของผู้ใช้ไปยังเป้าหมายที่กำหนด', NULL),
('SR_GATEOFHELL', 'Hell Gate', 10, 'Active / Damage', 'Requirement : Rising Dragon 5 / Tiger Cannon 5\nสามารถสร้างการโจมตีต่อศัตรูได้อย่างต่อเนื่องไม่จำกัดเป็นระยะเวลาสั้นๆ ยิ่ง HP ของผู้ใช้งานน้อยเท่าไหร่ Damage จะยิ่งสูงมากขึ้น เมื่อใช้สกิลจะใช้ MSP 20% และ ใช้ spirit spheres 5 ea หลังจากใช้ Fallen Empire จะสามารถใช้ตามลำดับได้ และเมื่อใช้ตามลำดับจะยิ่งเพิ่มพลังโจมตี', NULL),
('SR_GENTLETOUCH_QUIET', 'Gentle Touch - Silence', 5, 'Active / Damage and Debuff', 'Requirement : Power Implantation 1\nใช้วิชาลับจี้จุดกระตุ้นของเป้าหมาย , สร้างความเสียหายและทำให้เป้าหมายติดสถานะ Silience ค่า DEX ของผู้ใช้สามารถเพิ่มความรุนแรงของสกิลได้อย่างมาก', '[Level 1] : ระยะโจมตี 2 ช่อง / พลังโจมตี 100%\n[Level 2] : ระยะโจมตี 2 ช่อง / พลังโจมตี 200%\n[Level 3] : ระยะโจมตี 2 ช่อง / พลังโจมตี 300%\n[Level 4] : ระยะโจมตี 2 ช่อง / พลังโจมตี 400%\n[Level 5] : ระยะโจมตี 2 ช่อง / พลังโจมตี 500%'),
('SR_GENTLETOUCH_CURE', 'Gentle Touch - Speed', 5, 'Active /  Recovery and Buff', 'Requirement : Power Implantation 1\nใช้วิชาลับจี้จุดกระตุ้นของเป้าหมาย , ฟื้นฟู HP ของเป้าหมายและรักษาสถานะผิดปกติ , สกิลเลเวลจะช่วยเพิ่มโอกาสสำเร็จให้มากยิ่งขึ้น โดยสามารถรักษาสถานะต่างๆให้เป้าหมายได้ดังนี้ : Stone / Freezing / Stun / Poison / Silence / Blind / Confusion สามารถใช้สกิลเมื่อผู้ใช้ตกอยู่ในสถานะ : Stone / Freezing / Stun ได้ [ ต้องการ Spirit Sphere ในการใช้สกิลนี้ ตามระดับของเลเวลสกิล ]', NULL),
('SR_GENTLETOUCH_ENERGYGAIN', 'Gentle Touch - Save', 5, 'Active / Buff (To yourself)', 'Requirement : Gentle Touch-Silence 3\nใช้วิชาลับจี้จุดกระตุ้นบนร่างกายตนเอง เพื่อเพิ่มพลังในการต่อสู้ , มีโอกาสได้รับ Spirit Sphere เมื่อทำการโจมตีทางกายภาพ หรือได้รับความเสียหาย ต้องการ HP บางส่วนในการใช้สกิลนี้ , ไม่สามารถใช้ร่วมกับสกิล Gentle Touch - Opposite และ Gentle Touch - Alive ได้', '[Level 1] : ต้องการ HP 1%  / โอกาสได้รับ Spirit Sphere 15%\n[Level 2] : ต้องการ HP 2%  / โอกาสได้รับ Spirit Sphere 20%\n[Level 3] : ต้องการ HP 3%  / โอกาสได้รับ Spirit Sphere 25%\n[Level 4] : ต้องการ HP 4%  / โอกาสได้รับ Spirit Sphere 30%\n[Level 5] : ต้องการ HP 5%  / โอกาสได้รับ Spirit Sphere 35%'),
('SR_GENTLETOUCH_CHANGE', 'Gentle Touch - Opposite', 5, 'Active /  Buff', 'Requirement : Gentle Touch - Speed 4\nใช้วิชาลับจี้จุดกระตุ้นบนร่างกายตนเอง เพื่อเพิ่มพลังในการต่อสู้ , เปลี่ยน Pyscical Defense และ Magic Defense ให้เป็น Attack Power และ movement spee ต้องการ HP บางส่วน และยังมีผลลด MHP ในการใช้สกิลนี้ , ไม่สามารถใช้ร่วมกับสกิล Gentle Touch - Save และ Gentle Touch - Alive ได้[ ต้องการ Spirit Sphere ในการใช้สกิลนี้ ตามระดับเลเวลสกิล ]', '[Level 1] : ต้องการ HP 1%\n[Level 2] : ต้องการ HP 2%\n[Level 3] : ต้องการ HP 3%\n[Level 4] : ต้องการ HP 4%\n[Level 5] : ต้องการ HP 5%'),
('SR_GENTLETOUCH_REVITALIZE', 'Gentle Touch - Alive', 5, 'Active / Buff', 'Requirement : Gentle Touch - Opposite 5\nใช้วิชาลับจี้จุดกระตุ้นบนร่างกายตนเอง เพื่อเพิ่มพลังในการต่อสู้ , เพิ่ม VIT และ Max HP , เพิ่มความสามารถในการฟื้นฟู HP ตามปกติเพิ่ม Pysical Defense อย่างมาก , ในระยะสกิลแสดงผลไม่ว่าผู้ใช้จะเคลื่อนที่ หรือโจมตี ยังคงได้รับผลของ HP Recovery อยู่เหมือนเดิม ไม่สามารถใช้ร่วมกับสกิล Gentle Touch - Save และ Gentle Touch - Opposite ได้[ ต้องการ Spirit Sphere ในการใช้สกิลนี้ ตามระดับเลเวลของสกิล ]', '[Level 1] : MHP + 2%  / ความเร็วในการฟื้นฟู HP + 80%\n[Level 2] : MHP + 4%  / ความเร็วในการฟื้นฟู HP + 110%\n[Level 3] : MHP + 6%  / ความเร็วในการฟื้นฟู HP + 140%\n[Level 4] : MHP + 8%  / ความเร็วในการฟื้นฟู HP + 170%\n[Level 5] : MHP + 10%  / ความเร็วในการฟื้นฟู HP + 200%'),
('SR_HOWLINGOFLION', 'Lion Howling', 5, 'Active / Damage(Special)', 'Requirement : Power Absorb 1 / Lightning Ride 3\nคำรามด้วยเสียงอันกึกก้อง สร้างความเสียหายแก่ทุกเป้าหมาย รอบๆตัวผู้ใช้ และทำให้เป้าหมายติดสถานะ terrified หากเป้าหมายในระยะได้รับผลจากสกิลดนตรีหรือการเต้นจาก Minstrel หรือ Wanderer ผลของดนตรีหรือการเต้น จะถูกยกเลิก', '[Level 1] : ระยะ 7 x 7  ช่อง / พลังโจมตี 300% / โอกาศติดสถานะ terrified 10%\n[Level 2] : ระยะ 9 x 9  ช่อง / พลังโจมตี 600% / โอกาศติดสถานะ terrified 15%\n[Level 3] : ระยะ 11 x 11 ช่อง / พลังโจมตี 900% / โอกาศติดสถานะ terrified 20%\n[Level 4] : ระยะ 13 x 13 ช่อง / พลังโจมตี 1200% / โอกาศติดสถานะ terrified 25%\n[Level 5] : ระยะ 15 x 15 ช่อง / พลังโจมตี 1500% / โอกาศติดสถานะ terrified 30%'),
('SR_RIDEINLIGHTNING', 'Lightning Ride', 5, 'Active / Damage', 'Requirement : Throw Spirit Sphere 3\nรายละเอียด : ยิง Spirit Spheres ออกไป โดย Spirit Spheres จะเบิดและสร้างความเสียหายเป้นวงกว้าง , จำนวน Spirit Spheres ที่ต้องใช้ขึ้นอยู่กับเลเวลของสกิล หากมี Spirit Spheres มากกว่าจำนวนที่ต้องการ ความเสียหายก็จะสูงขึ้น , หากใช้สกิลนี้ด้วยอาวุธธาตุลม ความเสียหายจะเพิ่มมากขึ้นอีก ค่า DEX ของผู้ใช้สามารถเพิ่มความรุนแรงของสกิลนี้ได้', '[Level 1] : ระยะ 5 x 5  / ต้องการ 1 Spirit Sphere\n[Level 2] : ระยะ 5 x 5  / ต้องการ 2 Spirit Spheres\n[Level 3] : ระยะ 7 x 7  / ต้องการ 3 Spirit Spheres\n[Level 4] : ระยะ 7 x 7  / ต้องการ 4 Spirit Spheres\n[Level 5] : ระยะ 9 x 9  / ต้องการ 5 Spirit Spheres'),
('SR_FLASHCOMBO', 'Flash Combo', 5, 'ใช้งาน / สกิลต่อเนื่อง', 'Requirement : Dragon Combo 3 / Fallen Empire 3 / Tiger Cannon 1 / Sky Blow 1\nใช้งานการโจมตีทั้ง 4 สกิล Dragon Combo, Fallen Empire, Tiger Cannon, Sky Blow ต่อเนื่องกันด้วยความรวดเร็ว โดยแต่ละสกิลจะทำงานด้วย Lv. สูงสุดที่เรียน\nไม่สามารถใช้สกิลหรือไอเทมได้จนกว่าจะใช้สกิลต่อเนื่องครบหมด', '[Level 1] : ใช้ Spirit Sphere 5ea, เพิ่ม ATK 40 เป็นระยะเวลา 4 วินาที\n[Level 2] : ใช้ Spirit Sphere 5ea, เพิ่ม ATK 60 เป็นระยะเวลา 4 วินาที\n[Level 3] : ใช้ Spirit Sphere 4ea, เพิ่ม ATK 80 เป็นระยะเวลา 4 วินาที\n[Level 4] : ใช้ Spirit Sphere 4ea, เพิ่ม ATK 100 เป็นระยะเวลา 4 วินาที\n[Level 5] : ใช้ Spirit Sphere 3ea, เพิ่ม ATK 120 เป็นระยะเวลา 4 วินาที'),
('WA_SWING_DANCE', 'Swing Dance', 5, 'Active / Buff', 'Requirement : Lullaby 1\nสามารถใช้ได้เมื่อสวมใส่ แส้, เพิ่มความเร็วในการเคลื่อนที่ และ ASPD ให้กับ สมาชิกในปาร์ตี้เป็นเวลา 60 วินาที โดยผลของ ASPD สามารถเพิ่มขึ้นได้โดยขึ้นอยู่กับ skill Lv และ Lv ของสกิล skill lesson', '[Level 1] : ระยะของสกิล 15 x 15 ช่อง\n[Level 2] : ระยะของสกิล 17 x 17 ช่อง\n[Level 3] : ระยะของสกิล 19 x 19 ช่อง\n[Level 4] : ระยะของสกิล 21 x 21 ช่อง\n[Level 5] : ระยะของสกิล 23 x 23 ช่อง'),
('WA_SYMPHONY_OF_LOVER', 'Lover Symphony', 5, 'Active / Buff', 'Requirement : Lullaby 1\nเพิ่ม Magic Defense ของผู้ใช้และสมาชิกในปาร์ตี้ชั่วคราวเป็นเวลา 60 วินาที โดยผลของ Magic Defense สามารถเพิ่มขึ้นได้โดยขึ้นอยู่กับ Job Lv และ Lv ของสกิล skill lesson', '[Level 1] : ระยะของสกิล 15 x 15 ช่อง\n[Level 2] : ระยะของสกิล 17 x 17 ช่อง\n[Level 3] : ระยะของสกิล 19 x 19 ช่อง\n[Level 4] : ระยะของสกิล 21 x 21 ช่อง\n[Level 5] : ระยะของสกิล 23 x 23 ช่อง'),
('WA_MOONLIT_SERENADE', 'Moonlight Serenade', 5, 'Active / Buff', 'Requirement : Lullaby 1\nเพิ่ม MATK ของผู้ใช้และสมาชิกในปาร์ตี้ชั่วคราวเป็นเวลา 60 วินาที โดยผลของ Magic attack สามารถเพิ่มขึ้นได้โดยขึ้นอยู่กับ Job Lv และ Lv ของสกิล skill lesson', '[Level 1] : ระยะของสกิล 15 x 15 ช่อง\n[Level 2] : ระยะของสกิล 17 x 17 ช่อง\n[Level 3] : ระยะของสกิล 19 x 19 ช่อง\n[Level 4] : ระยะของสกิล 21 x 21 ช่อง\n[Level 5] : ระยะของสกิล 23 x 23 ช่อง'),
('MI_RUSH_WINDMILL', 'Rush To Windmill', 5, 'Active / Buff', 'Requirement : Lullaby 1\nเพิ่ม Physical Attack Power ของผู้ใช้และสมาชิกในปาร์ตี้ชั่วคราวเป็นเวลา 60 วินาที โดยผลของ Physical Attack Power สามารถเพิ่มขึ้นได้โดยขึ้นอยู่กับ Job Lv และ Lv ของสกิล skill lesson', '[Level 1] : ระยะของสกิล 15 x 15 ช่อง\n[Level 2] : ระยะของสกิล 17 x 17 ช่อง\n[Level 3] : ระยะของสกิล 19 x 19 ช่อง\n[Level 4] : ระยะของสกิล 21 x 21 ช่อง\n[Level 5] : ระยะของสกิล 23 x 23 ช่อง'),
('MI_ECHOSONG', 'Echo Song', 5, 'Active / Buff', 'Requirement : Lullaby 1\nเพิ่ม Physical Defense Power ของผู้ใช้และสมาชิกในปาร์ตี้ชั่วคราวเป็นเวลา 60 วินาที โดยผลของ Physical Defense Power สามารถเพิ่มขึ้นได้โดยขึ้นอยู่กับ Job Lv และ Lv ของสกิล skill lesson', '[Level 1] : ระยะของสกิล 15 x 15 ช่อง\n[Level 2] : ระยะของสกิล 17 x 17 ช่อง\n[Level 3] : ระยะของสกิล 19 x 19 ช่อง\n[Level 4] : ระยะของสกิล 21 x 21 ช่อง\n[Level 5] : ระยะของสกิล 23 x 23 ช่อง'),
('MI_HARMONIZE', 'Harmonize', 5, 'Active / Buff', 'Requirement : Lullaby 1\nลดค่า Status ให้กับเป้าหมาย 1 เป้าหมาย โดยรวมค่า bonus stat ของเป้าหมาย และผู้ร่าย เป็นเวลา 60 วินาที', '[Level 1] : All Status  เฉลี่ย 10 หน่วย\n[Level 2] : All Status  เฉลี่ย 15 หน่วย\n[Level 3] : All Status  เฉลี่ย 20 หน่วย\n[Level 4] : All Status  เฉลี่ย 25 หน่วย\n[Level 5] : All Status  เฉลี่ย 30 หน่วย'),
('WM_LESSON', 'Lesson', 10, 'Passive', 'Requirement : Wanderer, Minstrel Basic Skill\nเพิ่ม Max SP และ SP Recovery ที่เลเวล 5 ~ 10 สามารถใช้ทักษะร้องเพลง,เต้นของ 3rd Class ในขณะที่กำลังใช้สกิลร้องเพลง,เต้นและสกิลการแสดงคู่ของ 2nd Class ได้', '[Level 1] : MSP +30\n[Level 2] : MSP +60\n[Level 3] : MSP +90\n[Level 4] : MSP +120\n[Level 5] : MSP +150  / สามารถใช้สกิลร้องเพลงของ 3rd Class ขณะใช้สกิลร้องเพลงของ 2nd Class ได้\n[Level 6] : MSP +180  / สามารถใช้สกิลร้องเพลงของ 3rd Class ขณะใช้สกิลร้องเพลงของ 2nd Class ได้\n[Level 7] : MSP +200  / สามารถใช้สกิลร้องเพลงของ 3rd Class ขณะใช้สกิลร้องเพลงของ 2nd Class ได้\n[Level 8] : MSP +240  / สามารถใช้สกิลร้องเพลงของ 3rd Class ขณะใช้สกิลร้องเพลงของ 2nd Class ได้\n[Level 9] : MSP +270  / สามารถใช้สกิลร้องเพลงของ 3rd Class ขณะใช้สกิลร้องเพลงของ 2nd Class ได้\n[Level 10] : MSP +300 / สามารถใช้สกิลร้องเพลงของ 3rd Class ขณะใช้สกิลร้องเพลงของ 2nd Class ได้'),
('WM_METALICSOUND', 'Metalic Sound', 5, 'Active / Damage', 'Requirement : Dominion Impulse 1\nปล่อยเสียงระดับสูงใส่ 1 เป้าหมาย สร้างความเสียหายแก่ HP และ SP, ความเสียหายจะมากยิ่งขึ้นหากเป้าหมายกำลังหลับอยู่ , สกิล Lesson สามารถช่วยเพิ่มความรุนแรงของสกิลนี้ได้', '[Level 1] : MATK 120% + สกิล Lesson ที่เรียนรู้\n[Level 2] : MATK 240% + สกิล Lesson ที่เรียนรู้\n[Level 3] : MATK 360% + สกิล Lesson ที่เรียนรู้\n[Level 4] : MATK 480% + สกิล Lesson ที่เรียนรู้\n[Level 5] : MATK 600% + สกิล Lesson ที่เรียนรู้'),
('WM_REVERBERATION', 'Reverberation', 5, 'Active / Damage', 'Requirement : Unchained Serenade หรือ Hip Shaker 5\nสร้าง คลื่นเสียงระดับสูงจากพื้นดิน หากเป้าหมายออกจากพื้นที่สกิล หรือก่อนผลของสกิลจะหมดลงเป้าหมายที่อยู่ในขอบเขตของสกิลระยะ 3 x 3 ช่องจะได้รับความเสียหาย การดังสะท้อนสามารถยกเลิกได้หากได้รับการโจมตีทางกายภาพระยะไกลหรือเวทย์มนต์', '[Level 1] : พลังโจมตี 400% + MATK 200%\n[Level 2] : พลังโจมตี 500% + MATK 300%\n[Level 3] : พลังโจมตี 600% + MATK 400%\n[Level 4] : พลังโจมตี 700% + MATK 500%\n[Level 5] : พลังโจมตี 800% + MATK 600%'),
('WM_DOMINION_IMPULSE', 'Dominion Impulse', 1, 'Active / Special', 'Requirement : Reverberation 1\nเพิ่มระยะการสะท้อนของเสียงเป็น 11 x 11 ช่องรอบตัว สามารถใช้ทับซ้อนกับ การสะท้อนของเสียงจากผู้อื่นได้', NULL),
('WM_SEVERE_RAINSTORM', 'Severe Rainstorm', 5, 'Active / Damage', 'Requirement : Slinging Arrow หรือ Melody Strike 5\nปล่อยลูกธนูจำนวนนับไม่ถ้วนขึ้นฟ้า และตกลงมาในระยะ 11 x 11 ช่อง ความแรงของสกิลขึ้นอยู่กับค่า AGI และ DEX ต้องการลูกธนู 20 ea หากมีลูกธนูไม่ถึง 20 ea การใช้สกิลจะล้มเหลว', '[Level 1] : 1 hit ทุกๆ  0.3 วินาที / ระยะเวลา 0.9 วินาที\n[Level 2] : 1 hit ทุกๆ  0.3 วินาที / ระยะเวลา 1.5 วินาที\n[Level 3] : 1 hit ทุกๆ  0.3 วินาที / ระยะเวลา 2.1 วินาที\n[Level 4] : 1 hit ทุกๆ  0.3 วินาที / ระยะเวลา 2.7 วินาที\n[Level 5] : 1 hit ทุกๆ  0.3 วินาที / ระยะเวลา 3.0 วินาที'),
('WM_POEMOFNETHERWORLD', 'Despair Song', 5, 'Active / Debuff', 'Requirement : Lesson 1\nสร้างคลื่นเสียงชนิดพิเศษ ลงพื้นดิน ทำให้เป้าหมายในระยะไม่สามารถเคลื่อนที่ได้ สามารถร่ายสกิลสูงสุดได้ 5 ครั้งในเวลาเดียวกัน ไม่สามารถใช้กับ Boss Monster  เลเวลของผู้ใช้และเป้าหมายมีผลต่อระยะเวลาที่เคลื่อนที่ไม่ได้ [ขอบเขตของสกิล 3 x 3 ช่อง] ต้องการ 1 [Protect Neck Candy].', '[Level 1] : ระยะเวลาของสกิล 8 วินาที / Sound Wave Duration 9 วินาที\n[Level 2] : ระยะเวลาของสกิล 10 วินาที / Sound Wave Duration 11 วินาที\n[Level 3] : ระยะเวลาของสกิล 12 วินาที / Sound Wave Duration 13 วินาที\n[Level 4] : ระยะเวลาของสกิล 14 วินาที / Sound Wave Duration 15 วินาที\n[Level 5] : ระยะเวลาของสกิล 16 วินาที / Sound Wave Duration 17 วินาที'),
('WM_VOICEOFSIREN', 'Voice Of Siren', 5, 'Active / Debuff', 'Requirement : Despair Song 3\nสร้างความสนใจแก่เป้าหมายในระยะของสกิล และทำให้เป้าหมายคล้อยตาม  มอนสเตอร์จะไม่โจมตีเรา และระหว่างผลของสกิลเราจะไม่สามารถโจมตีเป้าหมายได้เช่นกัน เลเวลของเป้าหมายมีผลต่อระยะเวลาที่มีผล และผลของสกิลจะถูกยกเลิกเมื่อเป้าหมายได้รับการโจมตี', '[Level 1] : ระยะโจมตี 5 x 5  / ระยะเวลา 15 วินาที\n[Level 2] : ระยะโจมตี 7 x 7  / ระยะเวลา 18 วินาที\n[Level 3] : ระยะโจมตี 9 x 9  / ระยะเวลา 21 วินาที\n[Level 4] : ระยะโจมตี 11 x 11  / ระยะเวลา 24 วินาที\n[Level 5] : ระยะโจมตี 13 x 13  / ระยะเวลา 27 วินาที'),
('WM_DEADHILLHERE', 'At Dead Hill', 5, 'Active / Recovery', 'Requirement : Circling Nature 3\nฟื้นคืนชีวิตให้กับ 1 เป้าหมาย โดยเป้าหมายจะฟื้นขึ้นมาโดยฟื้น HP เท่ากับ SP ที่เหลือตอนตาย ถ้าเป้าหมายมี SP 0 จะฟื้นขึ้นมาโดยมี HP 1  ต้องการ 1 [Heartbroken Tears]', '[Level 1] : โอกาศสำเร็จ 90% / ใช้ 50% ของ SP ตอนเป้าหมายมีชีวิต\n[Level 2] : โอกาศสำเร็จ 92% / ใช้ 40% ของ SP ตอนเป้าหมายมีชีวิต\n[Level 3] : โอกาศสำเร็จ 94% / ใช้ 30% ของ SP ตอนเป้าหมายมีชีวิต\n[Level 4] : โอกาศสำเร็จ 96% / ใช้ 20% ของ SP ตอนเป้าหมายมีชีวิต\n[Level 5] : โอกาศสำเร็จ 98% / ใช้ 10% ของ SP ตอนเป้าหมายมีชีวิต'),
('WM_LULLABY_DEEPSLEEP', 'Lullaby', 5, 'Active / Debuff', 'Requirement : Lesson 1\nทำให้เป้าหมายที่อยู่รอบๆตัวเราตกอยู่ในสภานะ Deep Sleep'' ในขณะที่ตกอยู่ในสถานะ ''Deep Sleep'' จะไม่สามารถเคลื่อนที่ โจมตี ใช้ไอเทมหรือสกิลได้โดยหากเป้าหมายได้รับการโจมตีจะเป็นการยกเลิกสถานะ ''Deep Sleep'' แต่ในขณะที่ตกอยู่ในสถานะ ''Deep Sleep'' จะได้รับความเสียหายเป็น 1.5 เท่า และผู้ตกอยู่ในสถานะ ''Deep Sleep'' จะฟื้นฟู HP/SP 3% ทุกๆ 2 วินาที', '[Level 1] : ระยะ 11 x 11\n[Level 2] : ระยะ 13 x 13\n[Level 3] : ระยะ 15 x 15\n[Level 4] : ระยะ 17 x 17\n[Level 5] : ระยะ 19 x 19'),
('WM_SIRCLEOFNATURE', 'Circling Nature', 5, 'Active / Recovery', 'Requirement : Lesson 1\nสกิลนี้มีผลต่อผู้เล่นที่อยู่ในระยะทุกคน , ฟื้นฟู HP และลด SP หากผู้เล่นไม่มี SP เหลืออยู่จะไม่ได้รับผลของสกิลนี้', '[Level 1] : ระยะโจมตี 7 x 7  / SP ลดลง 4 ทุกๆ วินาที/ฟื้นฟู 40 HPต่อ วินาที\n[Level 2] : ระยะโจมตี 9 x 9 / SP ลดลง 8 ทุกๆ  วินาที/ ฟื้นฟู 80 HPต่อ วินาที\n[Level 3] : ระยะโจมตี 11 x 11 / SP ลดลง 12 ทุกๆ  วินาที/ ฟื้นฟู 120 HPต่อ วินาที\n[Level 4] : ระยะโจมตี 13 x 13 / SP ลดลง 16 ทุกๆ  วินาที/ ฟื้นฟู 160 HPต่อ วินาที\n[Level 5] : ระยะโจมตี 15 x 15 / SP ลดลง 20 ทุกๆ  วินาที/ ฟื้นฟู 200 HPต่อ วินาที'),
('WM_RANDOMIZESPELL', 'Formless Spell', 5, 'Active / Special', 'Requirement : Despair Song 1\nสุ่มใช้สกิลของ Magician หรือ Wizard โดยไม่ต้องใช้เงื่อนไขของสกิลที่สุ่มออกมาต้องการ', '[Level 1] : สุ่มใช้สกิลเลเวลเวทย์มนต์เลเวล  5\n[Level 2] : สุ่มใช้สกิลเลเวลเวทย์มนต์เลเวล  6\n[Level 3] : สุ่มใช้สกิลเลเวลเวทย์มนต์เลเวล  7\n[Level 4] : สุ่มใช้สกิลเลเวลเวทย์มนต์เลเวล  8\n[Level 5] : สุ่มใช้สกิลเลเวลเวทย์มนต์เลเวล  9'),
('WM_GLOOMYDAY', 'Gloomy Shyness', 5, 'Active / Buff', 'Requirement : Formless Spell 1\nเพิ่มความรุนแรงของสกิลบางสกิล หรือลดอัตราการหลบหลีกและ ASPD , สกิลที่ได้รับผล คือ [Hundred Spears / Brandish Spear / Clashing Spiral / Spear / Smite / Shield Boomerang / Rapid Smiting / Shield Press] หากเป้าหมายไม่มีสกิลดังกล่าวจะได้รับ อัตราการหลบหลีกและ ASPD แทน เมื่อใช้สกิลนี้ บางทีมีผลทำให้ความเร็วใการเคลื่อนที่ลดลง และ ยกเลิก pecopeco, dragon, gryphon ได้ สามารถใช้กับเพื่อนได้ และใน PK area', '[Level 1] : Flee Rate -25 / ASPD -20%\n[Level 2] : Flee Rate -30 / ASPD -25%\n[Level 3] : Flee Rate -35 / ASPD -30%\n[Level 4] : Flee Rate -40 / ASPD -35%\n[Level 5] : Flee Rate -45 / ASPD -40%'),
('WM_GREAT_ECHO', 'Great Echo', 5, 'Active / Damage / Chorus', 'Requirement : Metalic Sound 1\nสร้างเสียงสะท้อนกึกก้องอย่างรุนแรง สร้างความเสียหายแก่ทุกเป้าหมายในระยะของสกิล เพิ่มความรุนแรงของสกิลได้โดยขึ้นตามจำนวนของ Wanderer หรือ Minstrel อยู่อยู่ภายในปาร์ตี้ และลดการใช้ SP ลง โดย Wanderer และ/หรือ Minstrel ทุกคนในปาร์ตี้จะเสีย Sp จากการใช้สกิลนี้ไปด้วย ต้องการ : 1 [Protect Neck Candy].', '[Level 1] : ระยะโจมตี 5 x 5 / พลังโจมตี 600%\n[Level 2] : ระยะโจมตี 7 x 7 / พลังโจมตี 800%\n[Level 3] : ระยะโจมตี 7 x 7 / พลังโจมตี 1000%\n[Level 4] : ระยะโจมตี 9 x 9 / พลังโจมตี 1200%\n[Level 5] : ระยะโจมตี 9 x 9 / พลังโจมตี 1400%'),
('WM_SONG_OF_MANA', 'Song Of Mana', 5, 'Active / Buff / Chorus', 'Requirement : Swing Dance(Harmonize) , Lover Symphony (Rush To Windmill), Moonlight Serenade (Echo Song) 1\nดนตรีที่แห่งการฟื้นฟูที่ใช้การโคจรของ Mana , ฟื้นฟู 10 SP ทุกๆ 5 วินาที ให้กับสมาชิกในปาร์ตี้ทุกคน  อัตราการฟื้นฟูจะเพิ่มขึ้นได้หากมี Wanderer และ/หรือ Minstrel อยู่ในปาร์ตี้หลายคน', '[Level 1] : ระยะโจมตี 11 x 11 / ระยะเวลา 30 วินาที\n[Level 2] : ระยะโจมตี 13 x 13 / ระยะเวลา 60 วินาที\n[Level 3] : ระยะโจมตี 15 x 15 / ระยะเวลา 90 วินาที\n[Level 4] : ระยะโจมตี 17 x 17 / ระยะเวลา 120 วินาที\n[Level 5] : ระยะโจมตี 19 x 19 / ระยะเวลา 150 วินาที'),
('WM_DANCE_WITH_WUG', 'Dance With Wug', 5, 'Active / Buff / Chorus', 'Requirement : Swing Dance(Harmonize) , Lover Symphony (Rush To Windmill), Moonlight Serenade (Echo Song) 1\nตื่นตาตื่นใจไปกับเพลงเร็วเพิ่มความเร็วในการโจมตีของคุณและสมาชิกในปาร์ตี้ และลดระยะเวลาในการร่ายเวทย์ทั้งหมดลง และเพิ่มความแรงในการโจมตีระยะไกลของ Reanger และ Wolf ที่อยู่ใน Party หากมี Wanderer และ Minstrel อยู่ในปาร์ตี้ผลของความสามารถจะเพิ่มขึ้น', '[Level 1] : ระยะโจมตี 11 x 11 / ระยะเวลา 30 วินาที\n[Level 2] : ระยะโจมตี 13 x 13 / ระยะเวลา 60 วินาที\n[Level 3] : ระยะโจมตี 15 x 15 / ระยะเวลา 90 วินาที\n[Level 4] : ระยะโจมตี 17 x 17 / ระยะเวลา 120 วินาที\n[Level 5] : ระยะโจมตี 19 x 19 / ระยะเวลา 150 วินาที'),
('WM_SOUND_OF_DESTRUCTION', 'Destruction Song', 5, 'Active / Special / Chorus', 'Requirement : Saturday Fever 3 , Sinking Melody 3\nยกเลิกผลของ สกิลร้องเพลงหรือเต้นภายในระยะของสกิลทั้งหมด และสร้างความเสียหายหากยกเลิกผลของสกิลสำเร็จ และทำให้ติด stun 100% มีผลตามระดับของ Lv ของ skill Lesson  อัตราการสำเร็จจะสูงขึ้น หากมี Wanderer และ Minstrel อยู่ในปาร์ตี้หลายคน', '[Level 1] : ระยะผลของสกิล 9 x 9 ช่อง\n[Level 2] : ระยะผลของสกิล  9 x 9 ช่อง\n[Level 3] : ระยะผลของสกิล  11 x 11 ช่อง\n[Level 4] : ระยะผลของสกิล  13 x 13 ช่อง\n[Level 5] : ระยะผลของสกิล  15 x 15 ช่อง'),
('WM_SATURDAY_NIGHT_FEVER', 'Saturday Fever', 5, 'Active / Special / Chorus', 'Requirement : Dance With Wug 1\nสกิลนี้มีผลต่อเป้าหมายทั้งหมดในหน้าจอ ทำให้เป้าหมายเกิดสภาวะเสมือน Frantic โดยเมื่ออยู่ในสภาวะเสมือน Frenzy จะไม่สามารถฟื้นฟู HP/ SP , เพิ่มพลังโจมตี ลดพลังป้องกันและอัตราการหลบหลีกอย่างมาก รวมทั้งไม่สามารถใช้สกิลและไอเทมได้ เมื่อสภาวะเสมือน Frenzy หมดลง เราจะถูกบังคับให้นั่งเป็นเวลา 3 วินาที ถ้ามีผู้ที่ได้รับผลของสภาวะเสมือน Frenzy มากกว่า 7 คน ผู้เล่นทุกคนที่ได้รับผลนั้น จะได้รับความเสียหาย Damage 9999 จาก เทพเจ้าแห่งความบ้าคลั่ง', '[Level 1] : ระยะโจมตี 7 x 7  / พลังโจมตี +100 / Defense -20% / Flee Rate -50%\n[Level 2] : ระยะโจมตี 9 x 9   / พลังโจมตี +200 / Defense -30% / Flee Rate -60%\n[Level 3] : ระยะโจมตี 11 x 11   / พลังโจมตี +300 / Defense -40% / Flee Rate -70%\n[Level 4] : ระยะโจมตี 13 x 13   / พลังโจมตี +400 / Defense -50% / Flee Rate -80%\n[Level 5] : ระยะโจมตี 15 x 15   / พลังโจมตี +500 / Defense -60% / Flee Rate -90%'),
('WM_LERADS_DEW', 'Lerad''s Dew', 5, 'Active / Buff / Chorus', 'Requirement : Swing Dance(Harmonize) , Lover Symphony (Rush To Windmill), Moonlight Serenade (Echo Song) 1\nเพิ่ม Max HP แก่สมาชิกในปาร์ตี้ที่อยู่ในหน้าจอ ไม่มีผลต่อผู้เล่นที่อยู่ในสถานะ Berserk อัตราการเพิ่มของ Max HP จะเพิ่มสูงขึ้นได้ตามจำนวน Wanderer และ/หรือ Minstrel ที่อยู่ในปาร์ตี้', '[Level 1] : ระยะ 11 x 11 ช่อง / MHP + 200   / ระยะเวลา 20 วินาที\n[Level 2] : ระยะ 11 x 11 ช่อง / MHP + 400   / ระยะเวลา 30 วินาที\n[Level 3] : ระยะ 13 x 13 ช่อง / MHP + 600   / ระยะเวลา 40 วินาที\n[Level 4] : ระยะ 13 x 13 ช่อง / MHP + 800   / ระยะเวลา 50 วินาที\n[Level 5] : ระยะ 15 x 15 ช่อง / MHP + 1000   / ระยะเวลา 60 วินาที'),
('WM_MELODYOFSINK', 'Sinking Melody', 5, 'Active / Buff / Chorus', 'Requirement : Song Of Mana 1\nลด SP ของศัตรูทั้งหมดรอบตัวผู้ร่าย และลดค่า INT ของเป้าหมายลง โอกาสสำเร็จจะเพิ่มสูงขึ้นได้ตามจำนวน Wanderer และ/หรือ Minstrel ที่อยู่ในปาร์ตี้', '[Level 1] : โอกาสสำเร็จ 20 % / ระยะเวลา 20 วินาที\n[Level 2] : โอกาสสำเร็จ 25 % / ระยะเวลา 30 วินาที\n[Level 3] : โอกาสสำเร็จ 30 % / ระยะเวลา 40 วินาที\n[Level 4] : โอกาสสำเร็จ 35 % / ระยะเวลา 50 วินาที\n[Level 5] : โอกาสสำเร็จ 40 % / ระยะเวลา 60 วินาที'),
('WM_BEYOND_OF_WARCRY', 'Beyound Cry ', 5, 'Active / Buff / Chorus', 'Requirement : Lerad''s Dew 1\nลดค่า MHP ของเป้าหมายทั้งหมดรอบตัวผู้ร่าย แต่ STR และ Critical rate จะสูงขึ้นแทน โอกาสสำเร็จจะเพิ่มสูงขึ้นได้ตามจำนวน Wanderer และ/หรือ Minstrel ที่อยู่ในปาร์ตี้', '[Level 1] : โอกาสสำเร็จ 20 % / ระยะเวลา 20 วินาที\n[Level 2] : โอกาสสำเร็จ 25 % / ระยะเวลา 30 วินาที\n[Level 3] : โอกาสสำเร็จ 30 % / ระยะเวลา 40 วินาที\n[Level 4] : โอกาสสำเร็จ 35 % / ระยะเวลา 50 วินาที\n[Level 5] : โอกาสสำเร็จ 40 % / ระยะเวลา 60 วินาที'),
('WM_UNLIMITED_HUMMING_VOICE', 'Infinite Humming', 5, 'Active / Buff / Chorus', 'Requirement : Destruction Song 1 , Beyound Cry 1\nสกิลนี้มีผลให้ สกิลและเวทย์มนต์ที่ร่ายในบริเวณรอบตัวเราไม่สามารถถูกขัดขวางได้ แต่จะเสีย SP ในการใช้สกิลมากขึ้น 15% ถ้าหากมี Wanderer และ Minstrel อยู่ในปาร์ตี้หลายคน  จะลดการเสีย SP ที่เพิ่มขึ้นให้น้อยลงได้', '[Level 1] : ระยะของสกิล 11 x 11 / ระยะเวลา 60 วินาที\n[Level 2] : ระยะของสกิล 11 x 11 / ระยะเวลา 90 วินาที\n[Level 3] : ระยะของสกิล 13 x 13 / ระยะเวลา 120 วินาที\n[Level 4] : ระยะของสกิล 13 x 13 / ระยะเวลา 150 วินาที\n[Level 5] : ระยะของสกิล 15 x 15 / ระยะเวลา 180 วินาที'),
('SO_FIREWALK', 'Fire Walk', 5, 'Active / Special / Damage', 'Requirement : Volcano 1\nสร้างไฟขึ้นใต้เท้าของผู้ใช้ เมื่อผู้ใช้เดินไปรอบๆ จะสร้างความเสียหายธาตุไฟรอบบริเวณเดินผ่าน', '[Level 1] : สร้างได้สูงสุด 8\n[Level 2] : สร้างได้สูงสุด 10\n[Level 3] : สร้างได้สูงสุด 12\n[Level 4] : สร้างได้สูงสุด 14\n[Level 5] : สร้างได้สูงสุด 16'),
('SO_ELECTRICWALK', 'Electric Walk', 5, 'Active / Special / Damage', 'Requirement : Whirlwind 1\nสร้างไฟฟ้าขึ้นใต้เท้าของผู้ใช้ เมื่อผู้ใช้เดินไปรอบๆ จะสร้างความเสียหายธาตุลมรอบบริเวณเดินผ่าน', '[Level 1] : สร้างได้สูงสุด 8\n[Level 2] : สร้างได้สูงสุด 10\n[Level 3] : สร้างได้สูงสุด 12\n[Level 4] : สร้างได้สูงสุด 14\n[Level 5] : สร้างได้สูงสุด 16'),
('SO_SPELLFIST', 'Fist Spell', 5, 'Active / Special / Damage', 'Requirement : Hindsight 4\nเมื่อใช้สกิลขณะร่าย Fire, Cold, Lighthening Bolt การร่ายจะถูกยกเลิก แล้วจะรวบรวมสมาธิที่ฝ่ามือ  เมื่อไปโจมตีเป้าหมาย เป้าหมายจะได้รับความเสียหายจากเวทย์ Bolt นั้น  เลเวลสกิลที่สูงขึ้น จะเพิ่มความเสียหาย ระยะเวลาของสกิล และจำนวนครั้งในการโจมตีที่สกิลมีผล  เมื่อใช้สกิลอื่น จะเป็นการยกเลิกผลของสกิลนี้', '[Level 1] : ระยะเวลา 20 วินาที  / สร้างความเสียหายได้ 2 ครั้ง\n[Level 2] : ระยะเวลา 25 วินาที  / สร้างความเสียหายได้ 3 ครั้ง\n[Level 3] : ระยะเวลา 30 วินาที  / สร้างความเสียหายได้ 4 ครั้ง\n[Level 4] : ระยะเวลา 35 วินาที  / สร้างความเสียหายได้ 5 ครั้ง\n[Level 5] : ระยะเวลา 40 วินาที  / สร้างความเสียหายได้ 6 ครั้ง'),
('SO_EARTHGRAVE', 'Earth Grave ', 5, 'Active / Damage', 'Requirement : Earth Spike 5\nสร้างพื้นทื่สุญญากาศขึ้น สร้างความเสียหายเป็นธาตุดิน และทำให้เป้าหมายติดสถาะนะ [Bleeding]เพิ่มความเสียหายตามสกิลเลเวล และ Endow Quake, และสร้างความเสียหายต่อเป้าหมายที่ใช้สกิล Hiding/Clocking อยู่', '[Level 1] : ระยะ 7 x 7 ช่อง\n[Level 2] : ระยะ 7 x 7 ช่อง\n[Level 3] : ระยะ 7 x 7 ช่อง\n[Level 4] : ระยะ 9 x 9 ช่อง\n[Level 5] : ระยะ 9 x 9 ช่อง'),
('SO_DIAMONDDUST', 'Diamond Dust', 5, 'Active / Damage', 'Requirement : Deluge 3\nสร้างพายุที่หนาวเย็น สร้างความเสียหายเวทย์มนตร์ธาตุน้ำแก่เป้าหมาย มีโอกาสทำให้เป้าหมายติดสถานะ Freeze ชนิดใหม่ ไม่สามารถเคลื่อนที่ โจมตี ใช้สกิล และไอเทมได้ ไม่ถูกเปลี่ยนเป็นธาตุน้ำ ไม่ยกเลิกสถานะเมื่อถูกโจมตี ระยะเวลาการติด [Freezing] ถูกลดลงได้ด้วยค่า VIT', '[Level 1] : ระยะ 7 x 7 ช่อง\n[Level 2] : ระยะ 7 x 7 ช่อง\n[Level 3] : ระยะ 7 x 7 ช่อง\n[Level 4] : ระยะ 9 x 9 ช่อง\n[Level 5] : ระยะ 9 x 9 ช่อง'),
('SO_POISON_BUSTER', 'Poison Burst', 5, 'Active / Damage', 'Requirement : Killing Cloud 2\nสร้างพิษไปปกคลุมร่างกายเป้าหมาย ทำให้เป้าหมายได้รับความเสียหายจำนวนมาก  เมื่อใช่สกิลใส่เป้าหมายจะยกเลิกสถานะพิษ สกิลนี้ไม่มีผลต่อมอนสเตอร์ธาตุพิษ', NULL),
('SO_PSYCHIC_WAVE', 'Psychic Wave', 5, 'Active / Damage', 'Requirement : Dispell 2\nโจมตีเป้าหมายในระยะด้วยเวทย์มนตร์ไร้ธาตุ ด้วยการปล่อยคลื่นพลังจิตใส่เป้าหมายที่ได้รับความเสียหายจะติดสถานะ Stun', '[Level 1] : ระยะ 7 x 7 ช่อง / ครั้งโจมตีทั้งหมด  3\n[Level 2] : ระยะ 7 x 7 ช่อง / ครั้งโจมตีทั้งหมด  4\n[Level 3] : ระยะ 9 x 9 ช่อง / ครั้งโจมตีทั้งหมด  5\n[Level 4] : ระยะ 9 x 9 ช่อง / ครั้งโจมตีทั้งหมด  6\n[Level 5] : ระยะ 11 x 11 ช่อง / ครั้งโจมตีทั้งหมด  7'),
('SO_CLOUD_KILL', 'Killing Cloud', 5, 'Active / Damage', 'Requirement : Heaven''s Drive 5\nสร้างหมอกพิษขึ้นมาปกคลุมสร้างความเสียหายแก่เป้าหมายในระยะด้วยเวทย์มนตร์ธาตุพิษเป้าหมายที่ได้รับความเสียหายจะมีโอกาสติดสถานะ พิษ และมีโอกาสถูกเปลี่ยนเป็นธาตุ พิษ', '[Level 1] : ระยะเวลา 8 วินาที\n[Level 2] : ระยะเวลา 10 วินาที\n[Level 3] : ระยะเวลา 12 วินาที\n[Level 4] : ระยะเวลา 14 วินาที\n[Level 5] : ระยะเวลา 16 วินาที'),
('SO_STRIKING', 'Striking', 5, 'Active / Buff', 'Requirement : Endow Blaze 1 / Endow Tsunami 1 / Endow Tornado 1 / Endow Quake 1\nเพิ่มพลังโจมตี และค่า Critical ของผู้ใช้และผู้เล่นในปาร์ตี้ ความแรงของสกิลเพิ่มขึ้นได้ตามเลเวลของอาวุธ', NULL),
('SO_WARMER', 'Warmer', 5, 'Active / Ground / Recovery', 'Requirement : Volcano 1 / Whirlwind 1\nยกเลิกสถานะ Freeze และ Frozen ของทุกเป้าหมายในระยะ 7 x 7 ช่อง ในระยะเวลาของสกิล เป้าหมายในระยะจะไม่สามารถติดสถานะ Freeze และ Frozen ได้เป้าหมายในระยะจะได้รับการฟื้นฟู HP ทุก 3 วินาที', '[Level 1] : ระยะเวลา 40 วินาที\n[Level 2] : ระยะเวลา 45 วินาที\n[Level 3] : ระยะเวลา 50 วินาที\n[Level 4] : ระยะเวลา 55 วินาที\n[Level 5] : ระยะเวลา 60 วินาที'),
('SO_VACUUM_EXTREME', 'Extreme Vacuum', 5, 'Active / Special', 'Requirement : Magnetic Earth 2\nขุดหลุมบนพื้นดิน (1 cell) โดยจะจับเป้าหมายทั้งหมดไว้ตามระยะเวลาที่กำหนด ซึ่งเป้าหมายจะไม่สามารถเคลื่อนที่ได้จนกว่าจะสิ้นสุดระยะเวลา STR ยิ่งสูง ผลของสกิลยิ่งถูกลดลง บางสกิลสามารถยกเลิกผลของสกิล Extreme Vacuum ได้', '[Level 1] : ระยะ 3 x 3 ช่อง / ระยะเวลา 4 วินาที\n[Level 2] : ระยะ 3 x 3 ช่อง / ระยะเวลา 6 วินาที\n[Level 3] : ระยะ 5 x 5 ช่อง / ระยะเวลา 8 วินาที\n[Level 4] : ระยะ 5 x 5 ช่อง / ระยะเวลา 10 วินาที\n[Level 5] : ระยะ 7 x 7 ช่อง / ระยะเวลา 12 วินาที'),
('SO_VARETYR_SPEAR', 'Varetyr Spear', 5, 'Active / Damage', 'Requirement : Endow Quake 1 / Whirlwind 4\nเรียกหอกสายฟ้าลงมาจากท้องฟ้า โจมตีเป้าหมายและศัตรูโดยรอบ ด้วยความเสียหายทางกายภาพและเวทย์มนตร์ธาตุลมในเวลาเดียวกัน มีโอกาสทำให้เป้าหมายติดสถานะ Stun วามเสียหายเพิ่มเติม เพิ่มขึ้นตาม level ของสกิล Endow Tornado', '[Level 1] : target and surroundings 3 x 3 ช่อง\n[Level 2] : target and surroundings 3 x 3 ช่อง\n[Level 3] : target and surroundings 5 x 5 ช่อง\n[Level 4] : target and surroundings 5 x 5 ช่อง\n[Level 5] : target and surroundings 7 x 7 ช่อง'),
('SO_ARRULLO', 'Arrullo', 5, 'Active / Special', 'Requirement : Warmer 2\nทำให้เป้าหมายและศัตรูโดยรอบ ติดสถานะ Deep Sleep', '[Level 1] : 3 x 3 ช่อง รอบๆ เป้าหมาย\n[Level 2] : 3 x 3 ช่อง รอบๆ เป้าหมาย\n[Level 3] : 5 x 5 ช่อง รอบๆ เป้าหมาย\n[Level 4] : 5 x 5 ช่อง รอบๆ เป้าหมาย\n[Level 5] : 7 x 7 ช่อง รอบๆ เป้าหมาย'),
('SO_SUMMON_AGNI', 'Call Agni', 3, 'Active / Summon', 'Requirement : Spirit Control 1 / Warmer 3\nSummon Spirit of Fire, AGNI โดยใช้ [3 Red Blood หรือ 6 Red Blood หรือ 1 Flame Heart ] เพิ่มมากขึ้นตามระดับของทักษะสกิล', '[Level 1] : ระยะเวลา 600 วินาที / ใช้ 5 SP ทุกๆ 10 วินาที\n[Level 2] : ระยะเวลา 900 วินาที / ใช้ 8 SP ทุกๆ 10 วินาที\n[Level 3] : ระยะเวลา 1200 วินาที / ใช้ 11 SP ทุกๆ 10 วินาที'),
('SO_SUMMON_AQUA', 'Call Aqua', 3, 'Active / Summon', 'Requirement : Spirit Control 1 / Diamond Dust 3\nSummon spirit of water, AQUA โดยใช้ [3 Crystal Blue หรือ 6 Crystal Blue หรือ 1 Mistic Frozen ] เพิ่มมากขึ้นตามระดับของทักษะสกิล', '[Level 1] : ระยะเวลา 600 วินาที / ใช้ 5 SP ทุกๆ 10 วินาที\n[Level 2] : ระยะเวลา 900 วินาที / ใช้ 8 SP ทุกๆ 10 วินาที\n[Level 3] : ระยะเวลา 1200 วินาที / ใช้ 11 SP ทุกๆ 10 วินาที'),
('SO_SUMMON_VENTUS', 'Call Ventus', 3, 'Active / Summon', 'Requirement : Spirit Control 1 / Varetyr Spear 3\nSummon spirit of wind, Ventus โดยใช [3 Wind Of Verdure หรือ 6 Wind Of Verdure หรือ 1 Rough Wind ] เพิ่มมากขึ้นตามระดับของทักษะสกิล', '[Level 1] : ระยะเวลา 600 วินาที / ใช้ 5 SP ทุกๆ 10 วินาที\n[Level 2] : ระยะเวลา 900 วินาที / ใช้ 8 SP ทุกๆ 10 วินาที\n[Level 3] : ระยะเวลา 1200 วินาที / ใช้ 11 SP ทุกๆ 10 วินาที'),
('SO_SUMMON_TERA', 'Call Tera', 3, 'Active / Summon', 'Requirement : Spirit Control 1 / Earth Grave 3\nSummon spirit of earth, TERA โดยใช [3 Green Live หรือ 6 Green Live หรือ 1 Great Nature ] เพิ่มมากขึ้นตามระดับของทักษะสกิล', '[Level 1] : ระยะเวลา 600 วินาที / ใช้ 5 SP ทุกๆ 10 วินาที\n[Level 2] : ระยะเวลา 900 วินาที / ใช้ 8 SP ทุกๆ 10 วินาที\n[Level 3] : ระยะเวลา 1200 วินาที / ใช้ 11 SP ทุกๆ 10 วินาที'),
('SO_EL_CONTROL', 'Spirit Control ', 4, 'Active', 'Requirement : Element Analyze 1\nคำสั่งใน waiting mode spirit เพิ่อเปลี่ยนไปยัง mode Passive (Buff), Defensive (Defense), Offensive (Attack) เพื่อเปลี่ยนไปยัง waiting mode, ให้กดใช้คำสั่งสกิลเดิมซ้ำ เมื่อ spirits อยู่ใน waiting mode, พวกมันจะฟื้นฟู HP และ SP เรื่อยๆ', '[Level 1] : เปลี่ยน Spirit เป็น  Passive mode\n[Level 2] : เปลี่ยน Spirit เป็น  Defensive mode\n[Level 3] : เปลี่ยน Spirit เป็น  Offensive mode\n[Level 4] : เปลี่ยน Spirit เป็น  Waiting mode'),
('SO_EL_ACTION', 'Elemental Action', 1, 'Active', 'Requirement : Spirit Control 3\nใช้คำสั่ง 1 offensive (Attack) ได้ทันทีจาก summoned spirit', NULL),
('SO_EL_ANALYSIS', 'Element Analyze', 2, 'Active', 'Requirement : Flame Launcher 1 / Endow Tsunami 1 / Endow Tornado 1 / Endow Quake 1\nตรวจสอบ enchanted ores เพื่อใช้เป็นปฏิกริยาในการเรียก summoning spirits ข้างใน pure gemstones อีกทั้ง, โดยกลับกัน, รวม pure gemstones เป็น enchanted ore', '[Level 1] : ตรวจสอบ enchanted ores เป็น pure gemstones (ใช้ 1 of Flame Heart, Rough Wind, Mistic Frozen, Great Nature ในหน้าต่างการผสม, มันจะถูกแปรรูปเป็น Red Blood, Wind of Verdure, Crystal Blue, Green Live จะสุ่มจำนวนในการได้รับมา\n[Level 2] : รวม pure gemstones เพื่อเปลี่ยนเป็น enchanted ore (ใช้ 10 Red Blood, Wind of Verdure, Crystal Blue, Green Live ในหน้าต่างการผสม, มันจะถูกแปรรูปเป็น 1 Flame Heart, Rough Wind, Mistic Frozen, Great Nature ) มีโอกาศในการล้มเหลวการรวม pure gemstones และจะไม่ได้รับอะไรเลย'),
('SO_EL_SYMPATHY', 'Spirit Sympathy', 5, 'Passive', 'Requirement : Spirit Control 3\nเพิ่ม summoned spirit''s HP, SP และ ATK โดยการแบ่งปันความรู้สึกระหว่างผู้ใช่และ summon อีกทั้งยังลด SP ในการใช้ของผู้เล่น', '[Level 1] : เพิ่ม HP 5%,  SP 5% / พลังโจมตีเพิ่มขึ้น 25  / ลดการใช้ SP 10% ในการ summoning\n[Level 2] : เพิ่ม HP 10%, SP 10% / พลังโจมตีเพิ่มขึ้น 50  / ลดการใช้ SP 15% ในการ summoning\n[Level 3] : เพิ่ม HP 15%, SP 15% / พลังโจมตีเพิ่มขึ้น 75  / ลดการใช้ SP20% ในการ summoning\n[Level 4] : เพิ่ม HP 20%, SP 20% / พลังโจมตีเพิ่มขึ้น 100  / ลดการใช้ SP 25% ในการ summoning\n[Level 5] : เพิ่ม HP 25%, SP 25% / พลังโจมตีเพิ่มขึ้น 125  / ลดการใช้ SP 30% ในการ summoning'),
('SO_EL_CURE', 'Spirit Cure', 1, 'Active / Recovery', 'Requirement : Spirit Sympathy 1\nฟื้นฟู spirit HP และ SP โดยการใช้ HP และ SP ของตัวผู้เล่น', NULL),
('SO_FIRE_INSIGNIA', 'Fire Insignia', 3, 'Active / Ground Magic', 'Requirement : Call Agni 3\nวาดเครื่องหมายไฟไว้บนพื้น 3 x 3 ช่อง ฟื้นฟู 1% ของ HP ทุกๆ 5 วินาที ถ้าเป้าหมายสวมใส่เครื่องป้องกันธาตุไฟ หรือ เป็น monster ธาตุไำฟ ในทางกลับกัน, ลด HP ลง 1% ทุกๆ 5 วินาที, ถ้าเป้าหมายสวมใส่เครื่องป้องกันธาตุดิน หรือ เป็น monster ธาตุดิน เป้าหมายทั้งหมดที่เข้ามาอยู่ภายในระยะของสกิลจะได้รับความเสียหายเพิ่มขึ้น 1.5 เท่าจากการโจมตีด้วยธาติน้ำ ใช้ [ ต้องการ Scarlet Point : 1 / 2 / 3 ] ในการร่ายสกิลตามเลเวลทักษะของสกิล', '[Level 1] : เพิ่มพลังโจมตีของ AGNI ขึ้น 20% ฟื้นฟู HP, SP จำนวนหนึ่ง ทุก 3 วินาทีขึ้นเรื่อยๆ\n[Level 2] : พลังโจมตี + 50 ธาติของอาวุธเปลี่ยนเป็นธาติไฟ เพิ่มพลังโจมตีทางกายภาพขึ้น 10%\n[Level 3] : MATK + 50 เพิ่มพลังโจมตีอีก 25% โดยเพิ่มเฉพาะการโจมตีทางเวทย์ธาติไฟ'),
('SO_WATER_INSIGNIA', 'Water Insignia', 3, 'Active / Ground', 'Requirement : Call Aqua 3\nวาดเครื่องหมายน้ำไว้บนพื้น 3 x 3 ช่อง ฟื้่นฟู 1% ของ HP ทุกๆ 5 วินาที, ถ้าเป้าหมายสวมใส่เครื่องป้องกันธาติน้ำ หรือ เป็น monster ธาิติน้ำ ในทางกลับกัน, ลด HP ลง 1%  ทุกๆ 5 วินาที, ถ้าเป้าหมายสวมใส่เครื่องป้องกันธาติไฟ หรือ เป็น monster ธาติไฟ เป้าหมายทั้งหมดที่เข้ามาอยู่ภายในระยะของสกิลจะได้รับความเสียหายเพิ่มขึ้น 1.5 เท่าจากการโจมตีด้วยธาติลม ใช้ [ ต้องการ Indigo Point : 1 / 2 / 3 ] ในการร่ายสกิลตามเลเวลทักษะของสกิล', '[Level 1] : เพิ่มพลังโจมตีของ AQUA ขึ้น 20% ฟื้นฟู HP, SP จำนวนหนึ่ง ทุก 3 วินาทีขึ้นเรื่อยๆ\n[Level 2] : เพิ่มผลของการฟื้นฟูขึ้น 10% ธาติของอาวุธเปลี่ยนเป็นธาติน้ำ เพิ่มพลังโจมตีทางกายภาพขึ้น 10%\n[Level 3] : ลด Delay การร่ายเวทย์ลง 30% และเพิ่มพลังโจมตีขึ้น 25% โดยเฉพาะการโจมตีด้วยเวทย์ธาติน้ำ'),
('SO_WIND_INSIGNIA', 'Wind Insignia', 3, 'Active / Ground', 'Requirement : Call Ventus 3\nวาดเครื่องหมายลมไว้บนพื้น 3 x 3 ช่อง ฟื้นฟู 1% ของ HP ทุกๆ 5 วินาที, ถ้าเป้าหมายสวมใส่เครื่องป้องกันธาติลม หรือ เป็น monster ธาติลม ในทางกลับกัน, ลด HP ลง 1% ทุกๆ 5 seconds, ถ้าเป้าหมายสวมใส่เครื่องป้องกันธาติน้ำ หรือ เป็น monster ธาติน้ำ เป้าหมายทั้งหมดที่เข้ามาอยู่ในระยะของสกิลจะได้รับความเสียหายเพิ่มขึ้น 1.5 เท่าจากการโจมตีด้วยธาติดิน ใช้ [ ต้องการ Yellow Wish Point : 1 / 2 / 3 ] ในการร่ายสกิลตามเลเวลทักษะของสกิล', '[Level 1] : เพิ่มพลังโจมตีของ VENTUS ขึ้น 20% ฟื้นฟู HP, SP จำนวนหนึ่ง ทุก 3 วินาทีขึ้นเรื่อยๆ\n[Level 2] : เพิ่มความเร็วในการโจมตีขึ้นเล็กน้อย ธาติของอาวุธเปลี่ยนเป็นธาติลม เพิ่มพลังโจมตีทางกายภาพขึ้น 10%\n[Level 3] : ลด Delay การร่ายเวทย์ลง 50% และเพิ่มพลังโจมตีขึ้น 25% โดยเฉพาะการโจมตีด้วยเวทย์ธาติลม'),
('SO_EARTH_INSIGNIA', 'Earth Insignia', 3, 'Active / Ground', 'Requirement : Call Tera 3\nวาดเครื่องหมายดินไว้บนพื้น 3 x 3 ช่อง ฟื้นฟู 1% ของ HP ทุกๆ 5 วินาที, ถ้าเป้าหมายสวมใส่เครื่องป้องกันธาติดิน หรือ เป็น monster ธาติดิน ในทางกลับกัน, ลด HP ลง 1% ทุกๆ 5 วินาที, ถ้าเป้าหมายสวมใส่เครื่องป้องกันธาติลม หรือ หรือเป็น monster ธาติลม เป้าหมายทั้งหมดที่เข้ามาอยู่ในระยะของสกิลจะได้รับความเสียหายเพิ่มขึ้น 1.5 เท่าจากการโจมตีด้วยธาติำไฟ ใช้ [ ต้องการ Lime Green Point : 1 / 2 / 3 ] ในการร่ายสกิลตามเลเวลทักษะของสกิล', '[Level 1] : เพิ่มพลังโจมตีของ TERA ขึ้น 20% ฟื้นฟู HP, SP จำนวนหนึ่ง ทุกๆ 3 วินาทีขึ้นเรื่อยๆ\n[Level 2] : เพิ่ม MHP 500, DEF 50 ธาติของอาวุธเปลี่ยนเป็นธาติดิน เพิ่มพลังโจมตีทางกายภาพขึ้น 10%\n[Level 3] : เพิ่ม MSP 50 , MDEF 50 เพิ่มพลังโจมตีขึ้น 25% โดยเฉพาะการโจมตีด้วยเวทย์ธาิติดิน'),
('GN_TRAINING_SWORD', 'Sword Mastery', 5, 'Passive', 'Requirement : Genetic Basic\nเพิ่มพลังโจมตี และ HIT ของอาวุธประเภท One Handed Sword หรือ Dagger', '[Level 1] : พลังโจมตี + 10 / HIT + 3\n[Level 2] : พลังโจมตี + 20 / HIT + 6\n[Level 3] : พลังโจมตี + 30 / HIT + 9\n[Level 4] : พลังโจมตี + 40 / HIT + 12\n[Level 5] : พลังโจมตี + 50 / HIT + 15'),
('GN_REMODELING_CART', 'Cart Remodeling', 5, 'Passive', 'Requirement : Genetic Basic\nปรับแต่งรถเข็นของผู้ใช้ , เพิ่มน้ำหนักสูงสุด , เพิ่มความแม่นยำเมื่อใช้สกิล Cart Revolution , Cart Tornado และ Cart Cannon', '[Level 1] : Weight + 500 / Cart skill HIT + 4\n[Level 2] : Weight + 1000 / Cart skill HIT + 8\n[Level 3] : Weight + 1500 / Cart skill HIT + 12\n[Level 4] : Weight + 2000 / Cart skill HIT + 16\n[Level 5] : Weight + 2500 / Cart skill HIT + 20'),
('GN_CART_TORNADO', 'Cart Tornado Attack', 5, 'Active / Damage', 'Requirement : Cart Remodeling 1\nเหวี่ยงรถเข็นรอบๆตัวและกระแทกเป้าหมายในระยะ ให้กระเด็นถอยหลัง 2 ช่องและ ศัตรูในระยะ 2 ช่อง , ต้องการรถเข็นในการใช้สกิลนี้ สกิล Cart Remodeling และน้ำหนักในรถเข็น สามารถเพิ่มความรุนแรงของสกิลนี้ได้', '[Level 1] : พลังโจมตี 50%\n[Level 2] : พลังโจมตี 100%\n[Level 3] : พลังโจมตี 150%\n[Level 4] : พลังโจมตี 200%\n[Level 5] : พลังโจมตี 250%'),
('GN_CARTCANNON', 'Cart Cannon', 5, 'Active / Damage', 'Requirement : Cart Remodeling 2\nยิงกระสุนปืนจากรถเข็นสร้างความเสียหายอย่างมากแก่ 1 เป้าหมาย , ต้องการรถเข็นในการใช้สกิลนี้ สกิล Cart Remodeling และค่า INT ของผู้ใช้สามารถเพิ่มความรุนแรงของสกิลนี้ได้อย่างมาก ต้องการ 1 Cannon Ball', '[Level 1] : พลังโจมตี 60% +  Remodeling level\n[Level 2] : พลังโจมตี 120% +  Remodeling level\n[Level 3] : พลังโจมตี 180% +  Remodeling level\n[Level 4] : พลังโจมตี 240% +  Remodeling level\n[Level 5] : พลังโจมตี 300% +  Remodeling level'),
('GN_CARTBOOST', 'Cart Boost', 5, 'Buff (To yourself)', 'Requirement : Cart Remodeling 3\nเพิ่มความเร็วในการเคลื่อนที่ และ Attack Power เป็นเวลา 90 วินาที , ต้องการรถเข็นในการใช้สกิลนี้', '[Level 1] : ความเร็วในการเคลื่อนที่เพิ่มขึ้น 50% / พลังโจมตีเพิ่มขึ้น 10\n[Level 2] : ความเร็วในการเคลื่อนที่เพิ่มขึ้น 50% / พลังโจมตีเพิ่มขึ้น 20\n[Level 3] : ความเร็วในการเคลื่อนที่เพิ่มขึ้น 75% / พลังโจมตีเพิ่มขึ้น 30\n[Level 4] : ความเร็วในการเคลื่อนที่เพิ่มขึ้น 75% / พลังโจมตีเพิ่มขึ้น 40\n[Level 5] : ความเร็วในการเคลื่อนที่เพิ่มขึ้น 100% / พลังโจมตีเพิ่มขึ้น 50'),
('GN_THORNS_TRAP', 'Thorns Trap', 5, 'Special / Damage', 'Requirement : Special Pharmacy 2\nโยนกัปดักพืชหนามแหลมลงบนพื้นทำให้เป้าหมายเคลื่อนที่ไม่สะดวก , หากเป้าหมายยืนอยู่บน Trap จะได้รับความเสียหายตลอดเวลา และหากเป้าหมายได้รับความเสียหายจากการโจมตี ธาตุไฟ กับดักจะถูกทำลาย ต้องการ 1 Seed Of Horny Plant , Thorns Tap สามารถใช้ได้พร้อมกันสูงสุด 3 ครั้ง', '[Level 1] : ระยะเวลา 10 วินาที\n[Level 2] : ระยะเวลา 12 วินาที\n[Level 3] : ระยะเวลา 14 วินาที\n[Level 4] : ระยะเวลา 16 วินาที\n[Level 5] : ระยะเวลา 18 วินาที'),
('GN_BLOOD_SUCKER', 'Blood Sucker', 5, 'Special / Damage', 'Requirement : Special Pharmacy 3\nหว่านเมล็ดพืชสูบเลือดลงบนเป้าหมาย , เมื่อเป้าหมายได้รับความเสียหาย ผู้ใช้จะได้รับHP บางส่วน , สามารถใช้งานพร้อมกันได้ 3 เป้าหมาย หากผู้ใช้และเป้าหมายอยู่ห่างกันเกิน 12 ช่องผลของสกิลจะถูกยกเลิก ต้องการ 1 Bloodsuck Plant Seed', '[Level 1] : ระยะเวลา 20 วินาที\n[Level 2] : ระยะเวลา 22 วินาที\n[Level 3] : ระยะเวลา 24 วินาที\n[Level 4] : ระยะเวลา 26 วินาที\n[Level 5] : ระยะเวลา 28 วินาที'),
('GN_SPORE_EXPLOSION', 'Spore Explosion', 5, 'Special / Damage', 'Requirement : Special Pharmacy 4\nโปรยผงสปอร์เห็ดระเบิดลงบนเป้าหมาย , หลังจากผ่านไปครู่หนึ่ง สปอร์เห็ดจะระเบิด โดยจะไม่ได้สร้างความเสียหายแก่เป้าหมาย แต่จะสร้างความเสียหายทางเวทย์มนต์ให้แก่ทุกๆคนที่อยู่รอบๆเป้าหมาย , สกิลเลเวลจะช่วยเพิ่มระยะของสกิลนี้ได้ ต้องการ 1 Bomb Mushroom Spore', '[Level 1] : ระยะ 3 x 3 ช่อง / ระเบิดใน 2 วินาที\n[Level 2] : ระยะ 5 x 5 ช่อง / ระเบิดใน 2 วินาที\n[Level 3] : ระยะ 7 x 7 ช่อง / ระเบิดใน 3 วินาที\n[Level 4] : ระยะ 9 x 9 ช่อง / ระเบิดใน 3 วินาที\n[Level 5] : ระยะ 11 x 11 ช่อง / ระเบิดใน 4 วินาที'),
('GN_WALLOFTHORN', 'Wall Of Thorn', 5, 'Special / Wall', 'Requirement : Thorns Trap 3\nสร้างกำแพงพืชหนามขึ้นรอบๆ ตัวเป้าหมาย หากเป้าหมายสัมผัสกำแพงหนาม จะได้รับความเสียหาย , กำแพงนี้สามารถถูกโจมตีได้ และเมือ่ได้รับความเสียหายมากถึงที่กำหนด กำแพงจะหายไป หากำแพงหนามได้รับความเสียหายธาตุไฟ กำแพงหนามจะกลายเป็น Fire Wall สามารถใช้ได้ทีละ 1 กำแพงเท่านั้น ต้องการ 1 Seed Of Horny Plant', '[Level 1] : ระยะเวลา 10 วินาที\n[Level 2] : ระยะเวลา 11 วินาที\n[Level 3] : ระยะเวลา 12 วินาที\n[Level 4] : ระยะเวลา 13 วินาที\n[Level 5] : ระยะเวลา 14 วินาที'),
('GN_CRAZYWEED', 'Crazy Weed ', 10, 'Active / Damage', 'Requirement : Wall Of Thorn 3\nเรียกพืชดุร้ายออกมา สร้างความเสียหาย ธาตุดิน แก่ทุกเป้าหมายในระยะ และทำลาย Trap ในบริเวณรอบ ๆ สกิลเลเวลที่เพิ่มขึ้นจะช่วยเพิ่มความเสียหายและจำนวน Plant ที่สามารถเรียกออกมาได้ ต้องการ 1 Seed Of Horny Plant', '[Level 1] : พลังโจมตี 600% / 3 vines\n[Level 2] : พลังโจมตี 700% / 4 vines\n[Level 3] : พลังโจมตี 800% / 4 vines\n[Level 4] : พลังโจมตี 900% / 5 vines\n[Level 5] : พลังโจมตี 1000% / 5 vines\n[Level 6] : พลังโจมตี 1100% / 6 vines\n[Level 7] : พลังโจมตี 1200% / 6 vines\n[Level 8] : พลังโจมตี 1300% / 7 vines\n[Level 9] : พลังโจมตี 1400% / 7 vines\n[Level 10] : พลังโจมตี 1500% / 8 vines'),
('GN_DEMONIC_FIRE', 'Demonic Fire ', 5, 'Active / Damage', 'Requirement : Spore Explosion 3\nขว้างขวด Bottle Grenade ทำให้เกิดทะเลเพลิงขึ้น , เป้าหมายที่อยู่ในบริเวณดังกล่าวจะได้รับความเสียหายอย่างต่อเนื่อง และมีโอกาสติดสถานะ [Ignition] ต้องการ 1 Fire Bottle', '[Level 1] : ความเสียหายธาติไฟ 130 % / ระยะเวลา 10 วินาที / โอกาศติดสถานะ Ignition 8%\n[Level 2] : ความเสียหายธาติไฟ 150 % / ระยะเวลา 12 วินาที / โอกาศติดสถานะ Ignition 12%\n[Level 3] : ความเสียหายธาติไฟ 170 % / ระยะเวลา 14 วินาที / โอกาศติดสถานะ Ignition 16%\n[Level 4] : ความเสียหายธาติไฟ 190 % / ระยะเวลา 16 วินาที / โอกาศติดสถานะ Ignition 20%\n[Level 5] : ความเสียหายธาติไฟ 210 % / ระยะเวลา 18 วินาที / โอกาศติดสถานะ Ignition 24%'),
('GN_FIRE_EXPANSION', 'Fire Expansion', 5, 'Active / Special / Damage', 'Requirement : Demonic Fire 3\nหากใช้สกิลสกิลนี้ลงบนบริเวณทะเลเพลงของสกิล Demonic Fire จะทำให้เป้าหมายที่อยู่ในบริเวณของสกิล ได้รับผลกระทบเพิ่มขึ้นตามเลเวลของสกิล', '[Level 1] : ต้องการ Oil Bottle / เพิ่มพลังโจมตี Demonic Fire ขึ้น 50% / เพิ่มระยะเวลา + 10 วินาที\n[Level 2] : ต้องการ Explosive Powder/ เพิ่มพลังโจมตี Demonic Fire ขึ้นตาม INT ของผู้เล่น / ยกเลิกผลของ Demonic Fire\n[Level 3] : ต้องการ Smoke Powder / Demonic Fire เปลี่ยนเป็น Smoke bullet / ลดระยะการโจมตีระยะไกล / เพิ่ม Flee Rate\n[Level 4] : ต้องการ Tear Gas / Demonic Fire เปลี่ยนเป็น Tear Gas / ลด HP, HIT, Flee Rate ลง\n[Level 5] : ต้องการ Acid Bottle / Demonic Fire เปลี่ยนเป็น Acid Demonstration / ผลของสกิลเทียบเท่าผลจากสกิล Acid Demonstration ที่เราเรียนรู้'),
('GN_HELLS_PLANT', 'Hell Plant', 5, 'Active / Special / Damage', 'Requirement : Blood Sucker 3\nเรียกเมล็ดพืชจากนรกขึ้นสู่พื้นดิน , หากทำการจู่โจมใส่เป้าหมายที่อยู่ใกล้เมล็ดพืชนี้ เป้าหมายจะมีโอกาสติดสถานะ [Stun] และ [Bleeding]', '[Level 1] : summoning plants 2 / [Bleeding] 10 % / [Stun] 30%\n[Level 2] : summoning plants 3 / [Bleeding] 15 % / [Stun] 40%\n[Level 3] : summoning plants 4 / [Bleeding] 20 % / [Stun] 50%\n[Level 4] : summoning plants 5 / [Bleeding] 25 % / [Stun] 60%\n[Level 5] : summoning plants 6 / [Bleeding] 30 % / [Stun] 70%'),
('GN_MANDRAGORA', 'Mandragora Howling', 5, 'Active / Special / Damage', 'Requirement : Hell Plant  3\nปลุกชีพ MANDRAGORA จากผืนดินสร้างเสียงกรีดร้องอันร้ายกาจ , ลดค่า INT ของเป้าหมายและดูดกลืน SP , เพิ่ม Fix Casting Time ของเป้าหมายให้มากขึ้น โอกาสสำเร็จขึ้นอยู่กับค่า VIT และ LUK ของเป้าหมาย', '[Level 1] : ระยะสกิล 11 x 11  / INT - 4 / SP ลดลง 30%\n[Level 2] : ระยะสกิล 13 x 13  / INT - 8 / SP ลดลง 35%\n[Level 3] : ระยะสกิล 13 x 13  / INT - 12 / SP ลดลง 40%\n[Level 4] : ระยะสกิล 15 x 15  / INT - 16 / SP ลดลง 45%\n[Level 5] : ระยะสกิล 15 x 15  / INT - 20 / SP ลดลง 50%'),
('GN_SLINGITEM', 'Item Sling', 1, 'Active', 'Requirement : Change Material 1\nขว้าง fruit bombs หรือ pitching items ระยะของสกิล 11 ช่อง', NULL),
('GN_CHANGEMATERIAL', 'Change Material', 1, 'Active', 'Requirement : Genetic Basic\nผสมไอเทม 2 ชนิดเพื่อสร้างเป็นไอเทมชิ้นใหม่ อย่างไรก็ตามเราไม่สามารถสร้างไอเทมบางอย่างได้ , หากผู้ใช้ไม่ทราบชื่อของไอเทมและ ส่วนประกอบที่ถูกต้องในการผสม สกิลจะล้มเหลว มีคำบอกเล่าว่า สูตรผสมไอเทมนั้นอยู่ในสถานที่บางแห่งในโลกนี้', NULL),
('GN_MIX_COOKING', 'Mixed Cooking', 2, 'Active', 'Requirement : Special Pharmacy 1\nผสมวัตุดิบเพื่อประกอบเป็นอาหารที่อร่อยอย่างไม่น่าเชื่อ , หากใช้สกิล Mix Cooking เลเวล 2 จะสามารถประกอบอาหารได้ครั้งละ 10 ชิ้น ต้องการ Cooking Book และ ส่วนประกอบที่จำเป็นสำหรับการประกอบอาหารนั้นๆ ในการใช้สกิล', NULL),
('GN_MAKEBOMB', 'Bomb Creation', 2, 'Active', 'Requirement : Mixed Cooking 1\nสร้างผลระเบิดชนิดต่างๆ , หากใช้สกิล level 2 Bomb Creation จะสามารถสร้างระเบิดได้ครั้งละ 10 ชิ้น , ต้องการ ''Bomb Making Manual (Manual Book)'' ในการใช้สกิลนี้', NULL),
('GN_S_PHARMACY', 'Special Pharmacy ', 10, 'Active', 'Requirement : Genetic Basic\nเพิ่มทักษะในการสร้าง Potion และ เครื่องดื่ม แก่ Genetic ,  สกิลเลเวลจะช่วยเพิ่มจำนวนไอเทมที่จะได้รับในการสร้าง , ต้องการหนังสือคู่มือในการสร้าง Potion ตามชนิดของ Potion ที่จะสร้าง', NULL),
('AB_SECRAMENT', 'Secrament', 5, 'Buff', 'Requirement : Epiclesis 1 / Expiatio 1\nลด Delay การร่ายของเป้าหมายด้วยเวทย์มนตร์ศักดิ์สิทธิ์', '[Level 1] : ลด casting delay ลง 10% / ระยะเวลา 60 วินาที\n[Level 2] : ลด casting delay ลง 20% / ระยะเวลา 90 วินาที\n[Level 3] : ลด casting delay ลง 30% / ระยะเวลา 120 วินาที\n[Level 4] : ลด casting delay ลง 40% / ระยะเวลา 150 วินาที\n[Level 5] : ลด casting delay ลง 50% / ระยะเวลา 180 วินาที'),
('ALL_ODINS_RECALL', '', NULL, NULL, NULL, NULL),
('RETURN_TO_ELDICASTES', 'To El Dicastes', 1, 'Supportive(Return)', 'กลับไปยัง El Dicastes, the Capital of Sapha ระยะเวลา 5 นาที ในการใช้ครั้งต่อไป', NULL),
('HLIF_HEAL', 'Healing Hands', 5, NULL, 'ฟื้นค่า HP ให้กับผู้เล่น โดยการเลียนแบบ\nAcolyte''s Heal skill ค่า HP ที่จะเพิ่มขึ้นนั้นขึ้นกับสกิลเลเวล\nเลเวลและค่า INT ของผู้ร่าย การร่ายแต่ละครั้งใช้ Red Slim Potion 1 ea\nSP ที่ใช้แต่ละ Level', '[Lv 1] 13 SP\n[Lv 2] 16 SP\n[Lv 3] 19 SP\n[Lv 4] 22 SP\n[Lv 5] 25 SP'),
('HLIF_AVOID', 'Urgent Escape', 5, NULL, 'เพิ่มความเร็วในการเคลื่อนที่ของผู้ร่ายและ Homunculus ชั่วขณะ\nเพื่อใช้หนีจากสถานะการณ์ฉุกเฉิน', '[Lv 1] ความเร็วในการเคลื่อนที่ +10%, ระยะเวลา 40 วินาที\n[Lv 2] ความเร็วในการเคลื่อนที่ +20%, ระยะเวลา 35 วินาที\n[Lv 3] ความเร็วในการเคลื่อนที่ +30%, ระยะเวลา 30 วินาที\n[Lv 4] ความเร็วในการเคลื่อนที่ +40%, ระยะเวลา 25 วินาที\n[Lv 5] ความเร็วในการเคลื่อนที่ +50%, ระยะเวลา 20 วินาที'),
('HLIF_BRAIN', 'Brain Surgery', 5, 'Passive', 'เปลี่ยนรูปร่าง สมองของ Lif Homunculus\nเพื่อเพิ่ม MAX SP และอัตราการฟื้นค่า SP\nและยังเพิ่มความสามารถให้กับ Healing Hands skill', '[Lv 1] Max SP +1%, SP Recovery +3%, Healing Hands +2%\n[Lv 2] Max SP +2%, SP Recovery +6%, Healing Hands +4%\n[Lv 3] Max SP +3%, SP Recovery +9%, Healing Hands +6%\n[Lv 4] Max SP +4%, SP Recovery +12%, Healing Hands +8%\n[Lv 5] Max SP +5%, SP Recovery +15%, Healing Hands +10%'),
('HLIF_CHANGE', 'Mental Change', 3, NULL, 'เพิ่ม INT และ VIT ของ Homunculus\nและค่า ATK จะมีค่าเท่ากับ MATK\nหลังจากหมดระยะเวลาของสกิล\nHP และ SP จะเหลือ 10', '[Lv 1] ระยะเวลา : 1 นาที, VIT จะเพิ่มขึ้น : 30, INT จะเพิ่มขึ้น : 20, Skill Cool Time : 10 นาที\n[Lv 2] ระยะเวลา : 3 นาที, VIT จะเพิ่มขึ้น : 60, INT จะเพิ่มขึ้น : 40, Skill Cool Time : 15 นาที\n[Lv 3] ระยะเวลา : 5 นาที, VIT จะเพิ่มขึ้น : 90, INT จะเพิ่มขึ้น : 60, Skill Cool Time : 20 นาที'),
('HAMI_CASTLE', 'Castling', 5, NULL, 'สลับที่ทันใจสลับตำแหน่งระหว่างผู้ร่ายกับ\nAmistr Homunculus ขณะที่ศัตรูกำลังโจมตีผู้ร่ายแล้วทำการสลับ เป้าหมายจะตกไปอยู่ที่\nmonsters attacking the caster will target\nAmistr แทน', '[Lv 1] โอกาสสำเร็จ 20%\n[Lv 2] โอกาสสำเร็จ 40%\n[Lv 3] โอกาสสำเร็จ 60%\n[Lv 4] โอกาสสำเร็จ 80%\n[Lv 5] โอกาสสำเร็จ 100%'),
('HAMI_DEFENCE', 'Amistr Bulwark', 5, NULL, 'เพิ่มพลังป้องกันให้กับผู้ร่ายและ Amistr Homunculus\nชั่วระยะเวลาหนึ่ง', '[Lv 1] DEF +2, ระยะเวลา 40 วินาที\n[Lv 2] DEF +4, ระยะเวลา 35 วินาที\n[Lv 3] DEF +6, ระยะเวลา 30 วินาที\n[Lv 4] DEF +8, ระยะเวลา 25 วินาที\n[Lv 5] DEF +10, ระยะเวลา 20 วินาที'),
('HAMI_SKIN', 'Adamantium Skin', 5, 'Passive', 'Permanently increase the\nเพิ่มค่าพลังป้องกัน, Max HP และ HP\nRecovery Rate ให้กับ Hermunculus', '[Lv 1] MHP +2%, HP Recovery Rate +5%, DEF +4\n[Lv 2] MHP +4%, HP Recovery Rate +10%, DEF +8\n[Lv 3] MHP +6%, HP Recovery Rate +15%, DEF +12\n[Lv 4] MHP +8%, HP Recovery Rate +20%, DEF +16\n[Lv 5] MHP +10%, HP Recovery Rate +25%, DEF +20'),
('HAMI_BLOODLUST', 'Blood Lust', 3, NULL, 'เพิ่มพลังโจมตี ให้กับ\nHomunculus ชั่วคราว\nระหว่างอยู่ในสถานะ Blood Lust\nทุกการโจมตีของ Homunculus มีโอกาสฟื้นพลังเท่ากับ\n20% ของค่าความเสียหายที่สร้างให้กับศัตรู', '[Lv 1] ระยะเวลา 1 นาที, Attack Power +130%, HP Gain Chance +3%, Delay 5 นาที\n[Lv 2] ระยะเวลา 3 นาที, Attack Power +140%, HP Gain Chance +6%, Delay 10 นาที\n[Lv 3] ระยะเวลา 5 นาที, Attack Power +150%, HP Gain Chance +9%, Delay 15 นาที'),
('HFLI_MOON', 'Moonlight', 5, NULL, 'สั่ง\nFilir Homunculus ให้จิกเป้าหมาย', '[Lv 1] 1 Peck, Damage +220%\n[Lv 2] 2 Pecks, Damage +330%\n[Lv 3] 2 Pecks, Damage +440%\n[Lv 4] 2 Pecks, Damage +550%\n[Lv 5] 3 Pecks, Damage +660%'),
('HFLI_FLEET', 'Flitting', 5, NULL, 'เพิ่มพลังการโจมตีและ Aspd ให้กับ Filir Homunculus ชั่วคราว', '[Lv 1] Aspd +3 Attack Power +110%, ระยะเวลา 60 วินาที,  Delay skill 60 วินาที\n[Lv 2] Aspd +6 Attack Power +115%, ระยะเวลา 55 วินาที,  Delay skill 70 วินาที\n[Lv 3] Aspd +9 Attack Power +120%, ระยะเวลา 50 วินาที,  Delay skill 80 วินาที\n[Lv 4] Aspd +12 Attack Power +125%, ระยะเวลา 45 วินาที,  Delay skill 90 วินาที\n[Lv 5] Aspd +15 Attack Power +130%, ระยะเวลา 40 วินาที,  Delay skill 120 วินาที'),
('HFLI_SPEED', 'Accelerated Flight', 5, NULL, 'เพิ่มค่า Flee Rate, ให้กับ Filir Homunculus ชั่วคราว', '[Lv 1] Flee Rate +20, ระยะเวลา 60 วินาที, Delay 60 วินาที\n[Lv 2] Flee Rate +30, ระยะเวลา 55 วินาที, Delay 70 วินาที\n[Lv 3] Flee Rate +40, ระยะเวลา 50 วินาที, Delay 80 วินาที\n[Lv 4] Flee Rate +50, ระยะเวลา 45 วินาที, Delay 90 วินาที\n[Lv 5] Flee Rate +60, ระยะเวลา 40 วินาที, Delay 120 วินาที'),
('HFLI_SBR44', 'S.B.R.44', 3, NULL, 'ใช้ค่า, ความสัมพันธ์ระหว่างผู้ร่ายและ, Homunculus ในการสร้างความเสียหาย', '[Lv 1] 100 * ค่าความสนิมสนมที่ลดลง\n[Lv 2] 200 * ค่าความสนิมสนมที่ลดลง\n[Lv 3] 300 * ค่าความสนิมสนมที่ลดลง'),
('HVAN_CAPRICE', 'Caprice', 5, NULL, 'สุ่มร่าย Bolt skill, ชนิดต่างๆ โดยเลเวลของสกิลที่ร่ายขึ้นกับ\nskill level ของ Caprice', '[Lv 1] ร่าย Lv 1 Bolt skill\n[Lv 2] ร่าย Lv 2 Bolt skill\n[Lv 3] ร่าย Lv 3 Bolt skill\n[Lv 4] ร่าย Lv 4 Bolt skill\n[Lv 5] ร่าย Lv 5 Bolt skill'),
('HVAN_CHAOTIC', 'Chaotic Blessings', 5, NULL, 'ฟื้นค่า HP แบบสุ่ม\nระหว่างศัตรู, Homunculus และผู้เลี้ยง Homunculus', '[Lv 1] Lv 1 Heal, 20% ที่จะฟื้น HP ให้กับ Homunculus, 30% ที่จะฟื้น HP ให้กับผู้เลี้ยง, 50% ที่จะฟื้น HP ให้กับศัตรู\n[Lv 2] Lv 1~2 Heal, 50% ที่จะฟื้น HP ให้กับ Homunculus, 10% ที่จะฟื้น HP ให้กับผู้เลี้ยง, 40% ที่จะฟื้น HP ให้กับศัตรู\n[Lv 3] Lv 1~3 Heal, 25% ที่จะฟื้น HP ให้กับ Homunculus, 50% ที่จะฟื้น HP ให้กับผู้เลี้ยง, 25% ที่จะฟื้น HP ให้กับศัตรู\n[Lv 4] Lv 1~4 Heal, 60% ที่จะฟื้น HP ให้กับ Homunculus, 4% ที่จะฟื้น HP ให้กับผู้เลี้ยง, 36% ที่จะฟื้น HP ให้กับศัตรู\n[Lv 5] Lv 1~2 Heal, 34% ที่จะฟื้น HP ให้กับ Homunculus,33% ที่จะฟื้น HP ให้กับผู้เลี้ยง, 33% ที่จะฟื้น HP ให้กับศัตรู'),
('HVAN_INSTRUCT', 'Instruction Change', 5, 'Passive', 'เพิ่มค่า, INT และ STR ให้กับ Homunculus', '[Lv 1] +1 INT, +1 STR\n[Lv 2] +2 INT, +1 STR\n[Lv 3] +2 INT, +3 STR\n[Lv 4] +4 INT, +4 STR\n[Lv 5] +5 INT, +4 STR'),
('HVAN_EXPLOSION', 'Self-Destruction', 3, NULL, 'สั่ง, Homunculus ให้ระเบิดตัวเอง, สร้างความเสียหายแบบกลุ่ม ค่าความเสียหายขึ้นกับ Max HP, ของ Homuculus หากสกิลสำเร็จค่าความสัมพันธ์, ระหว่าง Homuculus และผู้เลี้ยงจะลดเหลือ 1', '[Lv 1] Damage = Max HP*1\n[Lv 2] Damage = Max HP*1.5\n[Lv 3] Damage = Max HP*2'),
('MS_BASH', 'Bash', 10, 'Offensive', 'เป้าหมาย : ศัตรู\nโจมตีศัตรู, ด้วยพลังอันรุนแรงในทีเดียว, ถ้ามีสกิล Fatal Blow, Bash ตั้งแต่เลเวล 5 ขึ้นไปมีโอกาสทำให้ศัตรูติด Stun', '[Level 1] : Atk 130%\n[Level 2] : Atk 160%\n[Level 3] : Atk 190%\n[Level 4] : Atk 220%\n[Level 5] : Atk 250%\n[Level 6] : Atk 280%\n[Level 7] : Atk 310%\n[Level 8] : Atk 340%\n[Level 9] : Atk 370%\n[Level 10] : Atk 400%'),
('MS_MAGNUM', 'Magnum Break', 10, 'Offensive(Fire)', 'ผู้ใช้, จะเสีย HP เล็กน้อย, ในการสร้างความเสียหายธาตุไฟ, บริเวณรอบตัวผู้ใช้และมีผลทำให้ศัตรูกระเด็นเล็กน้อย, หลังจากใช้\nMagnum Break 10 วินาที, อาวุธของผู้ใช้จะได้รับ, ความแข็งแกร่งจากธาตุไฟ, เพิ่มขึ้น 20%', '[Level 1] : Atk 120%\n[Level 2] : Atk 140%\n[Level 3] : Atk 160%\n[Level 4] : Atk 180%\n[Level 5] : Atk 200%\n[Level 6] : Atk 220%\n[Level 7] : Atk 240%\n[Level 8] : Atk 260%\n[Level 9] : Atk 280%\n[Level 10] : Atk 300%'),
('MS_BOWLINGBASH', 'Bowling Bash', NULL, 'Offensive', 'เป้าหมาย : ศัตรู\nโจมตี, ศัตรูด้วยพลังอันรุนแรง, ความเสียหายทำให้ศัตรูที่อยู่รอบๆ, โดนกระแทกกระเด็นออกไป', NULL),
('MS_PARRYING', 'Parry', 10, 'Supportive', 'ป้องกัน, การโจมตีด้วย, ดาบสองมือขณะต่อสู้, ถ้าป้องกันสำเร็จ, ผู้ใช้จะไม่ได้รับ, ผลของการโจมตีนั้น', '[Level 1] : Block +23%\n[Level 2] : Block +26%\n[Level 3] : Block +29%\n[Level 4] : Block +32%\n[Level 5] : Block +35%\n[Level 6] : Block +38%\n[Level 7] : Block +41%\n[Level 8] : Block +44%\n[Level 9] : Block +47%\n[Level 10] : Block +50%'),
('MS_REFLECTSHIELD', 'Reflect Shield', NULL, 'Supportive', 'สะท้อน, พลังโจมตี, ใส่ศัตรูเมื่อได้รับ, ความเสียหายทางกายภาพ, ระยะประชิด, ใช้ได้เมื่อถือโล่อยู่เท่านั้น', NULL),
('MS_BERSERK', 'Berserk', NULL, 'Supportive', 'ใช้พลัง แห่งความบ้าคลั่งงเพิ่ม Max HP ความเร็วในการเคลื่ยนที่ และพลังโจมตี\nแต่จะลดค่า Flee และ พลังป้องกันของผู้ใช้ เมื่อตกอยู่ในสถานะนี้ผู้ใช้จะ ทำได้แค่เพียงเคลื่อนที่กับโจมตีเท่านั้น ไม่สามารถใช้ไอเท็มหรือสกิล ช่วยเหลือใดๆ ได้\nHP จะลดลงเรื่อยๆ ทุกวินาที และ HP/SP จะไม่ฟื้นฟู  เป็นเวลา 5 นาที แม้ว่าจะหมด สถานะนี้แล้วก็ตาม', NULL),
('MA_DOUBLE', 'Double Strafing', NULL, 'Offensive', 'เป้าหมาย : ศัตรู\nยิงธนู สร้างความเสียหายให้กับเป้าหมาย 2 ครั้งซ้อนในการโจมตีทีเดียว', NULL),
('MA_SHOWER', 'Arrow shower', NULL, 'Offensive', 'เป้าหมาย : ศัตรู\nระดมยิงลูกธนูจำนวนมา ใส่เป้าหมายและศัตรูรอบๆ เป้าหมาย', NULL),
('MA_SKIDTRAP', 'Skid Trap', 5, 'Hidden trap', 'เป้าหมาย : พื้นดิน\nวางกับดัก ที่จะทำให้ศัตรู ลื่นไปในทิศทาง ที่ลูกศรชี้ใช้ Trap 1 อัน', '[Level 1] : 6 ช่อง, 300 วินาที\n[Level 2] : 7 ช่อง, 240 วินาที\n[Level 3] : 8 ช่อง, 180 วินาที\n[Level 4] : 9 ช่อง, 120 วินาที\n[Level 5] : 10 ช่อง, 60 วินาที'),
('MA_LANDMINE', 'Land Mine', 5, 'Hidden trap', 'เป้าหมาย : พื้นดิน\nวางกับดัก ที่ระเบิดศัตรูเพียงตัวเดียว เมื่อศัตรูเดินเข้ามาเหยีย ความแรงและระยะเวล ของกับดักขึ้นอยู่กับเลเวลสกิล', '[Level 1] : Atk 50%, 65 วินาที\n[Level 2] : Atk 75%, 50 วินาที\n[Level 3] : Atk 100%, 35 วินาที\n[Level 4] : Atk 125%, 20 วินาที\n[Level 5] : Atk 150%, 5 วินาที'),
('MA_SANDMAN', 'Sandman', 5, 'Hidden Trap', 'เป้าหมาย : พื้นดิน\nวางกับดัก ทำให้ศัตรูที่เหยียบมัน และศัตรูใกล้เคียง ติดสถานะหลับ ใช้กับดัก 1 อัน', '[Level 1] : 150 วินาที\n[Level 2] : 120 วินาที\n[Level 3] : 90 วินาที\n[Level 4] : 60 วินาที\n[Level 5] : 30 วินาที'),
('MA_FREEZINGTRAP', 'Freezing Trap', 5, 'Hidden trap', 'เป้าหมาย : พื้นดิน\nวางกับดัก ที่สามารถแช่แข็งศัตรูได้ เมื่อถูกเหยียบ ใช้กับดัก 2 อัน', '[Level 1] : 150 วินาที\n[Level 2] : 120 วินาที\n[Level 3] : 90 วินาที\n[Level 4] : 60 วินาที\n[Level 5] : 30 วินาที'),
('MA_REMOVETRAP', 'Remove Trap', NULL, 'Supportive', 'เป้าหมาย : Trap\nใช้เก็บ กับดักที่ถูกวาง อยู่บนพื้น กลับขึ้นมาได้', NULL),
('MA_CHARGEARROW', 'Charge Arrow', NULL, 'Offensive', 'เป้าหมาย : ศัตรู\nรั้งสายธนู จนสุดเพื่อเพิ่ม ความรุนแรงให้แก่ลูกธนู ทำให้เป้าหมาย กระเด็นออกไป 4 ช่อง', NULL),
('MA_SHARPSHOOTING', 'Sharpshooting', 5, 'Offensive', 'ยิงธนู พุ่งไปยังจุดตายของ เป้าหมายอย่างรวดเร็ว\nสร้างความเสียหายa เป้าหมาย แก่ศัตรูอย่างมาก การยิงนี้เป็น Critical\nAttack ที่ถูกคำนวน จากค่า Critical ของผู้ร่าย +20', '[Level 1] : Atk +150%\n[Level 2] : Atk +200%\n[Level 3] : Atk +250%\n[Level 4] : Atk +300%\n[Level 5] : Atk +350%'),
('ML_PIERCE', 'Pierce', NULL, 'Offensive', 'เป้าหมาย : ศัตรู\nโจมตีศัตรู โดยการแทงหอกออกไป จำนวนครั้งจะเพิ่มขึ้นตามขนาดของมอนสเตอร์ ใช้กับอาวุธประเภท Spear.\n[มอนสเตอร์ขนาดเล็ก] : 1 ครั้ง\n[มอนสเตอร์ขนาดกลาง] : 2 ครั้ง\n[มอนสเตอร์ขนาดใหญ่] : 3 ครั้ง', NULL),
('ML_BRANDISH', 'Brandish Spear', NULL, 'Offensive', 'เป้าหมาย : ศัตรู\nใช้หอกสร้างคลื่นพลัง โจมตีเป็นบริเวณกว้าง สามารถโจมตีศัตรูได้ทีละ หลายตัวพร้อมกัน ใช้กับ, อาวุธประเภท Spearจะใช้ได้ก็ต่อเมื่อ ขี่ PecoPeco อยู่เท่านั้น', NULL),
('ML_SPIRALPIERCE', 'Spiral Pierce', NULL, 'Offensive', 'โจมตี ศัตรูด้วยหอกควงสว่าน สร้างความเสียหายแก่ศัตรู\nเป็นจำนวน 5 ครั้ง ?เลเวลของสกิลและ\nน้ำหนักของอาวุธ มีผลต่อความแรงและ เลเวลของสกิลมีผลต่อระยะเวลาร่ายและดีเลย์ของสกิลนี้', NULL),
('ML_DEFENDER', 'Defender', NULL, 'Supportive', 'ลด ค่าความเสียหาย จากการโจมตีทางกายภาพ ระยะไกล และมีผลทำให้\nผู้ใช้เคลื่อนที่และ โจมตีช้าลง สามารถยกเลิก ผลของสกิลนี้ได้โดยการ กดใช้สกิลนี้อีกครั้ง ใช้ได้เมื่อถือโล่อยู่เท่านั้น', NULL),
('ML_AUTOGUARD', 'Auto Guard', NULL, 'Supportive', 'ป้องกัน การโจมตีทางกายภาพ ในระยะเวลา ที่กำหนด เมื่อทำการ ป้องกันการโจมตีได้\nตัวผู้ใช้จะชะงักไป 0.3 วินาที ถ้ามีเลเวลสกิลที่สูงขึ้น จะช่วยลดอาการชะงักให้น้อยลง ถ้าต้องการยกเลิกสกิลให้กดสกิลซ้ำอีกครั้ง ใช้ได้เมื่อถือโล่อยู่เท่านั้น', NULL),
('ML_DEVOTION', 'Devotion', NULL, 'Supportive', 'เป้าหมาย : สมาชิกในปาร์ตี้ 1 คน\nป้องกัน สมาชิกในปาร์ต โดยการที่ผู้ใช้จะรับค่าความเสียหาย แทนเป้าหมายทั้งหมด ตัวละครเป้าหมายต้อง มีเลเวลแตกต่าง กับผู้ใช้ไม่เกิน 10 เลเวล สกิลนี้จะถูก ยกเลิกก็ต่อเมื่อ เป้าหมายเคลื่อนที่ออกห่าง จากตัวผู้ใช้หรือตาย ไม่สามารถใช้กับ Crusaderหรือ Paladin ด้วยกันได้', NULL),
('MER_MAGNIFICAT', 'Magnificat', NULL, 'Supportive', 'เป้าหมาย : Player, Mercenary\nเพิ่มความเร็วการฟื้น SP 2 เท่าให้ กับสมาชิกทุกคนใน Party', NULL),
('MER_QUICKEN', 'Weapon Quicken', 10, 'Supportive', 'เพิ่มความเร็วในการ โจมตีชั่วคราว ระยะเวลาของสกิลจะเพิ่มขึ้น ตามเลเวลของสกิล', '[Level 1] : 30 วินาที\n[Level 2] : 60 วินาที\n[Level 3] : 1 นาที 30 วินาที\n[Level 4] : 2 นาที\n[Level 5] : 2 นาที 30 วินาที\n[Level 6] : 3 นาที\n[Level 7] : 3 นาที 30 วินาที\n[Level 8] : 4 นาที\n[Level 9] : 4 นาที 30 วินาที\n[Level 10] : 5 นาที'),
('MER_SIGHT', 'Sight', NULL, 'Supportive(Fire)', 'ตรวจสอบศัตรูที่ซ่อนอยู่ใกล้ๆ ตัวผู้ร่าย', NULL),
('MER_CRASH', 'Crash', 5, 'Offensive', 'เป้าหมาย : ศัตรู\nเพิ่มพลังโจมตี และเพิ่มโอกาสที่จะทำให้ ศัตรูติดสถานะ stun', '[Level 1] : Atk 110%, 6% Stun Rate\n[Level 2] : Atk 120%, 12% Stun Rate\n[Level 3] : Atk 130%, 18% Stun Rate\n[Level 4] : Atk 140%, 24% Stun Rate\n[Level 5] : Atk 150%, 30% Stun Rate'),
('MER_REGAIN', 'Regain', NULL, 'Supportive', 'เป้าหมาย : Player, Mercenary\nรักษาอาการ Stun และ Sleep ของเป้าหมาย', NULL),
('MER_TENDER', 'Tender', NULL, 'Supportive', 'เป้าหมาย : Player, Mercenary\nรักษาอาการ Freeze และ Stone ของเป้าหมาย', NULL),
('MER_BENEDICTION', 'Benediction', NULL, 'Supportive', 'เป้าหมาย : Player, Mercenary\nรักษาอาการ Curse และ Blind ของเป้าหมาย', NULL),
('MER_RECUPERATE', 'Recuperate', NULL, 'Supportive', 'เป้าหมาย : Player, Mercenary\nรักษาอาการ Silence และ Poison ของเป้าหมาย', NULL),
('MER_MENTALCURE', 'Mental Cure', NULL, 'Supportive', 'เป้าหมาย : Player, Mercenary\nรักษาอาการ Confusion และ Poison ของเป้าหมาย', NULL),
('MER_COMPRESS', 'Compress', NULL, 'Supportive', 'เป้าหมาย : Player, Mercenary\nรักษาอาการ Bleeding ของเป้าหมาย', NULL),
('MER_PROVOKE', 'Provoke', 10, 'Supportive', 'เป้าหมาย : ศัตรู\nทำให้พลังป้องกันของศัตรูลดลงแต่พลังโจมตีจะสูงขึ้น ใช้กับ Undead ไม่ได้ ผลของสกิลขึ้นอยู่กับระดับเลเวล', '[Level 1] : +5% Atk, -10% DEF\n[Level 2] : +8% Atk, -15% DEF\n[Level 3] : +11% Atk, -20% DEF\n[Level 4] : +14% Atk, -25% DEF\n[Level 5] : +17% Atk, -30% DEF\n[Level 6] : +20% Atk, -35% DEF\n[Level 7] : +23% Atk, -40% DEF\n[Level 8] : +26% Atk, -45% DEF\n[Level 9] : +29% Atk, -50% DEF\n[Level 10] : +32% Atk, -55% DEF'),
('MER_AUTOBERSERK', 'Auto Berserk', NULL, 'Passive', 'เมื่ออยู่ในสถานะตามเงื่อนไขจะเปรียบเสมือนได้รับสกิล Provoke  Level 10 สกิลจะทำงานเมื่อ HP น้อยกว่า 25% ของ Max HP และจะยกเลิกเมื่อ HP มากกว่า 25% ของ Max HP หรือผลของ Provoke ถูกลบล้าง', NULL),
('MER_DECAGI', 'Decrease AGI', NULL, 'Supportive', 'เป้าหมาย : ศัตรู\nลดความเร็วในการเคลื่อนท และความเร็วในการโจมตี ผลของสกิลขึ้นอยู่กับระดับเลเวลสกิล', NULL),
('MER_SCAPEGOAT', 'Scapegoat', NULL, 'Supportive', 'Mercenary จะสละ HP ที่เหลืออยู่ให้กับ ผู้เรียกใช้งาน', NULL),
('MER_LEXDIVINA', 'Lex Divina', NULL, 'Exorcism', 'เป้าหมาย : ศัตรู\nทำให้ศัตรูไม่สามารถใช้ Skill ได้ ชั่วขณะหนึ่ง', NULL),
('MER_ESTIMATION', 'Sense', NULL, 'Supportive', 'เป้าหมาย : มอนเตอร์\nใช้ตรวจสอบรายละเอียดของศัตร ซึ่งแสดงผลให้กับผู้ร่ายและคนในปาร์ตี้', NULL),
('MER_KYRIE', '', NULL, NULL, NULL, NULL),
('MER_BLESSING', '', NULL, NULL, NULL, NULL),
('MER_INCAGI', '', NULL, NULL, NULL, NULL),
('GD_APPROVAL', 'Official Guild Approval', NULL, 'Passive', 'เป้าหมาย : Guild\nได้รับประกาศนียบัตร guild อย่างเป็นทางการแห่งอาณาจักร Rune Midgard สมาชิกใน guild ทางการจะได้รับสิทธิ์ในการโจมตี Emperium ของ guild อื่นที่มีพื้นที่ของตัวเองได้', NULL),
('GD_KAFRACONTRACT', 'Contract With Kafra', NULL, 'Passive', 'เป้าหมาย : Guild\nสามารถจ้าง Kafra ได้จาก Kafra Corporation, เพื่อใช้งานในบริเวณพื้นที่ Guild ของตนได้', NULL),
('GD_GUARDRESEARCH', 'Guardian Research', NULL, 'Passive', 'เป้าหมาย : Guild\nศึกษาเทคโนโลยีของ Guardian จากการวิจัย Guild สามารถจ้าง guardians สำหรับพื้นที่ของตนได้', NULL),
('GD_GUARDUP', 'Strengthen Guardians', NULL, 'Passive', 'เพิ่มความแข็งแกร่งให้กับ Guardian\nLevel Skill ที่เพิ่มขึ้นจะเพิ่มพลังโจมตี และความเร็วให้กับ Guardian', NULL),
('GD_EXTENSION', 'Guild Extension', 10, 'Passive', 'เป้าหมาย : Guild\nเพิ่มจำนวนสมาชิกสูงสุดใน guild', '[Lv 1] : 20  คน\n[Lv 2] : 24  คน\n[Lv 3] : 28 คน\n[Lv 4] : 32 คน\n[Lv 5] : 36 คน\n[Lv 6] : 40 คน\n[Lv 7] : 44 คน\n[Lv 8] : 48 คน\n[Lv 9] : 52 คน\n[Lv10] : 56 คน'),
('GD_GLORYGUILD', '', NULL, NULL, NULL, NULL),
('GD_LEADERSHIP', 'Great Leadership', NULL, 'Passive', 'เป้าหมาย : สมาชิก Guild ในระยะ  5*5 รอบๆ Guild Master\nสมาชิก Guild ในระยะ  5*5 ช่อง รอบๆ Guild Master จะได้รับ +5 Str Bonus', NULL),
('GD_GLORYWOUNDS', 'Glorious Wounds', NULL, 'Passive', 'เป้าหมาย : สมาชิก Guild ในระยะ  5*5 รอบๆ Guild Master\nสมาชิก Guild ในระยะ  5*5 ช่อง รอบๆ Guild Master จะได้รับ +5 Vit Bonus', NULL),
('GD_SOULCOLD', 'Cold Heart', NULL, 'Passive', 'เป้าหมาย : สมาชิก Guild ในระยะ  5*5 รอบๆ Guild Master\nสมาชิก Guild ในระยะ  5*5 ช่อง รอบๆ Guild Master จะได้รับ +5 Agi Bonus', NULL),
('GD_HAWKEYES', 'Sharp Gaze', NULL, 'Passive', 'เป้าหมาย : สมาชิก Guild ในระยะ  5*5 รอบๆ Guild Master\nสมาชิก Guild ในระยะ  5*5 ช่อง รอบๆ Guild Master จะได้รับ +5 Dex Bonus', NULL),
('GD_BATTLEORDER', 'Battle Command', NULL, 'Support', 'เป้าหมาย : สมาชิก Guild ในระยะ  5*5 รอบๆ Guild Master\nSkill นี้ใช้ได้เฉพาะเวลา Guild war เท่านั้น\nสมาชิกในระยะสายตาของ Guild Master จะได้รับ +5 Str,Int,Dex Bonus Skill นี้มีระยะเวลา 1 นาที และใช้เวลา 5 นาทีในการ Cooldown', NULL),
('GD_REGENERATION', 'Regeneration', 3, 'Support', 'เป้าหมาย : สมาชิก Guild ในระยะสายตา\nSkill นี้ใช้ได้เฉพาะเวลา Guild war เท่านั้น\nGuild Master เพิ่มอัตราฟื้นคืน HP/SP ให้ สมาชิก Guild ในระยะสายตา. Skill นี้ใช้เวลา 5 นาทีในการ Cooldown', '[Lv 1] : อัตราฟื้นคืน HP  * 2\n[Lv 2] : อัตราฟื้นคืน HP/SP * 2\n[Lv 3] : อัตราฟื้นคืน HP/SP * 3'),
('GD_RESTORE', 'Restoration', NULL, 'Support', 'เป้าหมาย : สมาชิก Guild ในระยะสายตา\nSkill นี้ใช้ได้เฉพาะเวลา Guild war เท่านั้น\nGuild Master เพิ่มพลัง 90% ของ MAX HP/SP  ให้ สมาชิก Guild ในระยะสายตา Skill นี้ใช้เวลา 5 นาทีในการ Cooldown', NULL),
('GD_EMERGENCYCALL', 'Urgent Call', NULL, 'Support', 'เป้าหมาย : Every Guildsman\nSkill นี้ใช้ได้เฉพาะเวลา Guild war เท่านั้น\nGuild Master เรียกสมาชิกทุกคนที่อยู่ใน Game มาอยู่รอบๆ Guild Master. Skill นี้ใช้เวลา 5 นาทีในการ Cooldown', NULL),
('GD_DEVELOPMENT', 'Permanent Development', NULL, 'Passive', 'เมื่อทำการ Upgrade Agit ผลของ Skill นี้ จะมี โอกาส 50 % ที่จะเพิ่ม อีก 1 Point ให้กับ Tech\nสรุปผลคือ เมื่อมี Skill นี้ เมื่อ Upgrade Agit อาจจะได้ +1 หรือ +2', NULL),
('GD_ITEMEMERGENCYCALL', '', NULL, NULL, NULL, NULL),
('MH_SUMMON_LEGION', 'Call Legion', 5, NULL, 'เรียกฝูงแมลงออกมาโจมตีเป้าหมาย.\nskill level ที่สูงขึ้น, จะสามารถเรียกฝูงแมลงที่แข๊งแกร่งขึ้นได้', '[Lv 1] Summon Hornet / ระยะเวลา : 20 วินาที\n[Lv 2] Summon Giant Hornet / ระยะเวลา : 30 วินาที\n[Lv 3] Summon Giant Hornet / ระยะเวลา : 40 วินาที\n[Lv 4] Summon Luciola Versper / ระยะเวลา : 50 วินาที\n[Lv 5] Summon Luciola Versper / ระยะเวลา : 60 วินาที'),
('MH_NEEDLE_OF_PARALYZE', 'Needle Of Paralyze', 5, NULL, 'เปลี่ยนสถานะเป้าหมายให้ติดสถานะผิดปกติ อัมพาต (Paralysis)\nด้วยความเสียหายจากธาตุพิษ ด้วยพลังที่รุนแรงจาก Paralysis status\nศัตรูที่ติดสถานะนี้จะโดนตรึงให้อยู่กับที่ และระยะเวลาการร่ายเวทย์จะเพิ่มขึ้น อีกทั้งพลังป้องกันยังลดลงอีกด้วย\nระยะเวลาของ Paralyze ลดลงได้ด้วยจากค่า VIT และ LUK ของเป้าหมาย', '[Lv 1] โจมตีทางกายภาพ 800% / โอกาสติดสถานะ Paralysis 45%\n[Lv 2] โจมตีทางกายภาพ 900% / โอกาสติดสถานะ Paralysis 50%\n[Lv 3] โจมตีทางกายภาพ 1000% / โอกาสติดสถานะ Paralysis 55%\n[Lv 4] โจมตีทางกายภาพ 1100% / โอกาสติดสถานะ Paralysis 60%\n[Lv 5] โจมตีทางกายภาพ 1200% / โอกาสติดสถานะ Paralysis 65%'),
('MH_POISON_MIST', 'Poisonous Mist', 5, NULL, 'โปรยผงพิษลงบนพื้น ใครก็ตามที่เข้ามายังพื้นที่\nจะได้รับความเสียหายจากธาตุพิษอย่างต่อเนื่องด้วยความมืด ไม่สามารถใช้ได้มากกว่า 1 ครั้งในพื้นที่เดียวกัน', '[Lv 1] โอกาสติดสถานะ 20 % / ระยะเวลา : 12 วินาที\n[Lv 2] โอกาสติดสถานะ 30 % / ระยะเวลา : 14 วินาที\n[Lv 3] โอกาสติดสถานะ 40 % / ระยะเวลา : 16 วินาที\n[Lv 4] โอกาสติดสถานะ 50 % / ระยะเวลา : 18 วินาที\n[Lv 5] โอกาสติดสถานะ 60% / ระยะเวลา : 20 วินาที'),
('MH_PAIN_KILLER', 'Pain Killer', 5, NULL, 'แพร่พิษเข้าไปยังตัวของเป้าหมาย\nลดค่าความเีสียหายลง แต่ความเร็วในการโจมตีจะลดลงเช่นกัน', '[Lv 1] ระยะเวลา : 20 วินาที\n[Lv 2] ระยะเวลา : 30 วินาที\n[Lv 3] ระยะเวลา : 40 วินาที\n[Lv 4] ระยะเวลา : 50 วินาที\n[Lv 5] ระยะเวลา : 60 วินาที'),
('MH_LIGHT_OF_REGENE', 'Regene Light', 5, NULL, 'Homunculus ร่ายสกิล Light of Rejuvenation ให้แก่ผู้เล่น หากผู้เล่นตายในขณะที่ผลของสกิลยังแสดงผลอยู่,\nHomunculus จะเสียสละตัวเอง เพื่อชุบชีวิตเจ้าของโดยอัตโนมัติ, ค่าความสนิทสนมของ Homunculus จะลดลงเมื่อมีการใช้งานสกิลนี้\nหากผู้เล่นมี item ชุบชีวิตอื่นๆ อยู่ในตัว, ผลของ item นั้นจะถูกใช้งานก่อนสกิลนี้\nเลเวลที่สูงขึ้น, HP ที่ฟื้นคืนหลังจากที่ชุบชีวิตจะมากขึ้นตามไปด้วย', '[Lv 1] ระยะเวลา : 360 วินาที\n[Lv 2] ระยะเวลา : 420 วินาที\n[Lv 3] ระยะเวลา : 480 วินาที\n[Lv 4] ระยะเวลา : 540 วินาที\n[Lv 5] ระยะเวลา : 600 วินาที'),
('MH_OVERED_BOOST', 'Over Boost', 5, NULL, 'flee rate และ attack speed ของ Homunculus และผู้ใช้จะถูกบังคับให้เปลี่ยนไปตามเลเวลของสกิล,\nแต่พลังป้องกันจะลดลงครึ่งนึง ไม่มีผลกระทบกับ flee rate และ attack speed ที่เปลี่ยนไป\nเป้าหมายที่ได้รับผลของสกิล ค่าความหิวของ Homunculus  และ SP ของผู้ใช้\nจะลดลงครึ่งหนึ่ง', '[Lv 1] Flee 340 / ASPD 181\n[Lv 2] Flee 380 / ASPD 183\n[Lv 3] Flee 420 / ASPD 185\n[Lv 4] Flee 460 / ASPD 187\n[Lv 5] Flee 500 / ASPD 189'),
('MH_ERASER_CUTTER', 'Eraser Cutter', 5, NULL, 'สร้าง Sonic Blade ที่สามารถโจมตีศัตรูระยะไกล ได้หลายเป้าหมาย\nขึ้นอยู่กับ skill level, สามารถสร้างความเสียหายเป็นแบบ Wind Property หรือ ความเสียหายแบบ Neutral Property ได้', '[Lv 1] Atk 600%   / Wind Property Magic Damage\n[Lv 2] Atk 1000% / Neutral Property Magic Damage\n[Lv 3] Atk 800%  / Wind Property Magic Damage\n[Lv 4] Atk 1200% / Neutral Property Magic Damage\n[Lv 5] Atk 1000% / Wind Property MagicDamage'),
('MH_XENO_SLASHER', 'Xeno Slasher', 5, NULL, 'ใช้งาน Eraser Cutter เพื่อการโจมตีที่หลากหลายขึ้น\nโดยธาตุของ Eraser Cutter, จะขึ้นอยู๋กับ skill level ของมัน\nเป้าหมายทั้งหมดที่ได้รับความเสียหาย มีโอกาสที่จะติดสถานะผิดปกติของ [bleeding]', '[Lv 1] Atk 500% / สร้างความเสียหายด้วยเวทย์มนตร์ธาตุลม / 5 x 5 ช่อง\n[Lv 2] Atk 700% / สร้างความเสียหายด้วยเวทย์มนตร์ไร้ธาตุ / 5 x 5 ช่อง\n[Lv 3] Atk 600% / สร้างความเสียหายด้วยเวทย์มนตร์ธาตุลม / 7 x 7 ช่อง\n[Lv 4] Atk 900% / สร้างความเสียหายด้วยเวทย์มนตร์ไร้ธาตุ / 7 x 7 ช่อง\n[Lv 5] Atk 700% / สร้างความเสียหายด้วยเวทย์มนตร์ธาตุลม / 9 x 9 ช่อง'),
('MH_SILENT_BREEZE', 'Silent Breeze', 5, NULL, 'ทำให้เป้าหมายฟื้นฟูค่า HP ขึ้นจำนวนหนึ่ง แต่ยังร่าย\nsilent effect ไปยังเป้าหมายเพื่อป้องกันสกิลอื่นๆ เมื่อใช้สกิลนี้ยังยกเลิกผลจากสกิล\nMandragora Howling, Deep Sleep, Harmonize, Charm, Sleep, Confusion, Hallucination และผล จากสกิลอื่นๆ', '[Lv 1] ระยะเวลา : 9 วินาที\n[Lv 2] ระยะเวลา : 12 วินาที\n[Lv 3] ระยะเวลา : 15 วินาที\n[Lv 4] ระยะเวลา : 18 วินาที\n[Lv 5] ระยะเวลา : 21 วินาที'),
('MH_STAHL_HORN', 'Stahl Horn : Steel Horn', 5, NULL, 'Charge และ โจมตีไปยังเป้าหมาย\nทำให้เป้าหมายกระเ้ด็นออกไป 3 ช่อง และส่งผลให้เป้่าหมายติดสถานะ stun', '[Lv 1] Atk 600% / ภายในระยะ : 5 ช่อง / โอกาสติดสถานะ Stun 20%\n[Lv 2] Atk 700% / ภายในระยะ : 6 ช่อง / โอกาสติดสถานะ Stun 24%\n[Lv 3] Atk 800% / ภายในระยะ : 7 ช่อง / โอกาสติดสถานะ Stun 28%\n[Lv 4] Atk 900% / ภายในระยะ : 8 ช่อง / โอกาสติดสถานะ Stun 32%\n[Lv 5] Atk 1000% / ภายในระยะ : 9 ช่อง / โอกาสติดสถานะ Stun 36%'),
('MH_GOLDENE_FERSE', 'Goldene Ferse : Golden Heel', 5, NULL, 'เพิ่ม free rate และ ความเร็วในการโจมตีให้แก่ Homunculus การโจมตี\nจะสร้างความเสียหายด้วยค่าที่คงที่ สามารถโจมตีเป็นธาตุ Holy ได้ เมื่อมีการใช้งาน [Stahl Horn]\nในขณะที่ผลของสกิลยังคงอยู่ สกิลนี้ไม่สามารถใช้ร่วมกันกับ [Angriff Modus]', '[Lv 1] Flee Rate + 20  / เพิ่ม ASPD 10% / มีโอกาสโจมตีด้วยธาตุ Holy 4% / ระยะเวลา : 30 วินาที\n[Lv 2] Flee Rate + 30  / เพิ่ม ASPD 14% / มีโอกาสโจมตีด้วยธาตุ Holy 6% / ระยะเวลา : 45 วินาที\n[Lv 3] Flee Rate + 40  / เพิ่ม ASPD 18% / มีโอกาสโจมตีด้วยธาตุ Holy 8% / ระยะเวลา : 60 วินาที\n[Lv 4] Flee Rate + 50  / เพิ่ม ASPD 22% / มีโอกาสโจมตีด้วยธาตุ Holy 10% / ระยะเวลา : 75 วินาที\n[Lv 5] Flee Rate + 60  / เพิ่ม ASPD 26% / มีโอกาสโจมตีด้วยธาตุ Holy 12% / ระยะเวลา : 90 วินาที'),
('MH_STEINWAND', 'Steinwand : Stone Wall', 5, NULL, 'ร่าย [Safety Wall] ภายใต้เท้าของ Homunculus และผู้เล่น', '[Lv 1] ระยะเวลา : 30 วินาที\n[Lv 2] ระยะเวลา : 45 วินาที\n[Lv 3] ระยะเวลา : 60 วินาที\n[Lv 4] ระยะเวลา : 75 วินาที\n[Lv 5] ระยะเวลา : 90 วินาที'),
('MH_HEILIGE_STANGE', 'Heilige Stange : Holy Spear', 5, NULL, 'โจมตีด้วย Holy Property Magic Damage to ไปยังเป้าหมาย และศัตรูรอบๆ', '[Lv 1] Atk 750%  / Holy Property Damage / 3 x 3 ช่อง\n[Lv 2] Atk 1000% / Holy Property Damage / 3 x 3 ช่อง\n[Lv 3] Atk 1250% / Holy Property Damage / 3 x 3 ช่อง\n[Lv 4] Atk 1500% / Holy Property Damage / 3 x 3 ช่อง\n[Lv 5] Atk 1750% / Holy Property Damage / 5 x 5 ช่อง'),
('MH_ANGRIFFS_MODUS', 'Angriff Modus : Battle Mode', 5, NULL, 'เพิ่มพลังโจมตี Homunculus ในระยะเวลาที่กำหนด แต่ในทางกลับกัน\nลด defense และ flee rate ลงด้วย, สกิลนี้ไม่สามารถใช้ร่วมกันกับ [Goldene Ferse]', '[Lv 1] Atk +70  / Def -50  / Flee -60 / ระยะเวลา : 30 วินาที\n[Lv 2] Atk +90  / Def -70 / Flee -80 / ระยะเวลา : 45 วินาที\n[Lv 3] Atk +110 / Def -90 / Flee - 100 / ระยะเวลา : 60 วินาที\n[Lv 4] Atk +130 / Def -110 / Flee -120 / ระยะเวลา : 75 วินาที\n[Lv 5] Atk +150 / Def -130 / Flee -140 / ระยะเวลา : 90 วินาที'),
('MH_STYLE_CHANGE', 'Style Change', 1, NULL, 'เปลี่ยนรูปแบบ Homunculus จากรูปแบบ Fighter ไปยังรูปแบบ Grappler หรือ vice versa\nในรูปแบบการโจมตี Fighter, มันจะรวบรวมพลังงาน spirit spheres ในอัตราที่คงที่ ในขณะที่โจมตี หรือ รับความเสียหาย', NULL),
('MH_SONIC_CRAW', 'Sonic Claw', 5, NULL, 'สามารถใช้ได้เฉพาะ Fighter style ทำการโจมตีอย่างรวดเร็วด้วย Sonic Claw ไปยังเป้าหมาย\nจำนวนของการโจมตีขึ้นอยู่กับจำนวน spirit spheres, หากไม่มี spirit spheres การใช้งานสกิลจะล้มเหลว', '[Lv 1] พลังโจมตี 40%\n[Lv 2] พลังโจมตี 80%\n[Lv 3] พลังโจมตี 120%\n[Lv 4] พลังโจมตี 160%\n[Lv 5] พลังโจมตี 200%'),
('MH_SILVERVEIN_RUSH', 'Silvervein Rush', 5, NULL, 'สามารถใช้เมื่ออยู่ในสถานะ Fighter style เท่านั้น ใช้แบบโจมตีต่อเนื่องจากสกิล Sonic Claw\nต้องการ 1 spirit spheres เพื่อใช้งาน , ส่งผลให้เป้าหมายติดสถานะ stun state พร้อมทั้งยัง\nสร้างความเสียหายให้แก่เป้าหมาย', '[Lv 1] พลังโจมตี 150% / Stun Rate 25%\n[Lv 2] พลังโจมตี 300% / Stun Rate 30%\n[Lv 3] พลังโจมตี 450% / Stun Rate 35%\n[Lv 4] พลังโจมตี 600% / Stun Rate 40%\n[Lv 5] พลังโจมตี 750% / Stun Rate 45%'),
('MH_MIDNIGHT_FRENZY', 'Midnight Frenzy', 5, NULL, 'สามารถใช้เมื่ออยู่ในสถานะ Fighter style เท่านั้น ใช้แบบโจมตีต่อเนื่องจากสกิล Silvervein Rush\nต้องการ 2 spirit spheres เพื่อใช้งาน , ส่งผลให้เป้าหมายติดสถานะ Horror state\nพร้อมทั้งยังสร้างความเสียหายให้แก่เป้าหมาย เป้าหมายตกอยู่ในสถานะ Horror state ขึ้นอยู่กับ\nจำนวนของ spirit spheres ที่ใช้ สามารถใช้สกิล [Sonic Claw] ได้ต่อหลังจากใช้สกิลนี้', '[Lv 1] พลังโจมตี 300%\n[Lv 2] พลังโจมตี 600%\n[Lv 3] พลังโจมตี 900%\n[Lv 4] พลังโจมตี 1200%\n[Lv 5] พลังโจมตี 1500%'),
('MH_TINDER_BREAKER', 'Tinder Breaker', 5, NULL, 'จับเป้าหมายให้อยู่กับที่โดย ทั้งเป้าหมาย และ\nHomunculus จะไม่สามารถเคลื่อนไหวได้หลังจากใช้สกิล และค่า flee rate จะลดลงเหลือ 0 ต้องการ 1 spirit sphere\nหลังจากใช้ พลังโจมตี และการตรึงเป้าหมายขึ้นอยู่กับ STR ของ Homunculus', '[Lv 1] พลังโจมตี 100%\n[Lv 2] พลังโจมตี 200%\n[Lv 3] พลังโจมตี 300%\n[Lv 4] พลังโจมตี 400%\n[Lv 5] พลังโจมตี 500%'),
('MH_CBC', 'C.B.C (Continual Break Combo)', 5, NULL, 'ใช้ได้ต่อเนื่องจากสกิล Tinder Break เท่านั้น ต้องการ 1 spirit spheres ในการใช้\nสร้างความเสียหายและลด SP ลงอย่างต่อเนื่อง ถ้าเป้าหมายเป็น monster, เพิ่ม\nค่าความความเสียหายแทนการลด SP , ไม่สามารถเคลื่อนไหวได้ และค่า Free ลดลงเหลือ 0 เมื่อผลของสกิลนี้ยังใช้งาน เหมือนกับ Tinder Break\nระยะเวลาของสกิลเพิ่มขึ้นตาม STR ของ Homunculus', '[Lv 1] สร้างความเสียหาย 400 Damage\n[Lv 2] สร้างความเสียหาย 800 Damage\n[Lv 3] สร้างความเสียหาย 1200 Damage\n[Lv 4] สร้างความเสียหาย 1600 Damage\n[Lv 5] สร้างความเสียหาย 2000 Damage'),
('MH_EQC', 'E.Q.C (Eternal Quick Combo)', 5, NULL, 'สามารถใ้ช้ได้ต่อเมื่อ ใช้สกิล C.B.C. ต้องการ 2 spirit spheres เพื่อใช้งาน\nโจมตีเป้าหมาย และทำให้เป้าหมายติดสถานะ stun state 100% และยังทำให้ลดค่า MHP ลงด้วย, พลังโจมตี\nและพลังป้องกัน Homunculus เป็นอิสระจากเป้าหมายและสามารถเคลื่อนที่ หลังจากใช้สกิล\nอีกทั้งกลับไปอยู่ในสถานะปกติ ไม่สามารถใช้งานกับ Boss Monsters ได้', '[Lv 1] MHP ลดลง 2 % / Atk, Def ลดลง 5 %\n[Lv 2] MHP ลดลง 4 % / Atk, Def ลดลง 10 %\n[Lv 3] MHP ลดลง 6 % / Atk, Def ลดลง 15 %\n[Lv 4] MHP ลดลง 8 % / Atk, Def ลดลง 20 %\n[Lv 5] MHP ลดลง 10 % / Atk, Def ลดลง 25 %'),
('MH_MAGMA_FLOW', 'Magma Flow', 5, NULL, 'Homunculus ปล่อย magma ออกมาทุกครั้งที่ได้รับความเสียหาย\nมีผลให้สร้างความเสียหายด้วย Fire Property ไปยังเป้าหมายโดยรอบ', '[Lv 1] พลังโจมตี 100% /  ภายในระยะ : 3 x 3  / มีโอกาสออกสกิล 3 %\n[Lv 2] พลังโจมตี 200% /  ภายในระยะ : 3 x 3  / มีโอกาสออกสกิล 6 %\n[Lv 3] พลังโจมตี 300% /  ภายในระยะ : 3 x 3  / มีโอกาสออกสกิล 9 %\n[Lv 4] พลังโจมตี 400% /  ภายในระยะ : 5 x 5  / มีโอกาสออกสกิล 12 %\n[Lv 5] พลังโจมตี 500% /  ภายในระยะ : 5 x 5  / มีโอกาสออกสกิล 15 %'),
('MH_GRANITIC_ARMOR', 'Granitic Armor', 5, NULL, 'สร้างเกราะป้องกันรอบตัวรอบตัวของ Homunculus ขึ้นชั่วคราว\nทำให้พลังป้องกันของ Homunculus และเป้าหมายเพิ่มขึ้น, HP บางส่วนจะถูกใช้งานเมื่อหมดผลของสกิล\nระยะเวลาที่สกิลแสดงผล 60 วินาที', '[Lv 1] ลดค่าความเสียหายลง 2% / HP ลดลง 6% เมื่อหมดผลของสกิล\n[Lv 2] ลดค่าความเสียหายลง 4% / HP ลดลง 12% เมื่อหมดผลของสกิล\n[Lv 3] ลดค่าความเสียหายลง 6% / HP ลดลง 18% เมื่อหมดผลของสกิล\n[Lv 4] ลดค่าความเสียหายลง 8% / HP ลดลง 24% เมื่อหมดผลของสกิล\n[Lv 5] ลดค่าความเสียหายลง 10% / HP ลดลง 30% เมื่อหมดผลของสกิล'),
('MH_LAVA_SLIDE', 'Lava Slide', 5, NULL, 'ปลดปล่อย lava รอบๆพื้นที่ และสร้างความเสียหายแก่เป้าหมายโดยรอบในระยะของสกิล\nเป้าหมายทั้งหมดที่โดนผลของสกิลจะติดสถานะ ignite state ตามระดับเลเวล', '[Lv 1] Ignite Rate 10%\n[Lv 2] Ignite Rate 20%\n[Lv 3] Ignite Rate 30%\n[Lv 4] Ignite Rate 40%\n[Lv 5] Ignite Rate 50%'),
('MH_PYROCLASTIC', 'Pyroclastic', 5, NULL, 'Homunculus เปลี่ยนธาตุ ของตัวเอง และอาวุธของผู้ใช้\nเป็นการโจมตีด้วย Fire Property และเพิ่มพลังโจมตีขึ้นด้วย และยังมีโอกาสร่ายสกิล\n[Hammerfall] อัตโนมัติ เมื่อยังแสดงผลของสกิล อาวุธจะถูกทำลายเมื่อหมดผลของสกิล\nสกิลยิ่งเลเวลสูง, ผลของการร่ายสกิล Hammerfall ยิ่งสูงขึ้นตามไปด้วย', '[Lv 1] ระยะเวลา : 60 วินาที\n[Lv 2] ระยะเวลา : 90 วินาที\n[Lv 3] ระยะเวลา : 120 วินาที\n[Lv 4] ระยะเวลา : 150 วินาที\n[Lv 5] ระยะเวลา : 180 วินาที'),
('MH_VOLCANIC_ASH', 'Volcanic Ash', 5, NULL, 'ปลดปล่อยผงขี้เถ้าจากภูเขาำไฟ และสร้างความเสียหายให้แก่เป้าหมายโดยรอบ\nเป้าหมายโดยรอบติดสถานะ volcanic ash state ค่าความแม่นยำของเป้าหมาย\nลดลง และ มีโอกาสทำให้การร่ายสกิลถูกยกเลิก 50% ค่าความเสียหาย คิดเป็นการโจมตีจากธาตุ Fire Property\nถ้าเป้าหมายเป็น plant monster, พลังป้องกันจะลดลง 50%, ถ้าเป้าหมายเป็น water property, พลังโจมตี และ flee rate ลดลง 50%\nระยะเวลาของสกิลเพิ่มขึ้น ขึ้นอยู่กับเลเวลของสกิล สกิลนี้สามารถใ้ช้ได้เพียง 3 ครั้ง ในพื้นที่เท่านั้น', '[Lv 1] ระยะเวลา : 8 วินาท\n[Lv 2] ระยะเวลา : 16 วินาท\n[Lv 3] ระยะเวลา : 24 วินาท\n[Lv 4] ระยะเวลา : 32 วินาท\n[Lv 5] ระยะเวลา : 40 วินาท'),
('KO_YAMIKUMO', 'Shadow Hiding', 1, NULL, 'Requirement : Shadow Slash 5\nซ่อนตัวด้วย Skill นี้\nSkill นี้ทำงานเหมือนกับ  Hiding ของ Rogue\nผลของSkill จะถูกยกเลิก หาก SP ไม่เพียงพอ\nเหรือเมื่อกดใช้งาน Skill อีกครั้ง\nSP จะลดลงอย่างต่อเนื่องขณะที่ Skill นี้ทำงานอยู่', NULL),
('KO_RIGHT', 'Righthand Mastery', 5, NULL, 'คืนค่าพลังโจมตีของมือขวาที่เสียไป\nเมื่อสวมใส่อาวุธ\nทั้งสองข้าง\nพลังโจมตีเพิ่มขึ้น เมื่อถึง Lv. 4 และ Lv.5\nเมื่อเปรียบเทียบกับตอนใส่อาวุธมือเดียว', '[LV 1] Atk 80%\n[LV 2] Atk 90%\n[LV 3] Atk 100%\n[LV 4] Atk 110%\n[LV 5] Atk 120%'),
('KO_LEFT', 'Lefthand Mastery', 5, NULL, 'คืนค่าพลังโจมตีของมือซ้ายที่เสียไป\nเมื่อสวมใส่อาวุธ\nทั้งสองข้าง', '[LV 1] Atk 60%\n[LV 2] Atk 70%\n[LV 3] Atk 80%\n[LV 4] Atk 90%\n[LV 5] Atk 100%'),
('KO_JYUMONJIKIRI', 'Cross Slash ', 5, NULL, 'Requirement : Shadow Hiding 1\nการผสานกันระหว่าง Skill ของ Kagerou และ Oboro\nศัตรูที่ได้รับ Damage จาก Cross Slash\nจะตกอยู่ในสถานะ <cross wound> เป็นเวลา 3 วินาที\nและเมื่อทำการโจมตีด้วย Cross Slash ใส่ศัตรูที่ติดสถานะ cross wound\nจะทำให้ได้รับความเสียหายรุนแรงมากขึ้น\nความรุนแรง Skill มากขึ้นตาม Base Level ของผู้ใช้ ,', '[LV 1] Atk 150% / ระยะไกล 3 ช่อง\n[LV 2] Atk 300% / ระยะไกล 4 ช่อง\n[LV 3] Atk 450% / ระยะไกล 5 ช่อง\n[LV 4] Atk 600% / ระยะไกล 6 ช่อง\n[LV 5] Atk 750% / ระยะไกล 7 ช่อง'),
('KO_SETSUDAN', 'Soul Cutter', 5, NULL, 'Requirement : Cross 2\nโจมตีเป้าหมาย ถ้าเป้าหมายที่โดนโจมตี มีผลของ Soul Linker Spirit อยู่ จะได้รับความเสียหาย\nรุนแรงขึ้นและผล Soul Linker Spirit จะถูกยกเลิก\nความรุนแรงเพิ่มขึ้นตาม Skill Level', '[LV 1] Atk 100%\n[LV 2] Atk 200%\n[LV 3] Atk 300%\n[LV 4] Atk 400%\n[LV 5] Atk 500%'),
('KO_BAKURETSU', 'Kunai Explosion ', 5, NULL, 'Skill ที่ต้องการ : Throw Kunai 5\nปา Explosive Kunai และสร้างความเสียหายให้ศัตรูทุกตัวที่อยู่ในพื้นที่ของ Skill\nใช้ 1 Explosive Kunai\nโดยจะใช้ Explosive Kunai ที่อยู่ใน inventory ของผู้ใช้เท่านั้น\n(Explosive Kunai ไม่สามารถติดตั้งกับตัวผู้ใช้เหมือน Kunai ทั่วไป)', '[LV 1] ระยะไกล 7 ช่อง / AOE 3 x 3 ช่อง\n[LV 2] ระยะไกล 8 ช่อง / AOE 3 x 3 ช่อง\n[LV 3] ระยะไกล 9 ช่อง / AOE 3 x 3 ช่อง\n[LV 4] ระยะไกล 10 ช่อง / AOE 3 x 3 ช่อง\n[LV 5] ระยะไกล 11 ช่อง / AOE 3 x 3 ช่อง'),
('KO_HAPPOKUNAI', 'Kunai Splash', 5, NULL, 'Requirement : Kunai Explosion 1\nสร้างความเสียหายด้วยคุไนต่อศัตรูทุกตัวในขอบเขตที่กำหนดรอบ ๆ ตัวผู้ใช้สกิล\nเมื่อใช้สกิล สูญเสียคุไนที่ติดตั้งอยู่ 2 อัน', '[LV 1]  ขอบเขต 9 x 9 ช่อง\n[LV 2]  ขอบเขต 9 x 9 ช่อง\n[LV 3]  ขอบเขต 9 x 9 ช่อง\n[LV 4]  ขอบเขต 9 x 9 ช่อง\n[LV 5]  ขอบเขต 11 x 11 ช่อง'),
('KO_MUCHANAGE', 'Rapid Throw', 10, NULL, 'Skill ที่ต้องการ : Makibishi 3\nเวอร์ชั่นที่ดีกว่าเดิมของ skill ninja [Throw Coins]\nโดยขว้างเงินจำนวน 100,000 Zeny\nมีโอกาสสร้างความเสียหายแบบสุ่ม\nจากระยะไกล ใส่เป้าหมายและศัตรูโดยรอบ\nโดยไม่สนใจทุกการป้องกันของศัตรู\nสามารถร่ายลงพื้นได้\nสร้างความเสียหายเพียงครึ่งนึงแก่มอนสเตอร์ประเภท Boss.', '[LV 1] ใช้ 10,000 zeny\n5,000 ~ 10,000 สุ่มค่าความเสียหาย\n[LV 2] ใช้ 20,000 zeny\n10,000 ~ 20,000 สุ่มค่าความเสียหาย\n[LV 3] ใช้ 30,000 zeny\n15,000 ~ 30,000 สุ่มค่าความเสียหาย\n[LV 4] ใช้ 40,000 zeny\n20,000 ~ 40,000 สุ่มค่าความเสียหาย\n[LV 5] ใช้ 50,000 zeny\n25,000 ~ 50,000 สุ่มค่าความเสียหาย\n[LV 6] ใช้ 60,000 zeny\n30,000 ~ 60,000 สุ่มค่าความเสียหาย\n[LV 7] ใช้ 70,000 zeny\n35,000 ~ 70,000 สุ่มค่าความเสียหาย\n[LV 8] ใช้ 80,000 zeny\n40,000 ~ 80,000 สุ่มค่าความเสียหาย\n[LV 9] ใช้ 90,000 zeny\n45,000 ~ 90,000 สุ่มค่าความเสียหาย\n[Lv 10] ใช้ 100,000 zeny\n50,000 ~ 100,000 สุ่มค่าความเสียหาย'),
('KO_HUUMARANKA', 'Swirling Petal', 5, NULL, 'Requirement : Throw Huuma Shuriken 5\nขว้าง Shuriken ใส่เป้าหมาย\nและสร้างความเสียหายแก่ศัตรูทั้งหมดในระยะ 7 x 7 ช่อง\nยิ่งผู้ร่ายมีเลเวลของ Skill [Ninja skill: Throw Huuma Shuriken]\nและ Str สูงเท่าไหร่ความเสียหายที่ทำได้จะสูงขึ้น\nจะยิ่งสูงมากขึ้น\nต้องถืออาวุธประเภท Huuma Shuriken เท่านั้น', '[LV 1] Atk 150 % / ระยะไกล 9 ช่อง\n[LV 2] Atk 300 % / ระยะไกล 10 ช่อง\n[LV 3] Atk 450 % / ระยะไกล 11 ช่อง\n[LV 4] Atk 600 % / ระยะไกล 12 ช่อง\n[LV 5] Atk 750 % / ระยะไกล 13 ช่อง'),
('KO_MAKIBISHI', 'Makibishi', 5, NULL, 'Requirement : Throw Coins 1\nหว่านกับดักเหล็กอันแหลมคมเพื่อให้ศัตรูมาเหยียบ\nศัตรูที่เหยียบจะมีโอกาสติดสถานะ Immobilize หรือ Stun ชั่วขณะหนึ่ง\nหากเลเวล Skill สูงก็จะยิ่งสามารถ\nหว่านกับดักไว้บนพื้นได้มากขึ้น', '[LV 1] สามารถใช้ 3 Makibishi/Caltrop\n[LV 2] สามารถใช้ 4 Makibishi/Caltrop\n[LV 3] สามารถใช้ 5 Makibishi/Caltrop\n[LV 4] สามารถใช้ 6 Makibishi/Caltrop\n[LV 5] สามารถใช้ 7 Makibishi/Caltrop'),
('KO_MEIKYOUSISUI', 'Pure Soul ', 5, NULL, 'Requirement : Ninja Mastery 10\nตั้งสมาธิเป็นเวลา 10วินาที\nเพื่อฟื้นฟู HPและSPอย่างรวดเร็ว\nคุณจะไม่สามารถเคลื่อนไหวได้ระหว่างใช้Skillนี้\nและมีโอกาสที่จะไม่ได้รับความเสียหายที่โจมตีเข้ามา\nในขณะที่อยู่ในสถานะ Pure Soul', '[LV 1] ฟื้นฟู 2% HP/1% SP ต่อวินาที\n[LV 2] ฟื้นฟู 4% HP/2% SP ต่อวินาที\n[LV 3] ฟื้นฟู 6% HP/3% SP ต่อวินาที\n[LV 4] ฟื้นฟู 8% HP/4% SP ต่อวินาที\n[LV 5] ฟื้นฟู 10% HP/5% SP ต่อวินาที'),
('KO_ZANZOU', 'Illusion - Shadow', 5, NULL, 'Requirement : Cicada Skin Shed 1\nสร้างร่างจำแลงในรูปร่างของ Shinobi.\nร่างจำแลงจะมี HP เป็นของตัวเอง หาก HP เหลือ 0 ร่างจำแลงจะหายไป\nHP ของร่างจำแลงจะเพิ่มขึ้นตามค่า MSP ของผู้ใช้', '[LV 1] สร้างร่างจำแลง HP 6000 +MSP ของผู้ใช้\n[LV 2] สร้างร่างจำแลง HP 9000 +MSP ของผู้ใช้\n[LV 3] สร้างร่างจำแลง HP 12000 +MSP ของผู้ใช้\n[LV 4] สร้างร่างจำแลง HP 15000 +MSP ของผู้ใช้\n[LV 5] สร้างร่างจำแลง HP 18000 +MSP ของผู้ใช้'),
('KO_KYOUGAKU', 'Illusion - Shock', 5, NULL, 'Requirement : Illusion - Bewitch 2\nหลอนประสาทของเป้าหมาย\nค่า all stats ของเป้าหมายจะลดลงและเปลี่ยนเป้าหมายให้กลายเป็น\nมอนสเตอร์.\nเป้าหมายที่อยู่ภายใต้ผลของ Skill นี้จะไม่สามารถเปลี่ยนหรือ\nถอด item สวมใส่ได้\nSkill นี้ ไม่แสดงผลกับพันธมิตรและมอนสเตอร์\nสามารถใช้ได้ใน WoE เท่านั้น', '[LV 1] Stats ทั้งหมดลดลง 2 ~ 3\n[LV 2] Stats ทั้งหมดลดลง 4 ~ 6\n[LV 3] Stats ทั้งหมดลดลง 6 ~ 9\n[LV 4] Stats ทั้งหมดลดลง 8 ~ 12\n[LV 5] Stats ทั้งหมดลดลง 10 ~ 15'),
('KO_JYUSATSU', 'Illusion - Death', 5, NULL, 'Requirement : Illusion - Shock 3\nหลอนประสาทของเป้าหมาย\nค่า HP ของเป้าหมายจะลดลง\nและทำให้เป้าหมายอยู่ในสถานะ curse\nและมีโอกาสต่ำที่จะทำให้เป้าหมายติดสถานะ [Coma]\nโอกาสติด Coma มีผลต่อผู้เล่นที่เลเวลต่ำกว่าหรือเท่ากับเลเวลของผู้ใช้เท่านั้น\nและไม่มีผลกับมอนสเตอร์', NULL),
('KO_GENWAKU', 'Illusion - Bewitch', 5, NULL, 'Requirement : Cicada Skin Shed 1\nมีโอกาสสลับตำแหน่งระหว่างเป้าหมายกับผู้ใช้\nและมีโอกาสที่จะทำให้ผู้ใช้หรือเป้าหมายติดสถานะ [Confusion]', NULL),
('KO_IZAYOI', '16th Night ', 5, NULL, 'Requirement : Ninja Mastery 5\nเมื่อใช้ skill นี้ เวลาร่ายแบบคงที่ของ skill ninja\nจะหายไปทั้งหมด\nเวลาร่ายแบบผันแปรจะลดลงครึ่งนึง\nและเพิ่ม MATK ของผู้ใช้', NULL),
('KO_KAHU_ENTEN', 'Fire Charm', 1, NULL, 'ใช้ Fire Charm เรียก Fire aura เพื่อเพิ่มพลังโจมตีของ\nSkill ธาตุไฟ\nสามารถเรียกได้สูงสุด 10 aura\nอาวุธของคุณ จะเปลี่ยนเป็นธาตุไฟเมื่อเรียกครบ 10 aura\nอาวุธของคุณ จะเปลี่ยนเป็นธาตุไฟเมื่อเรียก 10 aura\nใช้ Fire Charm 1 ea ต่อการใช้สกิล 1 ครั้ง', NULL),
('KO_HYOUHU_HUBUKI', 'Ice Charm', 1, NULL, 'ใช้ Ice Charm เรียก Ice aura เพื่อเพิ่มพลังโจมตีของ\nSkill ธาตุน้ำ\nสามารถเรียกได้สูงสุด 10 aura\nสามารถรวมได้ถึง 10 spirit และอาวุธของคุณ\nอาวุธของคุณ จะเปลี่ยนเป็นธาตุน้ำเมื่อเรียกครบ 10 aura\nใช้ Ice Charm 1 ea ต่อการใช้สกิล 1 ครั้ง', NULL),
('KO_KAZEHU_SEIRAN', 'Wind Charm', 1, NULL, 'ใช้ Wind Charm เรียก Wind aura เพื่อเพิ่มการโจมตีของ\nSkill ธาตุลม.\nสามารถเรียกได้สูงสุด 10 aura\nอาวุธของคุณ จะเปลี่ยนเป็นธาตุลมเมื่อเรียกครบ 10 aura\nใช้ Wind Charm 1 ea ต่อการใช้สกิล 1 ครั้ง', NULL),
('KO_DOHU_KOUKAI', 'Earth Charm', 1, NULL, 'ใช้ Earth Charm เรียก Earth aura\nเพื่อเพิ่ม Atk และ Def ของผู้ใช้\nสามารถเรียกได้สูงสุด 10 aura\nอาวุธของคุณ จะเปลี่ยนเป็นธาตุดินเมื่อเรียกครบ 10 aura\nใช้ Earth Charm 1 ea ต่อการใช้สกิล 1 ครั้ง', NULL),
('KO_KAIHOU', 'Release Ninja Spell', 1, NULL, 'Requirement : Fire Charm 1, Ice Charm 1,\nWind Charm 1, Earth Charm 1\nปล่อย aura ที่เรียกไว้\nเพื่อสร้างความเสียหายต่อเป้าหมาย\nธาตุของความเสียหาย\nขึ้นอยู่กับธาตุของ aura ที่เรียกไว้', NULL),
('KO_ZENKAI', 'Cast Ninja Spell', 1, NULL, 'Requirement : Release Ninja Spell 1,\n16th Night 1\nปล่อย aura ที่เรียกไว้ลงบนพื้น\nเพื่อสร้างสนามพลังที่สร้างสถานะผิดปกติหลากหลายแบบ\nSpirit ธาตุไฟ - มีโอกาสทำให้ศัตรูในพื้นที่\nติดสถานะ Burning\nเพิ่มพลังโจมตีหากถืออาวุธธาตุไฟ\naura ธาตุน้ำ - มีโอกาสทำให้ศัตรูในพื้นที่\nพื้นที่ติดสถานะ Frozen/Freezing/Crystallization\nเพิ่มพลังโจมตีหากถืออาวุธธาตุน้ำ\naura ธาตุลม - มีโอกาสทำให้ศัตรูในพื้นที่\nติดสถานะ Silence/Sleep/Deep Sleep\nเพิ่มพลังโจมตีหากถืออาวุธธาตุลม\naura ธาตุดิน - มีโอกาสทำให้ศัตรูในพื้นที่\nติดสถานะ Stone Curse/Poison\nเพิ่มพลังโจมตีหากถืออาวุธธาตุดิน', NULL),
('KG_KAGEHUMI', 'Shadow Trampling', 5, NULL, 'Requirement : Illusion - Afterimage 1\nทำให้เป้าหมายที่ใช้ Skill ซ่อนตัวในระยะรอบตัว\nปรากฏตัวขึ้นและทำให้เคลื่อนที่ไม่ได้ชั่วขณะหนึ่ง ในระหว่างผลของ Skill เป้าหมายจะใช้ Skill ซ่อนตัวไม่ได้เช่นกัน\nไม่มีผลกับมอนสเตอร์ ใช้ได้ใน PVP และ WoE เท่านั้น', '[LV 1] AoE 5 x 5 ช่อง\n[LV 2] AoE 7 x 7 ช่อง\n[LV 3] AoE 9 x 9 ช่อง\n[LV 4] AoE 11 x 11 ช่อง\n[LV 5] AoE 13 x 13 ช่อง'),
('KG_KYOMU', 'Empty Shadow', 5, NULL, 'Requirement : Shadow Trampling 2\nยกเลิกผลของ Reflect Skill ของเป้าหมาย\nมีโอกาสล้มเหลวที่จะใช้ Skill ใส่เป้าหมาย\nได้รับผลของ Empty Shadow\nการใช้ Skill นี้จะใช้ Shadow Orb 1 ea', '[LV 1] ระยะเวลา 10 วินาที\n[LV 2] ระยะเวลา 15 วินาที\n[LV 3] ระยะเวลา 20 วินาที\n[LV 4] ระยะเวลา 25 วินาที\n[LV 5] ระยะเวลา 30 วินาที'),
('KG_KAGEMUSYA', 'Shadow Warrior', 5, NULL, 'Requirement : Empty Shadow 3\nทำให้เป้าหมายได้รับผลของ\n[Skill: Double Attack] ชั่วระยะหนึ่ง\nเสีย 1 SP ทุก 1 วินาที ในระยะเวลาของ Skill\nการใช้ Skill นี้จะใช้ Shadow Orb 1 ea', '[LV 1] ระยะเวลา 60 วินาที\n[LV 2] ระยะเวลา 90 วินาที\n[LV 3] ระยะเวลา 120 วินาที\n[LV 4] ระยะเวลา 150 วินาที\n[LV 5] ระยะเวลา 180 วินาที'),
('OB_ZANGETSU', 'Distorted Crescent', 5, NULL, 'Requirement : Illusion - Bewitch 1\nเพิ่มหรือลดค่า MATK หรือ ATK ของเป้าหมาย\nโดยขึ้นอยู่กับค่า HP กับ SP ของเป้าหมายที่มีในตอนนั้น', '[LV 1] ระยะเวลา 60 วินาที\n[LV 2] ระยะเวลา 75 วินาที\n[LV 3] ระยะเวลา 90 วินาที\n[LV 4] ระยะเวลา 105 วินาที\n[LV 5] ระยะเวลา 120 วินาที'),
('OB_AKAITSUKI', 'Ominous Moonlight', 5, NULL, 'Requirement : Distorted Crescent 2\nเป้าหมายที่อยู่ภายใต้ผลของ skill นี้\nหากได้รับผลของ skill ประเภท recovery skills บางสกิล  ,\nจะได้รับความเสียหายแทนการฟื้นฟู HP\nSkill นี้ไม่สามารถใช้กับผู้เล่นที่อยู่ภายนอก\nพื้นที่ PVP และไม่สามารถใช้กับพันธมิตร\nและมอนสเตอร์ประเภท Boss', '[LV 1] ระยะเวลา 10 วินาที\n[LV 2] ระยะเวลา 15 วินาที\n[LV 3] ระยะเวลา 20 วินาที\n[LV 4] ระยะเวลา 25 วินาที\n[LV 5] ระยะเวลา 30 วินาที'),
('OB_OBOROGENSOU', 'Moonlight Fantasy', 5, NULL, 'Requirement : Ominous Moonlight 3\nเพิ่มหรือลด HP และ SP ของเป้าหมายแบบสุ่ม\nขึ้นอยู่กับค่า HP กับ SP ของเป้าหมายที่มีในตอนนั้น\nเป้าหมายที่ได้รับผลของ Moonlight Fantasy\nเมื่อได้รับความเสียหายจากเวทมนต์\nจะกระจายความเสียหายที่ได้รับส่วนหนึ่ง ให้กับเป้าหมายโดยรอบ\nSkill นี้ใช้กับ monster ไม่ได้', '[LV 1] ระยะเวลา 10 วินาที\n[LV 2] ระยะเวลา 15 วินาที\n[LV 3] ระยะเวลา 20 วินาที\n[LV 4] ระยะเวลา 25 วินาที\n[LV 5] ระยะเวลา 30 วินาที'),
('ECLAGE_RECALL', 'ไปสู่ Eclage', 1, NULL, 'รูปแบบ Skill : Supportive\nวาร์ปไปเมือง Eclage. Eclage มีระยะเวลาร่ายคงตัว 3 วินาที สามารถใช้งานได้อีกครั้งหลังจาก 5 นาที.', NULL),
('MER_INVINCIBLEOFF2', 'Mind Bluster', 1, NULL, 'เนื้อหา : ตัดสายสัมพันธ์ระหว่างปีศาจร้ายและผู้ติดตามทำให้การปกป้องของปีศาจร้ายไร้ผลระยะยิง 2 เซลล์', NULL),
('GC_DARKCROW', 'Dark Claw', 5, 'ใช้งาน / ความเสียหาย - พิเศษ', 'Requirement : Dark Illusion 5\nทสร้างบาดแผลที่เจ็บปวดให้กับศัตรู เป้าหมายจะได้รับความเสียหายต่อการโจมตีทางกายภาพในระยะใกล้เพิ่มมากขึ้น โดยบาดแผลนี้จะคงอยู่เป็นเวลา 5 วินาที', '[Level 1] : ความเสียหาย 100% / เพิ่มความเสียหายของการโจมตีระยะใกล้ 1.3 เท่า\n[Level 2] : ความเสียหาย 200% / เพิ่มความเสียหายของการโจมตีระยะใกล้ 1.6 เท่า\n[Level 3] : ความเสียหาย 300% / เพิ่มความเสียหายของการโจมตีระยะใกล้ 1.9 เท่า\n[Level 4] : ความเสียหาย 400% / เพิ่มความเสียหายของการโจมตีระยะใกล้ 2.2 เท่า\n[Level 5] : ความเสียหาย 500% / เพิ่มความเสียหายของการโจมตีระยะใกล้ 2.5 เท่า'),
('RA_UNLIMIT', 'No Limits', 5, 'ใช้งาน / บัฟ (ตนเอง)', 'Requirement : Fear Breeze 5\nยืมพลังจากเทพ Ullr เทพแห่งการล่าและการยิงธนู ทำให้ได้รับความสามารถในการโจมตีระยะไกลเพิ่มขึ้นชั่วคราว แต่พลังป้องกันกายภาพและเวทมนตร์จะลดลงเหลือเพียง 1 ในเวลาที่กำหนด', '[Level 1] : เพิ่มพลังโจมตีทางกายภาพ 1.5 เท่าเป็นเวลา 1 นาที\n[Level 2] : เพิ่มพลังโจมตีทางกายภาพ 2.0 เท่าเป็นเวลา 1 นาที\n[Level 3] : เพิ่มพลังโจมตีทางกายภาพ 2.5 เท่าเป็นเวลา 1 นาที\n[Level 4] : เพิ่มพลังโจมตีทางกายภาพ 3.0 เท่าเป็นเวลา 1 นาที\n[Level 5] : เพิ่มพลังโจมตีทางกายภาพ 3.5 เท่าเป็นเวลา 1 นาที'),
('LG_KINGS_GRACE', 'King''s Grace', 5, 'ใช้งาน / บัฟ', 'Requirement : Reflect Damage 5\nด้วยการคุ้มครองจากกษัตริย์ ช่วยป้องกันความเสียหายและสถานะผิดปกติเกือบทั้งหมดของฝ่ายเดียวกัน\nใในระหว่างที่ได้รับการคุ้มครอง ผู้ที่ถูกคุ้มครองจะไม่สามารถควบคุมตัวละครได้ และจะได้รับผลนี้เฉพาะตนเองและสมาชิกในปาร์ตี้ภายใน PVP เท่านั้น\nช่วยรักษาสถานะผิดปกติ : Poison, Blind, Frozen, Stone Curse, Stun, Sleep, Bleeding, Curse, Chaos, Confusion, Hallucination, Silence, Burning, Freezing, Deep Sleep, Fear และ Mandragora Howling', '[Level 1] : รักษาสถานะผิดปกติในปาร์ตี้เป็นเวลา 5 วินาที, ฟื้นฟู HP 4% ต่อวินาที\n[Level 2] : รักษาสถานะผิดปกติในปาร์ตี้เป็นเวลา 5 วินาที, ฟื้นฟู HP 5% ต่อวินาที\n[Level 3] : รักษาสถานะผิดปกติในปาร์ตี้เป็นเวลา 5 วินาที, ฟื้นฟู HP 6% ต่อวินาที\n[Level 4] : รักษาสถานะผิดปกติในปาร์ตี้เป็นเวลา 5 วินาที, ฟื้นฟู HP 7% ต่อวินาที\n[Level 5] : รักษาสถานะผิดปกติในปาร์ตี้เป็นเวลา 5 วินาที, ฟื้นฟู HP 8% ต่อวินาที'),
('RK_DRAGONBREATH_WATER', 'Dragon Breath - Water', 10, 'ความเสียหายในขอบเขต', 'Requirement : Dragon Training 2\nปล่อยลมหายใจน้ำแข็งของมังกรออกมา มีโอกาสเล็กน้อยที่เป้าหมายจะติดสถานะ Freezing และเคลื่อนที่ช้าลง ความรุนแรงขึ้นอยู่กับ Max HP/Max SP ของผู้ใช้', NULL),
('NC_MAGMA_ERUPTION', 'Lava Flow', 5, 'ติดตัว', 'Requirement : Fire Earth Research 1\nทำให้เกิดแผ่นดินไหวที่รุนแรงและลาวาปะทุขึ้นมาจากพื้นดิน\nเมื่อฟาดลงที่พื้นดินอย่างรุนแรงจะสร้างความเสียหายและสถานะ Stun ภายในขอบเขต 7X7 ช่อง โดยลาวาที่ปะทุออกมานั้นจะคงอยู่เป็นระยะเวลา 5 วินาทีและไม่สามารถสร้างได้เกิน 3 ตำแหน่ง', '[Level 1] : พื้นที่ลาวา : สร้างความเสียหายตายตัว 1000 ในทุกๆ 0.5 วินาที, โอกาสการเกิด Burning 10%\n[Level 2] : พื้นที่ลาวา : สร้างความเสียหายตายตัว 1200 ในทุกๆ 0.5 วินาที, โอกาสการเกิด Burning 20%\n[Level 3] : พื้นที่ลาวา : สร้างความเสียหายตายตัว 1400 ในทุกๆ 0.5 วินาที, โอกาสการเกิด Burning 30%\n[Level 4] : พื้นที่ลาวา : สร้างความเสียหายตายตัว 1600 ในทุกๆ 0.5 วินาที, โอกาสการเกิด Burning 40%\n[Level 5] : พื้นที่ลาวา : สร้างความเสียหายตายตัว 1800 ในทุกๆ 0.5 วินาที, โอกาสการเกิด Burning 50%'),
('WM_FRIGG_SONG', 'Frigg''s Song', 5, 'ใช้งาน / บัฟ', 'Requirement : Lesson 2\nสกิลสำหรับอาวุธประเภทเครื่องดนตรี/แส้ ช่วยเพิ่ม Max HP ของฝ่ายเดียวกันทั้งหมดเป็นระยะเวลา 60 วินาทีและฟื้นฟู HP ในปริมาณที่กำหนด ใช้ Regrettable Tears 1ea\nใช้ได้กับตนเองและสมาชิกในปาร์ตี้ภายในพื้นที่ Siege เช่น PVP', '[Level 1] : ขอบเขตรอบๆ ตัวผู้ใช้ 7 x 7, เพิ่ม MHP 5%, ฟื้นฟูทีละ 100 ต่อวินาที\n[Level 2] : ขอบเขตรอบๆ ตัวผู้ใช้ 9 x 9, เพิ่ม MHP 10%, ฟื้นฟูทีละ 120 ต่อวินาที\n[Level 3] : ขอบเขตรอบๆ ตัวผู้ใช้ 11 x 11, เพิ่ม MHP 15%, ฟื้นฟูทีละ 140 ต่อวินาที\n[Level 4] : ขอบเขตรอบๆ ตัวผู้ใช้ 13 x 13, เพิ่ม MHP 20%, ฟื้นฟูทีละ 160 ต่อวินาที\n[Level 5] : ขอบเขตรอบๆ ตัวผู้ใช้ 15 x 15, เพิ่ม MHP 25%, ฟื้นฟูทีละ 180 ต่อวินาที'),
('SO_ELEMENTAL_SHIELD', 'Elemental Shield', 5, 'สนับสนุน (วิญญาณ)', 'Requirement : Spirit Control 3\nเป้าหมาย : พื้นดิน\nทำให้พลังวิญญาณระเบิดออก สร้าง Safety Wall พร้อมกับ Pneuma ขึ้นมาบนช่องที่ตนเองและสมาชิกในปาร์ตี้ยืนอยู่ Safety Wall และ Pneuma จะมีระยะเวลาต่อเนื่องของตนเองและจะหายไปเมื่อหมดความทนทานหรือระยะเวลาหมดลง\nมีขอบเขตทั้งหน้าจอ โดยมีผู้ใช้งานเป็นศูนย์กลางและวิญญาณที่ถูกเรียกออกมาจะหายไป\nใช้ Blue Gemstone 1ea', NULL),
('SC_ESCAPE', 'Urgent Escape', 5, 'ใช้งาน / สนับสนุน', 'Requirement : Triangle Shot 2\nวางกับดักและช่วยให้ตัวละครหลบออกจากพื้นที่อันตรายในทันทีที่ใช้งาน สร้างระยะห่างระหว่างตนเองกับศัตรู หากไม่สามารถก้าวข้ามช่องที่ไม่สามารถเคลื่อนที่ได้ จะเคลื่อนย้ายไปอยู่ในช่องข้างๆ แทน.\nในการใช้สกิลจะใช้ Special Alloy Trap 1ea และเมื่อใช้งานแล้วจะไม่สามารถเรียกคืนได้', '[Level 1] : ระยะหลบหลีก 5 ช่อง\n[Level 2] : ระยะหลบหลีก 6 ช่อง\n[Level 3] : ระยะหลบหลีก 7 ช่อง\n[Level 4] : ระยะหลบหลีก 8 ช่อง\n[Level 5] : ระยะหลบหลีก 9 ช่อง'),
('AB_OFFERTORIUM', 'Offertorium', 5, 'ใช้งาน / บัฟ', 'Requirement : Higness Heal 2\nช่วยเพิ่มความสามารถและผลของสกิลฟื้นฟูด้วยพลังแห่งเทพและการสวดภาวนา แล้วรักษาสถานะผิดปกติเกือบทั้งหมดของผู้ใช้งาน\nไม่สามารถใช้ทับซ้อนกับสกิล Magnificat ได้\nสถานะผิดปกติที่รักษาได้ : Bleeding, Blind, Burning, Chaos, Curse, Freezing, Hallucination, Mandragora Howling, Poison และพิษของ Guillotine Cross\nสกิลที่ได้รับผลการเพิ่มประสิทธิภาพ : Heal, Sanctuary, Coluseo Heal และ High Heal', '[Level 1] : เพิ่มอัตราการ Heal 1.3 เท่าเป็นระยะเวลา 90 วินาที / เพิ่มปริมาณ SP ที่เสียเมื่อใช้สกิลทั้งหมด 2.2 เท่า\n[Level 2] : เพิ่มอัตราการ Heal 1.6 เท่าเป็นระยะเวลา 90 วินาที / เพิ่มปริมาณ SP ที่เสียเมื่อใช้สกิลทั้งหมด 2.4 เท่า\n[Level 3] : เพิ่มอัตราการ Heal 1.9 เท่าเป็นระยะเวลา 90 วินาที / เพิ่มปริมาณ SP ที่เสียเมื่อใช้สกิลทั้งหมด 2.6 เท่า\n[Level 4] : เพิ่มอัตราการ Heal 2.2 เท่าเป็นระยะเวลา 90 วินาที / เพิ่มปริมาณ SP ที่เสียเมื่อใช้สกิลทั้งหมด 2.7 เท่า\n[Level 5] : เพิ่มอัตราการ Heal 2.5 เท่าเป็นระยะเวลา 90 วินาที / เพิ่มปริมาณ SP ที่เสียเมื่อใช้สกิลทั้งหมด 3 เท่า'),
('WL_TELEKINESIS_INTENSE', 'Intensification', 5, 'ใช้งาน / บัฟ', 'Requirement : Soul Expansion 5\nทำให้เวทมนตร์ธาตุวิญญาณไหลไปทั่วร่าง ปรับให้ร่างกายเหมาะสำหรับเวทมนตร์ธาตุวิญญาณ และทำให้ร่ายเวทมนตร์ได้รวดเร็วขึ้น\nสถานะนี้ไม่สามารถยกเลิกได้ด้วยสกิล Clearance หรือ Dispell', '[Level 1] : เพิ่มพลังโจมตีทางเวทมนตร์ธาตุวิญญาณ 1.4 เท่าเป็นเวลา 1 นาที / ลดระยะเวลาร่ายสกิล 10% / ลดปริมาณ SP ที่เสียของเวทมนตร์ธาตุวิญญาณ 10%\n[Level 2] : เพิ่มพลังโจมตีทางเวทมนตร์ธาตุวิญญาณ 1.8 เท่าเป็นเวลา 1 นาที / ลดระยะเวลาร่ายสกิล 20% / ลดปริมาณ SP ที่เสียของเวทมนตร์ธาตุวิญญาณ 20%\n[Level 3] : เพิ่มพลังโจมตีทางเวทมนตร์ธาตุวิญญาณ 2.2 เท่าเป็นเวลา 1 นาที / ลดระยะเวลาร่ายสกิล 30% / ลดปริมาณ SP ที่เสียของเวทมนตร์ธาตุวิญญาณ 30%\n[Level 4] : เพิ่มพลังโจมตีทางเวทมนตร์ธาตุวิญญาณ 2.6 เท่าเป็นเวลา 1 นาที / ลดระยะเวลาร่ายสกิล 40% / ลดปริมาณ SP ที่เสียของเวทมนตร์ธาตุวิญญาณ 40%\n[Level 5] : เพิ่มพลังโจมตีทางเวทมนตร์ธาตุวิญญาณ 3 เท่าเป็นเวลา 1 นาที / ลดระยะเวลาร่ายสกิล 50% / ลดปริมาณ SP ที่เสียของเวทมนตร์ธาตุวิญญาณ 50%'),
('ALL_FULL_THROTTLE', 'Full Throttle', 5, NULL, 'Requirement : อาชีพคลาส 3\nก้าวข้ามขีดกำจัดทั้งหมดโดยการใช้พลังชีวิตพื้นฐานทำให้เกิดความแข็งแกร่งขึ้นชั่วคราว หลังจากที่ระยะเวลาของสกิลสิ้นสุดลง ผู้ใช้จะตกอยู่ในสถานะ Rebound\nเมื่อใช้งานจะฟื้นฟู HP ทั้งหมดและเพิ่มความเร็วในการเคลื่อนที่ภายในระยะเวลาที่กำหนด All State + 20% สถานะนี้ไม่สามารถยกเลิกได้ด้วยสกิล Clearance หรือ Dispell', '[Level 1] : ระยะเวลาต่อเนื่อง 10 วินาที / ใช้ MSP 6% ต่อวินาที\n[Level 2] : ระยะเวลาต่อเนื่อง 15 วินาที / ใช้ MSP 4% ต่อวินาที\n[Level 3] : ระยะเวลาต่อเนื่อง 20 วินาที / ใช้ MSP 3% ต่อวินาที\n[Level 4] : ระยะเวลาต่อเนื่อง 25 วินาที / ใช้ MSP 2% ต่อวินาที\n[Level 5] : ระยะเวลาต่อเนื่อง 30 วินาที / ใช้ MSP 1% ต่อวินาที'),
('GN_ILLUSIONDOPING', 'Hallucination Drug', 5, 'พิเศษ / ดีบัฟ', 'Requirement : Special Pharmacy 1\nขว้างแอลกอฮอล์เข้มข้น มีโอกาสสูงที่จะทำให้เป้าหมายและรอบๆ เป้าหมาย ติดสถานะ Hallucination และถูกลดความแม่นยำลง ใช้ Alcohol 1ea', '[Level 1] : ความเสียหาย 100% / เป้าหมายและรอบๆ เป้าหมาย 9X9 ช่อง\n[Level 2] : ความเสียหาย 100% / เป้าหมายและรอบๆ เป้าหมาย 11X11 ช่อง\n[Level 3] : ความเสียหาย 100% / เป้าหมายและรอบๆ เป้าหมาย 13X13 ช่อง\n[Level 4] : ความเสียหาย 100% / เป้าหมายและรอบๆ เป้าหมาย 15X15 ช่อง\n[Level 5] : ความเสียหาย 100% / ทั้งหน้าจอโดยมีเป้าหมายเป็นศูนย์กลาง'),
('GM_ITEM_ATKMAX', 'Physical Item ATK Max', 1, NULL, 'พลังโจมตีสูงสุดของไอเทมโจมตีทางกายภาพ', NULL),
('GM_ITEM_ATKMIN', 'Physical Item ATK Min', 1, NULL, 'พลังโจมตีต่ำสุดของไอเทมโจมตีทางกายภาพ', NULL),
('GM_ITEM_MATKMAX', 'Magic Item ATK Max', 1, NULL, 'พลังโจมตีสูงสุดของไอเทมโจมตีทางเวทมนตร์', NULL),
('GM_ITEM_MATKMIN', 'Magic Item ATK Min', 1, NULL, 'พลังโจมตีต่ำสุดของไอเทมโจมตีทางกายภาพ', NULL),
('GD_GUILD_STORAGE', 'Guild Storage Extension', 5, 'Passive', 'เป้าหมาย : Guild\nเนื้อหา : จะสามารถใช้งานคลังกิลด์ได้ เพิ่มจำนวนช่องเก็บของในคลังจากการขยายคลังกิลด์', '[Level 1] : Slot 200 ช่อง\n[Level 2] : Slot 300ช่อง\n[Level 3] : Slot 400ช่อง\n[Level 4] : Slot 500ช่อง\n[Level 5] : Slot 600ช่อง'),
('RL_RICHS_COIN', 'Rich''s Coin', 1, NULL, 'Requirement : Coin Flip 5\nสาย : พิเศษ\nใช้ 100 Zeny แล้วจะสามารถสร้าง Coin ได้ทีละ 10 ชิ้น\nหากเรียนรู้สกิลนี้แล้ว เมื่อใช้ [Coin Flip] แล้วล้มเหลวก็จะไม่เสีย Coin ไป', NULL),
('RL_FALLEN_ANGEL', 'Fallen Angel', 1, NULL, 'Requirement : Desperado 10\nสาย : โจมตี / เคลื่อนที่\nสกิลสำหรับ Revolver (ปืนพก) เท่านั้น\nย้ายไปยังตำแหน่งที่กำหนด หากคุณใช้ Desperado ภายใน 2 วินาทีหลังจากเคลื่อนที่ความเสียหายของ Desperado จะเพิ่มขึ้น\nในกรณีที่โดนผนังหรือสิ่งกีดขวางกั้นระหว่างการเคลื่อนที่ สกิลที่ใช้จะล้มเหลวโดยอัตโนมัติ\nเมื่อใช้สกิลจะเสีย 1 Coin', NULL),
('RL_S_STORM', 'Shattering Storm', 5, NULL, 'Requirement : Disarm 1 / Crowd Control Shot 1\nสาย : โจมตี / พิเศษ\nสกิลสำหรับ Shotgun เท่านั้น\nมันทำลายหมวกและมอบ DMG ให้กับเป้าหมายและเป้าหมายทั้งหมดที่อยู่ในระยะ\nยิ่ง DEX กับเลเวลสกิลของผู้ใช้สูง และยิ่ง AGI กับเลเวลของเป้าหมายต่ำ ก็จะยิ่งเพิ่มอัตราความสำเร็จในการทำลายอุปกรณ์\nแต่ถ้ามีสกิล Coating อยู่ หรือเป็นไอเทมที่มีออปชั่นไม่สามารถทำลายได้ ก็จะไม่เกิด Shattering Storm ขึ้น\nเมื่อใช้สกิลจะเสีย Bullet ที่พกอยู่ 1 นัด', '[Lv 1] : ระยะ 5 x 5 / ATK 1900%\n[Lv 2] : ระยะ 5 x 5 / ATK 2100%\n[Lv 3] : ระยะ 5 x 5 / ATK 2300%\n[Lv 4] : ระยะ 5 x 5 / ATK 2500%\n[Lv 5] : ระยะ 7 x 7 / ATK 2700%'),
('RL_MASS_SPIRAL', 'Mass Spiral', 5, NULL, 'Requirement : Wounding Shot 1\nสาย : โจมตี / พิเศษ\nสกิลสำหรับ Rifle เท่านั้น\nหาก DEF ของเป้าหมายสูง ก็จะใช้กระสุนทะลุทะลวงที่เพิ่ม ATK\nเป้าหมายที่ได้รับ DMG มีโอกาสเกิดอัตราที่จะอยู่ในสถานะ Bleeding สูง\nเมื่อใช้สกิลจะเสีย Bullet ใน Full Metal Jacket ใน item Inventory 1 นัด', '[Level 1] : ATK 200% + ขึ้นอยู่กับ DEF ของเป้าหมาย\n[Level 2] : ATK 400% + ขึ้นอยู่กับ DEF ของเป้าหมาย\n[Level 3] : ATK 600% + ขึ้นอยู่กับ DEF ของเป้าหมาย\n[Level 4] : ATK 800% + ขึ้นอยู่กับ DEF ของเป้าหมาย\n[Level 5] : ATK 1000% + ขึ้นอยู่กับ DEF ของเป้าหมาย'),
('RL_E_CHAIN', 'Eternal Chain', 10, NULL, 'Requirement : Chain Action 10, Coin Flip 1\nสาย : สนับสนุน\nเมื่อใช้ [Eternal chain] จะเกิด [Chain Action] ขึ้น ไม่ว่าจะใช้เครื่องมือใดก็ตาม\nเลเวลของ [Chain Action] ที่เกิดขึ้นจะเท่ากันกับเลเวลของ [Eternal chain]\nเมื่อใช้สกิลจะเสีย 1 Coin', '[Level 1] : เวลาต่อเนื่อง 45 วินาที\n[Level 2] : เวลาต่อเนื่อง 60 วินาที\n[Level 3] : เวลาต่อเนื่อง 75 วินาที\n[Level 4] : เวลาต่อเนื่อง 90 วินาที\n[Level 5] : เวลาต่อเนื่อง 105 วินาที\n[Level 6] : เวลาต่อเนื่อง 120 วินาที\n[Level 7] : เวลาต่อเนื่อง 135 วินาที\n[Level 8] : เวลาต่อเนื่อง 150 วินาที\n[Level 9] : เวลาต่อเนื่อง 165 วินาที\n[Level 10] : เวลาต่อเนื่อง 180 วินาที'),
('RL_H_MINE', 'Howling Mine', 5, NULL, 'Requirement : Gunslinger Mine 1\nสาย : โจมตี / พิเศษ\nสกิลสำหรับ Grenade Launcher เท่านั้น\nสร้าง DMG ด้วยการยิงลูกระเบิดใส่เป้าหมาย สามารถใช้ Howling Mine ได้สูงสุด 5 ชิ้น\nหากใช้สกิล [Flicker] ในการกดระเบิด Howling Mine จะสามารถสร้าง DMG ธาตุไฟ ให้กับเป้าหมายและรอบๆ เป้าหมายเพิ่มเติมได้ด้วย\nHowling Mine ระเบิดได้ด้วยสกิล [Flicker] เท่านั้น หากไม่กดระเบิดภายใน 50 วินาที Howling Mine จะหล่นจากตัวเป้าหมายและหายไป\nเมื่อใช้สกิลจะเสีย Projection Landmines 1 อัน', '[Level 1] : ATK 400% + DMG 800%\n[Level 2] : ATK 600% + DMG 1100%\n[Level 3] : ATK 800% + DMG 1400%\n[Level 4] : ATK 1000% + DMG 1700%\n[Level 5] : ATK 1200% + DMG 2000%'),
('RL_FIRE_RAIN', 'Fire Rain', 5, NULL, 'Requirement : Gatling Fever 1\nสาย : พื้นดิน / โจมตี\nสกิลสำหรับ Gatling Gun เท่านั้น\nโจมตีที่พื้นดิน 3x10 เซลล์ด้านหน้าผู้ใช้ตามลำดับ DMG เพิ่มตาม ละเลเวลสกิลของผู้ใช้\nถ้าขอบเขตพื้นดินที่เกิด Fire Rain มีสกิลพื้นดินอยู่ จะลดการเกิดตามอัตราที่กำหนดของสกิลนั้นๆ\nเมื่อใช้สกิลจะเสีย Bullet ที่พกอยู่ 10 นัด', '[Level 1] : ATK 3800%, 20% ความน่าจะเป็นที่จะกำจัด SKill\n[Level 2] : ATK 4100%, 25%  ความน่าจะเป็นที่จะกำจัด SKill\n[Level 3] : ATK 4400%, 30%  ความน่าจะเป็นที่จะกำจัด SKill\n[Level 4] : ATK 4700%, 35%  ความน่าจะเป็นที่จะกำจัด SKill\n[Level 5] : ATK 5000%, 40%  ความน่าจะเป็นที่จะกำจัด SKill'),
('RL_FLICKER', 'Flicker', 1, NULL, 'Requirement : Coin Flip 1\nสาย : พิเศษ\nเมื่อสกิลพิเศษ [Howling Mind] / [Bind Trap] ของตัวเองที่อยู่บนจอเกิดขึ้น จะสามารถใช้ได้เฉพาะสกิลของตนเองเท่านั้น', NULL),
('RL_FIREDANCE', 'Fire Dance', 5, NULL, 'Requirement : Desperado 1\nสาย : โจมตี\nสกิลสำหรับ Revolver (ปืนพก) เท่านั้น\nโจมตีศัตรูที่อยู่ใกล้ ๆ ในพื้นที่ 7x7 เซลล์\nDMGเพิ่มขึ้นตามระดับ Desperado และระดับพื้นฐาน\nเมื่อใช้สกิลคุณจะเสียกระสุน 5 นัดในครอบครอง', '[Lv 1] : ATK 200%\n[Lv 2] : ATK 400%\n[Lv 3] : ATK 600%\n[Lv 4] : ATK 800%\n[Lv 5] : ATK 1000%'),
('RL_BANISHING_BUSTER', 'Vanishing Buster (การบังคับขับไล่)', 5, NULL, 'Requirement : Shatter Storm 1\nสาย : โจมตี / พิเศษ\nสกิลสำหรับ Shotgun เท่านั้น\nให้ DMG แก่เป้าหมายและลบเอฟเฟกต์บัฟที่มีต่อเป้าหมาย\nใช้กระสุน 1 นัดเมื่อใช้สกิล', '[Level 1] : ATK 2300%\n[Level 2] : ATK 2600%\n[Level 3] : ATK 2900%\n[Level 4] : ATK 3200%\n[Level 5] : ATK 3500%'),
('RL_AM_BLAST', 'Anti-Matter Blast', 5, NULL, 'Requirement : Mass Spiral 1\nสาย : โจมตี / พิเศษ\nสกิลสำหรับ Rifle เท่านั้น\nสร้าง DMG พร้อมลด [Resistance effect] เกี่ยวกับ Player-type DMG ที่เป้าหมายมีอยู่\nยิ่งระดับทักษะสูงความน่าจะเป็นของ Anti Material Effect ก็จะยิ่งสูงขึ้น\nเมื่อใช้สกิลคุณจะเสียกระสุน 1 นัดในครอบครอง', '[Level 1] : เวลาต่อเนื่อง 6 วินาที /โอกาส 30% ที่จะทำให้เกิดเอฟเฟกต์ /ลด Resistance 10%\n[Level 2] : เวลาต่อเนื่อง 7 วินาที /โอกาส 40% ที่จะทำให้เกิดเอฟเฟกต์ /ลด Resistance 20%\n[Level 3] : เวลาต่อเนื่อง 8 วินาที /โอกาส 50% ที่จะทำให้เกิดเอฟเฟกต์ /ลด Resistance 30%\n[Level 4] : เวลาต่อเนื่อง 9 วินาที /โอกาส 60% ที่จะทำให้เกิดเอฟเฟกต์ /ลด Resistance 40%\n[Level 5] : เวลาต่อเนื่อง 10 วินาที /โอกาส 70% ที่จะทำให้เกิดเอฟเฟกต์ /ลด Resistance 50%'),
('RL_QD_SHOT', 'Quick Draw Shot', 1, NULL, 'Requirement : Chain Action 1\nสาย : โจมตี\nQuick Draw Shot เป็นสกิลที่เพิ่ม ATK ให้เป้าหมายระหว่างการเกิด Chain Action\nเมื่อมี Chain Action เกิดขึ้น สามารถใช้สกิลนี้เป็นตัวเชื่อม ATK จะเพิ่มขึ้นตาม JOBLV ของ ผู้ใช้\nหากรอบตัวผู้ใช้ในขอบเขต 21x21 เซลล์ มีเป้าหมายที่โดน [Crimson Marker] อยู่ เป้าหมายนั้นจะได้รับ ATK เพิ่มเติมจาก Quick Draw Shot', NULL),
('RL_D_TAIL', 'Dragon Tail', 5, NULL, 'Requirement : Howling Mine 3\nสาย : โจมตี\nสกิลสำหรับ Grenade launcher เท่านั้น\nยิง Missile ใส่เป้าหมายและเป้าหมายทั้งหมดที่อยู่ภายในระยะโดยรอบ\nหากเป้าหมายติด Crimson Marker อยู่ จะยิ่งทำให้การโจมตีแรงขึ้น\nพลังโจมตีเพิ่มขึ้นตามเลเวลของตัวละคร\nเมื่อใช้สกิลจะเสีย Dragon Tail Missile 1 นัด', '[Level 1] : ATK 5000 %\n[Level 2] : ATK 6000%\n[Level 3] : ATK 7000%\n[Level 4] : ATK 8000%\n[Level 5] : ATK 9000%'),
('RL_R_TRIP', 'Round Trip', 5, NULL, 'Requirement : Fire Rain 1\nสาย : โจมตี\nสกิลสำหรับ Gatling Gunเท่านั้น\nโจมตีด้วย Gatling Gun ต่อศัตรูรอบตัว\nหากศัตรูทั้งหมดที่อยู่ใน Area of Effect ได้รับ DMG ก็จะถูกเด้งออกไปข้างนอกขอบเขต\nระหว่างที่เป้าหมายที่ได้รับ DMG และถูกเด้งออกไปข้างนอกขอบเขต จะเป็นการเพิ่ม DMG ด้วย\nความเสียหายจะเพิ่มขึ้นเพิ่มเติมตาม ระดับพื้นฐาน ของผู้ร่าย\nเมื่อใช้สกิลจะเสีย Bullet ที่พกอยู่ 5 นัด', '[Level 1] : ATK 700% / ขอบเขตที่เกิดผล 7 x 7\n[Level 2] : ATK 900% / ขอบเขตที่เกิดผล 7 x 7\n[Level 3] : ATK 1100% / ขอบเขตที่เกิดผล 9 x 9\n[Level 4] : ATK 1300% / ขอบเขตที่เกิดผล 11 x 11\n[Level 5] : ATK 1500% / ขอบเขตที่เกิดผล 13 x 13'),
('RL_HEAT_BARREL', 'Hot Barrel', 5, NULL, 'Requirement : Rich''s Coin 1\nสาย : ช่วยเหลือ\nใช้ Coin ทั้งหมดที่มีอยู่ โดยจะลด Fixed Casting เพิ่มความเร็วโจมตี และ เพิ่มพลังโจมตี แต่จะถูกลดอัตราหลบหลีก\nการโจมตีเพิ่มเติมและ ผลการลด Fixed Casting จะสูงขึ้นตามจำนวนของ Coin ที่เสียไป\nและถ้าคุณเปลี่ยนเครื่องมือในขณะที่ใช้ทักษะทักษะนั้นจะหายไปทันที\nสกิลนี้ไม่สามารถใช้ได้กับ [Last Stand] และ [Platinum Alter]', '[Level 1] : ASPD +1 / HIT -30 / เวลาต่อเนื่อง 60 วินาที\n[Level 2] : ASPD +2 / HIT -35 / เวลาต่อเนื่อง 60 วินาที\n[Level 3] : ASPD +3 / HIT -40 / เวลาต่อเนื่อง 60 วินาที\n[Level 4] : ASPD +4 / HIT -45 / เวลาต่อเนื่อง 60 วินาที\n[Level 5] : ASPD +5 / HIT -50 / เวลาต่อเนื่อง 60 วินาที'),
('RL_SLUGSHOT', 'Slug Shot', 5, NULL, 'Requirement : Vanishing Buster 3\nสาย : โจมตี / พิเศษ\nสกิลสำหรับ Shotgun เท่านั้น\nเนื่องจาก Slug Bullet หนักกว่าความแม่นยำจะลดลงเมื่อเป้าหมายอยู่ไกลออกไป อัตราส่วนการตีจะลดลงจากระยะ 3 เซลล์ขึ้นไป\nตัวละครที่โดน Slug Shot จะถูกกระแทกกลับ 6 เซลล์\nเมื่อใช้สกิลจะใช้ 1 Slug Bullet', '[Level 1] : 2000% ให้กับผู้เล่น /1200% สำหรับมอนสเตอร์ /ตั้งแต่ 3 เซลล์ อัตราความแม่นยำ -10 ต่อ 1เซลล์\n[Level 2] : 4000% ให้กับผู้เล่น /2400% สำหรับมอนสเตอร์ /ตั้งแต่ 3 เซลล์ อัตราความแม่นยำ -9 ต่อ 1เซลล์\n[Level 3] : 6000% ให้กับผู้เล่น /3600% สำหรับมอนสเตอร์ /ตั้งแต่ 3 เซลล์ ลดอัตราความแม่นยำ -8 ต่อ 1เซลล์\n[Level 4] : 8000% ให้กับผู้เล่น /4800% สำหรับมอนสเตอร์ /ตั้งแต่ 3 เซลล์ ลดอัตราความแม่นยำ -7 ต่อ 1เซลล์\n[Level 5] : 10000% ให้กับผู้เล่น /6000% สำหรับมอนสเตอร์ /ตั้งแต่ 3 เซลล์ ลดอัตราความแม่นยำ -6 ต่อ 1เซลล์'),
('RL_HAMMER_OF_GOD', 'God''s Hammer', 5, NULL, 'Requirement : Anti-Material Blast 3, Rich''s Coin 1\nสาย : โจมตี / พิเศษ\nสกิลสำหรับ Rifle เท่านั้น\nเป็นสกิลที่ใช้กำหนดพื้นที่เป้าหมายที่จะเรียกให้ Hammer of God มาโจมตี\nในกรณีที่เป้าหมายโดน [Crimson Marker] อยู่ จะทำการโจมตีที่เป้าหมายอย่างเม่นยำในขอบเขต 5x5 เซลล์\nแต่ถ้าไม่มีเป้าหมายที่โดน [Crimson Marker] อยู่เลย God''s Hammer ก็จะโจมตีแบบสุ่มรอบๆ บริเวณที่เป้าหมายอยู่\nเมื่อใช้สกิล Coin ทั้งหมดที่มีอยู่จะถูกใช้ไป โดยพลังโจมตีจะเพิ่มขึ้นตามจำนวน Coin ที่ใช้ในสกิลกับเลเวลของสกิล\nเป้าหมายที่ได้รับ DMG จะโดน Stun 100% และเวลาต่อเนื่องจะเพิ่มขึ้นตามเลเวลของสกิล', '[Level 1] : ATK 4200% / เวลาต่อเนื่องของ Stun 3 วินาที\n[Level 2] : ATK 5600% / เวลาต่อเนื่องของ Stun 3 วินาที\n[Level 3] : ATK 7000% / เวลาต่อเนื่องของ Stun 4 วินาที\n[Level 4] : ATK 8400% / เวลาต่อเนื่องของ Stun 4 วินาที\n[Level 5] : ATK 9800% / เวลาต่อเนื่องของ Stun 5 วินาที'),
('RL_C_MARKER', 'Crimson Marker', 1, NULL, 'Requirement : Coin Flip 1\nสาย : พิเศษ\nประทับ Bloody Brand ให้กับ 1 เป้าหมาย อัตราหลบหลีก -10 และ สร้างสัญลักษณ์บอกตำแหน่งใน Mini Map\nสามารถใช้ Crimson Marker กับเป้าหมายได้มากที่สุด 3 คน และจะส่งผลต่อสกิล [Quick Draw Shot] / [Dragon Tail] / [Hammer of God]', '[Level 1] : เวลาต่อเนื่อง 50 วินาที'),
('RL_P_ALTER', 'Platinum Altar', 5, NULL, 'Requirement : Rich''s Coin 1\nสาย : ช่วยเหลือ\nเกิดขึ้นเมื่อกระสุนที่ใช้เป็นธาตุ Holy เท่านั้น\nเมื่อใช้สกิล Coin ทั้งหมดที่มีอยู่จะถูกใช้ไป โดยพลังโจมตีจะเพิ่มขึ้นตามจำนวน Coin ที่ใช้ในการสร้างสกิลและเลเวลของสกิล\nฟิล์มป้องกันจะถูกสร้างขึ้นในช่วงระยะเวลาของเอฟเฟกต์ทักษะ จำนวนการโจมตีที่ฟิล์มป้องกันสามารถป้องกันได้ขึ้นอยู่กับเลเวลสกิล อย่างไรก็ตามหากโล่ถูกโจมตีโดย Holy Light มันจะแตก\nในกรณีที่เปลี่ยนอาวุธหรือกระสุน ก่อนเวลาต่อเนื่องจะหมดลงเอฟเฟกต์ของ Platinum Alter ก็จะหายไป(ฟิล์มกันรอยได้รับการบำรุงรักษา)\nสกิลนี้ไม่สามารถใช้ได้กับ [Last Stand] และ [Hot Barrel]', '[Level 1] : HP ของเกราะ = 5% ของ MAXHP, เวลาต่อเนื่อง 30 วินาที\n[Level 2] : HP ของเกราะ = 10% ของ MAXHP, เวลาต่อเนื่อง 45 วินาที\n[Level 3] : HP ของเกราะ = 15% ของ MAXHP, เวลาต่อเนื่อง 60 วินาที\n[Level 4] : HP ของเกราะ = 20% ของ MAXHP, เวลาต่อเนื่อง 75 วินาที\n[Level 5] : HP ของเกราะ = 25% ของ MAXHP, เวลาต่อเนื่อง 90 วินาที'),
('RL_B_TRAP', 'Binding Trap', 5, NULL, 'Requirement : Flicker 1\nสาย : พื้นดิน / พิเศษ\nติดตั้งกับดักพิเศษพร้อมคุณสมบัติในการชะลอความเร็วเคลื่อนที่ไว้ใต้เท้า\nลดความเร็วเคลื่อนที่ของเป้าหมายทั้งหมดที่อยู่ใน AoE ภายในเวลาต่อเนื่องที่กำหนด โดยที่เวลาต่อเนื่องของ Binding Trap จะลดไปตาม STR ของเป้าหมาย\nไม่สามารถติด Binding Trap ได้เกิน 1 ชิ้น หากใช้สกิล [Flicker] จะสามารถระเบิด Binding Trap แล้วเพิ่ม DMG ให้กับเป้าหมายได้\nDMG เพิ่มตาม DEX ของผู้ใช้ HP ของเป้าหมาย และเลเวลสกิล\nเมื่อใช้สกิลจะเสีย Special Alloy Trap 1 อัน', '[Level 1] : ขอบเขตที่เกิดผล 3 x 3 / เวลาต่อเนื่อง 4 + 6 วินาที\n[Level 2] : ขอบเขตที่เกิดผล 5 x 5 / เวลาต่อเนื่อง 4 + 7 วินาที\n[Level 3] : ขอบเขตที่เกิดผล 5 x 5 / เวลาต่อเนื่อง 4 + 8 วินาที\n[Level 4] : ขอบเขตที่เกิดผล 7 x 7 / เวลาต่อเนื่อง 4 + 9 วินาที\n[Level 5] : ขอบเขตที่เกิดผล 7 x 7 / เวลาต่อเนื่อง 4 + 10 วินาที');
